function renderCalendar() {
  const selectedMonth = selectedCalendarMonthDate();
  const taskEvents = getTaskCalendarEvents();
  const projectEvents = getProjectCalendarEvents();
  const visibleProjectEvents = getVisibleProjectCalendarEvents();
  const googleEvents = getGoogleCalendarEvents();
  const visibleGoogleEvents = getVisibleGoogleCalendarEvents();
  const calendarThemes = googleCalendarThemeAssignments();
  const combinedEvents = controlledItems("calendar", combinedCalendarSourceEvents(taskEvents, visibleProjectEvents, visibleGoogleEvents), "calendar");
  const control = viewControl("calendar");
  const weekStart = startOfWeek(new Date());
  const weekCount = control.mode === "week" ? 1 : 2;
  return `
    <section class="view">
      ${renderViewHeader("Calendar", "캘린더", `${combinedEvents.length} visible events`)}
      ${renderViewControls("calendar", { count: combinedEvents.length, total: taskEvents.length + projectEvents.length + visibleGoogleEvents.length })}
      <div class="calendar-view-switcher">${renderViewModeButtons("calendar", VIEW_MODE_OPTIONS.calendar, control.mode)}</div>
      <div class="calendar-layout">
        ${googleBackendStatus.connected ? "" : renderGoogleConnectPanel()}

        ${control.mode === "week" || control.mode === "twoWeeks" ? `
          <div class="panel calendar-week-panel">
            ${panelHeader(weekCount === 1 ? "This Week" : "Two Weeks", `${formatLongDate(weekStart)}부터`)}
            <div class="calendar-week-grid">${renderWeekDays(combinedEvents, calendarThemes, weekCount)}</div>
          </div>
        ` : ""}

        ${control.mode === "calendar" || control.mode === "agenda" ? `<div class="panel calendar-combined-panel">
          ${renderCalendarMonthPanelHeader(selectedMonth, combinedEvents.length)}
          ${renderCalendarLegend(combinedEvents, calendarThemes)}
          ${control.mode === "agenda" ? renderCalendarAgenda(combinedEvents, calendarThemes) : renderCombinedCalendar(combinedEvents, calendarThemes)}
        </div>` : ""}

        ${renderCalendarControls(taskEvents, projectEvents, googleEvents, calendarThemes)}
      </div>
    </section>
  `;
}

function combinedCalendarSourceEvents(taskEvents, projectEvents, visibleGoogleEvents) {
  const events = [];
  if (calendarSourceVisible("tasks")) {
    for (const event of taskEvents) events.push(event);
  }
  if (calendarSourceVisible("projects")) {
    for (const event of projectEvents) events.push(event);
  }
  for (const event of visibleGoogleEvents) events.push(event);
  return events;
}

function renderGoogleConnectPanel() {
  const configured = googleBackendStatus.configured;
  return `
    <div class="panel calendar-connect-panel">
      <div class="calendar-connect-copy">
        <span class="eyebrow">Google Calendar</span>
        <h2 class="panel-title">Google 로그인으로 캘린더 연결</h2>
        <p>${configured ? "로그인하면 Google 캘린더 목록과 일정을 바로 불러옵니다." : "로그인 버튼을 누르면 Google OAuth 설정 상태를 다시 확인합니다."}</p>
      </div>
      <button class="button calendar-google-login" type="button" data-action="connect-google"${googleBackendStatus.loading ? ' disabled aria-busy="true"' : ""}>${googleBackendStatus.loading ? "로그인 준비 중..." : "Google로 로그인"}</button>
    </div>
  `;
}

function renderCalendarControls(taskEvents, projectEvents, googleEvents, calendarThemes) {
  const googleCalendars = getGoogleCalendarOptions();
  const googleEventCounts = eventCountsByCalendarId(googleEvents);
  return `
    <details class="panel calendar-control-panel">
      <summary class="calendar-control-header">
        <div>
          <h2 class="panel-title">Visible Calendars</h2>
          <span class="calendar-panel-subtitle">${esc(googleCalendarStatusLabel())}</span>
        </div>
        <span class="calendar-control-chevron" aria-hidden="true">⌄</span>
      </summary>
      <div class="calendar-control-body">
        ${googleBackendStatus.connected ? `<div class="calendar-control-actions"><button class="button secondary" type="button" data-action="fetch-google">Google 새로고침</button></div>` : ""}
        <div class="calendar-filter-grid">
        <div class="calendar-filter-group">
          <strong class="calendar-filter-title">Personal Web</strong>
          <div class="calendar-toggle-list">
            ${renderCalendarSourceToggle("tasks", "Tasks", taskEvents.length, calendarThemes)}
            ${renderCalendarSourceToggle("projects", "Projects", projectEvents.length, calendarThemes)}
          </div>
          ${renderProjectCalendarToggles(projectEvents, calendarThemes)}
        </div>
        <div class="calendar-filter-group">
          <strong class="calendar-filter-title">Google Calendar</strong>
          <div class="calendar-toggle-list calendar-google-toggle-list">
            ${renderGoogleCalendarToggles(googleCalendars, googleEventCounts, calendarThemes)}
          </div>
        </div>
        </div>
      </div>
    </details>
  `;
}

function renderProjectCalendarToggles(projectEvents, calendarThemes) {
  if (!projectEvents.length) return "";
  let html = "";
  for (const project of projectEvents) {
    html += `
      <label class="calendar-toggle calendar-project-toggle" style="${calendarColorDeclarations(project, calendarThemes)}">
        <input type="checkbox" data-project-calendar-toggle="${esc(project.id)}" ${projectCalendarVisible(project.id) ? "checked" : ""}>
        <span class="calendar-toggle-mark"></span>
        <span class="calendar-toggle-text"><strong>${esc(project.title)}</strong></span>
      </label>
    `;
  }
  return `<div class="calendar-toggle-list calendar-project-toggle-list">${html}</div>`;
}

function renderGoogleCalendarToggles(calendars, eventCounts, calendarThemes) {
  if (!calendars.length) return `<div class="calendar-empty-state">Google 일정이 아직 불러와지지 않았습니다.</div>`;
  let html = "";
  for (const calendar of calendars) {
    html += renderGoogleCalendarToggle(calendar, eventCounts, calendarThemes);
  }
  return html;
}

function renderCalendarLegend(events, calendarThemes) {
  let taskCount = 0;
  let projectCount = 0;
  const googleCalendars = new Map();
  for (const event of events) {
    if (event.source === "task") {
      taskCount += 1;
      continue;
    }
    if (event.source === "project") {
      projectCount += 1;
      continue;
    }
    if (event.source !== "google") continue;
    const calendarId = event.calendarId || "primary";
    const current = googleCalendars.get(calendarId);
    if (current) {
      current.count += 1;
    } else {
      googleCalendars.set(calendarId, {
        calendarId,
        count: 1,
        label: event.calendarSummary || (calendarId === "primary" ? "Primary" : calendarId),
        backgroundColor: event.backgroundColor || "",
        foregroundColor: event.foregroundColor || "",
      });
    }
  }
  let items = "";
  if (taskCount) items += renderCalendarLegendItem("Tasks", taskCount, { source: "task" }, calendarThemes);
  if (projectCount) items += renderCalendarLegendItem("Projects", projectCount, { source: "project" }, calendarThemes);
  for (const option of getGoogleCalendarOptions()) {
    const calendar = googleCalendars.get(option.id);
    if (!calendar) continue;
    items += renderCalendarLegendItem(option.summary || calendar.label, calendar.count, {
      ...option,
      source: "google",
      calendarId: calendar.calendarId,
    }, calendarThemes);
  }
  if (!items) return "";
  return `<ul class="calendar-source-legend" aria-label="표시 중인 캘린더">${items}</ul>`;
}

function renderCalendarLegendItem(label, count, calendar, calendarThemes) {
  const countLabel = calendarCountLabel(count);
  return `
    <li class="calendar-legend-chip" style="${calendarColorDeclarations(calendar, calendarThemes)}" aria-label="${esc(`${label}, ${countLabel}`)}">
      <i class="source-dot" aria-hidden="true"></i>
      <span>${esc(label)}</span>
      <small>${esc(String(count))}</small>
    </li>
  `;
}

function renderCalendarMonthPanelHeader(selectedMonth, eventCount) {
  const label = ENGLISH_MONTH_FORMATTER.format(selectedMonth);
  return `
    <div class="calendar-panel-header">
      <div>
        <h2 class="panel-title">${esc(label)}</h2>
        <span class="calendar-panel-subtitle">${esc(calendarCountLabel(eventCount))}</span>
      </div>
      <div class="calendar-month-nav" aria-label="Calendar month navigation">
        <button class="button secondary calendar-month-button" type="button" data-calendar-month="prev" aria-label="Previous month">‹</button>
        <button class="button secondary calendar-month-current" type="button" data-calendar-month="today">${esc(label)}</button>
        <button class="button secondary calendar-month-button" type="button" data-calendar-month="next" aria-label="Next month">›</button>
      </div>
    </div>
  `;
}

function renderCalendarSourceToggle(source, label, count, calendarThemes) {
  const calendar = { source: source === "projects" ? "project" : "task" };
  return `
    <label class="calendar-toggle" style="${calendarColorDeclarations(calendar, calendarThemes)}">
      <input type="checkbox" data-calendar-source="${esc(source)}" ${calendarSourceVisible(source) ? "checked" : ""}>
      <span class="calendar-toggle-mark"></span>
      <span class="calendar-toggle-text">
        <strong>${esc(label)}</strong>
        <small>${esc(calendarCountLabel(count))}</small>
      </span>
    </label>
  `;
}

function renderGoogleCalendarToggle(calendar, googleEventCounts, calendarThemes) {
  const count = googleEventCounts.get(calendar.id) || 0;
  return `
    <label class="calendar-toggle calendar-google-toggle" style="${calendarColorDeclarations({ ...calendar, source: "google", calendarId: calendar.id }, calendarThemes)}">
      <input type="checkbox" data-google-calendar-toggle="${esc(calendar.id)}" ${googleCalendarVisible(calendar.id) ? "checked" : ""}>
      <span class="calendar-toggle-mark"></span>
      <span class="calendar-toggle-text">
        <strong>${esc(calendar.summary || calendar.id)}</strong>
        <small>${esc(calendarCountLabel(count))}</small>
      </span>
    </label>
  `;
}

function eventCountsByCalendarId(events) {
  const counts = new Map();
  for (const event of events) {
    const calendarId = event.calendarId || "primary";
    counts.set(calendarId, (counts.get(calendarId) || 0) + 1);
  }
  return counts;
}

function renderFinance() {
  if (financeWorkspace.status === "loading" || financeWorkspace.status === "idle") {
    return renderFinanceAccessScreen("loading");
  }
  if (financeWorkspace.status === "setup") return renderFinanceAccessScreen("setup");
  if (financeWorkspace.status === "locked") return renderFinanceAccessScreen("login");
  if (financeWorkspace.status === "error") return renderFinanceAccessScreen("error");
  return renderFinanceDashboard();
}

