function renderFinanceTab(state) {
  if (!financeModel) {
    return `
      <section class="finance-stage-panel panel" role="alert">
        <span class="finance-stage-index">계산 모듈 오류</span>
        <h2>가계부 계산 파일을 불러오지 못했습니다</h2>
        <p>화면을 새로고침한 뒤에도 같다면 배포된 정적 파일을 확인해주세요.</p>
      </section>
    `;
  }
  if (financeWorkspace.tab === "entries") return renderFinanceEntries(state);
  if (financeWorkspace.tab === "accounts") return renderFinanceAccounts(state);
  if (financeWorkspace.tab === "cards") return renderFinanceCards(state);
  if (financeWorkspace.tab === "fixed") return renderFinanceFixedCosts(state);
  if (financeWorkspace.tab === "stats") return renderFinanceStats(state);
  return renderFinanceOverview(state);
}

function renderFinanceOverview(state) {
  const summary = financeModel.financeMonthSummary(state, financeWorkspace.month);
  const today = dateKey(new Date());
  const balances = financeModel.accountBalances(state, today);
  const bankBalanceKrw = balances
    .filter(({ account }) => account.type === "bank")
    .reduce((total, item) => total + item.balanceKrw, 0);
  const cards = state.paymentMethods.filter((method) => method.type === "credit_card");
  return `
    <div class="finance-metric-grid metric-grid" aria-label="${esc(financeWorkspace.month)} 가계부 요약">
      ${renderFinanceMetric("은행 잔액", formatFinanceKrw(bankBalanceKrw), "", "balance")}
      ${renderFinanceMetric("수입", formatFinanceKrw(summary.incomeKrw), "", "balance")}
      ${renderFinanceMetric("지출", formatFinanceKrw(summary.spentKrw), "", "spent")}
      ${renderFinanceMetric("실제 출금", formatFinanceKrw(summary.cashOutKrw), "", "cash")}
    </div>
    <div class="finance-overview-grid">
      <section class="finance-stage-panel panel" aria-labelledby="finance-account-summary-title">
        <h2 id="finance-account-summary-title">계좌</h2>
        ${balances.length ? `
          <div class="finance-record-list">
            ${balances.map(({ account, balanceKrw }) => `
              <article class="finance-record">
                <div>
                  <strong>${esc(account.name)}</strong>
                  <small>${esc(financeAccountTypeLabel(account.type))}${account.institution ? ` · ${esc(account.institution)}` : ""}</small>
                </div>
                <span class="finance-record-amount">${esc(formatFinanceKrw(balanceKrw))}</span>
              </article>
            `).join("")}
          </div>
        ` : `
          <p>계좌를 등록하면 실제 입출금을 반영한 잔액을 보여 줍니다.</p>
          <button class="button" type="button" data-finance-tab="accounts">계좌 등록</button>
        `}
      </section>
      <section class="finance-stage-panel panel" aria-labelledby="finance-card-summary-title">
        <h2 id="finance-card-summary-title">신용카드</h2>
        ${cards.length ? `
          <div class="finance-record-list">
            ${cards.map((card) => `
              <article class="finance-record">
                <div>
                  <strong>${esc(card.name)}</strong>
                  <small>이번 달 사용액</small>
                </div>
                <span class="finance-record-amount">${esc(formatFinanceKrw(financeCardUsageKrw(state, card.id, financeWorkspace.month)))}</span>
              </article>
            `).join("")}
          </div>
        ` : `
          <p class="finance-empty-copy">등록된 신용카드가 없습니다.</p>
          <button class="button" type="button" data-finance-tab="cards">신용카드 등록</button>
        `}
      </section>
    </div>
  `;
}

function renderFinanceMetric(label, value, meta, tone) {
  const toneClass = {
    balance: "finance-metric-balance",
    spent: "finance-metric-spent",
    cash: "finance-metric-cash",
    scheduled: "finance-metric-scheduled",
  }[tone] || "";
  return `
    <article class="finance-metric metric ${toneClass}">
      <span class="metric-label">${esc(label)}</span>
      <strong class="metric-value">${esc(value)}</strong>
      ${meta ? `<small class="metric-sub">${esc(meta)}</small>` : ""}
    </article>
  `;
}

function renderFinanceEntries(state) {
  const accounts = state.accounts;
  const paymentMethods = state.paymentMethods;
  const defaultOn = financeDefaultDate();
  const entries = [...state.entries]
    .filter((entry) => entry.recognitionMonth === financeWorkspace.month && entry.status !== "void")
    .sort((left, right) => right.occurredOn.localeCompare(left.occurredOn) || right.id.localeCompare(left.id));
  const movements = [...state.movements]
    .filter((movement) => movement.postedOn.slice(0, 7) === financeWorkspace.month && movement.status !== "void")
    .sort((left, right) => right.postedOn.localeCompare(left.postedOn) || right.id.localeCompare(left.id));
  const refundableEntries = state.entries.filter((entry) => (
    entry.kind === "expense"
    && entry.status === "confirmed"
    && financeRefundableAmount(state, entry) > 0
  ));
  return `
    <section class="finance-section-heading">
      <h2>수입 지출 관리</h2>
    </section>
    ${!accounts.length || !paymentMethods.length ? `
      <section class="finance-inline-notice">
        <strong>기록 전에 계좌와 결제수단이 필요합니다.</strong>
        <button class="button secondary" type="button" data-finance-tab="accounts">계좌에서 등록</button>
      </section>
    ` : ""}
    <div class="finance-form-grid">
      <details class="finance-entry-form-card" ${paymentMethods.length ? "" : "open"}>
        <summary>지출</summary>
        <form data-form="finance-expense" class="finance-native-form">
          <div class="field-grid">
            ${financeTextInput("내용", "title", { placeholder: "예: 장보기", required: true })}
            ${financeMoneyInput("금액", "amountKrw")}
            ${financeDateInput("사용일", "occurredOn", defaultOn)}
            ${financeTextInput("분류", "category", { placeholder: "예: 식비" })}
            ${financeSelectInput("결제수단", "paymentMethodId", financePaymentMethodOptions(paymentMethods), { required: true, attributes: "data-finance-expense-payment-method" })}
            <fieldset data-finance-expense-card-fields hidden disabled>
              ${financeSelectInput("결제 방식", "cardPaymentType", [["single", "일시불"], ["installment", "할부"]], {
                required: true,
                allowEmpty: false,
                value: "single",
                attributes: "data-finance-expense-card-payment-type",
              })}
            </fieldset>
          </div>
          <button class="button" type="submit" ${paymentMethods.length ? "" : "disabled"}>쓴 기록 저장</button>
        </form>
      </details>
      <details class="finance-entry-form-card">
        <summary>수입</summary>
        <form data-form="finance-income" class="finance-native-form">
          <div class="field-grid">
            ${financeTextInput("내용", "title", { placeholder: "예: 급여", required: true })}
            ${financeMoneyInput("금액", "amountKrw")}
            ${financeDateInput("수입이 생긴 날", "occurredOn", defaultOn)}
            ${financeSelectInput("입금 계좌", "accountId", financeAccountOptions(accounts), { required: true })}
            ${financeDateInput("실제 입금일", "postedOn", defaultOn)}
            ${financeTextInput("분류", "category", { placeholder: "예: 급여" })}
          </div>
          <button class="button" type="submit" ${accounts.length ? "" : "disabled"}>받은 기록 저장</button>
        </form>
      </details>
      <details class="finance-entry-form-card">
        <summary>환불</summary>
        <form data-form="finance-refund" class="finance-native-form">
          <div class="field-grid">
            ${financeSelectInput("원래 쓴 기록", "originalEntryId", financeOriginalEntryOptions(state, refundableEntries), { required: true })}
            ${financeMoneyInput("환불 금액", "amountKrw")}
            ${financeDateInput("환불된 날", "occurredOn", defaultOn)}
            ${financeDateInput("실제 입금일", "postedOn", defaultOn, { hint: "신용카드 청구 차감이면 사용하지 않습니다." })}
            ${financeDateInput("청구 차감 예정일", "scheduledOn", "", { hint: "신용카드 환불에만 사용합니다." })}
          </div>
          <button class="button" type="submit" ${refundableEntries.length ? "" : "disabled"}>환불 기록 저장</button>
        </form>
      </details>
      <details class="finance-entry-form-card">
        <summary>계좌 이동</summary>
        <form data-form="finance-transfer" class="finance-native-form">
          <div class="field-grid">
            ${financeMoneyInput("금액", "amountKrw")}
            ${financeSelectInput("보낸 계좌", "fromAccountId", financeAccountOptions(accounts), { required: true })}
            ${financeSelectInput("받은 계좌", "toAccountId", financeAccountOptions(accounts), { required: true })}
            ${financeDateInput("실제 이동일", "postedOn", defaultOn)}
            ${financeTextInput("메모", "memo", { placeholder: "선택 입력" })}
          </div>
          <button class="button" type="submit" ${accounts.length > 1 ? "" : "disabled"}>계좌 이동 저장</button>
        </form>
      </details>
    </div>
    <div class="finance-ledger-grid">
      <section class="finance-stage-panel panel" aria-labelledby="finance-entry-list-title">
        <h2 id="finance-entry-list-title">수입·지출</h2>
        ${entries.length ? `
          <div class="finance-record-list">
            ${entries.map((entry) => renderFinanceEntryRecord(state, entry)).join("")}
          </div>
        ` : '<p class="finance-empty-copy">이 달의 사용·수입 기록이 없습니다.</p>'}
      </section>
      <section class="finance-stage-panel panel" aria-labelledby="finance-movement-list-title">
        <h2 id="finance-movement-list-title">계좌 이동</h2>
        ${movements.length ? `
          <div class="finance-record-list">
            ${movements.map((movement) => renderFinanceMovementRecord(state, movement)).join("")}
          </div>
        ` : '<p class="finance-empty-copy">이 달의 실제 입출금 기록이 없습니다.</p>'}
      </section>
    </div>
  `;
}

function renderFinanceSpendingCalendar(state, month) {
  const entryById = new Map(state.entries.map((entry) => [entry.id, entry]));
  const ruleById = new Map(state.recurringRules.map((rule) => [rule.id, rule]));
  const methodById = new Map(state.paymentMethods.map((method) => [method.id, method]));
  const byDay = new Map();
  const entries = state.entries
    .filter((entry) => (
      entry.status === "confirmed"
      && ["expense", "refund"].includes(entry.kind)
      && entry.occurredOn.slice(0, 7) === month
    ))
    .map((entry) => {
      const original = entry.kind === "refund" ? entryById.get(entry.originalEntryId) : entry;
      const fixed = ruleById.get(original?.recurringRuleId)?.kind === "fixed_expense";
      const method = methodById.get(entry.paymentMethodId || original?.paymentMethodId);
      return {
        entry,
        fixed,
        method,
        category: entry.source === "card_month_total" ? "월 합계" : entry.category || original?.category || "기타",
        signedAmountKrw: entry.kind === "refund" ? -entry.amountKrw : entry.amountKrw,
      };
    })
    .sort((left, right) => left.entry.title.localeCompare(right.entry.title, "ko") || left.entry.id.localeCompare(right.entry.id));
  for (const item of entries) {
    const day = Number(item.entry.occurredOn.slice(8, 10));
    const items = byDay.get(day) || [];
    items.push(item);
    byDay.set(day, items);
  }
  const today = dateKey(new Date());
  return `
    <section class="finance-spending-calendar-panel" data-finance-consumption-calendar aria-labelledby="finance-spending-calendar-title">
      <header class="finance-spending-calendar-header">
        <h2 id="finance-spending-calendar-title">지출 캘린더</h2>
        <div class="finance-calendar-month-control" aria-label="지출 캘린더 월">
          <button type="button" data-finance-month-shift="-1" data-finance-month-origin="calendar" aria-label="이전 달">‹</button>
          <strong>${esc(financePickerMonthLabel(month))}</strong>
          <button type="button" data-finance-month-shift="1" data-finance-month-origin="calendar" aria-label="다음 달">›</button>
        </div>
      </header>
      <div class="finance-consumption-legend" aria-label="지출 종류">
        <span>일반 지출</span><span>고정비</span><span>환불</span>
      </div>
      <div class="finance-spending-calendar-scroll">
        <div class="finance-calendar finance-spending-calendar" aria-label="${esc(month)} 지출 달력">
          ${FINANCE_WEEKDAY_LABELS.map((label) => `<span class="finance-calendar-weekday">${label}</span>`).join("")}
          ${financeCalendarDays(month).map((day) => {
            if (!day) return '<span class="finance-calendar-day finance-calendar-day-empty finance-spending-day" aria-hidden="true"></span>';
            const date = `${month}-${String(day).padStart(2, "0")}`;
            const items = byDay.get(day) || [];
            const totalKrw = items.reduce((total, item) => total + item.signedAmountKrw, 0);
            const fixedKrw = items.filter((item) => item.fixed).reduce((total, item) => total + item.signedAmountKrw, 0);
            const hasFixed = items.some((item) => item.fixed);
            const hasRegular = items.some((item) => !item.fixed && item.entry.kind === "expense");
            const hasRefund = items.some((item) => item.entry.kind === "refund");
            const weekday = parseDateOnly(date).getDay();
            const label = items.length
              ? `${date}, ${items.length}건, 합계 ${totalKrw < 0 ? "마이너스 " : ""}${formatFinanceKrw(Math.abs(totalKrw))}${hasFixed ? `, 고정비 ${formatFinanceKrw(Math.abs(fixedKrw))}` : ""}`
              : `${date}, 지출 없음`;
            return `
              <section
                class="finance-calendar-day finance-spending-day ${items.length ? "has-spending" : ""} ${hasRegular ? "has-regular-spending" : ""} ${hasFixed ? "has-fixed-cost" : ""} ${hasRefund ? "has-refund" : ""} ${date === today ? "is-today" : ""} ${weekday === 0 ? "is-sunday" : weekday === 6 ? "is-saturday" : ""}"
                data-finance-consumption-date="${esc(date)}"
                aria-label="${esc(label)}"
              >
                <header>
                  <time datetime="${esc(date)}">${day}</time>
                  ${items.length ? `<span class="finance-consumption-day-total">${totalKrw < 0 ? "−" : ""}${esc(formatFinanceKrw(Math.abs(totalKrw)))}</span>` : ""}
                </header>
                <div class="finance-consumption-items">
                  ${items.map(({ entry, fixed, method, category, signedAmountKrw }) => `
                    <article
                      class="finance-consumption-entry ${fixed ? "is-fixed" : ""} ${entry.kind === "refund" ? "is-refund" : ""}"
                      data-finance-consumption-entry="${esc(entry.id)}"
                    >
                      <span class="finance-consumption-entry-title">${esc(entry.title)}</span>
                      <span class="finance-consumption-entry-amount">${signedAmountKrw < 0 ? "−" : ""}${esc(formatFinanceKrw(Math.abs(signedAmountKrw)))}</span>
                      <small>${esc([fixed ? "고정비" : category, method?.name].filter(Boolean).join(" · "))}</small>
                    </article>
                  `).join("")}
                </div>
              </section>
            `;
          }).join("")}
        </div>
      </div>
    </section>
  `;
}

function financeCalendarDays(month) {
  const match = String(month || "").match(/^(\d{4})-(\d{2})$/);
  if (!match) return [];
  const year = Number(match[1]);
  const monthIndex = Number(match[2]) - 1;
  const dayCount = new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate();
  const firstWeekday = (new Date(Date.UTC(year, monthIndex, 1)).getUTCDay() + 6) % 7;
  const days = Array(firstWeekday).fill(0);
  for (let day = 1; day <= dayCount; day += 1) days.push(day);
  while (days.length % 7) days.push(0);
  return days;
}

function renderFinanceCardStatementForm(state, method) {
  const candidates = financeCardStatementCandidates(state, method.id, financeWorkspace.month);
  const existingStatement = state.cardStatements.find((statement) => (
    statement.paymentMethodId === method.id
    && statement.source !== "opening_installment"
    && statement.status === "confirmed"
    && statement.scheduledOn.slice(0, 7) === financeWorkspace.month
  ));
  const paidStatement = state.cardStatements.some((statement) => (
    statement.paymentMethodId === method.id
    && statement.source !== "opening_installment"
    && statement.status === "paid"
    && statement.scheduledOn.slice(0, 7) === financeWorkspace.month
  ));
  const candidateTotal = candidates.reduce((total, entry) => (
    total + (entry.kind === "refund" ? -entry.amountKrw : entry.amountKrw)
  ), 0);
  const installments = state.cardStatements.filter((statement) => (
    statement.paymentMethodId === method.id
    && statement.source === "opening_installment"
    && statement.status === "confirmed"
    && statement.scheduledOn.slice(0, 7) === financeWorkspace.month
  ));
  const installmentTotal = installments.reduce((total, statement) => total + statement.statementAmountKrw, 0);
  const candidateDates = candidates.map((entry) => entry.occurredOn).sort();
  const fallbackPeriod = financeModel.shiftMonthKey(financeWorkspace.month, -1);
  const periodStart = [existingStatement?.periodStart, candidateDates[0]].filter(Boolean).sort()[0] || `${fallbackPeriod}-01`;
  const periodEnd = [existingStatement?.periodEnd, candidateDates.at(-1)].filter(Boolean).sort().at(-1) || financeModel.dateForMonthDay(fallbackPeriod, 31);
  const paymentAccount = state.accounts.find((account) => account.id === method.paymentAccountId);
  const scheduledOn = financeModel.dateForMonthDay(financeWorkspace.month, method.dueDay || 1);
  const existingAdjustmentTotal = existingStatement?.adjustments?.reduce((total, item) => total + item.amountKrw, 0) || 0;
  const oneTimeTotal = (existingStatement?.statementAmountKrw || 0) + candidateTotal;
  const paymentTotal = oneTimeTotal + installmentTotal;
  const paid = paidStatement && !candidates.length && !installments.length;
  return `
    <details class="finance-entry-form-card">
      <summary>${esc(method.name)} ${paid ? "납부 완료" : "명세서 확정"}</summary>
      <form data-form="finance-card-statement" class="finance-native-form">
        <input type="hidden" name="paymentMethodId" value="${esc(method.id)}">
        <input type="hidden" name="settlementMonth" value="${esc(financeWorkspace.month)}">
        <input type="hidden" name="scheduledOn" value="${esc(scheduledOn)}">
        ${existingStatement ? `<input type="hidden" name="statementId" value="${esc(existingStatement.id)}">` : ""}
        ${candidates.map((entry) => `<input type="hidden" name="entryId" value="${esc(entry.id)}">`).join("")}
        <p class="finance-form-note">${esc(paymentAccount?.name || "설정된 계좌")}에서 카드대금이 바로 출금됩니다.</p>
        <div class="finance-statement-breakdown">
          ${financeFormFact(`${financePickerMonthLabel(fallbackPeriod)} 일시불 이용액`, formatFinanceKrw(oneTimeTotal - existingAdjustmentTotal))}
          ${financeFormFact("할부 총합", formatFinanceKrw(installmentTotal))}
          ${financeFormFact("기타 추가", formatFinanceKrw(existingAdjustmentTotal))}
        </div>
        <div class="field-grid">
          ${financeDateInput("사용 기간 시작", "periodStart", periodStart)}
          ${financeDateInput("사용 기간 끝", "periodEnd", periodEnd)}
          ${financeDateInput("실제 출금일", "postedOn", scheduledOn)}
          ${financeTextInput("기타 항목", "adjustmentLabel", { placeholder: "예: 카드론·수수료" })}
          ${financeMoneyInput("기타 금액", "adjustmentAmountKrw", { required: false, attributes: "data-finance-statement-adjustment-amount" })}
        </div>
        <p class="finance-form-fact finance-statement-total">
          <span>총 납부액</span>
          <strong data-finance-statement-total data-base-amount="${esc(paymentTotal)}">${esc(formatFinanceKrw(paymentTotal))}</strong>
        </p>
        <button class="button" type="submit" ${paid || (!paymentTotal && existingStatement) ? "disabled" : ""}>${paid ? "납부 완료" : "명세서 확정 및 출금"}</button>
      </form>
    </details>
  `;
}

function renderFinanceFixedCostPaymentForm(state, entry, settlement, rule) {
  const account = state.accounts.find((item) => item.id === rule.accountId);
  return `
    <details class="finance-entry-form-card finance-payment-confirm-card">
      <summary>${esc(entry.title)} 실제 출금 확인</summary>
      <form data-form="finance-fixed-cost-payment" class="finance-native-form">
        <input type="hidden" name="entryId" value="${esc(entry.id)}">
        <input type="hidden" name="settlementId" value="${esc(settlement.id)}">
        <p class="finance-form-note">출금 계좌 ${esc(account?.name || "설정 확인 필요")}</p>
        <div class="field-grid">
          ${financeDateInput("실제 출금일", "postedOn", settlement.scheduledOn)}
          ${financeMoneyInput("실제 금액", "amountKrw", { value: entry.amountKrw })}
        </div>
        <button class="button" type="submit">납부</button>
      </form>
    </details>
  `;
}

function renderFinanceCards(state) {
  const cards = state.paymentMethods.filter((method) => method.type === "credit_card");
  return `
    <section class="finance-section-heading">
      <h2>신용카드</h2>
    </section>
    ${renderFinancePaymentMethodManage(state, "credit")}
    ${cards.length ? `
      <div class="finance-card-workspaces">
        ${cards.map((method, index) => renderFinanceCardWorkspace(state, method, index === 0)).join("")}
      </div>
    ` : ""}
  `;
}

function renderFinanceCardWorkspace(state, method, open) {
  const month = financeWorkspace.month;
  const previousMonth = financeModel.shiftMonthKey(month, -1);
  const entries = financeCardUsageEntries(state, method.id, month);
  const plans = financeCardInstallmentPlans(state, method.id);
  const account = state.accounts.find((item) => item.id === method.paymentAccountId);
  const currentUsageKrw = financeCardUsageKrw(state, method.id, month);
  const totalUsageKrw = financeCardTotalUsageKrw(state, method.id);
  return `
    <details class="finance-stage-panel panel finance-card-workspace" data-finance-card="${esc(method.id)}" ${open ? "open" : ""}>
      <summary>
        <span><strong>${esc(method.name)}</strong><small>매월 ${esc(method.dueDay || 1)}일 납부 · ${esc(account?.name || "출금 계좌 확인 필요")}</small></span>
        <span>${esc(formatFinanceKrw(totalUsageKrw))}</span>
      </summary>
      <div class="finance-card-workspace-body">
        <div class="finance-metric-grid metric-grid finance-metric-grid-compact">
          ${renderFinanceMetric(`${month} 사용액`, formatFinanceKrw(currentUsageKrw), `${entries.length}개 기록`, "spent")}
          ${renderFinanceMetric(`${previousMonth} 사용액`, formatFinanceKrw(financeCardUsageKrw(state, method.id, previousMonth)), "이전 달", "scheduled")}
        </div>
        ${renderFinanceCardInstallmentSetup(state, method)}
        ${renderFinanceCardStatementForm(state, method)}
        <section class="finance-card-section" aria-labelledby="finance-card-records-${esc(method.id)}">
          <h3 id="finance-card-records-${esc(method.id)}">사용 내역</h3>
          <div class="finance-record-list">
            ${entries.map((entry) => renderFinanceEntryRecord(state, entry)).join("") || '<p class="finance-empty-copy">이 달의 카드 사용 기록이 없습니다.</p>'}
          </div>
        </section>
        <section class="finance-card-section" aria-labelledby="finance-card-schedule-${esc(method.id)}">
          <h3 id="finance-card-schedule-${esc(method.id)}">할부</h3>
          <div class="finance-installment-plans">
            ${plans.map(renderFinanceInstallmentPlan).join("") || '<p class="finance-empty-copy">등록된 할부가 없습니다.</p>'}
          </div>
        </section>
      </div>
    </details>
  `;
}

function renderFinanceCardInstallmentSetup(state, method) {
  const entries = financePendingCardInstallmentEntries(state, method.id);
  if (!entries.length) return "";
  const entry = entries[0];
  const installmentCount = 2;
  return `
    <details class="finance-entry-form-card">
      <summary>할부 설정 (${entries.length})</summary>
      <form data-form="finance-card-installment-setup" class="finance-native-form">
        <input type="hidden" name="paymentMethodId" value="${esc(method.id)}">
        <div class="field-grid">
          ${financeSelectInput("할부 항목", "entryId", entries.map((item) => [item.id, `${item.occurredOn} · ${item.title} · ${formatFinanceKrw(item.amountKrw)}`]), {
            required: true,
            allowEmpty: false,
            value: entry.id,
            attributes: "data-finance-installment-entry",
          })}
          ${financeNumberInput("개월", "installmentCount", installmentCount, 2, 120)}
        </div>
        <div class="field-grid finance-installment-setup-payments" data-finance-installment-payments>
          ${renderFinanceCardInstallmentPayments(method, entry, installmentCount)}
        </div>
        <div class="finance-statement-breakdown" data-finance-installment-preview data-principal-krw="${esc(entry.amountKrw)}">
          <p class="finance-form-fact"><span>원금</span><strong data-finance-installment-principal>${esc(formatFinanceKrw(entry.amountKrw))}</strong></p>
          <p class="finance-form-fact"><span>수수료</span><strong data-finance-installment-fee>${esc(formatFinanceKrw(0))}</strong></p>
          <p class="finance-form-fact"><span>총 납부액</span><strong data-finance-installment-total>${esc(formatFinanceKrw(entry.amountKrw))}</strong></p>
        </div>
        <button class="button" type="submit">할부 일정 저장</button>
      </form>
    </details>
  `;
}

function renderFinanceCardInstallmentPayments(method, entry, count) {
  const amounts = financeModel.splitKrw(entry.amountKrw, count);
  return financeCardInstallmentRows(method, entry, count, amounts).map((row) => (
    financeMoneyInput(`${financePickerMonthLabel(row.scheduledOn.slice(0, 7))} · ${row.installmentNumber}/${count}`, "paymentAmountKrw", {
      value: row.amountKrw,
      attributes: "data-finance-installment-payment",
    })
  )).join("");
}

function financeCardInstallmentRows(method, entry, count, amounts) {
  const firstOn = financeModel.scheduledCardPaymentOn(method, entry.occurredOn);
  if (!firstOn) return [];
  return amounts.map((amountKrw, index) => {
    const scheduledMonth = financeModel.shiftMonthKey(firstOn.slice(0, 7), index);
    return {
      amountKrw,
      installmentNumber: index + 1,
      scheduledOn: index ? financeModel.dateForMonthDay(scheduledMonth, method.dueDay || 1) : firstOn,
    };
  });
}

function renderFinanceInstallmentPlan(plan) {
  return `
    <details class="finance-installment-plan" data-finance-installment-plan="${esc(plan.planId)}">
      <summary data-finance-installment-toggle>
        <span><strong>${esc(plan.label)}</strong><small>${plan.remainingCount}회 남음 · ${esc(plan.firstOn)}~${esc(plan.lastOn)}</small></span>
        <span class="finance-installment-plan-balance">${esc(formatFinanceKrw(plan.remainingKrw))}</span>
      </summary>
      <div class="finance-installment-plan-body">
        <div class="finance-statement-breakdown">
          ${plan.principalKrw === null ? financeFormFact("총 금액", formatFinanceKrw(plan.totalKrw)) : `
            ${financeFormFact("원금", formatFinanceKrw(plan.principalKrw))}
            ${financeFormFact("수수료", formatFinanceKrw(plan.feeKrw))}
            ${financeFormFact("총 납부액", formatFinanceKrw(plan.totalKrw))}
          `}
        </div>
        <div>
          ${financeFormFact("납부 금액", formatFinanceKrw(plan.paidKrw))}
          ${financeFormFact("남은 금액", formatFinanceKrw(plan.remainingKrw))}
        </div>
        <div class="finance-installment-months">
          ${plan.statements.map((statement) => `
            <div>
              <span>${esc(`${statement.installmentNumber}/${statement.installmentCount}`)} · ${esc(statement.scheduledOn)}</span>
              <small>${esc(financeSettlementStatusLabel(statement.status))}</small>
              <strong>${esc(formatFinanceKrw(statement.statementAmountKrw))}</strong>
            </div>
          `).join("")}
        </div>
      </div>
    </details>
  `;
}

function financeCardInstallmentPlans(state, methodId) {
  const plans = new Map();
  for (const statement of state.cardStatements.filter((item) => item.paymentMethodId === methodId && item.source === "opening_installment")) {
    const plan = plans.get(statement.planId) || { planId: statement.planId, label: statement.label || "할부", statements: [] };
    plan.statements.push(statement);
    plans.set(statement.planId, plan);
  }
  return [...plans.values()].map((plan) => {
    plan.statements.sort((left, right) => left.installmentNumber - right.installmentNumber || left.scheduledOn.localeCompare(right.scheduledOn));
    plan.totalKrw = plan.statements.reduce((total, item) => total + item.statementAmountKrw, 0);
    const principalStatement = plan.statements.find((item) => Number.isSafeInteger(item.planPrincipalKrw));
    const purchaseEntryId = plan.statements.find((item) => item.purchaseEntryId)?.purchaseEntryId;
    const purchaseEntry = state.entries.find((item) => item.id === purchaseEntryId);
    plan.principalKrw = principalStatement?.planPrincipalKrw ?? purchaseEntry?.amountKrw ?? null;
    plan.feeKrw = plan.principalKrw === null ? null : plan.totalKrw - plan.principalKrw;
    plan.paidKrw = plan.statements.filter((item) => ["paid", "historical_paid"].includes(item.status)).reduce((total, item) => total + item.statementAmountKrw, 0);
    plan.remainingKrw = plan.totalKrw - plan.paidKrw;
    plan.remainingCount = plan.statements.filter((item) => ["estimated", "confirmed"].includes(item.status)).length;
    plan.firstOn = plan.statements[0]?.scheduledOn || "";
    plan.lastOn = plan.statements.at(-1)?.scheduledOn || "";
    return plan;
  }).sort((left, right) => left.firstOn.localeCompare(right.firstOn) || left.planId.localeCompare(right.planId));
}

function financeCardUsageEntries(state, methodId, month) {
  return state.entries
    .filter((entry) => (
      entry.paymentMethodId === methodId
      && entry.recognitionMonth === month
      && entry.status === "confirmed"
      && ["expense", "refund"].includes(entry.kind)
    ))
    .sort((left, right) => right.occurredOn.localeCompare(left.occurredOn) || right.id.localeCompare(left.id));
}

function financeCardUsageKrw(state, methodId, month) {
  return financeCardUsageEntries(state, methodId, month).reduce((total, entry) => (
    total + (entry.kind === "refund" ? -entry.amountKrw : entry.amountKrw)
  ), 0);
}

function financePendingCardInstallmentEntries(state, methodId) {
  const configuredEntryIds = new Set(state.cardStatements
    .filter((statement) => statement.source === "opening_installment" && statement.purchaseEntryId)
    .map((statement) => statement.purchaseEntryId));
  return state.entries
    .filter((entry) => (
      entry.paymentMethodId === methodId
      && entry.kind === "expense"
      && entry.status === "confirmed"
      && entry.cardPaymentType === "installment"
      && !configuredEntryIds.has(entry.id)
    ))
    .sort((left, right) => left.occurredOn.localeCompare(right.occurredOn) || left.id.localeCompare(right.id));
}

function financeCardTotalUsageKrw(state, methodId) {
  const entryById = new Map(state.entries.map((entry) => [entry.id, entry]));
  const entryTotal = state.settlements.filter((settlement) => (
    settlement.targetType === "entry"
    && ["estimated", "confirmed"].includes(settlement.status)
    && entryById.get(settlement.targetId)?.paymentMethodId === methodId
  )).reduce((total, settlement) => {
    const entry = entryById.get(settlement.targetId);
    return total + (entry.kind === "refund" ? -entry.amountKrw : entry.amountKrw);
  }, 0);
  const statementTotal = state.cardStatements.filter((statement) => (
    statement.paymentMethodId === methodId
    && ["estimated", "confirmed"].includes(statement.status)
  )).reduce((total, statement) => total + statement.statementAmountKrw, 0);
  const pendingInstallmentTotal = financePendingCardInstallmentEntries(state, methodId)
    .reduce((total, entry) => total + entry.amountKrw, 0);
  return entryTotal + statementTotal + pendingInstallmentTotal;
}

function financeMonthOptions(centerMonth, before, after) {
  return Array.from({ length: before + after + 1 }, (_, index) => {
    const value = financeModel.shiftMonthKey(centerMonth, index - before);
    return [value, financePickerMonthLabel(value)];
  });
}

