function renderEntityStat(label, value, meta = "") {
  return `
    <span class="entity-stat">
      <small>${esc(label)}</small>
      <strong>${esc(value)}</strong>
      ${meta ? `<em>${esc(meta)}</em>` : ""}
    </span>
  `;
}


function renderHabitItem(habit, today = dateKey(new Date())) {
  const days = habitPreviewDays(today);
  const completed = habitDoneCount(habit.id, days);
  const expanded = ui.expandedHabitId === habit.id;
  const statusLabel = { active: "활성", paused: "중단", archived: "보관" }[habit.status] || habit.status;
  const statusColor = habit.status === "active" ? "teal" : habit.status === "paused" ? "amber" : "rose";
  const relation = habit.projectId ? nameOf("projects", habit.projectId) : habit.boxId ? nameOf("boxes", habit.boxId) : "";
  const monthStats = habitMonthStats(habit.id, new Date(today));
  return `
    <article class="habit-item ${expanded ? "is-expanded" : ""}" data-habit-item="${habit.id}" data-habit-card="${habit.id}">
      <div class="habit-row" role="button" tabindex="0" data-habit-toggle="${habit.id}" aria-expanded="${expanded ? "true" : "false"}">
        <div class="habit-main">
          <div class="habit-title-line">
            <h3>${esc(habit.title)}</h3>
            <span class="habit-status ${statusColor}">${esc(statusLabel)}</span>
          </div>
          <div class="habit-context">
            <span>${esc(habit.target || "목표 기준 없음")}</span>
            ${relation ? `<span>${esc(relation)}</span>` : ""}
          </div>
        </div>
        <div class="habit-preview" aria-label="${esc(habit.title)} ${esc(habitRangeLabel(days))} 체크">
          <div class="habit-range-caption">${esc(habitRangeLabel(days))}</div>
          <div class="habit-days habit-days-inline" style="--habit-day-count:${days.length}" role="group">
            ${renderHabitDayButtons(habit, days, today)}
          </div>
        </div>
        <div class="habit-stat">
          <strong class="${completed >= Math.ceil(days.length * 0.7) ? "teal" : "amber"}" data-habit-progress="${habit.id}" data-habit-progress-total="${days.length}">${completed}/${days.length}</strong>
          <span>range</span>
        </div>
        <div class="habit-stat habit-month-stat">
          <strong class="${monthStats.completed >= Math.ceil(monthStats.total * 0.7) ? "teal" : "amber"}" data-habit-month-inline="${habit.id}" data-habit-month="${monthKey(new Date(today))}">${monthStats.completed}/${monthStats.total}</strong>
          <span>month</span>
        </div>
        <div class="habit-actions" aria-label="${esc(habit.title)} 관리">
          <button class="habit-edit-button" type="button" data-habit-edit="${habit.id}" aria-label="루틴 상세 편집">✎</button>
          <button class="habit-delete-button" type="button" data-habit-delete="${habit.id}" aria-label="루틴 삭제">삭제</button>
        </div>
        <span class="project-chevron habit-chevron" aria-hidden="true"></span>
      </div>
      <div class="habit-detail-shell" aria-hidden="${expanded ? "false" : "true"}">
        <div class="habit-detail">
          ${ui.editingHabitId === habit.id ? renderInlineEditPanel("habits", habit, "루틴 수정") : ""}
          ${renderHabitCalendar(habit, today, today)}
        </div>
      </div>
    </article>
  `;
}

function renderHabitDayButton(habit, date, today = dateKey(new Date())) {
  return `
    <button class="habit-day ${habitDone(habit.id, date) ? "is-done" : ""} ${date === today ? "is-today" : ""}" type="button" data-toggle-habit="${habit.id}" data-habit-date="${date}" aria-label="${date}">
      <span class="habit-day-fill" aria-hidden="true"></span>
      <span>${weekday(new Date(date))}</span>
      <strong>${date.slice(8)}</strong>
    </button>
  `;
}

function renderHabitCalendar(habit, currentDate, today = dateKey(new Date())) {
  const monthDate = new Date(currentDate);
  const currentMonth = monthKey(monthDate);
  const days = habitCalendarMonthDays(monthDate);
  const stats = habitMonthStats(habit.id, monthDate);
  return `
    <div class="habit-calendar">
      <div class="habit-calendar-head">
        <div>
          <strong>${esc(monthLabel(monthDate))}</strong>
          <span>${esc(habit.target || "루틴 체크 캘린더")}</span>
        </div>
        <span class="badge ${stats.completed >= Math.ceil(stats.total * 0.7) ? "teal" : "amber"}" data-habit-month-progress="${habit.id}" data-habit-month="${currentMonth}">${stats.completed}/${stats.total}</span>
      </div>
      <div class="habit-calendar-weekdays">
        ${renderWeekdayLabels(startOfSundayWeek(monthDate), true)}
      </div>
      <div class="habit-calendar-grid">
        ${renderHabitCalendarDays(habit, days, currentMonth, today)}
      </div>
    </div>
  `;
}

function renderHabitCard(habit, currentDate, expanded = false, today = dateKey(new Date())) {
  const start = startOfWeek(new Date(currentDate));
  const days = dateKeyRange(start, 7);
  const completed = habitDoneCount(habit.id, days);
  return `
    <article class="card" data-select-type="habits" data-select-id="${habit.id}" data-habit-card="${habit.id}">
      <h3 class="card-title">${esc(habit.title)}</h3>
      <p class="entity-preview">${esc(habit.target || "")}</p>
      <div class="habit-days" role="group" aria-label="${esc(habit.title)} 주간 체크">
        ${renderHabitDayButtons(habit, days, today)}
      </div>
      <div class="card-meta">
        <span class="badge ${completed >= 5 ? "teal" : "amber"}" data-habit-progress="${habit.id}">${completed}/7</span>
        ${badge(habit.cadence, "blue")}
        ${expanded && habit.projectId ? badge(nameOf("projects", habit.projectId), "violet") : ""}
      </div>
    </article>
  `;
}

function renderHabitDayButtons(habit, days, today) {
  let html = "";
  for (const date of days) {
    html += renderHabitDayButton(habit, date, today);
  }
  return html;
}

function renderHabitCalendarDays(habit, days, currentMonth, today) {
  let html = "";
  for (const day of days) {
    const key = dateKey(day);
    const done = habitDone(habit.id, key);
    html += `
      <button class="habit-calendar-day ${weekendClass(day)} ${monthKey(day) !== currentMonth ? "is-outside" : ""} ${key === today ? "is-today" : ""} ${done ? "is-done" : ""}" type="button" data-toggle-habit="${habit.id}" data-habit-date="${key}" aria-label="${key}">
        <span class="habit-day-fill" aria-hidden="true"></span>
        <span class="habit-calendar-date">${key.slice(8)}</span>
      </button>
    `;
  }
  return html;
}

function renderJournalCard(journal) {
  return `
    <article class="card" data-select-type="journals" data-select-id="${journal.id}">
      <h3 class="card-title">${esc(journal.title)}</h3>
      <p class="entity-preview">${esc(blockText(journal).slice(0, 120))}</p>
      <div class="card-meta">
        ${badge(journal.date || "", "teal")}
        ${badge(`${journal.satisfaction || 0}/10`, "amber")}
      </div>
    </article>
  `;
}

function renderCaptureCard(capture) {
  const draft = getCaptureDraft(capture.id);
  return `
    <article class="card capture-card ${draft ? "is-configuring" : ""}" data-select-type="captures" data-select-id="${capture.id}" data-delete-drag-type="captures" data-delete-drag-id="${capture.id}">
      <h3 class="card-title">${esc(capture.title)}</h3>
      ${capture.url ? `<p class="entity-preview">${esc(capture.url)}</p>` : ""}
      <div class="card-meta">
        ${badge("수집함", "blue")}
      </div>
      ${renderCaptureConvertActions(capture, draft)}${draft ? renderTaskCaptureFlow(capture, draft) : ""}
    </article>
  `;
}

function renderCaptureConvertActions(capture, draft) {
  let options = "";
  for (const [type, label] of CAPTURE_CONVERT_TYPES) {
    options += `
      <button class="button ghost ${draft?.type === type ? "is-active" : ""}" type="button" data-convert="${type}" data-capture-id="${capture.id}" aria-pressed="${draft?.type === type ? "true" : "false"}">${label}</button>
    `;
  }
  return `
    <div class="toolbar capture-type-toolbar" aria-label="분류 유형">
      ${options}
    </div>
  `;
}

function renderTaskCaptureFlow(capture, draft) {
  const steps = getTaskCaptureSteps(draft);
  const visibleCount = Math.min(draft.stepIndex + 1, steps.length);
  let rows = "";
  for (let index = 0; index < visibleCount; index += 1) {
    rows += renderTaskCaptureStep(capture.id, draft, steps[index], index);
  }
  const readyToSave = draft.stepIndex >= steps.length;
  const waitingForProjectEnd = draft.type === "projects" && draft.values?.startDate && !draft.values?.endDate;
  const targetLabel = captureTargetLabel(draft.type);
  return `
    <div class="capture-flow" data-task-flow="${capture.id}" aria-label="${esc(targetLabel)} 속성 선택">
      ${rows}
      ${readyToSave ? renderCaptureCalendar(capture.id, draft) : ""}
      ${
        readyToSave
          ? `<div class="capture-flow-save" data-flow-index="${steps.length}" style="--flow-index:${steps.length}">
              <div>
                <strong>${esc(targetLabel)}로 저장</strong>
                <span>${esc(taskCaptureSummary(draft))}</span>
              </div>
              <div class="capture-flow-save-actions">
                <button class="button ghost" type="button" data-task-flow-cancel="${capture.id}">취소</button>
                <button class="button" type="button" data-task-flow-save="${capture.id}" ${waitingForProjectEnd ? "disabled" : ""}>저장</button>
              </div>
            </div>`
          : ""
      }
    </div>
  `;
}

function renderTaskCaptureStep(captureId, draft, step, index) {
  const selectedValue = draft.values[step.key] || "";
  const active = index === draft.stepIndex;
  const selectedOption = taskStepOption(step, selectedValue);
  const options = active ? renderTaskCaptureStepOptions(captureId, step, selectedValue) : "";
  if (!active) {
    return `
      <div class="capture-flow-row is-complete" data-flow-index="${index}" style="--flow-index:${index}">
        <div class="capture-flow-label">
          <span>${esc(step.label)}</span>
          <small>${esc(step.hint)}</small>
        </div>
        <button class="capture-flow-summary is-selected" type="button" data-task-flow-jump="${captureId}" data-flow-step="${step.key}">
          <span>${esc(selectedOption.label)}</span>
          ${selectedOption.meta ? `<small>${esc(selectedOption.meta)}</small>` : ""}
        </button>
      </div>
    `;
  }
  return `
    <div class="capture-flow-row is-active" data-flow-index="${index}" style="--flow-index:${index}">
      <div class="capture-flow-label">
        <span>${esc(step.label)}</span>
        <small>${esc(step.hint)}</small>
      </div>
      <div class="capture-flow-options" role="group" aria-label="${esc(step.label)} 선택">
        ${options}
      </div>
    </div>
  `;
}

function renderTaskCaptureStepOptions(captureId, step, selectedValue) {
  let options = "";
  for (const option of step.options) {
    options += `
      <button class="capture-flow-option ${option.value === selectedValue ? "is-selected" : ""}" type="button" data-task-flow-choice="${captureId}" data-flow-step="${step.key}" data-flow-value="${esc(option.value)}">
        <span>${esc(option.label)}</span>
        ${option.meta ? `<small>${esc(option.meta)}</small>` : ""}
      </button>
    `;
  }
  return options;
}

function renderCaptureCalendar(captureId, draft) {
  if (!["tasks", "projects"].includes(draft.type)) return "";
  const values = draft.values || {};
  const taskDate = normalizeTaskDate(values.dueDate);
  const range = normalizedCaptureProjectRange(values);
  const selectedMonth = values.dateMonth || taskDate.slice(0, 7) || range.startDate.slice(0, 7) || monthKey(new Date());
  const monthDate = parseMonthKey(selectedMonth);
  const isProject = draft.type === "projects";
  const prompt = isProject
    ? !range.startDate
      ? "시작일을 선택하세요."
      : !values.endDate
        ? `${compactDateLabel(range.startDate)}부터 · 종료일을 선택하세요.`
        : `${compactDateLabel(range.startDate)} — ${compactDateLabel(range.endDate)}`
    : taskDate
      ? `${compactDateLabel(taskDate)}에 배치`
      : "선택하지 않으면 미계획으로 저장됩니다.";
  return `
    <section class="task-scheduler capture-calendar" data-capture-date-picker="${captureId}" aria-label="${isProject ? "Project 기간" : "Task 날짜"} 선택">
      <div class="task-scheduler-head">
        <div>
          <strong>${esc(monthLabel(monthDate))}</strong>
          <span>${esc(prompt)}</span>
        </div>
        <div class="task-scheduler-nav">
          <button class="task-scheduler-nav-button" type="button" data-capture-calendar-nav="previous" data-capture-calendar-month="${monthKey(addMonths(monthDate, -1))}" data-capture-id="${captureId}" aria-label="이전 달">‹</button>
          <button class="task-scheduler-nav-button" type="button" data-capture-calendar-nav="today" data-capture-calendar-month="${monthKey(new Date())}" data-capture-id="${captureId}">오늘</button>
          <button class="task-scheduler-nav-button" type="button" data-capture-calendar-nav="next" data-capture-calendar-month="${monthKey(addMonths(monthDate, 1))}" data-capture-id="${captureId}" aria-label="다음 달">›</button>
          <button class="task-scheduler-nav-button" type="button" data-capture-calendar-clear data-capture-id="${captureId}" aria-label="${isProject ? "기간 지우기" : "날짜 지우기"}">지우기</button>
        </div>
      </div>
      <div class="task-scheduler-weekdays">
        ${renderSchedulerWeekdayLabels()}
      </div>
      <div class="task-scheduler-grid">
        ${renderCaptureCalendarDays(captureId, draft, monthDate, taskDate, range)}
      </div>
    </section>
  `;
}

function renderCaptureCalendarDays(captureId, draft, monthDate, taskDate, range) {
  const today = dateKey(new Date());
  const isProject = draft.type === "projects";
  let html = "";
  for (const day of monthGridDays(monthDate)) {
    const key = dateKey(day);
    const outside = day.getMonth() !== monthDate.getMonth();
    const rangeEdge = isProject && (key === range.startDate || key === range.endDate);
    const inRange = isProject && range.startDate && range.endDate && key >= range.startDate && key <= range.endDate;
    const selected = isProject ? rangeEdge : key === taskDate;
    html += `
      <button
        class="task-scheduler-day ${outside ? "is-outside" : ""} ${key === today ? "is-today" : ""} ${selected ? "is-selected" : ""} ${inRange ? "is-in-range" : ""} ${key === range.startDate ? "is-range-start" : ""} ${key === range.endDate ? "is-range-end" : ""}"
        type="button"
        data-capture-calendar-date="${key}"
        data-capture-id="${captureId}"
        aria-label="${key}"
        aria-pressed="${selected || inRange ? "true" : "false"}"
      >
        <span>${day.getDate()}</span>
      </button>
    `;
  }
  return html;
}

function getCaptureDraft(captureId) {
  return ui.captureDrafts?.[captureId] || null;
}

function getTaskCaptureSteps(draft) {
  const type = draft?.type || "tasks";
  const values = draft?.values || {};
  const boxId = values.boxId || "";
  const projectId = values.projectId || "";
  const selectedProject = itemById("projects", projectId);
  const effectiveBoxId = boxId || selectedProject?.boxId || "";
  const { projects } = captureRelationCandidates({ effectiveBoxId });

  const boxStep = {
      key: "boxId",
      label: "Box",
      hint: "관리 영역",
      options: boxCaptureOptions(),
  };
  const projectStep = {
      key: "projectId",
      label: "Project",
      hint: "실행 맥락",
      options: projectCaptureOptions(projects),
  };
  if (type === "boxes") return [];
  if (type === "projects") return [boxStep];
  return [boxStep, projectStep];
}

function boxCaptureOptions() {
  const options = [{ value: "", label: "미지정", meta: "추후 연결" }];
  for (const box of state.boxes) {
    options.push({ value: box.id, label: box.name, meta: box.visibility === "pinned" ? "고정" : "" });
  }
  return options;
}

function projectCaptureOptions(projects) {
  const options = [{ value: "", label: "없음", meta: "독립 실행" }];
  for (const project of projects) {
    options.push({ value: project.id, label: project.name, meta: projectFlowMeta(project) });
  }
  return options;
}

function projectFlowMeta(project) {
  const status = STATUSES.project[project.status] || project.status || "";
  return status;
}

function taskStepOption(step, value) {
  for (const option of step.options) {
    if (option.value === value) return option;
  }
  return step.options[0] || { label: "미지정", meta: "" };
}

function taskStepOptionLabel(step, value) {
  return taskStepOption(step, value).label || "미지정";
}

function taskCaptureSummary(draft) {
  const steps = getTaskCaptureSteps(draft);
  if (!steps.length) return "상위 연결 없음";
  let summary = "";
  for (const step of steps) {
    const label = `${step.label}: ${taskStepOptionLabel(step, draft.values[step.key] || "")}`;
    summary = summary ? `${summary} · ${label}` : label;
  }
  if (draft.type === "tasks") {
    const dueDate = normalizeTaskDate(draft.values?.dueDate);
    summary += ` · 날짜: ${dueDate ? compactDateLabel(dueDate) : "미계획"}`;
  }
  if (draft.type === "projects") {
    const range = normalizedCaptureProjectRange(draft.values);
    summary += ` · 기간: ${range.startDate ? draft.values?.endDate ? `${compactDateLabel(range.startDate)}–${compactDateLabel(range.endDate)}` : "종료일 선택 중" : "미정"}`;
  }
  return summary;
}

function captureTargetLabel(type) {
  return {
    tasks: "Task",
    projects: "Project",
    boxes: "Box",
  }[type] || "항목";
}

function renderWeekDays(events = getCombinedCalendarEvents(), calendarThemes = googleCalendarThemeAssignments(), weekCount = 2) {
  const start = startOfWeek(new Date());
  const days = dateRange(start, weekCount * 7);
  const today = dateKey(new Date());
  let html = "";
  for (let weekIndex = 0; weekIndex < weekCount; weekIndex += 1) {
    const weekDays = days.slice(weekIndex * 7, weekIndex * 7 + 7);
    let dayHtml = "";
    for (let index = 0; index < weekDays.length; index += 1) {
      const day = weekDays[index];
      const key = dateKey(day);
      dayHtml += `
        <div class="day ${key === today ? "is-today" : ""}" style="grid-column: ${index + 1};">
          <div class="day-title"><span>${weekday(day)}</span><span>${key.slice(5)}</span></div>
          <div class="calendar-week-empty" aria-hidden="true"></div>
        </div>
      `;
    }
    html += `<div class="calendar-week-row">${dayHtml}${renderCalendarSpanLayer(events, weekDays, { className: "calendar-week-span-layer", limit: Number.MAX_SAFE_INTEGER, calendarThemes })}</div>`;
  }
  return html;
}

function renderCombinedCalendar(events = getCombinedCalendarEvents(), calendarThemes = googleCalendarThemeAssignments()) {
  const now = new Date();
  const today = dateKey(now);
  const selectedMonth = selectedCalendarMonthDate();
  const currentMonth = monthKey(selectedMonth);
  const days = calendarMonthGridDays(selectedMonth);
  const weeks = chunkCalendarWeeks(days);
  let weekHtml = "";
  for (const weekDays of weeks) {
    weekHtml += renderCombinedCalendarDays(weekDays, events, currentMonth, today, calendarThemes);
  }
  return `
    <div class="calendar-month-weekdays">
      ${renderWeekdayLabels(startOfSundayWeek(selectedMonth))}
    </div>
    <div class="calendar-month-grid">
      ${weekHtml}
    </div>
  `;
}

function renderCalendarAgenda(events = getCombinedCalendarEvents(), calendarThemes = googleCalendarThemeAssignments()) {
  if (!events.length) return empty("표시할 일정이 없습니다.");
  const range = combinedCalendarRange();
  const items = calendarAgendaItems(events, range);
  if (!items.length) return empty("표시할 일정이 없습니다.");
  let html = "";
  let currentDate = "";
  for (const item of items) {
    if (item.groupDate !== currentDate) {
      currentDate = item.groupDate;
      html += `
        <div class="calendar-agenda-date">
          <strong>${esc(compactDateLabel(currentDate))}</strong>
          <span>${esc(weekday(parseDateOnly(currentDate)))}</span>
        </div>
      `;
    }
    html += renderCalendarAgendaItem(item, calendarThemes);
  }
  return `<div class="calendar-agenda">${html}</div>`;
}

function calendarAgendaItems(events, range) {
  const items = [];
  for (const event of events) {
    const start = calendarEventStartKey(event);
    const end = calendarEventEndKey(event, start);
    if (!start || !end || end < range.start || start >= range.endExclusive) continue;
    const groupDate = start < range.start ? range.start : start;
    items.push({ event, groupDate, start, end });
  }
  items.sort(calendarAgendaSort);
  return items;
}

function calendarAgendaSort(a, b) {
  if (a.groupDate !== b.groupDate) return a.groupDate.localeCompare(b.groupDate);
  const aTime = a.event.start || a.start;
  const bTime = b.event.start || b.start;
  if (aTime !== bTime) return aTime.localeCompare(bTime);
  const sourceOrder = { project: 0, google: 1, task: 2, local: 3 };
  const sourceDiff = (sourceOrder[a.event.source] ?? 9) - (sourceOrder[b.event.source] ?? 9);
  if (sourceDiff) return sourceDiff;
  return (a.event.title || "").localeCompare(b.event.title || "");
}

function renderCalendarAgendaItem(item, calendarThemes) {
  const event = item.event;
  const attrs = event.selectType && event.selectId ? `data-select-type="${event.selectType}" data-select-id="${event.selectId}"` : "";
  const link = event.htmlLink ? `<a class="calendar-agenda-open" href="${esc(event.htmlLink)}" target="_blank" rel="noreferrer" aria-label="Google Calendar에서 열기">열기</a>` : "";
  const meta = calendarAgendaMetaLabel(event);
  const time = calendarAgendaTimeLabel(item);
  return `
    <article class="calendar-agenda-row ${calendarEventSourceClass(event)}" ${attrs} style="${calendarColorDeclarations(event, calendarThemes)}" aria-label="${esc(`${event.title || "(제목 없음)"}, ${meta}, ${time}`)}">
      <span class="source-dot ${esc(event.source || "local")}" aria-hidden="true"></span>
      <div class="calendar-agenda-main">
        <strong>${esc(event.title || "(제목 없음)")}</strong>
        <span>${esc(meta)}</span>
      </div>
      <time>${esc(time)}</time>
      ${link}
    </article>
  `;
}

function calendarAgendaMetaLabel(event) {
  if (event.source === "google") return event.calendarSummary || "Google Calendar";
  if (event.source === "project") return "Project";
  if (event.source === "task") return "Task";
  return "Calendar";
}

function calendarAgendaTimeLabel(item) {
  const { event, start, end } = item;
  if (start !== end) return `${compactDateLabel(start)} - ${compactDateLabel(end)}`;
  return calendarEventTimeLabel(event) || "종일";
}

function renderCombinedCalendarDays(days, eventsByDate, currentMonth, today, calendarThemes) {
  const events = Array.isArray(eventsByDate) ? eventsByDate : [];
  const pastWeek = days.length === 7 && dateKey(days[6]) < dateKey(startOfWeek(new Date()));
  let html = "";
  for (let index = 0; index < days.length; index += 1) {
    const day = days[index];
    const key = dateKey(day);
    const monthBoundary = day.getDate() === 1 ? `<strong class="calendar-month-boundary">${day.getMonth() + 1}월</strong>` : "";
    html += `
      <div class="calendar-month-day ${monthKey(day) !== currentMonth ? "is-outside" : ""} ${key === today ? "is-today" : ""}" style="grid-column: ${index + 1};">
        <div class="calendar-month-date">${monthBoundary}<span>${key.slice(8)}</span></div>
      </div>
    `;
  }
  return `
    <div class="calendar-month-week ${pastWeek ? "is-past-week" : ""}">
      ${html}
      ${renderCalendarSpanLayer(events, days, { className: "calendar-month-span-layer", limit: Number.MAX_SAFE_INTEGER, calendarThemes })}
    </div>
  `;
}

function chunkCalendarWeeks(days) {
  const weeks = [];
  for (let index = 0; index < days.length; index += 7) {
    weeks.push(days.slice(index, index + 7));
  }
  return weeks;
}

function renderCalendarSpanLayer(events, days, { className = "", limit = 4, calendarThemes } = {}) {
  const { segments, overflow } = calendarSpanSegments(events, days, limit);
  const maxRow = Math.max(1, limit + 1);
  const eventHtml = renderCalendarEvents(segments, { compact: true, limit: segments.length, calendarThemes });
  const overflowHtml = overflow
    ? `<span class="calendar-span-more" style="grid-row: ${maxRow};">+${overflow}</span>`
    : "";
  return `
    <div class="calendar-span-layer ${className}" aria-label="연속 일정">
      ${eventHtml}
      ${overflowHtml}
    </div>
  `;
}

function calendarSpanSegments(events, days, limit) {
  const firstKey = days.length ? dateKey(days[0]) : "";
  const lastKey = days.length ? dateKey(days[days.length - 1]) : "";
  if (!firstKey || !lastKey) return { segments: [], overflow: 0 };
  const dayIndexByKey = new Map();
  for (let index = 0; index < days.length; index += 1) {
    dayIndexByKey.set(dateKey(days[index]), index);
  }
  const candidates = [];
  for (const event of events) {
    const start = calendarEventStartKey(event);
    const end = calendarEventEndKey(event, start);
    if (!start || !end || end < firstKey || start > lastKey) continue;
    const segmentStart = start > firstKey ? start : firstKey;
    const segmentEnd = end < lastKey ? end : lastKey;
    const startIndex = dayIndexByKey.get(segmentStart);
    const endIndex = dayIndexByKey.get(segmentEnd);
    if (startIndex === undefined || endIndex === undefined || endIndex < startIndex) continue;
    candidates.push({
      event,
      start,
      end,
      segmentStart,
      segmentEnd,
      startIndex,
      endIndex,
      spanDays: endIndex - startIndex + 1,
    });
  }
  candidates.sort(calendarSpanSort);
  const lanes = [];
  const segments = [];
  let overflow = 0;
  for (const segment of candidates) {
    let lane = lanes.findIndex((laneEnd) => laneEnd < segment.startIndex);
    if (lane < 0) lane = lanes.length;
    if (lane >= limit) {
      overflow += 1;
      continue;
    }
    lanes[lane] = segment.endIndex;
    segments.push({ ...segment, lane });
  }
  return { segments, overflow };
}

function renderCalendarEvents(events, { compact = false, limit = Infinity, emptyHtml = "", calendarThemes } = {}) {
  if (!events.length) return emptyHtml;
  let html = "";
  const count = Math.min(events.length, limit);
  for (let index = 0; index < count; index += 1) {
    html += renderCalendarSpanEvent(events[index], { compact, calendarThemes });
  }
  return html;
}

function calendarSpanSort(a, b) {
  if (a.startIndex !== b.startIndex) return a.startIndex - b.startIndex;
  const sourceOrder = { project: 0, google: 1, task: 2, local: 3 };
  const sourceDiff = (sourceOrder[a.event.source] ?? 9) - (sourceOrder[b.event.source] ?? 9);
  if (sourceDiff) return sourceDiff;
  if (a.spanDays !== b.spanDays) return b.spanDays - a.spanDays;
  return (a.event.title || "").localeCompare(b.event.title || "");
}

function renderCalendarSpanEvent(segment, { calendarThemes } = {}) {
  const { event } = segment;
  const attrs = event.selectType && event.selectId ? `data-select-type="${event.selectType}" data-select-id="${event.selectId}"` : "";
  const link = event.htmlLink ? `<a class="calendar-span-open" href="${esc(event.htmlLink)}" target="_blank" rel="noreferrer" aria-label="Google Calendar에서 열기">↗</a>` : "";
  const startClass = segment.start === segment.segmentStart ? "is-span-start" : "";
  const endClass = segment.end === segment.segmentEnd ? "is-span-end" : "";
  const edgeClass = segment.startIndex >= 5 ? "is-near-end" : "";
  const eventKey = `${event.source || "local"}:${event.id || event.title || "event"}:${segment.segmentStart}:${segment.startIndex}`;
  const meta = calendarAgendaMetaLabel(event);
  const time = calendarEventTimeLabel(event) || "종일";
  const dates = segment.start === segment.end
    ? compactDateLabel(segment.start)
    : `${compactDateLabel(segment.start)} – ${compactDateLabel(segment.end)}`;
  return `
    <article class="calendar-span-event ${calendarEventSourceClass(event)} ${startClass} ${endClass} ${edgeClass}" ${attrs} style="${calendarColorDeclarations(event, calendarThemes)} grid-column: ${segment.startIndex + 1} / span ${segment.spanDays}; grid-row: ${segment.lane + 1};" data-calendar-event-key="${esc(eventKey)}">
      <button class="calendar-span-toggle" type="button" data-calendar-event-toggle="${esc(eventKey)}" aria-expanded="false" aria-label="${esc(`${event.title || "(제목 없음)"}, ${meta}, ${time}`)}">
        <span class="calendar-span-time">${esc(time)}</span>
        <span class="calendar-span-copy">
          <strong>${esc(event.title || "(제목 없음)")}</strong>
          <span class="calendar-span-detail">${esc(`${dates} · ${meta}`)}</span>
        </span>
      </button>
      ${link}
    </article>
  `;
}

function toggleCalendarSpanEvent(eventElement) {
  const expand = !eventElement.classList.contains("is-expanded");
  closeCalendarSpanEvents();
  if (!expand) return;
  const bounds = eventElement.getBoundingClientRect();
  const computed = window.getComputedStyle(eventElement);
  const horizontalMargin = (Number.parseFloat(computed.marginLeft) || 0) + (Number.parseFloat(computed.marginRight) || 0);
  const calendarViewport = eventElement.closest(".calendar-combined-panel, .calendar-week-panel, .project-calendar-scroll");
  const viewportWidth = calendarViewport?.clientWidth || window.innerWidth - 40;
  const maximumWidth = Math.max(0, Math.min(window.innerWidth - 40, viewportWidth) - horizontalMargin);
  const expandedWidth = Math.min(Math.max(bounds.width, 300), maximumWidth);
  const viewportBounds = calendarViewport?.getBoundingClientRect();
  const rightAnchored = eventElement.classList.contains("is-near-end");
  let expandedLeft = rightAnchored ? bounds.right - expandedWidth : bounds.left;
  let horizontalShift = 0;
  if (viewportBounds) {
    const leftEdge = viewportBounds.left + horizontalMargin / 2;
    const rightEdge = viewportBounds.right - horizontalMargin / 2;
    if (expandedLeft + expandedWidth > rightEdge) horizontalShift = rightEdge - expandedLeft - expandedWidth;
    if (expandedLeft + horizontalShift < leftEdge) horizontalShift += leftEdge - expandedLeft - horizontalShift;
  }
  const clone = eventElement.cloneNode(true);
  clone.classList.add("is-expanded", "is-measuring");
  clone.style.position = "fixed";
  clone.style.left = "-10000px";
  clone.style.top = "0";
  clone.style.width = `${expandedWidth}px`;
  clone.style.height = "auto";
  clone.style.overflow = "visible";
  clone.style.margin = "0";
  clone.style.visibility = "hidden";
  clone.style.pointerEvents = "none";
  clone.style.transition = "none";
  document.body.appendChild(clone);
  const expandedHeight = Math.max(58, Math.ceil(clone.scrollHeight));
  clone.remove();
  eventElement.style.setProperty("--calendar-span-expanded-width", `${expandedWidth}px`);
  eventElement.style.setProperty("--calendar-span-expanded-height", `${expandedHeight}px`);
  eventElement.style.setProperty("--calendar-span-shift-x", `${horizontalShift}px`);
  eventElement.classList.add("is-expanded");
  eventElement.querySelector("[data-calendar-event-toggle]")?.setAttribute("aria-expanded", "true");
}

function closeCalendarSpanEvents() {
  document.querySelectorAll(".calendar-span-event.is-expanded").forEach((entry) => {
    entry.classList.remove("is-expanded");
    entry.querySelector("[data-calendar-event-toggle]")?.setAttribute("aria-expanded", "false");
  });
}

function calendarEventStartKey(event) {
  if (event.startDate) return event.startDate;
  if (!event.start) return "";
  return dateKey(new Date(event.start));
}

function calendarEventEndKey(event, fallback = "") {
  const rawEnd = event.endDate || (event.end ? dateKey(new Date(event.end)) : fallback);
  if (!fallback || !rawEnd) return rawEnd || fallback;
  return rawEnd < fallback ? fallback : rawEnd;
}

function getLocalCalendarEvents() {
  const events = [];
  if (calendarSourceVisible("tasks")) events.push(...getTaskCalendarEvents());
  if (calendarSourceVisible("projects")) events.push(...getVisibleProjectCalendarEvents());
  return events;
}


function getTaskCalendarEvents() {
  const events = [];
  for (const task of state.tasks) {
    if (!task.dueDate || task.status === "done" || task.status === "canceled") continue;
    events.push({
      id: task.id,
      source: "task",
      title: task.title,
      start: `${task.dueDate}T00:00`,
      end: `${task.dueDate}T23:59`,
      startDate: task.dueDate,
      endDate: task.dueDate,
      allDay: true,
      selectType: "tasks",
      selectId: task.id,
    });
  }
  return events;
}

function getProjectCalendarEvents({ visibleOnly = false } = {}) {
  const events = [];
  for (const project of state.projects) {
    if (!(project.startDate || project.endDate) || project.status === "paused") continue;
    if (visibleOnly && !projectCalendarVisible(project.id)) continue;
    const startDate = project.startDate || project.endDate;
    const rawEndDate = project.endDate || project.startDate;
    const endDate = rawEndDate < startDate ? startDate : rawEndDate;
    events.push({
      id: project.id,
      source: "project",
      title: project.name,
      start: `${startDate}T00:00`,
      end: `${endDate}T23:59`,
      startDate,
      endDate,
      allDay: true,
      selectType: "projects",
      selectId: project.id,
    });
  }
  return events;
}

function getVisibleProjectCalendarEvents() {
  return getProjectCalendarEvents({ visibleOnly: true });
}

function getGoogleCalendarEvents({ visibleOnly = false } = {}) {
  const events = [];
  for (const event of state.googleEvents || []) {
    if (event.status === "cancelled") continue;
    if (visibleOnly && !googleCalendarVisible(event.calendarId || "primary")) continue;
    events.push(event);
  }
  return events;
}

function getVisibleGoogleCalendarEvents() {
  return getGoogleCalendarEvents({ visibleOnly: true });
}

function getCombinedCalendarEvents() {
  return [...getLocalCalendarEvents(), ...getVisibleGoogleCalendarEvents()];
}


function calendarEventSourceClass(event) {
  if (event.source === "google") return "is-google";
  if (event.source === "project") return "is-project";
  if (event.source === "task") return "is-task";
  return "is-local";
}

function byCalendarEventTime(a, b) {
  if (a.allDay !== b.allDay) return a.allDay ? -1 : 1;
  return (a.start || a.startDate || "").localeCompare(b.start || b.startDate || "");
}

function calendarEventTimeLabel(event) {
  if (event.allDay) return "종일";
  if (!event.start) return "";
  return formatTime(event.start);
}

function googleCalendarStatusLabel() {
  const calendars = getGoogleCalendarOptions();
  if (state.settings.lastGoogleFetchAt) return `Updated ${formatDateTime(state.settings.lastGoogleFetchAt)}`;
  return calendars.length ? `${calendars.length} Google calendars` : "Local calendar";
}

function combinedCalendarRange(monthDate = selectedCalendarMonthDate()) {
  const days = calendarMonthGridDays(monthDate);
  return {
    start: dateKey(days[0]),
    endExclusive: dateKey(addDays(days[days.length - 1], 1)),
  };
}

function selectedCalendarMonthDate() {
  return parseMonthKey(ui.calendarMonth || monthKey(new Date()));
}

function selectedProjectCalendarDate() {
  return parseDateOnly(ui.projectCalendarAnchor || dateKey(new Date()));
}

function setProjectCalendarMode(mode) {
  const nextMode = mode === "month" ? "month" : "week";
  if (ui.projectCalendarMode === nextMode) return;
  const previousHeight = measureProjectCalendarBodyHeight();
  ui.projectCalendarMode = nextMode;
  renderView({ soft: true });
  animateProjectCalendarBodyResize(previousHeight);
}

function changeProjectCalendarAnchor(direction) {
  const mode = ui.projectCalendarMode === "month" ? "month" : "week";
  const current = selectedProjectCalendarDate();
  const previousHeight = measureProjectCalendarBodyHeight();
  if (direction === "today") {
    ui.projectCalendarAnchor = dateKey(new Date());
  } else if (direction === "prev") {
    ui.projectCalendarAnchor = dateKey(mode === "month" ? addMonths(current, -1) : addDays(current, -7));
  } else if (direction === "next") {
    ui.projectCalendarAnchor = dateKey(mode === "month" ? addMonths(current, 1) : addDays(current, 7));
  }
  renderView({ soft: true });
  animateProjectCalendarBodyResize(previousHeight);
}

function projectWeekRangeLabel(anchor) {
  const start = startOfWeek(anchor);
  const end = addDays(start, 6);
  return `${compactDateLabel(dateKey(start))} - ${compactDateLabel(dateKey(end))}`;
}

function measureProjectCalendarBodyHeight() {
  const body = document.querySelector(".project-calendar-body");
  return body ? body.getBoundingClientRect().height : null;
}

function animateProjectCalendarBodyResize(previousHeight) {
  if (previousHeight === null || previousHeight === undefined || ui.view !== "projects") return;
  window.clearTimeout(projectCalendarResizeTimer);
  const body = document.querySelector(".project-calendar-body");
  if (!body) return;
  const nextHeight = body.getBoundingClientRect().height;
  if (Math.abs(nextHeight - previousHeight) < 1) return;
  body.classList.remove("is-resizing");
  body.style.transition = "none";
  body.style.overflow = "hidden";
  body.style.height = `${previousHeight}px`;
  body.getBoundingClientRect();
  body.style.transition = "";
  body.classList.add("is-resizing");
  requestAnimationFrame(() => {
    let completed = false;
    const finish = (event) => {
      if (event && (event.target !== body || event.propertyName !== "height")) return;
      if (completed) return;
      completed = true;
      window.clearTimeout(projectCalendarResizeTimer);
      body.removeEventListener("transitionend", finish);
      body.classList.remove("is-resizing");
      body.style.height = "";
      body.style.overflow = "";
    };
    body.addEventListener("transitionend", finish);
    body.style.height = `${nextHeight}px`;
    projectCalendarResizeTimer = window.setTimeout(finish, 720);
  });
}

function changeCalendarMonth(direction) {
  const current = selectedCalendarMonthDate();
  if (direction === "today") {
    ui.calendarMonth = monthKey(new Date());
  } else if (direction === "prev") {
    ui.calendarMonth = monthKey(addMonths(current, -1));
  } else if (direction === "next") {
    ui.calendarMonth = monthKey(addMonths(current, 1));
  }
  renderView({ soft: true });
  if (googleBackendStatus.connected) fetchGoogleCalendarEvents({ silent: true });
}

function calendarSourceVisible(source) {
  const sources = normalizeCalendarSources(state.settings.calendarSources);
  return sources[source] !== false;
}

function setCalendarSourceVisible(source, visible) {
  state.settings.calendarSources = normalizeCalendarSources(state.settings.calendarSources);
  state.settings.calendarSources[source] = Boolean(visible);
  saveState();
  renderView({ soft: true });
}

function projectCalendarVisible(projectId) {
  if (!projectId) return true;
  return state.settings.visibleProjectCalendars?.[projectId] !== false;
}

function setProjectCalendarVisible(projectId, visible) {
  if (!projectId) return;
  state.settings.visibleProjectCalendars = {
    ...(state.settings.visibleProjectCalendars || {}),
    [projectId]: Boolean(visible),
  };
  saveState();
  renderView({ soft: true });
}

function googleCalendarVisible(calendarId) {
  if (!calendarId) return true;
  const visible = state.settings.visibleGoogleCalendars || {};
  return visible[calendarId] !== false;
}

function setGoogleCalendarVisible(calendarId, visible) {
  if (!calendarId) return;
  state.settings.visibleGoogleCalendars = {
    ...(state.settings.visibleGoogleCalendars || {}),
    [calendarId]: Boolean(visible),
  };
  saveState();
  renderView({ soft: true });
}

function getGoogleCalendarOptions() {
  const calendarsById = new Map();
  for (const calendar of state.googleCalendars || []) {
    const normalized = normalizeGoogleCalendarEntry(calendar);
    if (normalized?.id) calendarsById.set(normalized.id, normalized);
  }
  for (const event of state.googleEvents || []) {
    const calendarId = event.calendarId || "primary";
    if (!calendarsById.has(calendarId)) {
      calendarsById.set(calendarId, fallbackGoogleCalendar(calendarId, event.calendarSummary || calendarId));
    }
  }
  const calendars = [];
  for (const calendar of calendarsById.values()) {
    calendars.push(calendar);
  }
  return calendars.sort((a, b) => {
    if (Boolean(a.primary) !== Boolean(b.primary)) return a.primary ? -1 : 1;
    return (a.summary || a.id).localeCompare(b.summary || b.id);
  });
}

function calendarCountLabel(count) {
  return `${count} ${count === 1 ? "event" : "events"}`;
}

function sanitizeCalendarHexColor(value, fallback = "") {
  const color = String(value || "").trim().toLowerCase();
  if (/^#[0-9a-f]{6}$/i.test(color)) return color;
  if (/^#[0-9a-f]{3}$/i.test(color)) {
    return `#${color[1]}${color[1]}${color[2]}${color[2]}${color[3]}${color[3]}`;
  }
  return fallback;
}

function stableCalendarColorIndex(value) {
  const text = String(value || "primary");
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function nextGoogleCalendarColor(identity, usedColors) {
  const startIndex = stableCalendarColorIndex(identity) % GOOGLE_CALENDAR_COLOR_PALETTE.length;
  for (let offset = 0; offset < GOOGLE_CALENDAR_COLOR_PALETTE.length; offset += 1) {
    const color = GOOGLE_CALENDAR_COLOR_PALETTE[(startIndex + offset) % GOOGLE_CALENDAR_COLOR_PALETTE.length];
    if (!usedColors.has(color)) return color;
  }
  for (let attempt = 0; attempt < MAX_CALENDAR_COLOR_ASSIGNMENTS; attempt += 1) {
    const color = derivedGoogleCalendarColor(identity, attempt);
    if (!usedColors.has(color)) return color;
  }
  return derivedGoogleCalendarColor(identity, MAX_CALENDAR_COLOR_ASSIGNMENTS);
}

function derivedGoogleCalendarColor(identity, attempt) {
  const hash = stableCalendarColorIndex(`${identity}:${attempt}`);
  const hue = hash % 360;
  const saturation = 58 + ((hash >>> 9) % 3) * 8;
  const lightness = 36 + ((hash >>> 17) % 3) * 6;
  return hslCalendarColor(hue, saturation, lightness);
}

function hslCalendarColor(hue, saturation, lightness) {
  const normalizedSaturation = saturation / 100;
  const normalizedLightness = lightness / 100;
  const chroma = (1 - Math.abs(2 * normalizedLightness - 1)) * normalizedSaturation;
  const sector = (((hue % 360) + 360) % 360) / 60;
  const intermediate = chroma * (1 - Math.abs((sector % 2) - 1));
  let red = 0;
  let green = 0;
  let blue = 0;
  if (sector < 1) [red, green] = [chroma, intermediate];
  else if (sector < 2) [red, green] = [intermediate, chroma];
  else if (sector < 3) [green, blue] = [chroma, intermediate];
  else if (sector < 4) [green, blue] = [intermediate, chroma];
  else if (sector < 5) [red, blue] = [intermediate, chroma];
  else [red, blue] = [chroma, intermediate];
  const match = normalizedLightness - chroma / 2;
  return `#${calendarHexChannel(red + match)}${calendarHexChannel(green + match)}${calendarHexChannel(blue + match)}`;
}

function calendarHexChannel(value) {
  return Math.round(Math.max(0, Math.min(1, value)) * 255).toString(16).padStart(2, "0");
}

function calendarContrastColor(backgroundColor, foregroundColor = "") {
  const preferred = sanitizeCalendarHexColor(foregroundColor);
  if (preferred) return preferred;
  const safeBackground = sanitizeCalendarHexColor(backgroundColor, LOCAL_CALENDAR_THEMES.local.color);
  const hex = safeBackground.slice(1);
  const red = Number.parseInt(hex.slice(0, 2), 16);
  const green = Number.parseInt(hex.slice(2, 4), 16);
  const blue = Number.parseInt(hex.slice(4, 6), 16);
  return (red * 299 + green * 587 + blue * 114) / 1000 > 158 ? "#17202f" : "#ffffff";
}

function normalizeCalendarColorAssignments(value) {
  const normalized = Object.create(null);
  if (!isPlainObject(value)) return normalized;
  let count = 0;
  for (const calendarId in value) {
    if (!Object.prototype.hasOwnProperty.call(value, calendarId) || count >= MAX_CALENDAR_COLOR_ASSIGNMENTS) continue;
    if (!calendarId || calendarId === "__proto__" || calendarId === "prototype" || calendarId === "constructor" || calendarId.length > 512) continue;
    const color = sanitizeCalendarHexColor(value[calendarId]);
    if (!color) continue;
    normalized[calendarId] = color;
    count += 1;
  }
  return normalized;
}

function allocateGoogleCalendarThemes(calendars, savedAssignments = {}) {
  const themes = new Map();
  const usedColors = new Set([
    LOCAL_CALENDAR_THEMES.tasks.color,
    LOCAL_CALENDAR_THEMES.projects.color,
  ]);
  const assignments = Object.create(null);
  const normalizedAssignments = normalizeCalendarColorAssignments(savedAssignments);
  const assignmentIds = Object.keys(normalizedAssignments).sort();
  for (const calendarId of assignmentIds) {
    const color = normalizedAssignments[calendarId];
    if (usedColors.has(color)) continue;
    assignments[calendarId] = color;
    usedColors.add(color);
  }
  const sortedCalendars = calendars.slice().sort((a, b) => String(a.id || "primary").localeCompare(String(b.id || "primary")));
  const reservedColors = new Map();
  for (const calendar of sortedCalendars) {
    const calendarId = String(calendar.id || "primary");
    if (assignments[calendarId]) continue;
    const preferred = sanitizeCalendarHexColor(calendar.backgroundColor);
    if (preferred && !usedColors.has(preferred) && !reservedColors.has(preferred)) {
      reservedColors.set(preferred, calendarId);
    }
  }
  for (const color of reservedColors.keys()) usedColors.add(color);
  for (const calendar of sortedCalendars) {
    const calendarId = String(calendar.id || "primary");
    const identity = `google:${calendarId}`;
    const preferred = sanitizeCalendarHexColor(calendar.backgroundColor);
    const existing = assignments[calendarId];
    const color = existing || (preferred && reservedColors.get(preferred) === calendarId
      ? preferred
      : nextGoogleCalendarColor(identity, usedColors));
    assignments[calendarId] = color;
    usedColors.add(color);
    themes.set(calendarId, {
      color,
      contrast: calendarContrastColor(color, color === preferred ? calendar.foregroundColor : ""),
    });
  }
  return { assignments, themes };
}

function googleCalendarThemeAssignments(calendars = getGoogleCalendarOptions()) {
  const allocation = allocateGoogleCalendarThemes(calendars, state?.settings?.calendarColorAssignments);
  if (state?.settings) state.settings.calendarColorAssignments = allocation.assignments;
  return allocation.themes;
}

function calendarThemeFor(calendar, calendarThemes) {
  const source = String(calendar?.source || "").toLowerCase();
  if (source === "task" || source === "tasks") return LOCAL_CALENDAR_THEMES.tasks;
  if (source === "project" || source === "projects") return LOCAL_CALENDAR_THEMES.projects;
  if (source === "google" || calendar?.calendarId || (!source && calendar?.id)) {
    const calendarId = source === "google"
      ? String(calendar?.calendarId || "primary")
      : String(calendar?.calendarId || calendar?.id || "primary");
    const assigned = calendarThemes?.get(calendarId);
    if (assigned) return assigned;
    const preferred = sanitizeCalendarHexColor(calendar?.backgroundColor);
    const color = preferred || nextGoogleCalendarColor(`google:${calendarId}`, new Set([
      LOCAL_CALENDAR_THEMES.tasks.color,
      LOCAL_CALENDAR_THEMES.projects.color,
    ]));
    return {
      color,
      contrast: calendarContrastColor(color, color === preferred ? calendar?.foregroundColor : ""),
    };
  }
  return LOCAL_CALENDAR_THEMES.local;
}

function calendarColorDeclarations(calendar, calendarThemes) {
  const theme = calendarThemeFor(calendar, calendarThemes);
  const color = sanitizeCalendarHexColor(theme.color, LOCAL_CALENDAR_THEMES.local.color);
  const contrast = sanitizeCalendarHexColor(theme.contrast, calendarContrastColor(color));
  return `--calendar-color: ${color}; --calendar-contrast: ${contrast};`;
}









function syncElementAttributes(current, next) {
  for (const attribute of [...current.attributes]) {
    if (!next.hasAttribute(attribute.name)) current.removeAttribute(attribute.name);
  }
  for (const attribute of [...next.attributes]) {
    if (current.getAttribute(attribute.name) !== attribute.value) current.setAttribute(attribute.name, attribute.value);
  }
}










































function renderDetailFields(type, item) {
  if (type === "tasks") {
    return renderTaskPropertyFields(item);
  }
  if (type === "projects") {
    return `
      <div class="field-grid">
        ${selectField("상태", "status", item.status, STATUSES.project)}
        ${relationField("박스", "boxId", item.boxId, state.boxes, "name")}
        ${dateField("시작일", "startDate", item.startDate)}
        ${dateField("종료일", "endDate", item.endDate)}
      </div>
    `;
  }
  if (type === "boxes") {
    return `
      <div class="field-grid">
        ${selectField("구분", "visibility", item.visibility, { pinned: "고정", normal: "일반", archived: "아카이브" })}
        ${selectField("색상", "color", item.color, { blue: "Blue", teal: "Teal", amber: "Amber", violet: "Violet", rose: "Rose" })}
      </div>
    `;
  }
  if (type === "habits") {
    return `
      <div class="field-grid">
        ${selectField("상태", "status", item.status, { active: "활성", paused: "중단", archived: "보관" })}
        ${selectField("주기", "cadence", item.cadence, { daily: "매일", weekdays: "평일", weekly: "주간" })}
        ${textField("목표", "target", item.target || "")}
        ${relationField("박스", "boxId", item.boxId, state.boxes, "name")}
        ${relationField("프로젝트", "projectId", item.projectId, state.projects, "name")}
      </div>
    `;
  }
  if (type === "journals") {
    return `
      <div class="field-grid">
        ${dateField("날짜", "date", item.date)}
        ${numberField("만족도", "satisfaction", item.satisfaction || 0)}
      </div>
    `;
  }
  return "";
}

function renderTaskPropertyFields(task, options = {}) {
  const className = options.className ? ` ${options.className}` : "";
  return `
    <div class="field-grid${className}">
      ${options.includeTitle ? textField("제목", "title", task.title || "") : ""}
      ${dateField("날짜", "dueDate", task.dueDate)}
      ${relationField("박스", "boxId", task.boxId, state.boxes, "name")}
      ${relationField("프로젝트", "projectId", task.projectId, state.projects, "name")}
    </div>
  `;
}


function renderInlineBlockEditor(type, ownerId, blocksList) {
  const owner = itemById(type, ownerId);
  const safeBlocks = ensureEditableBlocks(owner || { blocks: blocksList });
  return `
    <div class="task-inline-notes">
      <div class="task-inline-section-head">
        <strong>추가 메모</strong>
        <span>Block editor</span>
      </div>
      <div class="block-editor" data-owner-type="${type}" data-owner-id="${ownerId}">
        ${renderBlocks(safeBlocks, type, ownerId)}
      </div>
    </div>
  `;
}

function renderBlocks(blocksList, ownerType, ownerId) {
  let html = "";
  let openListType = "";
  let openListIndent = -1;
  const toggleStack = [];
  const numberedCounters = [];
  for (let index = 0; index < blocksList.length; index += 1) {
    const block = blocksList[index];
    const indent = blockIndent(block);
    const listType = block.type === "bullet" || block.type === "numbered" ? block.type : "";
    if (listType !== openListType || (listType && indent !== openListIndent)) {
      if (openListType) html += "</div>";
      if (listType) {
        const label = listType === "numbered" ? "번호 목록" : "글머리 기호 목록";
        html += `<div class="block-list" role="list" aria-label="${label}" data-list-indent="${indent}">`;
      }
      openListType = listType;
      openListIndent = listType ? indent : -1;
    }
    while (toggleStack.length && indent <= toggleStack[toggleStack.length - 1].indent) {
      toggleStack.pop();
    }
    const listMarker = numberedListMarkerForBlock(block, indent, numberedCounters);
    html += renderBlock(block, ownerType, ownerId, {
      hidden: stackHasCollapsedToggle(toggleStack),
      indent,
      listMarker,
      listItem: Boolean(listType),
      hasToggleChildren: blockHasToggleChildren(blocksList, index),
    });
    if (block.type === "toggle") {
      toggleStack.push({ indent, collapsed: block.collapsed === true });
    }
  }
  if (openListType) html += "</div>";
  return html;
}

function renderBlockDragHandle(blockId) {
  return `
    <button class="block-drag-handle" type="button" data-block-drag="${blockId}" aria-label="블록 이동">
      <span class="block-drag-grip" aria-hidden="true">
        <span class="block-drag-dot"></span>
        <span class="block-drag-dot"></span>
        <span class="block-drag-dot"></span>
        <span class="block-drag-dot"></span>
        <span class="block-drag-dot"></span>
        <span class="block-drag-dot"></span>
      </span>
    </button>
  `;
}

function numberedListMarkerForBlock(block, indent, counters) {
  counters.length = Math.min(counters.length, indent + 1);
  if (block.type !== "numbered") {
    counters[indent] = 0;
    return "";
  }
  const nextNumber = numberedBlockStart(block) || (counters[indent] || 0) + 1;
  counters[indent] = nextNumber;
  return `${nextNumber}.`;
}

function numberedBlockStart(block) {
  const value = Number.parseInt(block?.listStart, 10);
  return Number.isInteger(value) && value > 0 && value <= 999_999 ? value : 0;
}

function blockAnchorId(blockId) {
  return `block-${encodeURIComponent(String(blockId || ""))}`;
}

function renderBlock(block, ownerType = "", ownerId = "", meta = {}) {
  const isSelected =
    ui.blockSelection.ownerType === ownerType &&
    ui.blockSelection.ownerId === ownerId &&
    ui.blockSelection.ids.includes(block.id);
  const indent = normalizedBlockIndent(meta.indent ?? block.indent);
  const blockColor = ownerType === "resources" ? "" : normalizeBlockColorValue(block.color);
  const blockBackgroundColor = ownerType === "resources" ? "" : normalizeBlockColorValue(block.backgroundColor);
  const hiddenAttr = meta.hidden ? ` data-hidden-by-toggle="true" hidden aria-hidden="true"` : ` data-hidden-by-toggle="false"`;
  const blockTools = ownerType === "resources"
    ? ""
    : `${renderBlockDragHandle(block.id)}<button class="block-tool" type="button" data-block-add="${esc(block.id)}" aria-label="블록 추가">+</button>`;
  const listMarker = meta.listItem
    ? `<span class="block-list-marker" aria-hidden="true">${esc(block.type === "numbered" ? meta.listMarker : "•")}</span>`
    : "";
  const colorAttr = blockColor ? ` data-block-color="${blockColor}"` : "";
  const backgroundColorAttr = blockBackgroundColor ? ` data-block-background="${blockBackgroundColor}"` : "";
  const listSemanticAttr = meta.listItem ? ` role="listitem" aria-level="${indent + 1}"` : "";
  const blockStyle = blockStyleForBlock(indent, blockColor, blockBackgroundColor);
  if (block.type === "divider") {
    return `
      <div class="block ${isSelected ? "is-selected" : ""}" id="${esc(blockAnchorId(block.id))}" data-block-id="${block.id}" data-type="divider" data-checked="false" data-indent="${indent}"${colorAttr}${backgroundColorAttr}${hiddenAttr}${blockStyle}>
        ${blockTools}
        <div class="block-divider" role="separator"></div>
      </div>
    `;
  }
  if (isUrlPreviewBlockType(block.type)) {
    return renderUrlPreviewBlock(block, {
      isSelected,
      indent,
      colorAttr,
      backgroundColorAttr,
      hiddenAttr,
      blockStyle,
      blockTools,
    });
  }
  if (block.type === IMAGE_BLOCK_TYPE) {
    return renderResourceImageBlock(block, {
      isSelected,
      indent,
      hiddenAttr,
      blockStyle,
      blockTools,
    });
  }
  const toggleCollapsed = block.type === "toggle" && block.collapsed === true && !meta.routeTemporarilyExpanded;
  return `
    <div class="block ${isSelected ? "is-selected" : ""}" id="${esc(blockAnchorId(block.id))}" data-block-id="${block.id}" data-type="${block.type}" data-checked="${block.checked ? "true" : "false"}" data-indent="${indent}"${listSemanticAttr}${colorAttr}${backgroundColorAttr} data-toggle-collapsed="${toggleCollapsed ? "true" : "false"}" data-toggle-has-children="${meta.hasToggleChildren ? "true" : "false"}"${hiddenAttr}${blockStyle}>
      ${blockTools}
      ${block.type === "todo" ? `<button class="block-check ${block.checked ? "is-done" : ""}" type="button" data-block-check="${block.id}" aria-label="체크" aria-pressed="${block.checked ? "true" : "false"}"></button>` : ""}
      ${block.type === "toggle" ? `<button class="block-toggle" type="button" data-block-toggle="${block.id}" aria-label="${toggleCollapsed ? "토글 펼치기" : "토글 접기"}" aria-expanded="${toggleCollapsed ? "false" : "true"}">▸</button>` : ""}
      ${listMarker}
      ${renderEditableBlockContent(block, "", ownerType, ownerId)}
    </div>
  `;
}

function isUrlPreviewBlockType(type = "") {
  return Object.prototype.hasOwnProperty.call(URL_BLOCK_TYPES, type);
}

function isSupportedEditorBlockType(type = "") {
  return Boolean(BLOCK_TYPES[type]) || isUrlPreviewBlockType(type) || type === IMAGE_BLOCK_TYPE;
}

function renderResourceImageBlock(block, meta = {}) {
  const safeUrl = normalizeResourceImageUrl(block.url);
  const alt = String(block.alt || block.text || "").trim();
  return `
    <div class="block resource-image-block ${meta.isSelected ? "is-selected" : ""}" id="${esc(blockAnchorId(block.id))}" data-block-id="${esc(block.id)}" data-type="image" data-checked="false" data-indent="${meta.indent}"${meta.hiddenAttr || ""}${meta.blockStyle || ""}>
      ${meta.blockTools || ""}
      <figure class="resource-image-figure block-content" data-block-content="${esc(block.id)}" data-resource-image-select tabindex="0" role="group" aria-label="이미지${alt ? `: ${esc(alt)}` : ""}">
        ${safeUrl ? `<img src="${esc(safeUrl)}" alt="${esc(alt)}" loading="lazy" decoding="async" referrerpolicy="no-referrer">` : `<span class="resource-image-error" role="status">이미지를 불러올 수 없습니다.</span>`}
        ${alt ? `<figcaption>${esc(alt)}</figcaption>` : ""}
      </figure>
    </div>
  `;
}

function renderUrlPreviewBlock(block, meta = {}) {
  const safeUrl = normalizeStandaloneHttpsUrl(block.url || block.text || "");
  const preview = urlPreviewParts(safeUrl);
  const label = block.type === "embed" ? "정적 임베드 미리보기" : "북마크 미리보기";
  const description = block.type === "embed"
    ? "외부 콘텐츠는 자동 실행하지 않습니다. 원본은 새 탭에서만 열립니다."
    : "원격 메타데이터를 가져오지 않는 안전한 북마크입니다.";
  return `
    <div class="block ${meta.isSelected ? "is-selected" : ""}" id="${esc(blockAnchorId(block.id))}" data-block-id="${block.id}" data-type="${block.type}" data-checked="false" data-indent="${meta.indent}"${meta.colorAttr || ""}${meta.backgroundColorAttr || ""}${meta.hiddenAttr || ""}${meta.blockStyle || ""}>
      ${meta.blockTools || ""}
      <div
        class="block-content block-url-preview-content"
        data-block-content="${block.id}"
        data-url-block-preview="${block.type}"
        tabindex="0"
        role="group"
        aria-label="${label}: ${esc(preview.host || safeUrl)}"
      >
        <span class="block-url-preview-icon" aria-hidden="true">${block.type === "embed" ? "◇" : "↗"}</span>
        <span class="block-url-preview-copy">
          <strong>${esc(preview.host || "안전하지 않은 URL")}</strong>
          <span title="${esc(safeUrl)}">${esc(preview.display || "지원하지 않는 URL")}</span>
          <small>${description}</small>
        </span>
        ${safeUrl ? `<a class="block-url-preview-open" href="${esc(safeUrl)}" target="_blank" rel="noopener noreferrer nofollow" aria-label="${esc(label)} 원본을 새 탭에서 열기">열기</a>` : ""}
      </div>
    </div>
  `;
}

function urlPreviewParts(value = "") {
  const safeUrl = normalizeStandaloneHttpsUrl(value);
  if (!safeUrl) return { host: "", display: "" };
  try {
    const parsed = new URL(safeUrl);
    const suffix = `${parsed.pathname === "/" ? "" : parsed.pathname}${parsed.search}${parsed.hash}`;
    const display = `${parsed.hostname}${suffix}`;
    return {
      host: parsed.hostname,
      display: display.length > 140 ? `${display.slice(0, 137)}…` : display,
    };
  } catch (_) {
    return { host: "", display: "" };
  }
}

function renderEditableBlockContent(block, listMarkerAttr = "", ownerType = "", ownerId = "") {
  const editable = `<span class="block-content ${block.text ? "" : "is-empty"}" contenteditable="true" spellcheck="true" role="textbox" aria-multiline="true" aria-label="${esc(blockEditorAriaLabel(block))}" data-block-content="${block.id}"${listMarkerAttr} data-placeholder="${blockPlaceholder(block)}">${renderInlineText(block)}</span>`;
  if (block.type === "heading1") return `<h1 class="block-semantic-wrap">${editable}</h1>`;
  if (block.type === "heading2") return `<h2 class="block-semantic-wrap">${editable}</h2>`;
  if (block.type === "heading3") return `<h3 class="block-semantic-wrap">${editable}</h3>`;
  if (block.type === "heading4") return `<h4 class="block-semantic-wrap">${editable}</h4>`;
  if (block.type === "heading5") return `<h5 class="block-semantic-wrap">${editable}</h5>`;
  if (block.type === "heading6") return `<h6 class="block-semantic-wrap">${editable}</h6>`;
  if (block.type === "quote") return `<blockquote class="block-semantic-wrap">${editable}</blockquote>`;
  if (block.type === "code") {
    const language = normalizeCodeLanguage(block.language);
    const lineCount = codeBlockLineCount(block.text);
    return `
      <section class="code-space" data-code-space data-code-block-id="${esc(block.id)}">
        <header class="code-space-header">
          <span class="code-space-window-controls" aria-hidden="true"><i></i><i></i><i></i></span>
          <span class="code-space-title">Code Space</span>
          <div class="code-space-actions">
            <details class="code-language-picker">
              <summary class="code-language-trigger" role="button" aria-haspopup="menu" aria-expanded="false" data-code-language-trigger="${esc(block.id)}" aria-label="코드 언어 선택, 현재 ${esc(codeLanguageLabel(language))}"><span>언어</span><strong>${esc(codeLanguageLabel(language))}</strong></summary>
              <div class="code-language-menu" role="menu" aria-label="코드 언어" popover="manual" hidden>
                ${renderCodeLanguageMenuOptions(language, ownerType, ownerId, block.id)}
              </div>
            </details>
            <button class="code-space-copy" type="button" data-code-copy="${esc(block.id)}" data-owner-type="${esc(ownerType)}" data-owner-id="${esc(ownerId)}" aria-label="코드 복사">복사</button>
          </div>
        </header>
        <div class="code-space-body">
          <span class="code-space-lines" data-code-line-numbers aria-hidden="true">${renderCodeLineNumbers(block.text)}</span>
          <pre class="block-semantic-wrap code-space-editor" aria-label="${esc(language ? `${language} 코드 블록` : "코드 블록")}" data-code-language="${esc(language || "plaintext")}"><code class="code-space-source block-content ${block.text ? "" : "is-empty"}" contenteditable="true" spellcheck="false" role="textbox" aria-multiline="true" aria-label="${esc(language ? `${language} 코드 블록 편집` : "코드 블록 편집")}" data-block-content="${esc(block.id)}"${listMarkerAttr} data-placeholder="코드를 입력하세요">${esc(block.text || "")}</code></pre>
        </div>
        <footer class="code-space-footer"><span data-code-line-summary>${lineCount}줄</span><span>UTF-8</span></footer>
      </section>
    `;
  }
  return editable;
}

function normalizeCodeLanguage(value = "") {
  return String(value || "").trim().split(/\s+/, 1)[0].slice(0, 64);
}

function codeLanguageLabel(value = "") {
  const language = normalizeCodeLanguage(value);
  return CODE_LANGUAGE_OPTIONS.find(([optionValue]) => optionValue === language)?.[1] || language || "일반 텍스트";
}

function renderCodeLanguageMenuOptions(value = "", ownerType = "", ownerId = "", blockId = "") {
  const language = normalizeCodeLanguage(value);
  const options = language && !CODE_LANGUAGE_VALUES.has(language)
    ? [[language, `${language} (사용자 지정)`], ...CODE_LANGUAGE_OPTIONS]
    : CODE_LANGUAGE_OPTIONS;
  return options.map(([optionValue, label]) => `
    <button class="code-language-option ${optionValue === language ? "is-active" : ""}" type="button" role="menuitemradio" aria-checked="${optionValue === language ? "true" : "false"}" data-code-language-value="${esc(optionValue)}" data-code-language-block="${esc(blockId)}" data-owner-type="${esc(ownerType)}" data-owner-id="${esc(ownerId)}">${esc(label)}</button>
  `).join("");
}

function codeBlockLineCount(value = "") {
  return Math.max(1, String(value || "").split("\n").length);
}

function renderCodeLineNumbers(value = "") {
  return Array.from({ length: codeBlockLineCount(value) }, (_, index) => `<i>${index + 1}</i>`).join("");
}

function syncCodeSpaceMetrics(blockContent, value = "") {
  const codeSpace = blockContent?.closest?.("[data-code-space]");
  if (!codeSpace) return;
  const lineCount = codeBlockLineCount(value);
  const lineNumbers = codeSpace.querySelector("[data-code-line-numbers]");
  const summary = codeSpace.querySelector("[data-code-line-summary]");
  if (lineNumbers) lineNumbers.innerHTML = renderCodeLineNumbers(value);
  if (summary) summary.textContent = `${lineCount}줄`;
}

function blockEditorAriaLabel(block) {
  const labels = {
    paragraph: "텍스트 블록 편집",
    heading1: "제목 1 블록 편집",
    heading2: "제목 2 블록 편집",
    heading3: "제목 3 블록 편집",
    heading4: "제목 4 블록 편집",
    heading5: "제목 5 블록 편집",
    heading6: "제목 6 블록 편집",
    bullet: "글머리 기호 블록 편집",
    numbered: "번호 목록 블록 편집",
    todo: "할 일 블록 편집",
    toggle: "토글 블록 편집",
    quote: "인용 블록 편집",
    callout: "콜아웃 블록 편집",
  };
  return labels[block.type] || "블록 편집";
}

function blockStyleForBlock(indent, color = "", backgroundColor = "") {
  const style = [`--block-indent:${indent}`];
  const textColor = color ? BLOCK_COLOR_OPTIONS[color]?.text || "" : "";
  const background = backgroundColor ? BLOCK_COLOR_OPTIONS[backgroundColor]?.background || "" : "";
  if (textColor) style.push(`--block-text-color:${textColor}`);
  if (background) {
    style.push(`--block-background-color:${background}`);
    style.push(`--block-background-hover:${background}`);
  }
  return ` style="${style.join(";")}"`;
}

function ensureEditableBlocks(item, options = {}) {
  if (!item.blocks) item.blocks = [];
  let changed = false;
  for (const block of item.blocks) {
    if (normalizeEditableBlock(block)) changed = true;
  }
  if (!item.blocks.length || item.blocks.every((block) => block.type === "divider")) {
    item.blocks.push({ id: id(), type: "paragraph", text: "", checked: false, indent: 0, collapsed: false });
    changed = true;
  }
  if (changed && options.save !== false) saveState();
  return item.blocks;
}

function normalizeEditableBlock(block) {
  if (!isPlainObject(block)) return false;
  let changed = false;
  if (isUrlPreviewBlockType(block.type)) {
    const safeUrl = normalizeStandaloneHttpsUrl(block.url || block.text || "");
    if (!safeUrl) {
      block.type = "paragraph";
      delete block.url;
      changed = true;
    } else {
      if (block.url !== safeUrl) {
        block.url = safeUrl;
        changed = true;
      }
      if (block.text !== safeUrl) {
        block.text = safeUrl;
        changed = true;
      }
      if (Array.isArray(block.marks) && block.marks.length) {
        block.marks = [];
        changed = true;
      }
    }
  } else if (block.type === IMAGE_BLOCK_TYPE) {
    const safeUrl = normalizeResourceImageUrl(block.url);
    if (!safeUrl) {
      block.type = "paragraph";
      block.text = String(block.alt || block.text || "");
      delete block.url;
      delete block.alt;
      changed = true;
    } else {
      if (block.url !== safeUrl) {
        block.url = safeUrl;
        changed = true;
      }
      const alt = String(block.alt || block.text || "").slice(0, 2_000);
      if (block.alt !== alt) {
        block.alt = alt;
        changed = true;
      }
      if (block.text !== alt) {
        block.text = alt;
        changed = true;
      }
      if (Array.isArray(block.marks) && block.marks.length) {
        block.marks = [];
        changed = true;
      }
    }
  } else if (!BLOCK_TYPES[block.type]) {
    block.type = "paragraph";
    changed = true;
  }
  if (typeof block.text !== "string") {
    block.text = block.text === undefined || block.text === null ? "" : String(block.text);
    changed = true;
  }
  const marks = block.type === "code" ? [] : normalizeInlineMarks(block.text, block.marks);
  if (!inlineMarksEqual(block.marks, marks)) {
    block.marks = marks;
    changed = true;
  }
  const color = normalizeBlockColorValue(block.color);
  if ((block.color || "") !== color) {
    if (color) block.color = color;
    else delete block.color;
    changed = true;
  }
  const backgroundColor = normalizeBlockColorValue(block.backgroundColor);
  if ((block.backgroundColor || "") !== backgroundColor) {
    if (backgroundColor) block.backgroundColor = backgroundColor;
    else delete block.backgroundColor;
    changed = true;
  }
  if (typeof block.checked !== "boolean") {
    block.checked = false;
    changed = true;
  }
  if (block.type === "code") {
    const language = typeof block.language === "string" ? block.language.trim().split(/\s+/, 1)[0].slice(0, 64) : "";
    if (block.language !== language) {
      if (language) block.language = language;
      else delete block.language;
      changed = true;
    }
  } else if (Object.prototype.hasOwnProperty.call(block, "language")) {
    delete block.language;
    changed = true;
  }
  if (block.type === "numbered") {
    const listStart = numberedBlockStart(block);
    if (listStart) {
      if (block.listStart !== listStart) {
        block.listStart = listStart;
        changed = true;
      }
    } else if (Object.prototype.hasOwnProperty.call(block, "listStart")) {
      delete block.listStart;
      changed = true;
    }
  } else if (Object.prototype.hasOwnProperty.call(block, "listStart")) {
    delete block.listStart;
    changed = true;
  }
  const indent = normalizedBlockIndent(block.indent);
  if (block.indent !== indent) {
    block.indent = indent;
    changed = true;
  }
  if (block.type === "toggle") {
    if (typeof block.collapsed !== "boolean") {
      block.collapsed = false;
      changed = true;
    }
  } else if (block.collapsed !== false) {
    block.collapsed = false;
    changed = true;
  }
  return changed;
}

function normalizedBlockIndent(value) {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed)) return 0;
  return Math.max(0, Math.min(MAX_BLOCK_INDENT, parsed));
}

function blockIndent(block) {
  return normalizedBlockIndent(block?.indent);
}

function stackHasCollapsedToggle(stack) {
  for (const entry of stack) {
    if (entry.collapsed) return true;
  }
  return false;
}

function blockHasToggleChildren(blocksList, index) {
  const block = blocksList[index];
  if (!block || block.type !== "toggle") return false;
  const indent = blockIndent(block);
  for (let nextIndex = index + 1; nextIndex < blocksList.length; nextIndex += 1) {
    const nextIndent = blockIndent(blocksList[nextIndex]);
    if (nextIndent <= indent) return false;
    return true;
  }
  return false;
}

function renderInlineText(block) {
  const text = block.text || "";
  if (!text) return "";
  const marks = normalizeInlineMarks(text, block.marks);
  if (!marks.length) return esc(text);
  const points = new Set([0, text.length]);
  for (const mark of marks) {
    points.add(mark.start);
    points.add(mark.end);
  }
  const sorted = [...points].sort((a, b) => a - b);
  let html = "";
  for (let index = 0; index < sorted.length - 1; index += 1) {
    const start = sorted[index];
    const end = sorted[index + 1];
    if (end <= start) continue;
    const active = marks.filter((mark) => mark.start <= start && mark.end >= end);
    html += renderInlineSegment(text.slice(start, end), active);
  }
  return html;
}

function renderInlineSegment(text, activeMarks) {
  let html = esc(text);
  const sortedMarks = [...activeMarks].sort((a, b) => INLINE_MARK_TYPES.indexOf(a.type) - INLINE_MARK_TYPES.indexOf(b.type));
  for (let index = sortedMarks.length - 1; index >= 0; index -= 1) {
    const mark = sortedMarks[index];
    const type = mark.type;
    if (type === "resourceLink") {
      const resourceId = String(mark.resourceId || "").trim();
      if (!resourceId) continue;
      const targetState = resourceCitationTargetState(resourceId);
      const targetLabel = resourceCitationTargetLabel(resourceId, targetState);
      html = `<a class="inline-mark ${INLINE_MARK_CLASS_NAMES.resourceLink}" data-inline-mark="resourceLink" data-resource-citation="${esc(resourceId)}" data-resource-citation-state="${targetState}" href="${esc(resourceCitationHref(resourceId))}" tabindex="0"${targetState === "active" ? "" : ' aria-disabled="true"'} aria-label="${esc(targetLabel)}" title="${esc(targetLabel)}">${html}</a>`;
    } else if (type === "link") {
      const href = normalizeInlineHref(mark.href || "");
      if (!href) continue;
      html = `<a class="inline-mark ${INLINE_MARK_CLASS_NAMES.link}" data-inline-mark="link" href="${esc(href)}" target="_blank" rel="noopener noreferrer" tabindex="0">${html}</a>`;
    } else if (type === "textColor" || type === "backgroundColor") {
      const color = normalizeBlockColorValue(mark.color);
      if (!color) continue;
      html = `<span class="inline-mark ${INLINE_MARK_CLASS_NAMES[type]}" data-inline-mark="${type}" data-inline-color="${color}">${html}</span>`;
    } else if (type === "comment") {
      html = `<span class="inline-mark ${INLINE_MARK_CLASS_NAMES.comment}" data-inline-mark="comment" data-inline-comment-id="${esc(mark.commentId || "")}" data-comment-body="${esc(mark.body || "")}" title="${esc(mark.body || "")}">${html}</span>`;
    } else if (type === "mention") {
      const targetState = pageMentionTargetState(mark);
      const targetStateLabel = pageMentionTargetStateLabel(mark, targetState);
      const interactive = mark.mentionType === "page" && MENTION_PAGE_COLLECTION_BY_TYPE.has(mark.targetType) && Boolean(mark.targetId);
      html = `<span class="inline-mark ${INLINE_MARK_CLASS_NAMES.mention}" data-inline-mark="mention" data-mention-type="${esc(mark.mentionType || "")}" data-mention-label="${esc(mark.label || "")}" data-mention-date="${esc(mark.dateKey || "")}" data-mention-target-type="${esc(mark.targetType || "")}" data-mention-target-id="${esc(mark.targetId || "")}"${targetState ? ` data-mention-target-state="${targetState}"` : ""}${interactive ? ' role="link" tabindex="0" contenteditable="false"' : ""}${targetStateLabel ? ` aria-label="${esc(`${mark.label || text}, ${targetStateLabel}`)}" title="${esc(targetStateLabel)}"` : ""}>${html}</span>`;
    } else if (type === "equation") {
      const formula = mark.formula || text;
      html = `<span class="inline-mark ${INLINE_MARK_CLASS_NAMES.equation}" data-inline-mark="equation" data-equation-formula="${esc(formula)}" data-equation-display="${esc(renderEquationDisplay(formula))}" title="${esc(formula)}"><span class="inline-equation-source">${html}</span></span>`;
    } else {
      html = `<span class="inline-mark ${INLINE_MARK_CLASS_NAMES[type] || ""}" data-inline-mark="${type}">${html}</span>`;
    }
  }
  return html;
}

function resourceCitationHref(resourceId = "") {
  return `#resource/${encodeURIComponent(String(resourceId || ""))}`;
}

function resourceCitationTargetState(resourceId = "") {
  const resource = itemById("resources", resourceId);
  if (!resource) return "missing";
  return resource.trashedAt ? "trashed" : "active";
}

function resourceCitationTargetLabel(resourceId = "", targetState = resourceCitationTargetState(resourceId)) {
  const resource = itemById("resources", resourceId);
  const title = String(resource?.title || "제목 없는 Resource").trim() || "제목 없는 Resource";
  if (targetState === "trashed") return `${title}, 휴지통의 Resource`;
  if (targetState === "missing") return "연결된 Resource를 찾을 수 없음";
  return `${title} 열기`;
}

function activateResourceCitationTarget(citation) {
  if (!(citation instanceof Element)) return false;
  const resourceId = String(citation.dataset.resourceCitation || "");
  const targetState = resourceCitationTargetState(resourceId);
  if (targetState === "missing") {
    showToast("연결된 Resource를 찾을 수 없습니다.");
    return false;
  }
  if (targetState === "trashed") {
    showToast("연결된 Resource가 휴지통에 있습니다.");
    return false;
  }
  window.getSelection()?.removeAllRanges();
  if (ui.view !== "resources") setView("resources");
  return openResourceDocument(resourceId);
}

function pageMentionTargetState(mark) {
  if (mark?.mentionType !== "page" || !mark?.targetType || !mark?.targetId) return "";
  if (!MENTION_PAGE_COLLECTION_BY_TYPE.has(mark.targetType)) return "missing";
  const target = itemById(mark.targetType, mark.targetId);
  if (!target) return "missing";
  return "active";
}

function pageMentionTargetTypeLabel(targetType = "") {
  return MENTION_PAGE_COLLECTION_BY_TYPE.get(targetType)?.label || "Page";
}

function pageMentionTargetStateLabel(mark, targetState = pageMentionTargetState(mark)) {
  const typeLabel = pageMentionTargetTypeLabel(mark?.targetType);
  if (targetState === "trashed") return `휴지통의 ${typeLabel}`;
  if (targetState === "missing") return `찾을 수 없는 ${typeLabel}`;
  if (targetState === "active") return `${typeLabel} 열기`;
  return "";
}



function activatePageMentionTarget(mention) {
  if (!(mention instanceof Element)) return false;
  const targetType = String(mention.dataset.mentionTargetType || "");
  const targetId = String(mention.dataset.mentionTargetId || "");
  const typeLabel = pageMentionTargetTypeLabel(targetType);
  if (!MENTION_PAGE_COLLECTION_BY_TYPE.has(targetType) || !targetId) {
    showToast("지원하지 않는 페이지 멘션입니다.");
    return false;
  }
  const target = itemById(targetType, targetId);
  if (!target) {
    showToast(`연결된 ${typeLabel}을(를) 찾을 수 없습니다.`);
    return false;
  }
  return navigateToMentionTargetView(targetType, targetId);
}

function navigateToMentionTargetView(targetType, targetId) {
  const view = MENTION_TARGET_VIEW_BY_TYPE[targetType];
  if (!view || !itemById(targetType, targetId)) return false;
  const viewChanged = ui.view !== view;
  setView(view);
  if (targetType === "projects") ui.expandedProjectId = targetId;
  if (targetType === "habits") ui.expandedHabitId = targetId;
  if (!viewChanged || targetType === "projects" || targetType === "habits") renderView({ soft: true });
  requestAnimationFrame(() => requestAnimationFrame(() => focusMentionTargetInView(targetType, targetId)));
  return true;
}

function focusMentionTargetInView(targetType, targetId) {
  const escapedId = cssEscape(targetId);
  const selector = targetType === "projects"
    ? `[data-project-toggle="${escapedId}"]`
    : targetType === "habits"
      ? `[data-habit-toggle="${escapedId}"]`
      : targetType === "tasks"
        ? `[data-task-id="${escapedId}"]`
        : `[data-select-type="${cssEscape(targetType)}"][data-select-id="${escapedId}"]`;
  const destination = els.viewRoot?.querySelector(selector);
  if (!destination) {
    els.viewRoot?.focus?.({ preventScroll: true });
    showToast(`연결된 ${pageMentionTargetTypeLabel(targetType)}이(가) 현재 필터에 표시되지 않습니다.`);
    return false;
  }
  if (!destination.matches("button, a[href], input, select, textarea, [contenteditable='true'], [tabindex]")) destination.tabIndex = -1;
  destination.scrollIntoView({ block: "center", inline: "nearest" });
  destination.focus({ preventScroll: true });
  return true;
}

function normalizeInlineMarks(text = "", marks = []) {
  if (!Array.isArray(marks)) return [];
  const textLength = String(text).length;
  const normalized = [];
  for (const mark of marks) {
    if (!mark || !INLINE_MARK_TYPES.includes(mark.type)) continue;
    const start = Math.max(0, Math.min(textLength, Number.parseInt(mark.start, 10) || 0));
    const end = Math.max(0, Math.min(textLength, Number.parseInt(mark.end, 10) || 0));
    if (end <= start) continue;
    if (mark.type === "link") {
      const href = normalizeInlineHref(mark.href || mark.url || "");
      if (!href) continue;
      normalized.push({ type: mark.type, start, end, href });
    } else if (mark.type === "resourceLink") {
      const resourceId = String(mark.resourceId || mark.targetId || "").trim();
      if (!resourceId) continue;
      normalized.push({ type: mark.type, start, end, resourceId });
    } else if (mark.type === "comment") {
      const body = String(mark.body || mark.comment || "").trim();
      if (!body) continue;
      const commentId = String(mark.commentId || mark.id || `${start}-${end}-${body}`);
      normalized.push({ type: mark.type, start, end, commentId, body });
    } else if (mark.type === "mention") {
      const mentionType = normalizeMentionType(mark.mentionType || mark.kind || "");
      const label = String(mark.label || String(text).slice(start, end) || "").trim();
      if (!mentionType || !label) continue;
      const normalizedMark = { type: mark.type, start, end, mentionType, label };
      const date = normalizeMentionDateKey(mark.dateKey || mark.date || "");
      if (date) normalizedMark.dateKey = date;
      const targetType = String(mark.targetType || "").trim();
      const targetId = String(mark.targetId || mark.pageId || "").trim();
      if (targetType && targetId) {
        normalizedMark.targetType = targetType;
        normalizedMark.targetId = targetId;
      }
      normalized.push(normalizedMark);
    } else if (mark.type === "equation") {
      const formula = normalizeEquationFormula(mark.formula || mark.equation || String(text).slice(start, end));
      if (!formula) continue;
      normalized.push({ type: mark.type, start, end, formula });
    } else if (mark.type === "textColor" || mark.type === "backgroundColor") {
      const color = normalizeBlockColorValue(mark.color || mark.value || "");
      if (!color) continue;
      normalized.push({ type: mark.type, start, end, color });
    } else {
      normalized.push({ type: mark.type, start, end });
    }
  }
  const resourceLinks = resolveResourceLinkOverlaps(normalized.filter((mark) => mark.type === "resourceLink"));
  const withoutResourceLinks = normalized.filter((mark) => mark.type !== "resourceLink");
  const withoutConflictingLinks = resourceLinks.length
    ? withoutResourceLinks.filter((mark) => mark.type !== "link" || !resourceLinks.some((resourceLink) => resourceLink.start < mark.end && resourceLink.end > mark.start))
    : withoutResourceLinks;
  const resolved = [...withoutConflictingLinks, ...resourceLinks];
  resolved.sort((a, b) => a.start - b.start || a.end - b.end || INLINE_MARK_TYPES.indexOf(a.type) - INLINE_MARK_TYPES.indexOf(b.type));
  return mergeInlineMarks(resolved);
}

function resolveResourceLinkOverlaps(marks = []) {
  const sorted = marks
    .map((mark) => ({ ...mark }))
    .sort((left, right) => left.start - right.start || left.end - right.end || left.resourceId.localeCompare(right.resourceId));
  const resolved = [];
  for (const mark of sorted) {
    const previous = resolved[resolved.length - 1];
    if (!previous || mark.start >= previous.end) {
      resolved.push(mark);
      continue;
    }
    if (previous.resourceId === mark.resourceId) {
      previous.end = Math.max(previous.end, mark.end);
      continue;
    }
    if (mark.end > previous.end) resolved.push({ ...mark, start: previous.end });
  }
  return resolved;
}

function mergeInlineMarks(marks) {
  const merged = [];
  for (const mark of marks) {
    const previous = [...merged].reverse().find((candidate) => (
      candidate.type === mark.type && inlineMarkPayloadEqual(candidate, mark) && mark.start <= candidate.end
    ));
    if (previous) {
      previous.end = Math.max(previous.end, mark.end);
    } else {
      merged.push({ ...mark });
    }
  }
  return merged.sort((a, b) => a.start - b.start || a.end - b.end || INLINE_MARK_TYPES.indexOf(a.type) - INLINE_MARK_TYPES.indexOf(b.type));
}

function inlineMarksEqual(left = [], right = []) {
  if (!Array.isArray(left) || left.length !== right.length) return false;
  return left.every((mark, index) => {
    const other = right[index];
    return mark?.type === other?.type && mark.start === other.start && mark.end === other.end && inlineMarkPayloadEqual(mark, other);
  });
}

function inlineMarkPayloadEqual(left, right) {
  if (left?.type === "link" || right?.type === "link") return (left?.href || "") === (right?.href || "");
  if (left?.type === "resourceLink" || right?.type === "resourceLink") return (left?.resourceId || "") === (right?.resourceId || "");
  if (left?.type === "comment" || right?.type === "comment") {
    return (left?.commentId || "") === (right?.commentId || "") && (left?.body || "") === (right?.body || "");
  }
  if (left?.type === "mention" || right?.type === "mention") {
    return (
      (left?.mentionType || "") === (right?.mentionType || "") &&
      (left?.label || "") === (right?.label || "") &&
      (left?.dateKey || "") === (right?.dateKey || "") &&
      (left?.targetType || "") === (right?.targetType || "") &&
      (left?.targetId || "") === (right?.targetId || "")
    );
  }
  if (left?.type === "equation" || right?.type === "equation") {
    return (left?.formula || "") === (right?.formula || "");
  }
  if (["textColor", "backgroundColor"].includes(left?.type) || ["textColor", "backgroundColor"].includes(right?.type)) {
    return normalizeBlockColorValue(left?.color) === normalizeBlockColorValue(right?.color);
  }
  return true;
}

function normalizeEquationFormula(value = "") {
  return String(value || "").replace(/\s+/g, " ").trim();
}

function renderEquationDisplay(value = "") {
  let formula = normalizeEquationFormula(value);
  if (!formula) return "";
  formula = formula.replace(/\\left\s*/g, "").replace(/\\right\s*/g, "");
  let previous = "";
  while (formula !== previous) {
    previous = formula;
    formula = formula.replace(/\\frac\s*\{([^{}]+)\}\s*\{([^{}]+)\}/g, (_, numerator, denominator) => `${renderEquationDisplay(numerator)}⁄${renderEquationDisplay(denominator)}`);
    formula = formula.replace(/\\sqrt\s*\{([^{}]+)\}/g, (_, body) => `√${renderEquationDisplay(body)}`);
  }
  formula = formula.replace(/\\([a-zA-Z]+)\s*\{([^{}]*)\}/g, (_, command, body) => {
    if (command === "text" || command === "mathrm" || command === "operatorname") return body;
    return `${equationCommandSymbol(command)}${body}`;
  });
  formula = formula.replace(/\\([a-zA-Z]+)/g, (_, command) => equationCommandSymbol(command));
  formula = formula.replace(/\^\{([^{}]+)\}/g, (_, body) => equationScriptText(body, "sup"));
  formula = formula.replace(/_\{([^{}]+)\}/g, (_, body) => equationScriptText(body, "sub"));
  formula = formula.replace(/\^([A-Za-z0-9+\-=()])/g, (_, body) => equationScriptText(body, "sup"));
  formula = formula.replace(/_([A-Za-z0-9+\-=()])/g, (_, body) => equationScriptText(body, "sub"));
  formula = formula.replace(/[{}]/g, "");
  return formula.replace(/\s+/g, " ").trim();
}

function equationCommandSymbol(command = "") {
  const symbols = {
    alpha: "α",
    beta: "β",
    gamma: "γ",
    delta: "δ",
    epsilon: "ε",
    zeta: "ζ",
    eta: "η",
    theta: "θ",
    iota: "ι",
    kappa: "κ",
    lambda: "λ",
    mu: "μ",
    nu: "ν",
    xi: "ξ",
    pi: "π",
    rho: "ρ",
    sigma: "σ",
    tau: "τ",
    upsilon: "υ",
    phi: "φ",
    chi: "χ",
    psi: "ψ",
    omega: "ω",
    Gamma: "Γ",
    Delta: "Δ",
    Theta: "Θ",
    Lambda: "Λ",
    Xi: "Ξ",
    Pi: "Π",
    Sigma: "Σ",
    Phi: "Φ",
    Psi: "Ψ",
    Omega: "Ω",
    times: "×",
    cdot: "⋅",
    div: "÷",
    pm: "±",
    mp: "∓",
    le: "≤",
    leq: "≤",
    ge: "≥",
    geq: "≥",
    neq: "≠",
    approx: "≈",
    sim: "∼",
    infty: "∞",
    partial: "∂",
    nabla: "∇",
    sum: "∑",
    prod: "∏",
    int: "∫",
    lim: "lim",
    log: "log",
    ln: "ln",
    sin: "sin",
    cos: "cos",
    tan: "tan",
    to: "→",
    rightarrow: "→",
    leftarrow: "←",
    leftrightarrow: "↔",
  };
  return symbols[command] || command;
}

function equationScriptText(value = "", mode = "sup") {
  const superscript = {
    0: "⁰", 1: "¹", 2: "²", 3: "³", 4: "⁴", 5: "⁵", 6: "⁶", 7: "⁷", 8: "⁸", 9: "⁹",
    a: "ᵃ", b: "ᵇ", c: "ᶜ", d: "ᵈ", e: "ᵉ", f: "ᶠ", g: "ᵍ", h: "ʰ", i: "ⁱ", j: "ʲ", k: "ᵏ", l: "ˡ", m: "ᵐ", n: "ⁿ", o: "ᵒ", p: "ᵖ", r: "ʳ", s: "ˢ", t: "ᵗ", u: "ᵘ", v: "ᵛ", w: "ʷ", x: "ˣ", y: "ʸ", z: "ᶻ",
    A: "ᴬ", B: "ᴮ", D: "ᴰ", E: "ᴱ", G: "ᴳ", H: "ᴴ", I: "ᴵ", J: "ᴶ", K: "ᴷ", L: "ᴸ", M: "ᴹ", N: "ᴺ", O: "ᴼ", P: "ᴾ", R: "ᴿ", T: "ᵀ", U: "ᵁ", V: "ⱽ", W: "ᵂ",
    "+": "⁺", "-": "⁻", "=": "⁼", "(": "⁽", ")": "⁾",
  };
  const subscript = {
    0: "₀", 1: "₁", 2: "₂", 3: "₃", 4: "₄", 5: "₅", 6: "₆", 7: "₇", 8: "₈", 9: "₉",
    a: "ₐ", e: "ₑ", h: "ₕ", i: "ᵢ", j: "ⱼ", k: "ₖ", l: "ₗ", m: "ₘ", n: "ₙ", o: "ₒ", p: "ₚ", r: "ᵣ", s: "ₛ", t: "ₜ", u: "ᵤ", v: "ᵥ", x: "ₓ",
    "+": "₊", "-": "₋", "=": "₌", "(": "₍", ")": "₎",
  };
  const table = mode === "sub" ? subscript : superscript;
  return String(value || "").split("").map((char) => table[char] || char).join("");
}

function normalizeMentionType(value = "") {
  const type = String(value || "").trim().toLowerCase();
  return ["date", "reminder", "page", "person"].includes(type) ? type : "";
}

function normalizeMentionDateKey(value = "") {
  const text = String(value || "").trim();
  return /^\d{4}-\d{2}-\d{2}$/.test(text) ? text : "";
}

function normalizeInlineHref(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (/^(https?:|mailto:|tel:)/i.test(raw)) return raw;
  if (/^www\./i.test(raw)) return `https://${raw}`;
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(raw)) return `mailto:${raw}`;
  if (/^[\w.-]+\.[a-z]{2,}(?:[/?#].*)?$/i.test(raw)) return `https://${raw}`;
  if (/^(?:\/(?!\/)|#|\?|\.\.?\/)/.test(raw)) return raw;
  return "";
}

function openInlineLinkExternally(linkElement) {
  const href = normalizeInlineHref(linkElement?.dataset?.inlineHref || linkElement?.getAttribute?.("href") || "");
  if (!href) return false;
  const openedWindow = window.open(href, "_blank", "noopener,noreferrer");
  if (openedWindow) openedWindow.opener = null;
  return true;
}

function blockPlaceholder(block) {
  if (block.type === "heading1") return "제목 1";
  if (block.type === "heading2") return "제목 2";
  if (block.type === "heading3") return "제목 3";
  if (block.type === "heading4") return "제목 4";
  if (block.type === "heading5") return "제목 5";
  if (block.type === "heading6") return "제목 6";
  if (block.type === "todo") return "할 일";
  if (block.type === "toggle") return "토글";
  if (block.type === "quote") return "인용";
  if (block.type === "callout") return "콜아웃";
  if (block.type === "code") return "코드";
  return "텍스트 입력";
}

function renderOverlays() {
  if (ui.resourceCitationPopover && !resourceCitationPopoverIsValid(ui.resourceCitationPopover)) ui.resourceCitationPopover = null;
  if (ui.taskPlacement && !itemById("tasks", ui.taskPlacement.taskId)) {
    ui.taskPlacement = null;
    if (ui.scheduler?.mode === "quick-create") ui.scheduler = null;
  }
  updateTaskSchedulingMode();
  els.overlayRoot.innerHTML = `
    ${ui.commandOpen ? renderCommandMenu() : ""}
    ${ui.inlineToolbar ? renderInlineFormatToolbar() : ""}
    ${ui.linkPopover ? renderLinkPopover() : ""}
    ${ui.resourceCitationPopover ? renderResourceCitationPopover() : ""}
    ${ui.commentPopover ? renderCommentPopover() : ""}
    ${ui.equationPopover ? renderEquationPopover() : ""}
    ${ui.urlPasteChoice ? renderUrlPasteChoice() : ""}
    ${ui.selectedBlockMenu ? renderSelectedBlocksMenu() : ""}
    ${ui.mention ? renderMentionMenu() : ""}
    ${ui.pageCommand ? renderPageCommandMenu() : ""}
    ${ui.emojiCommand ? renderEmojiMenu() : ""}
    ${ui.scheduler ? renderTaskScheduler() : ""}
    ${ui.taskPlacement && !ui.scheduler ? renderQuickTaskPlacement() : ""}
    ${ui.todayBatch ? renderTodayBatch() : ""}
    ${ui.deleteDrag ? renderDeleteDragOverlay() : ""}
    ${ui.projectDeleteConfirmId ? renderProjectDeleteConfirm() : ""}
    ${ui.boxDeleteConfirmId ? renderBoxDeleteConfirm() : ""}
    ${ui.habitDeleteConfirmId ? renderHabitDeleteConfirm() : ""}
    ${ui.view === "today" && ui.todayTaskDrag && !ui.todayTaskDrag.batch ? renderTodayFloatingDrop() : ""}
    ${ui.blockDrag ? renderBlockDragGhost() : ""}
    ${ui.todayTaskDrag ? renderTodayTaskDragGhost() : ""}
    ${renderServiceWorkerUpdateNotice()}
  `;
  decorateButtons(els.overlayRoot);
  syncEditorCommandMenuAria();
  syncInlineToolbarPosition();
  scheduleInlineToolbarPositionSync();
}

function renderUrlPasteChoice() {
  const choice = ui.urlPasteChoice;
  if (!choice) return "";
  const selectedIndex = Math.max(0, Math.min(URL_PASTE_CHOICE_ACTIONS.length - 1, choice.selectedIndex || 0));
  const items = URL_PASTE_CHOICE_ACTIONS.map((item, index) => `
    <button
      class="url-paste-choice-item ${index === selectedIndex ? "is-active" : ""} ${item.action === "cancel" ? "is-cancel" : ""}"
      id="url-paste-choice-item-${index}"
      type="button"
      role="menuitem"
      data-url-paste-choice-action="${item.action}"
      data-url-paste-choice-index="${index}"
      tabindex="${index === selectedIndex ? "0" : "-1"}"
    >
      <span class="url-paste-choice-icon" aria-hidden="true">${item.icon}</span>
      <span class="url-paste-choice-copy"><strong>${item.label}</strong><span>${item.hint}</span></span>
    </button>
  `).join("");
  return `
    <section
      class="url-paste-choice"
      id="url-paste-choice-menu"
      data-url-paste-choice-menu
      role="menu"
      aria-label="URL 붙여넣기 방식 선택"
      aria-activedescendant="url-paste-choice-item-${selectedIndex}"
      style="left:${Math.round(choice.x || 8)}px;top:${Math.round(choice.y || 8)}px"
    >
      <div class="url-paste-choice-head">
        <strong>URL 붙여넣기</strong>
        <span title="${esc(choice.url)}">${esc(choice.url)}</span>
      </div>
      <div class="url-paste-choice-items">${items}</div>
    </section>
  `;
}

function editorCommandMenuId(kind, blockId) {
  return `${kind}-menu-${encodeURIComponent(String(blockId || "current"))}`;
}

function editorCommandMenuItemId(kind, blockId, index) {
  return `${editorCommandMenuId(kind, blockId)}-item-${index}`;
}

function syncEditorCommandMenuAria() {
  document.querySelectorAll("[data-editor-command-open]").forEach((element) => {
    element.removeAttribute("data-editor-command-open");
    element.removeAttribute("aria-controls");
    element.removeAttribute("aria-activedescendant");
    element.removeAttribute("aria-haspopup");
    element.removeAttribute("aria-expanded");
  });
  const commands = [
    ["block-selection", ui.selectedBlockMenu],
    ["mention", ui.mention],
    ["page-command", ui.pageCommand],
    ["emoji", ui.emojiCommand],
  ];
  for (const [kind, command] of commands) {
    if (!command?.blockId) continue;
    const content = document.querySelector(`[data-block-content="${cssEscape(command.blockId)}"]`);
    const menuId = editorCommandMenuId(kind, command.blockId);
    const activeId = editorCommandMenuItemId(kind, command.blockId, Math.max(0, command.selectedIndex || 0));
    if (!content || !document.getElementById(menuId)) continue;
    content.dataset.editorCommandOpen = kind;
    content.setAttribute("aria-controls", menuId);
    content.setAttribute("aria-haspopup", "menu");
    content.setAttribute("aria-expanded", "true");
    if (document.getElementById(activeId)) content.setAttribute("aria-activedescendant", activeId);
    const query = document.querySelector("[data-selected-block-query]");
    if (kind === "block-selection" && query) {
      query.setAttribute("aria-controls", menuId);
      if (document.getElementById(activeId)) query.setAttribute("aria-activedescendant", activeId);
    }
  }
}

function registerServiceWorkerUpdateFlow() {
  if (!("serviceWorker" in navigator) || location.protocol === "file:") return;
  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (hasUnsavedResourceWork()) {
      serviceWorkerUpdateApplying = false;
      serviceWorkerUpdateAvailable = true;
      renderServiceWorkerUpdateNoticeIfNeeded();
      return;
    }
    window.location.reload();
  });
  navigator.serviceWorker
    .register("/service-worker.js", { updateViaCache: "none" })
    .then((registration) => {
      activeServiceWorkerRegistration = registration;
      observeServiceWorkerRegistration(registration);
      return registration.update();
    })
    .catch(() => {});
}

function observeServiceWorkerRegistration(registration) {
  if (registration.waiting) setWaitingServiceWorkerRegistration(registration);
  registration.addEventListener("updatefound", () => {
    const worker = registration.installing;
    if (!worker) return;
    worker.addEventListener("statechange", () => {
      if (worker.state === "installed" && navigator.serviceWorker.controller && registration.waiting) {
        setWaitingServiceWorkerRegistration(registration);
      }
    });
  });
}

function setWaitingServiceWorkerRegistration(registration) {
  waitingServiceWorkerRegistration = registration;
  serviceWorkerUpdateAvailable = true;
  if (!hasUnsavedResourceWork()) {
    applyWaitingServiceWorkerUpdate();
    return;
  }
  renderServiceWorkerUpdateNoticeIfNeeded();
}

function hasUnsavedResourceWork() {
  return Boolean(
    localResourcePersistence.pending ||
    localResourcePersistence.operations.length ||
    remoteStateSavePending ||
    remoteStateSaveInFlight ||
    databaseBackendStatus.saving ||
    databaseBackendStatus.conflict
  );
}

function hasPendingLocalWorkspaceWork() {
  return Boolean(
    dirtyResourceIds.size ||
    pendingResourceOperationGroups.length ||
    localWorkspaceOperationRequired ||
    localResourceWriteTimer ||
    localResourcePersistence.pending ||
    localResourcePersistence.operations.length ||
    remoteStateSavePending ||
    remoteStateSaveInFlight ||
    remoteStateSaveBlocked ||
    databaseBackendStatus.saving ||
    databaseBackendStatus.conflict ||
    localStateChangedBeforeDatabaseReady ||
    ui.composingBlockId ||
    ui.blockDrag ||
    ui.todayTaskDrag ||
    ui.deleteDrag ||
    ui.scheduler?.dragging ||
    ui.taskPlacement
  );
}

function renderServiceWorkerUpdateNotice() {
  if (!serviceWorkerUpdateAvailable) return "";
  const blocked = hasUnsavedResourceWork();
  return `
    <section class="service-worker-update" role="status">
      <div><strong>새 앱 버전 준비됨</strong><span>${blocked ? "pending 저장을 마친 뒤 적용할 수 있습니다." : "저장된 상태입니다. 준비가 되면 업데이트하세요."}</span></div>
      <button class="button" type="button" data-action="apply-app-update" ${blocked ? "disabled" : ""}>업데이트 적용</button>
    </section>
  `;
}

function renderServiceWorkerUpdateNoticeIfNeeded() {
  if (!serviceWorkerUpdateAvailable || !els.overlayRoot || ui.taskPlacement) return;
  if (!hasUnsavedResourceWork()) {
    applyWaitingServiceWorkerUpdate();
    return;
  }
  renderOverlays();
}

async function applyWaitingServiceWorkerUpdate() {
  if (!serviceWorkerUpdateAvailable || serviceWorkerUpdateApplying || hasUnsavedResourceWork()) return false;
  serviceWorkerUpdateApplying = true;
  const registration = waitingServiceWorkerRegistration || await navigator.serviceWorker.getRegistration();
  if (registration?.waiting) {
    registration.waiting.postMessage({ type: "SKIP_WAITING" });
    window.setTimeout(() => {
      if (!serviceWorkerUpdateApplying) return;
      if (hasUnsavedResourceWork()) {
        serviceWorkerUpdateApplying = false;
        serviceWorkerUpdateAvailable = true;
        renderServiceWorkerUpdateNoticeIfNeeded();
        return;
      }
      window.location.reload();
    }, 750);
  } else {
    window.location.reload();
  }
  return true;
}

function handleResourceConnectionLost() {
  stopRemoteStateEvents();
  scheduleRemoteStateRefresh();
;
  renderServiceWorkerUpdateNoticeIfNeeded();
}

async function handleResourceConnectionRestored() {
  if (navigator.onLine === false) {
    if (app.dataset.workspaceAuthority !== "ready") setWorkspaceAuthorityMode("offline");
    scheduleRemoteStateRefresh();
    return;
  }
  const requiresAuthoritativeReload = app.dataset.workspaceAuthority !== "ready";
  if (!databaseBackendStatus.connected || requiresAuthoritativeReload) {
    setWorkspaceAuthorityMode("loading");
  }
  if (requiresAuthoritativeReload) {
    await initializeDatabaseState();
    setWorkspaceAuthorityMode(databaseBackendStatus.connected && !databaseBackendStatus.conflict ? "ready" : "offline");
    scheduleRemoteStateRefresh();
;
    return;
  }
  connectRemoteStateEvents();
  if (databaseBackendStatus.conflict) {
    const restored = await reloadRemoteStateAfterConflict({ force: true, silent: true });
    if (!restored) setWorkspaceAuthorityMode("offline");
    scheduleRemoteStateRefresh();
;
    return;
  }
  if (localResourcePersistence.operations.length) {
    await markLocalResourceOperations("retrying", {
      incrementAttempts: false,
      excludeStatuses: ["failed", "conflict"],
    });
    remoteStateSavePending = hasAutomaticallySaveableLocalOperations();
  }
  if (databaseBackendStatus.connected && remoteStateSavePending) {
    queueRemoteStateSave({ immediate: true });
  } else if (databaseBackendStatus.connected) {
    await refreshRemoteStateIfNewer();
  } else {
    if (!databaseBackendStatus.connected) await initializeDatabaseState();
  }
  setWorkspaceAuthorityMode(databaseBackendStatus.connected && !databaseBackendStatus.conflict ? "ready" : "offline");
  scheduleRemoteStateRefresh();
;
}

function updateTaskSchedulingMode() {
  const taskPlacementOpen = Boolean(ui.taskPlacement);
  const todayBatchOpen = Boolean(ui.todayBatch);
  const modalOpen = taskPlacementOpen || todayBatchOpen;
  const resourceDocumentOpen = ui.view === "resources" && Boolean(ui.activeResourceId);
  const relationPlacementOpen = taskPlacementOpen && Number(ui.taskPlacement?.phaseIndex || 0) > 0;
  app.classList.toggle("is-task-scheduling", Boolean(ui.scheduler?.dragging && ui.view === "tasks"));
  app.classList.toggle("is-task-placement", taskPlacementOpen);
  app.classList.toggle("is-task-placement-date", taskPlacementOpen && !relationPlacementOpen);
  els.overlayRoot?.classList.toggle("has-task-placement", modalOpen);
  els.overlayRoot?.classList.toggle("has-relation-placement", relationPlacementOpen || ui.todayBatch?.phase === "place");
  document.documentElement.classList.toggle("is-task-placement-open", modalOpen);
  document.body.classList.toggle("is-task-placement-open", modalOpen);
  app.querySelector(".layout")?.toggleAttribute("inert", modalOpen || resourceDocumentOpen);
  els.fab?.toggleAttribute("inert", modalOpen || resourceDocumentOpen);
  app.classList.toggle("is-delete-dragging", Boolean(ui.deleteDrag));
  app.classList.toggle("is-block-dragging", Boolean(ui.blockDrag?.active));
}

function renderTaskScheduler() {
  const scheduler = ui.scheduler;
  const task = itemById("tasks", scheduler?.taskId);
  if (!scheduler || !task) return "";
  const placementFlow = scheduler.mode === "quick-create" && ui.taskPlacement?.taskId === task.id;
  const monthDate = parseMonthKey(scheduler.month);
  const today = dateKey(new Date());
  const scheduledDate = task.dueDate || "";
  const days = monthGridDays(monthDate);
  const laneTargets = schedulerLaneTargets(task.id);
  const dayTaskCounts = schedulerTaskCountsByDate(task.id);
  const prevMonth = addMonths(monthDate, -1);
  const nextMonth = addMonths(monthDate, 1);
  const dragOverTarget = scheduler.dragOverTarget;
  return `
    <div class="task-scheduler-backdrop ${placementFlow ? "is-quick-placement" : ""}" aria-hidden="true"></div>
    <div class="task-scheduler-stage ${placementFlow ? "is-quick-placement" : ""} ${scheduler.monthEdge ? `is-edge-${scheduler.monthEdge}` : ""}" role="dialog" aria-modal="${placementFlow ? "true" : "false"}" aria-label="Task 날짜 배치">
      <div class="task-scheduler-lanes" aria-label="Task 배치 칸">
        ${renderSchedulerLanes(laneTargets, dragOverTarget)}
      </div>
      <div class="task-scheduler-month-zone is-prev" aria-hidden="true">
        <span>${esc(monthSideLabel(prevMonth))}</span>
      </div>
      <div class="task-scheduler">
        ${placementFlow ? renderQuickTaskPlacementProgress(0) : ""}
        <div class="task-scheduler-head">
          <div>
            ${placementFlow ? `<span class="quick-placement-kicker">1 / 3 · 날짜</span>` : ""}
            <strong>${placementFlow ? "날짜에 배치" : esc(monthLabel(monthDate))}</strong>
            <span>${placementFlow ? `${esc(task.title)} · ${esc(monthLabel(monthDate))}` : esc(task.title)}</span>
          </div>
          <div class="task-scheduler-nav">
            <button class="task-scheduler-nav-button" type="button" data-scheduler-month="${monthKey(addMonths(monthDate, -1))}" aria-label="이전 달">‹</button>
            <button class="task-scheduler-nav-button" type="button" data-scheduler-month="${monthKey(new Date())}">오늘</button>
            <button class="task-scheduler-nav-button" type="button" data-scheduler-month="${monthKey(addMonths(monthDate, 1))}" aria-label="다음 달">›</button>
            <button class="task-scheduler-nav-button" type="button" data-scheduler-close aria-label="닫기">닫기</button>
          </div>
        </div>
        <div class="task-scheduler-weekdays">
          ${renderSchedulerWeekdayLabels()}
        </div>
        <div class="task-scheduler-grid">
          ${renderSchedulerMonthDays(days, monthDate, today, scheduledDate, dayTaskCounts, dragOverTarget)}
        </div>
      </div>
      <div class="task-scheduler-month-zone is-next" aria-hidden="true">
        <span>${esc(monthSideLabel(nextMonth))}</span>
      </div>
      ${
        placementFlow
          ? renderQuickTaskFirstActions()
          : `<button class="task-scheduler-delete-zone ${scheduler.dragOverAction === "delete" ? "is-drop-target" : ""}" type="button" data-scheduler-action="delete" aria-label="Task 삭제">
              <span>
                <strong>삭제</strong>
                <em>완전히 제거</em>
              </span>
            </button>`
      }
    </div>
    ${
      scheduler.dragging
        ? `<div class="schedule-drag-ghost" style="left:${scheduler.dragX}px;top:${scheduler.dragY}px;width:${scheduler.dragWidth}px">
            <strong>${esc(task.title)}</strong>
            <span>날짜 칸에 놓기</span>
          </div>`
        : ""
    }
  `;
}

function renderQuickTaskFirstActions() {
  return `
    <div class="quick-placement-first-actions" role="group" aria-label="새 할 일 생성 방식">
      <button class="task-scheduler-lane quick-placement-first-action is-cancel" type="button" data-placement-create-cancel>
        <span><strong>취소</strong><em>할 일 생성 취소</em></span>
      </button>
      <button class="task-scheduler-lane quick-placement-first-action is-create" type="button" data-placement-create-now>
        <span><strong>바로 만들기</strong><em>선택 없이 저장</em></span>
      </button>
    </div>
  `;
}

function renderQuickTaskPlacementProgress(activeIndex) {
  const labels = ["날짜", "Box", "Project"];
  let steps = "";
  for (let index = 0; index < labels.length; index += 1) {
    steps += `
      <span class="quick-placement-progress-step ${index === activeIndex ? "is-active" : ""} ${index < activeIndex ? "is-complete" : ""}">
        <i aria-hidden="true"></i>
        <small>${esc(labels[index])}</small>
      </span>
    `;
  }
  return `<div class="quick-placement-progress" aria-label="할 일 배치 진행 단계">${steps}</div>`;
}

function renderQuickTaskPlacement() {
  const placement = ui.taskPlacement;
  const task = itemById("tasks", placement?.taskId);
  if (!placement || !task || placement.phaseIndex < 1) return "";
  syncQuickTaskPlacementValues(placement, task);
  const relationSteps = getTaskCaptureSteps({ type: "tasks", values: placement.values });
  const relationIndex = Math.max(0, Math.min(relationSteps.length - 1, placement.phaseIndex - 1));
  const step = relationSteps[relationIndex];
  if (!step) return "";
  let options = "";
  for (const option of step.options) {
    const selected = (placement.values[step.key] || "") === option.value;
    options += `
      <button
        class="quick-placement-choice ${selected ? "is-current" : ""}"
        type="button"
        data-placement-choice
        data-placement-step="${step.key}"
        data-placement-value="${esc(option.value)}"
      >
        <span>${esc(option.label)}</span>
        ${option.meta ? `<small>${esc(option.meta)}</small>` : ""}
      </button>
    `;
  }
  return `
    <button class="quick-placement-backdrop" type="button" data-placement-cancel aria-label="할 일 배치 건너뛰기"></button>
    <section
      class="quick-placement-stage"
      data-quick-placement
      data-placement-phase="${step.key}"
      role="dialog"
      aria-modal="true"
      aria-labelledby="quick-placement-title"
    >
      ${renderQuickTaskPlacementProgress(placement.phaseIndex)}
      <header class="quick-placement-head">
        <div>
          <span class="quick-placement-kicker">${placement.phaseIndex + 1} / 3 · ${esc(step.label)}</span>
          <h2 id="quick-placement-title">${esc(step.label)}에 배치</h2>
          <p>${esc(step.hint)}을 선택하면 다음 단계로 이어집니다.</p>
        </div>
        <button class="quick-placement-close" type="button" data-placement-cancel aria-label="할 일 배치 건너뛰기">건너뛰기</button>
      </header>
      <div class="quick-placement-task-title" title="${esc(task.title)}">${esc(task.title)}</div>
      <div class="quick-placement-choices" role="group" aria-label="${esc(step.label)} 선택">
        ${options}
      </div>
      <footer class="quick-placement-footer">
        <button class="button ghost" type="button" data-placement-back>이전</button>
        <span>선택 내용은 단계마다 바로 저장됩니다.</span>
      </footer>
    </section>
  `;
}

function renderSchedulerLanes(lanes, dragOverTarget) {
  let html = "";
  for (const lane of lanes) {
    html += `
      <button class="task-scheduler-lane ${lane.targetKey === dragOverTarget ? "is-drop-target" : ""}" type="button" ${lane.date ? `data-scheduler-date="${lane.date}"` : ""} ${lane.action ? `data-scheduler-action="${lane.action}"` : ""} data-scheduler-lane="${lane.key}">
        <span>
          <strong>${esc(lane.title)}</strong>
          <em>${esc(lane.meta)}</em>
        </span>
        <small>${lane.count}</small>
      </button>
    `;
  }
  return html;
}

function renderSchedulerWeekdayLabels() {
  let html = "";
  for (const day of SCHEDULER_WEEKDAY_LABELS) {
    html += `<span>${day}</span>`;
  }
  return html;
}

function renderSchedulerMonthDays(days, monthDate, today, scheduledDate, dayTaskCounts, dragOverTarget) {
  let html = "";
  for (const day of days) {
    const key = dateKey(day);
    const outside = day.getMonth() !== monthDate.getMonth();
    const count = dayTaskCounts.get(key) || 0;
    html += `
      <button class="task-scheduler-day ${outside ? "is-outside" : ""} ${key === today ? "is-today" : ""} ${key === scheduledDate ? "is-selected" : ""} ${`date:${key}` === dragOverTarget ? "is-drop-target" : ""}" type="button" data-scheduler-date="${key}">
        <span>${day.getDate()}</span>
        ${count ? `<small>${count}</small>` : ""}
      </button>
    `;
  }
  return html;
}

function renderDeleteDragOverlay() {
  const drag = ui.deleteDrag;
  if (!drag) return "";
  const label = deleteDragTypeLabel(drag.type);
  const actions = dragActionTargets(drag.type, drag.id);
  return `
    <div class="task-scheduler-backdrop delete-drag-backdrop" aria-hidden="true"></div>
    <div class="delete-drag-stage ${actions.length > 1 ? "is-multi-action" : ""}" role="dialog" aria-label="${esc(label)} 이동">
      ${renderDeleteDragActions(actions, drag.targetAction)}
    </div>
    <div class="schedule-drag-ghost delete-drag-ghost" style="left:${drag.dragX}px;top:${drag.dragY}px;width:${drag.dragWidth}px">
      <strong>${esc(drag.title || label)}</strong>
      <span>${actions.length > 1 ? "원하는 영역에 놓기" : "삭제 영역에 놓기"}</span>
    </div>
  `;
}

function renderDeleteDragActions(actions, targetAction) {
  let html = "";
  for (const action of actions) {
    html += `
      <button class="${action.tone === "delete" ? "task-scheduler-delete-zone delete-drop-zone" : "task-scheduler-lane delete-drop-zone"} ${targetAction === action.action ? "is-drop-target" : ""}" type="button" data-delete-drop data-drag-action="${action.action}">
        <span>
          <strong>${esc(action.title)}</strong>
          <em>${esc(action.meta)}</em>
        </span>
        ${action.count !== undefined ? `<small>${action.count}</small>` : ""}
      </button>
    `;
  }
  return html;
}

