function handleAction(action, actionButton = null) {
  if (action === "toggle-nav") {
    resetNavShortcutState({ closeAutoOpened: false });
    if (ui.navOpen) {
      closeNav();
    } else {
      openNav();
    }
    return;
  }
  if (action === "close-nav") {
    resetNavShortcutState({ closeAutoOpened: false });
    closeNav();
    return;
  }
  if (action === "open-command") {
    ui.commandOpen = !ui.commandOpen;
    ui.selectedBlockMenu = null;
    renderOverlays();
    return;
  }
  ui.commandOpen = false;
  renderOverlays();

  if (action === "retry-finance") {
    financeWorkspace.status = "idle";
    return loadFinanceWorkspace();
  }
  if (action === "finance-logout") return logoutFinance();
  if (action === "new-today-batch") return openTodayBatch(actionButton);
  if (action === "close-today-batch") return closeTodayBatch({ announce: true });
  if (action === "new-task") return createTaskFromAction(actionButton);
  if (action === "new-project") return createProject();
  if (action === "new-box") return createBox();
  if (action === "new-resource") return createResourceFromAction(actionButton);
  if (action === "new-habit") return createHabit();
  if (action === "new-journal") return createJournal();
  if (action === "new-capture") return createCapture();
  if (action === "connect-google") return connectGoogle();
  if (action === "fetch-google") return fetchGoogleCalendarEvents();
  if (action === "sync-google") return syncGoogleCalendar();
  if (action === "export-json") return exportJson();
  if (action === "reload-remote-state") return reloadRemoteStateAfterConflict();
  if (action === "apply-app-update") return applyWaitingServiceWorkerUpdate();
  if (action === "reset-demo-data") return resetDemoData();
}

function quickCreateContext(actionButton) {
  const zone = actionButton?.closest?.("[data-capture-zone]");
  if (!zone) return null;
  const input = zone.querySelector("[data-form='quick-capture'] [name='title']");
  return input ? { input, title: input.value.trim() } : null;
}

function requireQuickCreateTitle(context, kindLabel) {
  if (!context || context.title) return true;
  context.input.focus();
  showToast(`${kindLabel} 내용을 먼저 입력해주세요.`);
  return false;
}

function createTaskFromAction(actionButton) {
  const context = quickCreateContext(actionButton);
  if (!context) return createTask();
  if (!requireQuickCreateTitle(context, "할 일")) return null;
  const task = createTask(context?.title || "새 할 일", {
    navigate: false,
    initial: { boxId: "", projectId: "", resourceId: "" },
  });
  if (!task) return null;
  if (context) context.input.value = "";
  startQuickTaskPlacement(task.id, actionButton);
  return task;
}

function openTodayBatch(opener) {
  if (ui.todayBatch) return;
  ui.commandOpen = false;
  ui.scheduler = null;
  ui.taskPlacement = null;
  ui.todayBatch = {
    phase: "input",
    draft: "",
    taskIds: [],
    returnFocus: opener instanceof HTMLElement ? opener : null,
  };
  renderOverlays();
  requestAnimationFrame(() => document.querySelector("[data-today-batch-input]")?.focus());
}

function startTodayBatchPlacement(value = ui.todayBatch?.draft || "") {
  const batch = ui.todayBatch;
  if (!batch || batch.phase !== "input") return;
  const titles = String(value || "")
    .split(/\r?\n/)
    .map((title) => title.trim())
    .filter(Boolean);
  if (!titles.length) {
    showToast("한 줄 이상 할 일을 입력해주세요.");
    requestAnimationFrame(() => document.querySelector("[data-today-batch-input]")?.focus());
    return;
  }
  const today = dateKey(new Date());
  batch.taskIds = titles.map((title) => createTask(title, {
    deferCreate: true,
    initial: {
      status: "todo",
      dueDate: today,
      boxId: "",
      projectId: "",
      resourceId: "",
    },
  }).id);
  batch.phase = "place";
  batch.draft = "";
  saveState();
  renderView({ soft: true, animateCards: true });
  renderOverlays();
  requestAnimationFrame(() => document.querySelector("[data-today-batch-task]")?.focus());
}

function closeTodayBatch({ announce = false } = {}) {
  const batch = ui.todayBatch;
  if (!batch) return;
  const remaining = batch.phase === "place" ? batch.taskIds.length : 0;
  const returnFocus = batch.returnFocus;
  if (ui.todayTaskDrag?.batch) clearTodayTaskDragState();
  ui.pendingTodayTaskDrag = null;
  ui.todayBatch = null;
  renderView({ soft: true });
  renderOverlays();
  if (announce && remaining) showToast(`남은 ${remaining}개는 속성 없이 오늘 할 일에 남겼습니다.`);
  requestAnimationFrame(() => {
    const fallback = document.querySelector('[data-action="new-today-batch"]');
    const target = returnFocus instanceof HTMLElement && returnFocus.isConnected ? returnFocus : fallback;
    target?.focus({ preventScroll: true });
  });
}

function commitTodayBatchDrop(task, action) {
  const batch = ui.todayBatch;
  if (!batch || batch.phase !== "place" || !batch.taskIds.includes(task.id)) return;
  if (action.startsWith("project:")) {
    const projectId = action.slice("project:".length);
    if (!itemById("projects", projectId)) return;
    task.boxId = "";
    task.projectId = "";
    task.resourceId = "";
    applyTaskFieldValue(task, "projectId", projectId);
  } else if (action === "unassigned") {
    task.boxId = "";
    task.projectId = "";
    task.resourceId = "";
  } else if (action === "delete") {
    deleteEntity("tasks", task.id);
  } else {
    return;
  }

  batch.taskIds = batch.taskIds.filter((taskId) => taskId !== task.id);
  saveState();
  if (!batch.taskIds.length) {
    const returnFocus = batch.returnFocus;
    ui.todayBatch = null;
    renderView({ soft: true, animateCards: true });
    renderOverlays();
    showToast("오늘 할 일 배치를 마쳤습니다.");
    requestAnimationFrame(() => {
      const fallback = document.querySelector('[data-action="new-today-batch"]');
      const target = returnFocus instanceof HTMLElement && returnFocus.isConnected ? returnFocus : fallback;
      target?.focus({ preventScroll: true });
    });
    return;
  }
  renderView({ soft: true, animateCards: true });
  renderOverlays();
  requestAnimationFrame(() => document.querySelector("[data-today-batch-task]")?.focus());
}

function createResourceFromAction() {
  return createResource();
}

function createResource(title = "새 자료") {
  const createdAt = new Date().toISOString();
  const resource = normalizeResourceRecord({
    id: id(),
    title,
    type: "note",
    importance: "normal",
    pinned: false,
    readLater: false,
    url: "",
    boxId: "",
    projectId: "",
    createdAt,
    updatedAt: createdAt,
    revision: 1,
    timestampSource: "native",
    blocks: [{ id: id(), type: "paragraph", text: "", marks: [], checked: false, indent: 0, collapsed: false }],
  }, createdAt);
  state.resources.push(resource);
  dirtyResourceIds.add(resource.id);
  ui.activeResourceId = resource.id;
  if (ui.view !== "resources") {
    ui.view = "resources";
    updateNav();
  }
  saveState();
  renderView({ soft: true });
  renderOverlays();
  requestAnimationFrame(() => document.querySelector(`[data-resource-title="${cssEscape(resource.id)}"]`)?.focus());
  showToast("새 자료를 만들었습니다.");
  return resource;
}

function openResourceDocument(resourceId) {
  const resource = itemById("resources", resourceId);
  if (!resource || resource.trashedAt) return false;
  if (ui.activeResourceId && ui.activeResourceId !== resource.id) {
    cancelEditorMarqueeDrag();
    clearBlockSelection();
  }
  ui.activeResourceId = resource.id;
  ui.selectedBlockMenu = null;
  ui.inlineToolbar = null;
  ui.linkPopover = null;
  ui.resourceCitationPopover = null;
  ui.commentPopover = null;
  ui.equationPopover = null;
  renderView({ soft: true });
  renderOverlays();
  requestAnimationFrame(() => document.querySelector(`[data-resource-title="${cssEscape(resource.id)}"]`)?.focus({ preventScroll: true }));
  return true;
}

function closeResourceDocument() {
  const resourceId = ui.activeResourceId;
  cancelEditorMarqueeDrag();
  clearBlockSelection();
  ui.activeResourceId = "";
  ui.selectedBlockMenu = null;
  ui.inlineToolbar = null;
  ui.linkPopover = null;
  ui.resourceCitationPopover = null;
  ui.commentPopover = null;
  ui.equationPopover = null;
  renderView({ soft: true });
  renderOverlays();
  requestAnimationFrame(() => document.querySelector(`[data-resource-open="${cssEscape(resourceId)}"]`)?.focus({ preventScroll: true }));
}

function trapResourceDocumentFocus(event) {
  const dialog = els.detailRoot?.querySelector("[data-resource-document]");
  if (!dialog || event.key !== "Tab" || event.target.closest?.("[data-block-content][contenteditable='true']")) return false;
  const selector = "a[href], button:not([disabled]), summary, textarea:not([disabled]), input:not([disabled]):not([type='file']), select:not([disabled]), [contenteditable='true'], [tabindex]:not([tabindex='-1'])";
  const focusable = [dialog, els.overlayRoot]
    .flatMap((scope) => [...scope.querySelectorAll(selector)])
    .filter((element) => !element.hidden && element.getClientRects().length);
  if (!focusable.length) return false;
  const first = focusable[0];
  const last = focusable[focusable.length - 1];
  if (
    !focusable.includes(document.activeElement)
    || (!event.shiftKey && document.activeElement === last)
    || (event.shiftKey && document.activeElement === first)
  ) {
    event.preventDefault();
    event.stopPropagation();
    (event.shiftKey ? last : first).focus({ preventScroll: true });
    return true;
  }
  return false;
}

function codeLanguagePopoverIsOpen(menu) {
  if (!(menu instanceof HTMLElement) || typeof menu.matches !== "function") return false;
  try {
    return menu.matches(":popover-open");
  } catch {
    return false;
  }
}

function placeCodeLanguageMenu(picker) {
  if (!(picker instanceof HTMLElement)) return;
  const trigger = picker.querySelector("[data-code-language-trigger]");
  const menu = picker.querySelector(".code-language-menu");
  if (!trigger || !menu) return;
  const rect = trigger.getBoundingClientRect();
  const viewport = visualViewportBounds();
  const edge = 12;
  const gap = 7;
  const below = Math.max(0, viewport.bottom - rect.bottom - gap - edge);
  const above = Math.max(0, rect.top - gap - edge - viewport.top);
  const desired = Math.min(menu.scrollHeight + 2, 320, viewport.height - edge * 2);
  const opensUp = below < desired && above > below;
  const available = Math.max(0, opensUp ? above : below);
  picker.classList.toggle("opens-up", opensUp);
  if (!codeLanguagePopoverIsOpen(menu)) return;
  const width = Math.max(0, Math.min(190, viewport.width - edge * 2));
  const left = Math.max(viewport.left + edge, Math.min(rect.right - width, viewport.right - width - edge));
  const height = Math.min(desired, available || desired);
  const top = opensUp
    ? Math.max(viewport.top + edge, rect.top - gap - height)
    : Math.min(viewport.bottom - edge, rect.bottom + gap);
  menu.style.left = `${Math.round(left)}px`;
  menu.style.top = `${Math.round(top)}px`;
  menu.style.right = "auto";
  menu.style.bottom = "auto";
  menu.style.width = `${Math.round(width)}px`;
  menu.style.maxHeight = `${Math.max(0, Math.floor(height))}px`;
}

function openCodeLanguagePicker(picker, options = {}) {
  if (!(picker instanceof HTMLDetailsElement)) return;
  document.querySelectorAll(".code-language-picker[open]").forEach((other) => {
    if (other !== picker) closeCodeLanguagePicker(other);
  });
  const menu = picker.querySelector(".code-language-menu");
  const trigger = picker.querySelector("[data-code-language-trigger]");
  if (!menu || !trigger) return;
  picker.open = true;
  menu.hidden = false;
  if (typeof menu.showPopover === "function" && !codeLanguagePopoverIsOpen(menu)) {
    try {
      menu.showPopover();
    } catch {
      // Older web views keep the existing absolutely positioned fallback.
    }
  }
  trigger.setAttribute("aria-expanded", "true");
  placeCodeLanguageMenu(picker);
  if (options.focusFirst) {
    requestAnimationFrame(() => picker.querySelector("[data-code-language-value]")?.focus({ preventScroll: true }));
  }
}

function closeCodeLanguagePicker(picker, options = {}) {
  if (!(picker instanceof HTMLDetailsElement)) return;
  const menu = picker.querySelector(".code-language-menu");
  const trigger = picker.querySelector("[data-code-language-trigger]");
  if (codeLanguagePopoverIsOpen(menu) && typeof menu.hidePopover === "function") {
    try {
      menu.hidePopover();
    } catch {
      // The editor may have rerendered while the menu was closing.
    }
  }
  picker.open = false;
  picker.classList.remove("opens-up");
  trigger?.setAttribute("aria-expanded", "false");
  if (menu) {
    menu.hidden = true;
    menu.style.removeProperty("left");
    menu.style.removeProperty("top");
    menu.style.removeProperty("right");
    menu.style.removeProperty("bottom");
    menu.style.removeProperty("width");
    menu.style.removeProperty("max-height");
  }
  if (options.focus) trigger?.focus({ preventScroll: true });
}

function toggleCodeLanguagePicker(picker) {
  if (!(picker instanceof HTMLDetailsElement)) return;
  if (picker.open) closeCodeLanguagePicker(picker);
  else openCodeLanguagePicker(picker);
}

function scheduleCodeLanguagePositionSync(event = null) {
  if (event?.target?.closest?.(".code-language-menu")) return;
  if (codeLanguagePositionFrame) return;
  codeLanguagePositionFrame = window.requestAnimationFrame(() => {
    codeLanguagePositionFrame = 0;
    const picker = document.querySelector(".code-language-picker[open]");
    if (picker) placeCodeLanguageMenu(picker);
  });
}

function handleCodeLanguagePickerKeydown(event) {
  if (!(event.target instanceof Element)) return false;
  const targetPicker = event.target.closest(".code-language-picker");
  const openPicker = targetPicker?.open ? targetPicker : document.querySelector(".code-language-picker[open]");
  const picker = targetPicker || openPicker;
  if (!picker) return false;
  const trigger = picker.querySelector("[data-code-language-trigger]");
  const options = [...picker.querySelectorAll("[data-code-language-value]")].filter((option) => option.getClientRects().length);
  if (event.key === "Escape" && openPicker) {
    event.preventDefault();
    event.stopPropagation();
    closeCodeLanguagePicker(openPicker, { focus: true });
    return true;
  }
  if (event.target === trigger && event.key === "ArrowDown") {
    event.preventDefault();
    event.stopPropagation();
    openCodeLanguagePicker(picker, { focusFirst: true });
    return true;
  }
  const optionIndex = options.indexOf(event.target);
  if (optionIndex < 0 || !["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return false;
  event.preventDefault();
  event.stopPropagation();
  const nextIndex = event.key === "Home"
    ? 0
    : event.key === "End"
      ? options.length - 1
      : (optionIndex + (event.key === "ArrowDown" ? 1 : -1) + options.length) % options.length;
  options[nextIndex]?.focus({ preventScroll: true });
  return true;
}

function updateResourceTitle(input) {
  const resource = itemById("resources", input?.dataset.resourceTitle);
  if (!resourceMutationAllowed(resource)) return;
  const title = String(input.value || "").slice(0, MAX_RESOURCE_TITLE_LENGTH);
  if (resource.title === title) return;
  resource.title = title;
  markResourceChanged(resource);
  saveState();
}

function markResourceChanged(resourceOrId) {
  const resource = typeof resourceOrId === "string" ? itemById("resources", resourceOrId) : resourceOrId;
  if (!resourceMutationAllowed(resource)) return null;
  if (!dirtyResourceIds.has(resource.id)) return touchResource(resource);
  resource.updatedAt = new Date(Math.max(Date.now(), stateTimestamp(resource.updatedAt) + 1)).toISOString();
  return resource;
}

async function writePlainTextToClipboard(value = "") {
  const text = String(value || "");
  if (navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch (_) {
      // Fall through to the selection-based copy path.
    }
  }
  const activeElement = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const textarea = document.createElement("textarea");
  textarea.value = text;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.left = "-9999px";
  textarea.style.opacity = "0";
  document.body.appendChild(textarea);
  textarea.select();
  let copied = false;
  try {
    copied = document.execCommand("copy");
  } finally {
    textarea.remove();
    activeElement?.focus?.({ preventScroll: true });
  }
  if (!copied) throw new Error("Clipboard API unavailable");
  return true;
}

async function copyCodeBlock(control) {
  const ownerType = control?.dataset.ownerType || "";
  const ownerId = control?.dataset.ownerId || "";
  const blockId = control?.dataset.codeCopy || "";
  const block = itemById(ownerType, ownerId)?.blocks?.find((entry) => entry.id === blockId);
  if (!block || block.type !== "code") return false;
  try {
    await writePlainTextToClipboard(block.text || "");
    showToast("코드를 복사했습니다.");
    return true;
  } catch (_) {
    showToast("코드를 복사하지 못했습니다.");
    return false;
  }
}

function updateCodeBlockLanguage(control) {
  const ownerType = control?.dataset.ownerType || "";
  const ownerId = control?.dataset.ownerId || "";
  const blockId = control?.dataset.codeLanguageBlock || "";
  if (!editorOwnerMutationAllowed(ownerType, ownerId)) {
    renderEditorMutation(ownerType, ownerId);
    return false;
  }
  const item = itemById(ownerType, ownerId);
  const block = item?.blocks?.find((entry) => entry.id === blockId);
  if (!block || block.type !== "code") return false;
  const language = normalizeCodeLanguage(control.dataset.codeLanguageValue);
  if (normalizeCodeLanguage(block.language) === language) return true;
  const history = beginEditorHistory(ownerType, ownerId, { blockId, position: "end" });
  if (language) block.language = language;
  else delete block.language;
  if (ownerType === "resources") markResourceChanged(ownerId);
  commitEditorHistory(history, { blockId, position: "end" });
  saveState();
  renderEditorMutation(ownerType, ownerId);
  requestAnimationFrame(() => document.querySelector(`[data-code-language-trigger="${cssEscape(blockId)}"]`)?.focus({ preventScroll: true }));
  return true;
}

async function uploadResourceImageFile(file) {
  const response = await fetch("/api/resource-images", {
    method: "POST",
    headers: { "Content-Type": file.type },
    body: file,
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(payload.error || "이미지 업로드에 실패했습니다.");
  const url = normalizeResourceImageUrl(payload.url);
  if (!url) throw new Error("서버가 안전하지 않은 이미지 주소를 반환했습니다.");
  return url;
}

function insertResourceImageBlock(target, url, alt = "") {
  if (target.ownerType !== "resources" || !resourceMutationAllowed(target.ownerId)) return false;
  const resource = itemById("resources", target.ownerId);
  const index = resource?.blocks?.findIndex((block) => block.id === target.blockId) ?? -1;
  if (index < 0) return false;
  const block = resource.blocks[index];
  const safeRange = normalizeTextRange(target.range, (block.text || "").length);
  const replaceBlock = safeRange.start === 0 && safeRange.end === (block.text || "").length;
  const safeAlt = String(alt || "").slice(0, 2_000);
  const imageBlock = {
    id: replaceBlock ? block.id : id(),
    type: IMAGE_BLOCK_TYPE,
    text: safeAlt,
    alt: safeAlt,
    url,
    marks: [],
    checked: false,
    indent: blockIndent(block),
    collapsed: false,
  };
  const history = beginEditorHistory("resources", resource.id, { blockId: block.id, position: "end" });
  if (replaceBlock) resource.blocks.splice(index, 1, imageBlock);
  else resource.blocks.splice(index + 1, 0, imageBlock);
  markResourceChanged(resource);
  commitEditorHistory(history, { blockId: imageBlock.id, position: "end" });
  saveState();
  renderEditorMutation("resources", resource.id);
  requestAnimationFrame(() => document.querySelector(`[data-block-content="${cssEscape(imageBlock.id)}"]`)?.focus({ preventScroll: true }));
  return true;
}

function handleSelectedBlocksMenuOutsideClick(event) {
  if (!selectedBlocksMenuModeActive()) return false;
  if (!(event.target instanceof Element) || event.target.closest(".selected-block-menu")) return false;
  event.preventDefault();
  event.stopPropagation();
  const clickedBlockContent = event.target.closest("[data-block-content]");
  ui.selectedBlockMenu = null;
  clearBlockSelection();
  renderOverlays();
  if (clickedBlockContent) {
    focusBlockContentAtClientPoint(clickedBlockContent, event.clientX, event.clientY);
  } else {
    deactivateActiveBlockContent();
  }
  return true;
}

function handleSelectedBlocksMenuOutsidePointerDown(event) {
  if (!selectedBlocksMenuModeActive()) return false;
  if (!(event.target instanceof Element) || event.target.closest(".selected-block-menu")) return false;
  const blockTool = event.target.closest("[data-block-drag], [data-block-add], [data-block-toggle], [data-block-check]");
  const clickedBlockContent = event.target.closest("[data-block-content]");
  const menuSelection = selectedBlocksMenuSelection();
  const clickedBlock = event.target.closest(".block[data-block-id]");
  const clickedEditor = clickedBlock?.closest(".block-editor");
  const clickedSelectedBlock =
    menuSelection?.ids?.includes(clickedBlock?.dataset?.blockId || "") &&
    clickedEditor?.dataset?.ownerType === menuSelection.ownerType &&
    clickedEditor?.dataset?.ownerId === menuSelection.ownerId;
  ui.selectedBlockMenu = null;
  if (clickedSelectedBlock && menuSelection?.ids?.length) {
    restoreBlockSelection(menuSelection.ownerType, menuSelection.ownerId, menuSelection.ids);
    renderOverlays();
    return false;
  }
  clearBlockSelection();
  renderOverlays();
  if (blockTool) return false;
  event.preventDefault();
  event.stopPropagation();
  if (clickedBlockContent) {
    focusBlockContentAtClientPoint(clickedBlockContent, event.clientX, event.clientY);
  } else {
    deactivateActiveBlockContent();
  }
  return true;
}

function handleSubmit(event) {
  const form = event.target.closest("form");
  if (!form) return;
  event.preventDefault();
  if (form.dataset.form === "finance-login") {
    submitFinanceLogin(form);
    return;
  }
  if (form.dataset.form === "finance-account") {
    submitFinanceAccount(form);
    return;
  }
  if (form.dataset.form === "finance-payment-method") {
    submitFinancePaymentMethod(form);
    return;
  }
  if (form.dataset.form === "finance-loan") {
    submitFinanceLoan(form);
    return;
  }
  if (form.dataset.form === "finance-recurring-rule") {
    submitFinanceRecurringRule(form);
    return;
  }
  if (form.dataset.form === "finance-balance-check") {
    submitFinanceBalanceCheck(form);
    return;
  }
  if (form.dataset.form === "finance-expense") {
    submitFinanceExpense(form);
    return;
  }
  if (form.dataset.form === "finance-income") {
    submitFinanceIncome(form);
    return;
  }
  if (form.dataset.form === "finance-refund") {
    submitFinanceRefund(form);
    return;
  }
  if (form.dataset.form === "finance-transfer") {
    submitFinanceTransfer(form);
    return;
  }
  if (form.dataset.form === "finance-card-installment-setup") {
    submitFinanceCardInstallmentSetup(form);
    return;
  }
  if (form.dataset.form === "finance-card-statement") {
    submitFinanceCardStatement(form);
    return;
  }
  if (form.dataset.form === "finance-fixed-cost-payment") {
    submitFinanceFixedCostPayment(form);
    return;
  }
  if (form.dataset.form === "today-batch") {
    startTodayBatchPlacement(form.querySelector("[data-today-batch-input]")?.value || "");
    return;
  }
  if (form.matches("[data-inline-link-popover]")) {
    applyInlineLink(form.querySelector("[data-inline-link-input]")?.value || "");
    return;
  }
  if (form.matches("[data-inline-comment-popover]")) {
    applyInlineComment(form.querySelector("[data-inline-comment-input]")?.value || "");
    return;
  }
  if (form.matches("[data-inline-equation-popover]")) {
    applyInlineEquation(form.querySelector("[data-inline-equation-input]")?.value || "");
    return;
  }
  if (form.dataset.form === "quick-capture") {
    const input = form.elements.title;
    const title = input.value.trim();
    if (!title) return;
    state.captures.push({
      id: id(),
      title,
      url: title.match(/https?:\/\/\S+/)?.[0] || "",
      createdAt: new Date().toISOString(),
    });
    ui.todayInboxOpen = true;
    input.value = "";
    saveState();
    showToast("수집함에 추가했습니다.");
    if (["today", "database"].includes(ui.view)) renderView({ soft: true });
  }
}

function handleInput(event) {
  const financeIntegerInput = event.target.closest("[data-finance-integer-input]");
  if (financeIntegerInput && !event.isComposing) formatFinanceIntegerInput(financeIntegerInput);

  const financeInstallmentCount = event.target.closest('form[data-form="finance-card-installment-setup"] [name="installmentCount"]');

if (financeInstallmentCount && !event.isComposing) {
    syncFinanceCardInstallmentSetup(financeInstallmentCount.form);
    return;
  }

const financeInstallmentPayment = event.target.closest("[data-finance-installment-payment]");

if (financeInstallmentPayment && !event.isComposing) {
    syncFinanceCardInstallmentPreview(financeInstallmentPayment.form);
    return;
  }
  const financeStatementAdjustment = event.target.closest("[data-finance-statement-adjustment-amount]");
  if (financeStatementAdjustment) {
    const total = financeStatementAdjustment.form?.querySelector("[data-finance-statement-total]");
    const amount = financeIntegerValue(financeStatementAdjustment.value);
    if (total) total.textContent = formatFinanceKrw(Number(total.dataset.baseAmount || 0) + (Number.isSafeInteger(amount) && amount > 0 ? amount : 0));
    return;
  }

  const todayBatchInput = event.target.closest("[data-today-batch-input]");
  if (todayBatchInput && ui.todayBatch?.phase === "input") {
    ui.todayBatch.draft = todayBatchInput.value;
    return;
  }

  const resourceTitle = event.target.closest("[data-resource-title]");
  if (resourceTitle) {
    updateResourceTitle(resourceTitle);
    return;
  }

  const selectedBlockQuery = event.target.closest("[data-selected-block-query]");
  if (selectedBlockQuery) {
    updateSelectedBlockMenuQuery(selectedBlockQuery.value || "");
    return;
  }

  const resourceCitationQuery = event.target.closest("[data-resource-citation-query]");
  if (resourceCitationQuery) {
    updateResourceCitationQuery(resourceCitationQuery.value || "");
    return;
  }



  const inlineTaskTitle = event.target.closest("[data-task-inline-title]");
  if (inlineTaskTitle) {
    const task = itemById("tasks", inlineTaskTitle.dataset.taskInlineTitle);
    if (!task) return;
    task.title = inlineTaskTitle.value;
    saveState();
    const cardTitle = inlineTaskTitle.closest(".task-inline-item")?.querySelector(".card-title");
    if (cardTitle) cardTitle.textContent = task.title || "제목 없음";
    return;
  }

  const blockContent = event.target.closest("[data-block-content]");
  if (blockContent) {
    const editor = blockContent.closest(".block-editor");
    if (editor && !editorOwnerMutationAllowed(editor.dataset.ownerType, editor.dataset.ownerId)) {
      const resource = itemById("resources", editor.dataset.ownerId);
      const block = resource?.blocks?.find((entry) => entry.id === blockContent.dataset.blockContent);
      if (block) syncBlockContentMarkupFromState(blockContent, block);
      return;
    }
    if (isSelectedBlocksMenuOpen()) {
      event.preventDefault?.();
      renderView({ soft: true });
      renderOverlays();
      requestAnimationFrame(focusSelectedBlockMenuQuery);
      return;
    }
    if (isComposingBlock(blockContent)) {
      syncComposingBlockEmptyState(blockContent, event);
      return;
    }
    updateBlockText(blockContent, event);
    return;
  }

  const setting = event.target.closest("[data-setting]");
  if (setting) {
    state.settings[setting.dataset.setting] = setting.value;
    saveState();
  }
}

function handleChange(event) {
  const financeExpensePayment = event.target.closest("[data-finance-expense-payment-method], [data-finance-expense-card-payment-type]");

if (financeExpensePayment) {
    syncFinanceExpensePaymentFields(financeExpensePayment.closest("form"));
    return;
  }

const financeInstallmentEntry = event.target.closest("[data-finance-installment-entry]");

if (financeInstallmentEntry) {
    syncFinanceCardInstallmentSetup(financeInstallmentEntry.closest("form"));
    return;
  }
  const financePaymentType = event.target.closest("[data-finance-payment-type]");
  if (financePaymentType) {
    syncFinancePaymentMethodFields(financePaymentType.closest("form"));
    return;
  }
  const financeMonth = event.target.closest("[data-finance-month]");
  if (financeMonth) {
    if (/^\d{4}-(?:0[1-9]|1[0-2])$/.test(financeMonth.value)) financeWorkspace.month = financeMonth.value;
    if (ui.view === "finance") renderView({ soft: true, transition: true });
    requestAnimationFrame(() => els.viewRoot
      .querySelector("[data-finance-month]")
      ?.closest("[data-finance-select]")
      ?.querySelector("[data-finance-select-trigger]")
      ?.focus({ preventScroll: true }));
    return;
  }



  const calendarSource = event.target.closest("[data-calendar-source]");
  if (calendarSource) {
    setCalendarSourceVisible(calendarSource.dataset.calendarSource, calendarSource.checked);
    return;
  }

  const projectCalendarToggle = event.target.closest("[data-project-calendar-toggle]");
  if (projectCalendarToggle) {
    setProjectCalendarVisible(projectCalendarToggle.dataset.projectCalendarToggle, projectCalendarToggle.checked);
    return;
  }

  const googleCalendarToggle = event.target.closest("[data-google-calendar-toggle]");
  if (googleCalendarToggle) {
    setGoogleCalendarVisible(googleCalendarToggle.dataset.googleCalendarToggle, googleCalendarToggle.checked);
    return;
  }

  const field = event.target.closest("[data-field]");
  if (!field) return;
  const inlineOwner = field.closest("[data-inline-owner-type][data-inline-owner-id]");
  const inlineType = inlineOwner?.dataset.inlineOwnerType || "";
  const item = inlineOwner ? itemById(inlineType, inlineOwner.dataset.inlineOwnerId) : null;
  if (!item) return;
  let value = field.type === "checkbox" ? field.checked : field.value;
  if (value === "true") value = true;
  if (value === "false") value = false;
  if (field.type === "number") value = Number(value);
  const ownerType = inlineType || "";
  if (!editorOwnerMutationAllowed(ownerType, item.id)) {
    if (field.type === "checkbox") field.checked = Boolean(item[field.dataset.field]);
    else field.value = String(item[field.dataset.field] ?? "");
    return;
  }
  applyFieldValue(ownerType, item, field.dataset.field, value);
  saveState();
  renderView({ soft: true });
}

function applyFieldValue(ownerType, item, fieldName, value) {
  if (ownerType === "tasks") {
    applyTaskFieldValue(item, fieldName, value);
    return;
  }
  if (ownerType === "projects" && fieldName === "status") {
    item.status = normalizeProjectStatus(value);
    return;
  }
  item[fieldName] = value;
}

function applyTaskFieldValue(task, fieldName, value) {
  if (fieldName === "dueDate") {
    setTaskDate(task, value);
    return;
  }

  task[fieldName] = value;

  if (fieldName === "status") {
    task.completedAt = value === "done" ? task.completedAt || new Date().toISOString() : "";
  }

  if (["boxId", "projectId", "resourceId"].includes(fieldName)) {
    normalizeTaskRelations(task, fieldName);
  }
}

function handleBeforeInput(event) {
  const financeIntegerInput = event.target.closest("[data-finance-integer-input]");
  if (
    financeIntegerInput
    && event.inputType === "deleteContentBackward"
    && financeIntegerInput.selectionStart === financeIntegerInput.selectionEnd
    && financeIntegerInput.selectionStart > 1
    && financeIntegerInput.value[financeIntegerInput.selectionStart - 1] === ","
  ) {
    event.preventDefault();
    const end = financeIntegerInput.selectionStart;
    financeIntegerInput.value = `${financeIntegerInput.value.slice(0, end - 2)}${financeIntegerInput.value.slice(end)}`;
    financeIntegerInput.setSelectionRange(end - 2, end - 2);
    financeIntegerInput.dispatchEvent(new Event("input", { bubbles: true }));
    return;
  }

  const blockContent = event.target.closest("[data-block-content]");
  if (
    blockContent
    && (event.inputType === "historyUndo" || event.inputType === "historyRedo")
  ) {
    event.preventDefault();
    event.stopPropagation();
    if (event.inputType === "historyRedo") redoEditorHistory();
    else undoEditorHistory();
    return;
  }
  if (!blockContent) return;
  const ownerEditor = blockContent.closest(".block-editor");
  if (ownerEditor && !editorOwnerMutationAllowed(ownerEditor.dataset.ownerType, ownerEditor.dataset.ownerId)) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  if (isComposingInput(event, blockContent)) return;
  if (handlePendingSoftLineBreakBeforeInput(event, blockContent)) return;
  if (handlePendingMarkdownTextBeforeInput(event, blockContent)) return;
  if (event.inputType === "insertLineBreak" || (event.inputType === "insertParagraph" && event.shiftKey)) {
    event.preventDefault();
    event.stopPropagation();
    const editor = blockContent.closest(".block-editor");
    insertSoftLineBreak(editor.dataset.ownerType, editor.dataset.ownerId, blockContent.dataset.blockContent, blockContent);
    return;
  }
  if (event.inputType === "insertParagraph" && !event.shiftKey) {
    event.preventDefault();
    event.stopPropagation();
    if (shouldIgnoreDuplicateBlockParagraphInput(blockContent.dataset.blockContent)) return;
    const editor = blockContent.closest(".block-editor");
    if (insertCodeBlockLineBreak(editor.dataset.ownerType, editor.dataset.ownerId, blockContent.dataset.blockContent, blockContent)) return;
    insertBlockFromCaret(editor.dataset.ownerType, editor.dataset.ownerId, blockContent.dataset.blockContent, blockContent);
    return;
  }
  stageEditorTextHistoryBeforeInput(event, blockContent);
}

function handleCompositionStart(event) {
  const blockContent = event.target.closest("[data-block-content]");
  if (!blockContent) return;
  const editor = blockContent.closest(".block-editor");
  if (!editor || !editorOwnerMutationAllowed(editor.dataset.ownerType, editor.dataset.ownerId)) return;
  const offsets = selectionOffsetsInside(blockContent);
  beginEditorTextHistory(
    editor.dataset.ownerType,
    editor.dataset.ownerId,
    blockContent.dataset.blockContent,
    {
      blockId: blockContent.dataset.blockContent,
      start: offsets?.start ?? 0,
      end: offsets?.end ?? offsets?.start ?? 0,
    },
    { forceNew: true },
  );
  ui.composingBlockId = blockContent.dataset.blockContent;
  ui.compositionState = {
    blockId: blockContent.dataset.blockContent,
    start: Number.isInteger(offsets?.start) ? offsets.start : null,
    end: Number.isInteger(offsets?.end) ? offsets.end : null,
    text: blockContent.textContent || "",
  };
}

function handleCompositionUpdate(event) {
  const blockContent = event.target.closest("[data-block-content]");
  if (!blockContent) return;
  const editor = blockContent.closest(".block-editor");
  if (editor && !editorOwnerMutationAllowed(editor.dataset.ownerType, editor.dataset.ownerId)) return;
  syncComposingBlockEmptyState(blockContent, event);
}

function handleCompositionEnd(event) {
  const blockContent = event.target.closest("[data-block-content]");
  if (!blockContent) return;
  const editor = blockContent.closest(".block-editor");
  if (editor && !editorOwnerMutationAllowed(editor.dataset.ownerType, editor.dataset.ownerId)) return;
  const blockId = blockContent.dataset.blockContent;
  const compositionState = ui.compositionState?.blockId === blockId ? ui.compositionState : null;
  const currentText = blockContent.textContent || "";
  const replacedLength = Number.isInteger(compositionState?.start) && Number.isInteger(compositionState?.end)
    ? Math.max(0, compositionState.end - compositionState.start)
    : 0;
  const inferredCommittedLength = Number.isInteger(compositionState?.start) && typeof compositionState?.text === "string"
    ? Math.max(0, currentText.length - (compositionState.text.length - replacedLength))
    : null;
  const eventCommittedLength = typeof event.data === "string" && event.data.length > 0 ? event.data.length : null;
  const committedLength = Number.isInteger(eventCommittedLength) ? eventCommittedLength : inferredCommittedLength;
  const caretOffset = Number.isInteger(compositionState?.start) && Number.isInteger(committedLength)
    ? compositionState.start + committedLength
    : null;
  ui.recentCompositionCommit = {
    blockId,
    time: Date.now(),
    pending: true,
  };
  ui.composingBlockId = "";
  ui.compositionState = null;
  requestAnimationFrame(() => {
    if (!blockContent.isConnected) return;
    updateBlockText(blockContent);
    if (ui.recentCompositionCommit?.blockId === blockId) {
      ui.recentCompositionCommit.pending = false;
      ui.recentCompositionCommit.time = Date.now();
    }
    if (!Number.isInteger(caretOffset) || !blockContent.isConnected || document.activeElement !== blockContent) return;
    placeCaretAtTextOffset(blockContent, Math.min(caretOffset, (blockContent.textContent || "").length));
  });
}

function syncComposingBlockEmptyState(blockContent, event = null) {
  const text = normalizeEditorPlainText(blockContent?.textContent || "");
  const composingText = typeof event?.data === "string" ? event.data : "";
  blockContent?.classList?.toggle("is-empty", !text && !composingText);
}

function isComposingInput(event, blockContent = null) {
  if (event.isComposing || event.keyCode === 229) return true;
  return Boolean(blockContent && isComposingBlock(blockContent));
}

function isComposingBlock(blockContent) {
  return Boolean(ui.composingBlockId && blockContent?.dataset?.blockContent === ui.composingBlockId);
}

function handleRecentCompositionEnter(event, ownerType, ownerId, blockId, blockContent) {
  const recent = ui.recentCompositionCommit;
  if (
    !recent ||
    recent.blockId !== blockId ||
    event.key !== "Enter" ||
    event.shiftKey ||
    event.metaKey ||
    event.ctrlKey ||
    event.altKey ||
    Date.now() - recent.time > 220
  ) {
    return false;
  }
  const item = itemById(ownerType, ownerId);
  const block = item?.blocks?.find((entry) => entry.id === blockId);
  const domText = normalizeEditorPlainText(blockContent.textContent || "");
  const stateText = typeof block?.text === "string" ? block.text : "";
  if (!recent.pending && domText === stateText) return false;
  event.preventDefault();
  event.stopPropagation();
  markHandledBlockParagraphInput(blockId);
  ui.recentCompositionCommit = null;
  requestAnimationFrame(() => {
    if (!blockContent.isConnected) return;
    updateBlockText(blockContent);
    if (insertCodeBlockLineBreak(ownerType, ownerId, blockId, blockContent)) return;
    insertBlockFromCaret(ownerType, ownerId, blockId, blockContent);
  });
  return true;
}

function markHandledBlockParagraphInput(blockId) {
  ui.lastHandledBlockParagraphInput = {
    blockId,
    time: Date.now(),
  };
}

function shouldIgnoreDuplicateBlockParagraphInput(blockId) {
  const latest = ui.lastHandledBlockParagraphInput;
  if (!latest || latest.blockId !== blockId) return false;
  if (Date.now() - latest.time > 250) return false;
  ui.lastHandledBlockParagraphInput = null;
  return true;
}

function handleFocusIn(event) {
  const blockContent = event.target.closest("[data-block-content]");
  if (!blockContent) return;
  if (shouldPreserveBlockSelectionFocus(blockContent)) {
    blockContent.blur();
    return;
  }
  activateBlockContent(blockContent);
}

function handleFocusOut(event) {
  const financeSelect = event.target.closest("[data-finance-select]");
  if (financeSelect && !financeSelect.contains(event.relatedTarget)) closeFinanceSelect(financeSelect);
  const blockContent = event.target.closest("[data-block-content]");
  if (!blockContent) return;
  if (pendingEditorTextHistoryMatches(
    blockContent.closest(".block-editor")?.dataset.ownerType,
    blockContent.closest(".block-editor")?.dataset.ownerId,
    blockContent.dataset.blockContent,
  )) flushPendingEditorTextHistory();
  rememberEditableControlFocusRangeFromFocusOut(blockContent, event.relatedTarget);
  blockContent.classList.remove("is-active");
  blockContent.closest(".block")?.classList.remove("is-active-block");
  if (ui.activeBlockId === blockContent.dataset.blockContent) ui.activeBlockId = "";
}

function activateBlockContent(blockContent) {
  if (isSelectedBlocksMenuOpen()) {
    blockContent.blur();
    focusSelectedBlockMenuQuery();
    return;
  }
  if (ui.pendingEmptyContinuationExit?.blockId && ui.pendingEmptyContinuationExit.blockId !== blockContent.dataset.blockContent) {
    ui.pendingEmptyContinuationExit = null;
  }
  clearBlockSelection();
  ui.activeBlockId = blockContent.dataset.blockContent;
  const editor = blockContent.closest(".block-editor");
  ui.recentBlockFocus = {
    ownerType: editor?.dataset.ownerType || "",
    ownerId: editor?.dataset.ownerId || "",
    blockId: blockContent.dataset.blockContent,
    expiresAt: Date.now() + 60000,
  };
  app.querySelectorAll(".block-content.is-active").forEach((entry) => entry.classList.remove("is-active"));
  app.querySelectorAll(".block.is-active-block").forEach((entry) => entry.classList.remove("is-active-block"));
  blockContent.classList.toggle("is-empty", (blockContent.textContent || "") === "");
  blockContent.classList.add("is-active");
  blockContent.closest(".block")?.classList.add("is-active-block");
}

function shouldPreserveBlockSelectionFocus(blockContent) {
  if (!ui.blockSelection.ids.length) return false;
  const block = blockContent.closest(".block");
  const editor = blockContent.closest(".block-editor");
  if (!block || !editor) return false;
  const selected =
    ui.blockSelection.ownerType === editor.dataset.ownerType &&
    ui.blockSelection.ownerId === editor.dataset.ownerId &&
    ui.blockSelection.ids.includes(block.dataset.blockId);
  if (!selected) return false;
  return Boolean(ui.blockDrag) || ui.suppressBlockClickUntil > Date.now();
}

function deactivateActiveBlockContent(preserveRecentFocus = false) {
  ui.activeBlockId = "";
  if (!preserveRecentFocus) ui.recentBlockFocus = null;
  app.querySelectorAll(".block-content.is-active").forEach((entry) => entry.classList.remove("is-active"));
  app.querySelectorAll(".block.is-active-block").forEach((entry) => entry.classList.remove("is-active-block"));
}

function editorBottomClickTarget(event) {
  if (!(event.target instanceof Element)) return null;
  if (event.target.closest("button, input, select, textarea, summary, a, [contenteditable='true'], .selected-block-menu")) return null;
  const shell = event.target.closest(".task-inline-notes, .panel");
  if (!shell) return null;
  const editor = shell.querySelector(".block-editor");
  if (!editor) return null;
  const editorRect = editor.getBoundingClientRect();
  const shellRect = shell.getBoundingClientRect();
  const left = Math.min(editorRect.left, shellRect.left) - 120;
  const right = Math.max(editorRect.right, shellRect.right) + 120;
  if (event.clientX < left || event.clientX > right) return null;
  if (event.target.closest(".block")) return null;
  const belowLastBlock = event.clientY >= editorRect.bottom - 10 && event.clientY <= shellRect.bottom + 160;
  const insideEditorGap = event.clientY >= editorRect.top && event.clientY <= editorRect.bottom;
  return belowLastBlock || insideEditorGap ? editor : null;
}

function editorWhitespaceBlockClickTarget(event) {
  if (!(event.target instanceof Element)) return null;
  if (event.target.closest("button, input, select, textarea, summary, a, [contenteditable='true'], .selected-block-menu")) return null;
  const directBlock = event.target.closest(".block[data-block-id]");
  if (directBlock && !directBlock.hidden && directBlock.getAttribute("aria-hidden") !== "true") {
    return directBlock.querySelector("[data-block-content]");
  }
  const shell = event.target.closest(".task-inline-notes, .panel");
  const editor = shell?.querySelector(".block-editor");
  if (!editor) return null;
  const editorRect = editor.getBoundingClientRect();
  const shellRect = shell.getBoundingClientRect();
  const left = Math.min(editorRect.left, shellRect.left) - 120;
  const right = Math.max(editorRect.right, shellRect.right) + 120;
  if (event.clientX < left || event.clientX > right) return null;
  let nearest = null;
  let nearestDistance = Infinity;
  editor.querySelectorAll(".block[data-block-id]").forEach((block) => {
    if (block.hidden || block.getAttribute("aria-hidden") === "true") return;
    const rect = block.getBoundingClientRect();
    if (event.clientY < rect.top - 3 || event.clientY > rect.bottom + 3) return;
    const distance = Math.abs(event.clientY - (rect.top + rect.height / 2));
    if (distance < nearestDistance) {
      nearest = block;
      nearestDistance = distance;
    }
  });
  return nearest?.querySelector("[data-block-content]") || null;
}

function focusEditorBottom(ownerType, ownerId) {
  if (!editorOwnerMutationAllowed(ownerType, ownerId)) return;
  const item = itemById(ownerType, ownerId);
  if (!item) return;
  const editableBlocks = ensureEditableBlocks(item);
  let target = editableBlocks[editableBlocks.length - 1];
  const needsTrailingLine =
    !target ||
    target.type !== "paragraph" ||
    blockIndent(target) !== 0 ||
    (target.text || "") !== "";
  if (needsTrailingLine) {
    const history = beginEditorHistory(ownerType, ownerId, { blockId: target?.id || "", position: "end" });
    target = { id: id(), type: "paragraph", text: "", checked: false, indent: 0, collapsed: false };
    editableBlocks.push(target);
    commitEditorHistory(history, { blockId: target.id, start: 0, end: 0 });
    saveState();
    renderEditorMutation(ownerType, ownerId);
  }
  focusBlockContentAfterRender(target.id);
}









function renderEditorMutation(ownerType, ownerId, options = {}) {
  const refreshed = refreshBlockEditorsAfterMutation(ownerType, ownerId);
  if (!refreshed || (options.forceView && ownerType !== "resources")) renderView({ soft: true });
}































































































function beginBlockDrag(blockId, event, options = {}) {
  const captureElement = options.captureTarget instanceof Element ? options.captureTarget : null;
  const block = options.block || event.target.closest(".block") || captureElement?.closest(".block") || document.querySelector(`[data-block-id="${cssEscape(blockId)}"]`);
  const editor = options.editor || event.target.closest(".block-editor") || block?.closest(".block-editor") || captureElement?.closest(".block-editor");
  if (!block || !editor) return;
  const ownerType = editor.dataset.ownerType;
  const ownerId = editor.dataset.ownerId;
  if (!editorOwnerMutationAllowed(ownerType, ownerId)) return;
  const contentRect = block.querySelector(".block-content")?.getBoundingClientRect();
  const startedFromHandle = Boolean(captureElement?.matches?.("[data-block-drag]") || event.target.closest("[data-block-drag]"));
  const existingSelection =
    ui.blockSelection.ownerType === ownerType &&
    ui.blockSelection.ownerId === ownerId &&
    ui.blockSelection.ids.includes(blockId)
      ? orderedSelectedBlockIds(editor)
      : [];
  const item = itemById(ownerType, ownerId);
  const dragIds = existingSelection.length ? [...selectedBlockSubtreeIds(item?.blocks || [], existingSelection)] : blockDragIdsForBlock(item?.blocks || [], blockId);
  const selectionIds = existingSelection.length ? existingSelection : [blockId];
  const blockRect = block.getBoundingClientRect();
  if (!existingSelection.length) clearBlockSelection();
  ui.selectedBlockMenu = null;
  ui.inlineToolbar = null;
  ui.linkPopover = null;
  ui.resourceCitationPopover = null;
  ui.commentPopover = null;
  ui.blockDrag = {
    ownerType,
    ownerId,
    blockId,
    dragIds,
    selectionIds,
    pointerId: eventPointerId(event),
    startX: options.startX ?? event.clientX,
    startY: options.startY ?? event.clientY,
    indentOriginX: options.indentOriginX ?? (startedFromHandle && contentRect ? contentRect.left : event.clientX),
    dragX: event.clientX + 14,
    dragY: event.clientY + 14,
    dragWidth: Math.min(360, Math.max(220, blockRect.width || 260)),
    activationDistance: options.activationDistance ?? (startedFromHandle ? BLOCK_HANDLE_DRAG_ACTIVATION_DISTANCE : BLOCK_BODY_DRAG_ACTIVATION_DISTANCE),
    active: false,
    copyMode: Boolean(event.altKey),
    restoreSelectionOnCancel: options.restoreSelectionOnCancel !== false,
    openMenuOnClick: options.openMenuOnClick === true,
    editOnClickIfNotDragged: options.editOnClickIfNotDragged === true,
    targetId: "",
    position: "after",
  };
  ui.suppressBlockClickUntil = Date.now() + 700;
  dragIds.forEach((id) => {
    editor.querySelector(`[data-block-id="${id}"]`)?.classList.add("is-block-drag-source");
  });
  try {
    if (event.pointerId !== undefined) (options.captureTarget || event.target).setPointerCapture?.(event.pointerId);
  } catch (_) {}
  event.preventDefault();
  event.stopPropagation();
}

function eventPointerId(event) {
  return event.pointerId ?? "mouse";
}

function canStartCustomPointerDrag(event) {
  if (!event || event.isPrimary === false) return false;
  if (event.button !== undefined && event.button !== 0) return false;
  return true;
}


function customPointerDragPendingOrActive() {
  return Boolean(
    ui.pendingNavDrag ||
    ui.navPointerDrag ||
    ui.pendingBlockToolDrag ||
    ui.blockDrag ||
    ui.pendingEditorMarquee ||
    ui.editorMarquee ||
    ui.pendingTodayTaskDrag ||
    ui.todayTaskDrag ||
    ui.pendingDeleteDrag ||
    ui.deleteDrag ||
    ui.pendingScheduleDrag ||
    ui.scheduler?.dragging
  );
}

function handleCustomPointerDragSelectStart(event) {
  if (!customPointerDragPendingOrActive()) return;
  event.preventDefault();
}

function cancelPendingPointerDrags() {
  ui.pendingNavDrag = null;
  ui.pendingBlockToolDrag = null;
  if (ui.pendingEditorMarquee) {
    releaseEditorMarqueePointerCapture(ui.pendingEditorMarquee);
    ui.pendingEditorMarquee = null;
  }
  ui.pendingTodayTaskDrag = null;
  ui.pendingDeleteDrag = null;
  ui.pendingScheduleDrag = null;
}

function blockDragIdsForBlock(blocksList, blockId) {
  const index = blocksList.findIndex((block) => block.id === blockId);
  if (index < 0) return [blockId];
  const ids = [];
  const endIndex = blockSubtreeEndIndex(blocksList, index);
  for (let nextIndex = index; nextIndex <= endIndex; nextIndex += 1) {
    ids.push(blocksList[nextIndex].id);
  }
  return ids.length ? ids : [blockId];
}

function handleBlockPointerMove(event) {
  rememberSelectedBlockDragHover(event);
  const pendingToolDrag = ui.pendingBlockToolDrag;
  if (pendingToolDrag && sameMouseLikePointer(pendingToolDrag.pointerId, event)) {
    const distance = Math.hypot(event.clientX - pendingToolDrag.startX, event.clientY - pendingToolDrag.startY);
    pendingToolDrag.maxDistance = Math.max(pendingToolDrag.maxDistance || 0, distance);
    if (distance < BLOCK_HANDLE_DRAG_ACTIVATION_DISTANCE) return;
    const startedButton =
      pendingToolDrag.target instanceof Element &&
      pendingToolDrag.target.isConnected &&
      pendingToolDrag.target.matches?.(`[data-block-add="${cssEscape(pendingToolDrag.blockId)}"]`)
        ? pendingToolDrag.target
        : null;
    const button = startedButton || document.querySelector(`[data-block-add="${cssEscape(pendingToolDrag.blockId)}"]`);
    const block = button?.closest(".block");
    const editor = block?.closest(".block-editor");
    ui.pendingBlockToolDrag = null;
    if (!block || !editor) return;
    const blockIsSelectedForDrag =
      ui.blockSelection.ownerType === editor.dataset.ownerType &&
      ui.blockSelection.ownerId === editor.dataset.ownerId &&
      ui.blockSelection.ids.includes(pendingToolDrag.blockId);
    if (blockIsSelectedForDrag) {
      const selectedContentRect = block.querySelector(".block-content")?.getBoundingClientRect();
      beginBlockDrag(pendingToolDrag.blockId, event, {
        block,
        editor,
        captureTarget: pendingToolDrag.target || button,
        startX: pendingToolDrag.startX,
        startY: pendingToolDrag.startY,
        indentOriginX: selectedContentRect?.left ?? pendingToolDrag.startX,
        activationDistance: BLOCK_BODY_DRAG_ACTIVATION_DISTANCE,
      });
    } else {
      beginBlockDrag(pendingToolDrag.blockId, event, {
        block,
        editor,
        captureTarget: pendingToolDrag.target || button,
        startX: pendingToolDrag.startX,
        startY: pendingToolDrag.startY,
      });
    }
  }
  const drag = ui.blockDrag;
  if (!drag || drag.pointerId !== eventPointerId(event)) return;
  const distance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY);
  const activationDistance = Number.isFinite(drag.activationDistance) ? drag.activationDistance : 4;
  if (!drag.active && distance < activationDistance) return;
  const becameActive = !drag.active;
  const nextCopyMode = Boolean(event.altKey);
  const copyModeChanged = drag.copyMode !== nextCopyMode;
  drag.copyMode = nextCopyMode;
  drag.active = true;
  updateBlockDragGhostPosition(event.clientX, event.clientY);
  if (becameActive || copyModeChanged) renderOverlays();
  event.preventDefault();
  event.stopPropagation();
  const target = blockDragTargetFromPoint(drag.ownerType, drag.ownerId, event.clientX, event.clientY);
  setBlockDropTarget(target);
}

function finishBlockDrag(event) {
  if (ui.pendingBlockToolDrag && sameMouseLikePointer(ui.pendingBlockToolDrag.pointerId, event)) {
    const pendingToolDrag = ui.pendingBlockToolDrag;
    const distance = Math.hypot((event?.clientX ?? pendingToolDrag.startX) - pendingToolDrag.startX, (event?.clientY ?? pendingToolDrag.startY) - pendingToolDrag.startY);
    const movedEnoughToCancelClick = Math.max(pendingToolDrag.maxDistance || 0, distance) > BLOCK_HANDLE_DRAG_ACTIVATION_DISTANCE;
    ui.pendingBlockToolDrag = null;
    if (movedEnoughToCancelClick) {
      ui.suppressBlockAddClickUntil = Date.now() + 220;
      event.preventDefault();
      event.stopPropagation();
      return;
    }
  }
  const drag = ui.blockDrag;
  if (!drag || drag.pointerId !== eventPointerId(event)) return;
  event.preventDefault();
  cleanupBlockDragClasses();
  ui.blockDrag = null;
  renderOverlays();
  if (!drag.active) {
    ui.suppressBlockClickUntil = Date.now() + (drag.openMenuOnClick ? 260 : 80);
    if (drag.editOnClickIfNotDragged) {
      clearBlockSelection();
      const blockContent = document.querySelector(`[data-block-content="${cssEscape(drag.blockId)}"]`);
      if (blockContent) focusBlockContentAtClientPoint(blockContent, event.clientX, event.clientY);
      return;
    }
    if (drag.restoreSelectionOnCancel) {
      requestAnimationFrame(() => {
        restoreBlockSelection(drag.ownerType, drag.ownerId, drag.selectionIds || [drag.blockId]);
        if (drag.openMenuOnClick) openSelectedBlocksMenu();
      });
    }
    return;
  }
  ui.suppressBlockClickUntil = Date.now() + 160;
  if (!drag.targetId) {
    if (drag.restoreSelectionOnCancel && Array.isArray(drag.selectionIds) && drag.selectionIds.length) {
      requestAnimationFrame(() => restoreBlockSelection(drag.ownerType, drag.ownerId, drag.selectionIds));
    }
    return;
  }
  const dropAsCopy = drag.copyMode === true || event.altKey === true;
  if (dropAsCopy) {
    copyBlocksToDropTarget(drag.ownerType, drag.ownerId, drag.dragIds || [drag.blockId], drag.targetId, drag.position, {
      targetIndent: drag.targetIndent,
      selectionIds: drag.selectionIds || [drag.blockId],
    });
    return;
  }
  moveBlocks(drag.ownerType, drag.ownerId, drag.dragIds || [drag.blockId], drag.targetId, drag.position, {
    targetIndent: drag.targetIndent,
    preserveSelection: true,
    selectionIds: drag.selectionIds || [drag.blockId],
  });
}

function cancelBlockDrag(event) {
  if (event && ui.pendingBlockToolDrag && sameMouseLikePointer(ui.pendingBlockToolDrag.pointerId, event)) ui.pendingBlockToolDrag = null;
  if (event && ui.blockDrag?.pointerId !== eventPointerId(event)) return;
  const drag = ui.blockDrag;
  const restoreSelection =
    drag?.restoreSelectionOnCancel && Array.isArray(drag.selectionIds) && drag.selectionIds.length
      ? { ownerType: drag.ownerType, ownerId: drag.ownerId, ids: drag.selectionIds.slice() }
      : null;
  cleanupBlockDragClasses();
  ui.blockDrag = null;
  renderOverlays();
  ui.suppressBlockClickUntil = Date.now() + 250;
  if (restoreSelection) {
    requestAnimationFrame(() => restoreBlockSelection(restoreSelection.ownerType, restoreSelection.ownerId, restoreSelection.ids));
  }
}

function updateBlockDragGhostPosition(clientX, clientY) {
  const drag = ui.blockDrag;
  if (!drag) return;
  drag.dragX = clientX + 14;
  drag.dragY = clientY + 14;
  const ghost = document.querySelector(".block-drag-ghost");
  if (!ghost) return;
  ghost.style.left = `${Math.round(drag.dragX)}px`;
  ghost.style.top = `${Math.round(drag.dragY)}px`;
}

function blockDragTargetFromPoint(ownerType, ownerId, clientX, clientY) {
  const editor = document.querySelector(`.block-editor[data-owner-type="${ownerType}"][data-owner-id="${ownerId}"]`);
  if (!editor) return {};
  const editorRect = editor.getBoundingClientRect();
  const editorGutter = 112;
  if (clientX < editorRect.left - editorGutter || clientX > editorRect.right + editorGutter || clientY < editorRect.top - 80 || clientY > editorRect.bottom + 120) {
    return {};
  }
  const dragIds = new Set(ui.blockDrag?.dragIds || []);
  if (!dragIds.size && ui.blockDrag?.blockId) dragIds.add(ui.blockDrag.blockId);
  let firstBlock = null;
  let lastBlock = null;
  let matched = null;
  editor.querySelectorAll(".block").forEach((block) => {
    if (block.hidden || block.getAttribute("aria-hidden") === "true") return;
    if (dragIds.has(block.dataset.blockId)) return;
    if (!firstBlock) firstBlock = block;
    lastBlock = block;
    if (matched) return;
    const rect = block.getBoundingClientRect();
    if (clientY >= rect.top && clientY <= rect.bottom) matched = block;
  });
  if (!firstBlock) return {};
  const targetBlock = matched || (clientY < firstBlock.getBoundingClientRect().top ? firstBlock : lastBlock);
  const rect = targetBlock.getBoundingClientRect();
  const position = clientY < rect.top + rect.height / 2 ? "before" : "after";
  const blockIndentValue = normalizedBlockIndent(targetBlock.dataset.indent);
  const rawTargetIndent = blockDropIndentFromPoint(targetBlock, clientX);
  return {
    element: targetBlock,
    targetId: targetBlock.dataset.blockId,
    position,
    targetIndent: position === "before" ? Math.min(rawTargetIndent, blockIndentValue) : rawTargetIndent,
  };
}

function blockDropIndentFromPoint(block, clientX) {
  const baseIndent = normalizedBlockIndent(block?.dataset?.indent);
  const contentRect = block.querySelector(".block-content")?.getBoundingClientRect();
  if (contentRect && clientX > contentRect.right + 8) return baseIndent;
  const editor = block.closest(".block-editor");
  const indentSize = Number.parseFloat(getComputedStyle(editor || block).getPropertyValue("--block-indent-size")) || 28;
  const dragBaseIndent = blockDragBaseIndent();
  const dragDelta = blockDragHorizontalIndentDelta(clientX, indentSize);
  return Math.max(0, Math.min(MAX_BLOCK_INDENT, baseIndent + 1, dragBaseIndent + dragDelta));
}

function blockDragBaseIndent() {
  const drag = ui.blockDrag;
  if (!drag) return 0;
  const item = itemById(drag.ownerType, drag.ownerId);
  const baseId = drag.dragIds?.[0] || drag.blockId;
  const block = item?.blocks?.find((entry) => entry.id === baseId);
  return blockIndent(block);
}

function blockDragHorizontalIndentDelta(clientX, indentSize) {
  const drag = ui.blockDrag;
  if (!drag || !indentSize) return 0;
  const delta = clientX - (Number.isFinite(drag.indentOriginX) ? drag.indentOriginX : drag.startX);
  const deadZone = indentSize * 1.35;
  if (Math.abs(delta) < deadZone) return 0;
  return delta > 0
    ? Math.floor((delta - deadZone) / indentSize) + 1
    : Math.ceil((delta + deadZone) / indentSize) - 1;
}

function setBlockDropTarget(target = {}) {
  if (!ui.blockDrag) return;
  if (ui.blockDrag.targetId === target.targetId && ui.blockDrag.position === target.position && ui.blockDrag.targetIndent === target.targetIndent) return;
  cleanupBlockDropClasses();
  ui.blockDrag.targetId = target.targetId || "";
  ui.blockDrag.position = target.position || "after";
  ui.blockDrag.targetIndent = Number.isInteger(target.targetIndent) ? target.targetIndent : null;
  if (!target.element || (ui.blockDrag.dragIds || [ui.blockDrag.blockId]).includes(target.targetId)) return;
  if (Number.isInteger(ui.blockDrag.targetIndent)) target.element.style.setProperty("--block-drop-indent", String(ui.blockDrag.targetIndent));
  target.element.classList.add(target.position === "before" ? "is-block-drop-before" : "is-block-drop-after");
}

function cleanupBlockDropClasses() {
  document.querySelectorAll(".is-block-drop-before, .is-block-drop-after").forEach((entry) => {
    entry.classList.remove("is-block-drop-before", "is-block-drop-after");
    entry.style.removeProperty("--block-drop-indent");
  });
}

function cleanupBlockDragClasses() {
  cleanupBlockDropClasses();
  document.querySelectorAll(".is-block-drag-source").forEach((entry) => entry.classList.remove("is-block-drag-source"));
}

function copyBlocksToDropTarget(ownerType, ownerId, blockIds, targetId, position, options = {}) {
  if (!editorOwnerMutationAllowed(ownerType, ownerId)) return false;
  if (!blockIds.length || blockIds.includes(targetId)) return false;
  const item = itemById(ownerType, ownerId);
  if (!item?.blocks) return false;
  const sourceIds = new Set(blockIds);
  const sourceBlocks = item.blocks.filter((block) => sourceIds.has(block.id));
  if (!sourceBlocks.length) return false;
  const sourceToDuplicate = new Map();
  const duplicates = sourceBlocks.map((block) => {
    const duplicate = duplicateEditorBlock(block);
    sourceToDuplicate.set(block.id, duplicate.id);
    return duplicate;
  });
  const targetBlock = item.blocks.find((entry) => entry.id === targetId);
  const targetIndent = moveDropTargetIndent(targetBlock, options.targetIndent);
  normalizeMovedBlockIndentsForDrop(duplicates, targetBlock, targetIndent);
  const targetIndex = item.blocks.findIndex((entry) => entry.id === targetId);
  const history = beginEditorHistory(ownerType, ownerId, { blockId: sourceBlocks[0].id, position: "end" });
  if (targetIndex < 0) {
    item.blocks.push(...duplicates);
  } else {
    const insertIndex = moveDropInsertIndex(item.blocks, targetIndex, position, targetIndent);
    item.blocks.splice(insertIndex, 0, ...duplicates);
  }
  const selectionSourceIds = Array.isArray(options.selectionIds) && options.selectionIds.length ? options.selectionIds : blockIds;
  const duplicatedSelectionIds = selectionSourceIds.map((blockId) => sourceToDuplicate.get(blockId)).filter(Boolean);
  const preservedSelectionIds = duplicatedSelectionIds.length ? duplicatedSelectionIds : [duplicates[0].id];
  ui.blockSelection = { ownerType, ownerId, ids: preservedSelectionIds };
  commitEditorHistory(history, { blockId: preservedSelectionIds[0], position: "end" });
  saveState();
  if (!refreshBlockEditorsAfterMutation(ownerType, ownerId)) renderEditorMutation(ownerType, ownerId);
  requestAnimationFrame(() => restoreBlockSelection(ownerType, ownerId, preservedSelectionIds));
  return true;
}

function moveBlocks(ownerType, ownerId, blockIds, targetId, position, options = {}) {
  if (!editorOwnerMutationAllowed(ownerType, ownerId)) return false;
  if (!blockIds.length || blockIds.includes(targetId)) return false;
  const item = itemById(ownerType, ownerId);
  if (!item?.blocks) return false;
  const moveSet = new Set(blockIds);
  const moving = [];
  const remaining = [];
  const movedIds = [];
  item.blocks.forEach((block) => {
    if (moveSet.has(block.id)) {
      moving.push(block);
      movedIds.push(block.id);
    } else {
      remaining.push(block);
    }
  });
  if (!moving.length) return false;
  const history = beginEditorHistory(ownerType, ownerId, { blockId: moving[0].id, position: "end" });
  const targetBlock = item.blocks.find((entry) => entry.id === targetId);
  const targetIndent = moveDropTargetIndent(targetBlock, options.targetIndent);
  normalizeMovedBlockIndentsForDrop(moving, targetBlock, targetIndent);
  item.blocks = remaining;
  const targetIndex = item.blocks.findIndex((entry) => entry.id === targetId);
  if (targetIndex < 0) {
    item.blocks.push(...moving);
  } else {
    const insertIndex = moveDropInsertIndex(item.blocks, targetIndex, position, targetIndent);
    item.blocks.splice(insertIndex, 0, ...moving);
  }
  const preservedSelectionIds = Array.isArray(options.selectionIds) && options.selectionIds.length ? options.selectionIds.slice() : movedIds;
  const preserveSelection = options.preserveSelection === true || movedIds.length > 1;
  ui.blockSelection = movedIds.length > 1 ? { ownerType, ownerId, ids: movedIds } : { ownerType: "", ownerId: "", ids: [] };
  if (preserveSelection) ui.blockSelection = { ownerType, ownerId, ids: preservedSelectionIds };
  commitEditorHistory(history, { blockId: moving[0].id, position: "end" });
  saveState();
  if (!refreshBlockEditorsAfterMutation(ownerType, ownerId)) renderEditorMutation(ownerType, ownerId);
  if (preserveSelection) {
    restoreBlockSelection(ownerType, ownerId, preservedSelectionIds);
  } else {
    focusBlockContentAfterRender(moving[0].id);
  }
  return true;
}

function refreshBlockEditorsAfterMutation(ownerType, ownerId) {
  const item = itemById(ownerType, ownerId);
  if (!item?.blocks) return false;
  const selector = `.block-editor[data-owner-type="${cssEscape(ownerType)}"][data-owner-id="${cssEscape(ownerId)}"]`;
  const editors = [...document.querySelectorAll(selector)];
  if (!editors.length) return false;
  const blocksHtml = renderBlocks(item.blocks, ownerType, ownerId);
  for (const editor of editors) patchBlockEditorStructure(editor, blocksHtml);
  return true;
}

function patchBlockEditorStructure(editor, blocksHtml) {
  const template = document.createElement("template");
  template.innerHTML = blocksHtml;
  const existingBlocks = new Map(
    [...editor.querySelectorAll(".block[data-block-id]")].map((block) => [block.dataset.blockId, block]),
  );
  const reusableBlock = (nextBlock) => {
    const currentBlock = existingBlocks.get(nextBlock.dataset.blockId || "");
    if (!currentBlock || currentBlock.dataset.type !== nextBlock.dataset.type) return nextBlock.cloneNode(true);
    const currentContent = currentBlock.querySelector(":scope > [data-block-content], :scope > .block-semantic-wrap > [data-block-content]");
    const nextContent = nextBlock.querySelector(":scope > [data-block-content], :scope > .block-semantic-wrap > [data-block-content]");
    if (!currentContent || !nextContent || !currentContent.isEqualNode(nextContent)) return nextBlock.cloneNode(true);
    syncElementAttributes(currentBlock, nextBlock);
    for (const selector of [":scope > .block-check", ":scope > .block-toggle", ":scope > .block-list-marker", ":scope > .block-tool", ":scope > .block-drag-handle"]) {
      const currentControl = currentBlock.querySelector(selector);
      const nextControl = nextBlock.querySelector(selector);
      if (currentControl && nextControl) {
        syncElementAttributes(currentControl, nextControl);
        if (currentControl.textContent !== nextControl.textContent) currentControl.textContent = nextControl.textContent;
      }
    }
    return currentBlock;
  };

  const anchor = document.createComment("block-patch-anchor");
  editor.insertBefore(anchor, editor.firstChild);
  for (const nextTopLevel of [...template.content.children]) {
    if (nextTopLevel.matches(".block-list")) {
      const list = nextTopLevel.cloneNode(false);
      editor.insertBefore(list, anchor);
      for (const nextBlock of [...nextTopLevel.children]) {
        if (nextBlock.matches(".block[data-block-id]")) list.appendChild(reusableBlock(nextBlock));
      }
      continue;
    }
    if (nextTopLevel.matches(".block[data-block-id]")) editor.insertBefore(reusableBlock(nextTopLevel), anchor);
  }
  while (anchor.nextSibling) anchor.nextSibling.remove();
  anchor.remove();
}


function moveDropTargetIndent(targetBlock, targetIndent = null) {
  if (Number.isInteger(targetIndent)) return normalizedBlockIndent(targetIndent);
  return targetBlock ? blockIndent(targetBlock) : 0;
}

function moveDropInsertIndex(blocksList, targetIndex, position, targetIndent) {
  const parentIndex = containingParentIndexForBlock(blocksList, targetIndex, targetIndent);
  if (parentIndex >= 0) return blockSubtreeEndIndex(blocksList, parentIndex) + 1;
  return position === "before" ? targetIndex : blockSubtreeEndIndex(blocksList, targetIndex) + 1;
}

function normalizeMovedBlockIndentsForDrop(moving, targetBlock, targetIndent = null) {
  if (!moving.length) return;
  const currentBaseIndent = blockIndent(moving[0]);
  const nextBaseIndent = moveDropTargetIndent(targetBlock, targetIndent);
  const delta = nextBaseIndent - currentBaseIndent;
  if (!delta) return;
  for (const block of moving) {
    block.indent = normalizedBlockIndent(blockIndent(block) + delta);
  }
}

function orderedSelectedBlockIds(editor) {
  const selected = new Set(ui.blockSelection.ids);
  const ids = [];
  editor.querySelectorAll(".block").forEach((block) => {
    const blockId = block.dataset.blockId;
    if (selected.has(blockId)) ids.push(blockId);
  });
  return ids;
}

function restoreBlockSelection(ownerType, ownerId, ids) {
  const previousSelectionKey = blockSelectionAnnouncementKey(ui.blockSelection);
  const expandedIds = expandedBlockSelectionIds(ownerType, ownerId, ids);
  ui.blockSelection = { ownerType, ownerId, ids: expandedIds };
  if (expandedIds.length) {
    ui.recentBlockFocus = {
      ownerType,
      ownerId,
      blockId: expandedIds[0],
      expiresAt: Date.now() + 60000,
    };
  }
  if (expandedIds.length) clearInlineEditingOverlaysForBlockSelection();
  const editor = document.querySelector(`.block-editor[data-owner-type="${ownerType}"][data-owner-id="${ownerId}"]`);
  document.querySelectorAll(".block.is-selected").forEach((block) => {
    if (!editor || !editor.contains(block) || !expandedIds.includes(block.dataset.blockId)) {
      block.classList.remove("is-selected");
    }
  });
  if (!editor) return;
  editor.querySelectorAll(".block").forEach((block) => {
    block.classList.toggle("is-selected", expandedIds.includes(block.dataset.blockId));
  });
  document.activeElement?.blur();
  if (expandedIds.length && previousSelectionKey !== blockSelectionAnnouncementKey(ui.blockSelection)) {
    announceBlockSelection(expandedIds.length);
  }
}

function blockSelectionAnnouncementKey(selection = {}) {
  return `${selection.ownerType || ""}:${selection.ownerId || ""}:${(selection.ids || []).join(",")}`;
}

function announceAppStatus(message) {
  const target = document.querySelector(".resource-document [data-resource-announcements]")
    || els.appAnnouncements
    || document.querySelector("#appAnnouncements");
  if (!target) return;
  window.clearTimeout(appAnnouncementTimer);
  target.textContent = "";
  appAnnouncementTimer = window.setTimeout(() => {
    if (target.isConnected) target.textContent = message;
  }, 20);
}

function announceBlockSelection(count) {
  announceAppStatus(count > 0 ? `${count}개 블록 선택됨` : "블록 선택 해제됨");
}

function expandedBlockSelectionIds(ownerType, ownerId, ids = []) {
  const item = itemById(ownerType, ownerId);
  if (!item?.blocks || !ids.length) return ids.slice();
  const expanded = selectedBlockSubtreeIds(item.blocks, ids);
  return item.blocks.map((block) => block.id).filter((blockId) => expanded.has(blockId));
}









function resourceEditorMarqueeTarget(event) {
  if (!(event?.target instanceof Element) || !canStartCustomPointerDrag(event)) return null;
  if (event.target.closest("button, input, select, textarea, summary, a, [contenteditable='true'], .selected-block-menu, .inline-format-toolbar")) return null;
  const documentPanel = event.target.closest(".resource-document");
  const editor = documentPanel?.querySelector('.block-editor[data-owner-type="resources"]');
  if (!documentPanel || !editor) return null;
  const panelRect = documentPanel.getBoundingClientRect();
  const editorRect = editor.getBoundingClientRect();
  const gutterLeft = Math.max(panelRect.left + 4, editorRect.left - EDITOR_MARQUEE_GUTTER_WIDTH);
  const gutterRight = editorRect.left + 10;
  const verticalBottom = Math.max(editorRect.bottom + 72, panelRect.bottom - 24);
  if (event.clientX < gutterLeft || event.clientX > gutterRight) return null;
  if (event.clientY < editorRect.top - 8 || event.clientY > verticalBottom) return null;
  return { documentPanel, editor };
}

function beginPendingEditorMarquee(event) {
  const target = resourceEditorMarqueeTarget(event);
  if (!target) return false;
  cancelEditorMarqueeDrag();
  const captureTarget = event.target instanceof Element ? event.target : target.documentPanel;
  ui.pendingEditorMarquee = {
    editor: target.editor,
    documentPanel: target.documentPanel,
    ownerType: target.editor.dataset.ownerType,
    ownerId: target.editor.dataset.ownerId,
    pointerId: eventPointerId(event),
    startX: event.clientX,
    startY: event.clientY,
    captureTarget,
  };
  try {
    if (event.pointerId !== undefined && captureTarget.setPointerCapture) captureTarget.setPointerCapture(event.pointerId);
  } catch (_) {}
  event.preventDefault();
  event.stopPropagation();
  return true;
}

function releaseEditorMarqueePointerCapture(drag) {
  if (!drag?.captureTarget?.releasePointerCapture || drag.pointerId === "mouse") return;
  try {
    drag.captureTarget.releasePointerCapture(drag.pointerId);
  } catch (_) {}
}

function visibleEditorMarqueeBlocks(editor) {
  return [...(editor?.querySelectorAll(".block[data-block-id]") || [])].filter((block) => (
    !block.hidden && block.getAttribute("aria-hidden") !== "true" && block.getClientRects().length
  ));
}

function nearestEditorMarqueeBlock(blocks, clientY) {
  let nearest = null;
  let nearestDistance = Infinity;
  for (const block of blocks) {
    const rect = block.getBoundingClientRect();
    const distance = clientY < rect.top
      ? rect.top - clientY
      : clientY > rect.bottom
        ? clientY - rect.bottom
        : 0;
    if (distance < nearestDistance) {
      nearest = block;
      nearestDistance = distance;
    }
  }
  return nearest;
}

function sameEditorMarqueeSelection(ownerType, ownerId, ids) {
  return ui.blockSelection.ownerType === ownerType
    && ui.blockSelection.ownerId === ownerId
    && ui.blockSelection.ids.length === ids.length
    && ui.blockSelection.ids.every((id, index) => id === ids[index]);
}

function renderEditorMarqueeRect(drag, selectedBlocks) {
  const marquee = drag.marqueeElement;
  if (!marquee || !selectedBlocks.length) return;
  const scrollerRect = drag.documentPanel.getBoundingClientRect();
  const editorRect = drag.editor.getBoundingClientRect();
  const firstRect = selectedBlocks[0].getBoundingClientRect();
  const lastRect = selectedBlocks[selectedBlocks.length - 1].getBoundingClientRect();
  const left = Math.max(scrollerRect.left + 2, editorRect.left - EDITOR_MARQUEE_GUTTER_WIDTH + 2);
  const right = Math.min(scrollerRect.right - 2, editorRect.right + 2);
  const top = Math.max(scrollerRect.top + 2, Math.min(firstRect.top, lastRect.top) - 1);
  const bottom = Math.min(scrollerRect.bottom - 2, Math.max(firstRect.bottom, lastRect.bottom) + 1);
  marquee.style.left = `${Math.round(left)}px`;
  marquee.style.top = `${Math.round(top)}px`;
  marquee.style.width = `${Math.max(1, Math.round(right - left))}px`;
  marquee.style.height = `${Math.max(1, Math.round(bottom - top))}px`;
}

function updateEditorMarqueeSelection(drag, clientY, options = {}) {
  if (!drag?.editor?.isConnected || !drag.documentPanel?.isConnected) return;
  drag.lastY = clientY;
  const blocks = visibleEditorMarqueeBlocks(drag.editor);
  if (!blocks.length) return;
  const anchorIndex = Math.max(0, blocks.findIndex((block) => block.dataset.blockId === drag.anchorBlockId));
  const focusBlock = nearestEditorMarqueeBlock(blocks, clientY);
  const focusIndex = Math.max(0, blocks.indexOf(focusBlock));
  const start = Math.min(anchorIndex, focusIndex);
  const end = Math.max(anchorIndex, focusIndex);
  const selectedBlocks = blocks.slice(start, end + 1);
  const ids = selectedBlocks.map((block) => block.dataset.blockId).filter(Boolean);
  const expandedIds = expandedBlockSelectionIds(drag.ownerType, drag.ownerId, ids);
  if (ids.length && !sameEditorMarqueeSelection(drag.ownerType, drag.ownerId, expandedIds)) {
    restoreBlockSelection(drag.ownerType, drag.ownerId, ids);
  }
  renderEditorMarqueeRect(drag, selectedBlocks);
  if (!options.skipAutoScroll) updateEditorMarqueeAutoScroll(drag);
}

function updateEditorMarqueeAutoScroll(drag) {
  const rect = drag.documentPanel.getBoundingClientRect();
  const y = drag.lastY;
  let velocity = 0;
  if (y < rect.top + EDITOR_MARQUEE_AUTOSCROLL_EDGE) {
    velocity = -Math.max(2, Math.min(16, (rect.top + EDITOR_MARQUEE_AUTOSCROLL_EDGE - y) * 0.32));
  } else if (y > rect.bottom - EDITOR_MARQUEE_AUTOSCROLL_EDGE) {
    velocity = Math.max(2, Math.min(16, (y - (rect.bottom - EDITOR_MARQUEE_AUTOSCROLL_EDGE)) * 0.32));
  }
  if (!velocity) {
    stopDragAutoScroll("marquee");
    return;
  }
  if (ui.dragAutoScroll?.mode === "marquee") {
    ui.dragAutoScroll.velocity = velocity;
    return;
  }
  stopDragAutoScroll();
  const autoScroll = { mode: "marquee", velocity, frame: 0 };
  const step = () => {
    if (ui.dragAutoScroll !== autoScroll || ui.editorMarquee !== drag) return;
    const before = drag.documentPanel.scrollTop;
    drag.documentPanel.scrollTop += autoScroll.velocity;
    updateEditorMarqueeSelection(drag, drag.lastY, { skipAutoScroll: true });
    if (Math.abs(drag.documentPanel.scrollTop - before) < 0.5) {
      stopDragAutoScroll("marquee");
      return;
    }
    autoScroll.frame = requestAnimationFrame(step);
  };
  ui.dragAutoScroll = autoScroll;
  autoScroll.frame = requestAnimationFrame(step);
}

function activatePendingEditorMarquee(pending, event) {
  const blocks = visibleEditorMarqueeBlocks(pending.editor);
  const anchorBlock = nearestEditorMarqueeBlock(blocks, pending.startY);
  if (!anchorBlock) {
    ui.pendingEditorMarquee = null;
    return null;
  }
  const marqueeElement = document.createElement("div");
  marqueeElement.className = "editor-marquee";
  marqueeElement.setAttribute("aria-hidden", "true");
  document.body.append(marqueeElement);
  const drag = {
    ...pending,
    active: true,
    anchorBlockId: anchorBlock.dataset.blockId,
    lastY: event.clientY,
    marqueeElement,
  };
  ui.pendingEditorMarquee = null;
  ui.editorMarquee = drag;
  clearBlockSelection();
  clearInlineEditingOverlaysForBlockSelection();
  window.getSelection()?.removeAllRanges();
  deactivateActiveBlockContent(true);
  updateEditorMarqueeSelection(drag, event.clientY);
  return drag;
}

function handleEditorMarqueePointerMove(event) {
  const pending = ui.pendingEditorMarquee;
  if (pending && sameMouseLikePointer(pending.pointerId, event)) {
    const distance = Math.hypot(event.clientX - pending.startX, event.clientY - pending.startY);
    if (distance < EDITOR_MARQUEE_ACTIVATION_DISTANCE) return;
    activatePendingEditorMarquee(pending, event);
  }
  const drag = ui.editorMarquee;
  if (!drag || !sameMouseLikePointer(drag.pointerId, event)) return;
  event.preventDefault();
  event.stopPropagation();
  updateEditorMarqueeSelection(drag, event.clientY);
}

function finishEditorMarqueeDrag(event) {
  const pending = ui.pendingEditorMarquee;
  if (pending && (!event || sameMouseLikePointer(pending.pointerId, event))) {
    ui.pendingEditorMarquee = null;
    releaseEditorMarqueePointerCapture(pending);
    return;
  }
  const drag = ui.editorMarquee;
  if (!drag || (event && !sameMouseLikePointer(drag.pointerId, event))) return;
  event?.preventDefault?.();
  event?.stopPropagation?.();
  stopDragAutoScroll("marquee");
  drag.marqueeElement?.remove();
  ui.editorMarquee = null;
  ui.suppressBlockClickUntil = Date.now() + 260;
  releaseEditorMarqueePointerCapture(drag);
}

function cancelEditorMarqueeDrag(event) {
  const carriesPointerIdentity = Boolean(event && (event.pointerId !== undefined || /^(?:mouse|pointer)/.test(event.type || "")));
  let cancelledAnyMarquee = false;
  if (ui.pendingEditorMarquee && (!event || !carriesPointerIdentity || sameMouseLikePointer(ui.pendingEditorMarquee.pointerId, event))) {
    const pending = ui.pendingEditorMarquee;
    ui.pendingEditorMarquee = null;
    releaseEditorMarqueePointerCapture(pending);
    cancelledAnyMarquee = true;
  }
  if (!ui.editorMarquee) {
    if (cancelledAnyMarquee) ui.suppressBlockClickUntil = Date.now() + 260;
    return;
  }
  if (event && carriesPointerIdentity && !sameMouseLikePointer(ui.editorMarquee.pointerId, event)) return;
  const drag = ui.editorMarquee;
  const wasActive = drag.active === true;
  stopDragAutoScroll("marquee");
  drag.marqueeElement?.remove();
  ui.editorMarquee = null;
  releaseEditorMarqueePointerCapture(drag);
  if (wasActive) {
    clearBlockSelection();
    window.getSelection()?.removeAllRanges();
  }
  if (cancelledAnyMarquee || wasActive) {
    ui.suppressBlockClickUntil = Date.now() + 260;
  }
}






function stopDragAutoScroll(mode = "") {
  if (!ui.dragAutoScroll) return;
  if (mode && ui.dragAutoScroll.mode !== mode) return;
  cancelAnimationFrame(ui.dragAutoScroll.frame);
  ui.dragAutoScroll = null;
}




function handleBlockSelectAll(blockContent, ownerType, ownerId) {
  const blockId = blockContent?.dataset?.blockContent || "";
  if (!blockId) return;
  selectSingleBlock(ownerType, ownerId, blockId);
}

function handleBlockContentSelectAllShortcut(blockContent, ownerType, ownerId) {
  const blockId = blockContent?.dataset?.blockContent || "";
  if (!blockId) return;
  const textLength = (blockContent.textContent || "").length;
  const offsets = selectionOffsetsInside(blockContent);
  const fullySelected =
    textLength > 0 &&
    offsets &&
    !offsets.collapsed &&
    offsets.start <= 0 &&
    offsets.end >= textLength;
  if (textLength > 0 && !fullySelected) {
    clearBlockSelection();
    ui.selectedBlockMenu = null;
    ui.linkPopover = null;
    ui.resourceCitationPopover = null;
    ui.commentPopover = null;
    blockContent.focus();
    activateBlockContent(blockContent);
    setSelectionOffsets(blockContent, 0, textLength);
    return;
  }
  handleBlockSelectAll(blockContent, ownerType, ownerId);
}

function selectSingleBlock(ownerType, ownerId, blockId) {
  const editor = document.querySelector(`.block-editor[data-owner-type="${ownerType}"][data-owner-id="${ownerId}"]`);
  if (!editor) return;
  ui.pendingMarkdownTextTarget = null;
  ui.pendingEmptyContinuationExit = null;
  clearBlockSelection();
  restoreBlockSelection(ownerType, ownerId, [blockId]);
  window.getSelection()?.removeAllRanges();
  deactivateActiveBlockContent(true);
  document.activeElement?.blur();
}

function selectAllBlocks(ownerType, ownerId) {
  const editor = document.querySelector(`.block-editor[data-owner-type="${ownerType}"][data-owner-id="${ownerId}"]`);
  if (!editor) return;
  ui.pendingMarkdownTextTarget = null;
  ui.pendingEmptyContinuationExit = null;
  const ids = [];
  editor.querySelectorAll(".block").forEach((block) => {
    block.classList.add("is-selected");
    ids.push(block.dataset.blockId);
  });
  ui.blockSelection = { ownerType, ownerId, ids };
  if (ids.length) clearInlineEditingOverlaysForBlockSelection();
  const selection = window.getSelection();
  selection?.removeAllRanges();
  deactivateActiveBlockContent();
  document.activeElement?.blur();
  if (ids.length) announceBlockSelection(ids.length);
}

function focusSelectedBlockForEditing(position = "end") {
  const selection = ui.blockSelection;
  if (!selection.ids.length) return false;
  const editor = document.querySelector(`.block-editor[data-owner-type="${selection.ownerType}"][data-owner-id="${selection.ownerId}"]`);
  if (!editor) {
    clearBlockSelection();
    return false;
  }
  const selected = new Set(selection.ids);
  let targetBlock = null;
  editor.querySelectorAll(".block").forEach((block) => {
    if (targetBlock || block.hidden || block.getAttribute("aria-hidden") === "true") return;
    if (selected.has(block.dataset.blockId)) targetBlock = block;
  });
  const targetId = targetBlock?.dataset.blockId || selection.ids[0];
  clearBlockSelection();
  focusBlockContentAtPosition(targetId, position);
  return true;
}

function moveSelectedBlockSelection(direction, expand = false) {
  const selection = ui.blockSelection;
  if (!selection.ids.length) return false;
  const editor = document.querySelector(`.block-editor[data-owner-type="${selection.ownerType}"][data-owner-id="${selection.ownerId}"]`);
  if (!editor) {
    clearBlockSelection();
    return false;
  }
  const visibleIds = visibleBlockIdsInEditor(editor);
  if (!visibleIds.length) return false;
  const selectedVisibleIds = visibleIds.filter((id) => selection.ids.includes(id));
  if (!selectedVisibleIds.length) return false;
  const firstIndex = visibleIds.indexOf(selectedVisibleIds[0]);
  const lastIndex = visibleIds.indexOf(selectedVisibleIds[selectedVisibleIds.length - 1]);
  if (expand) {
    const nextIndex = direction > 0 ? lastIndex + 1 : firstIndex - 1;
    if (nextIndex < 0 || nextIndex >= visibleIds.length) return true;
    const nextIds = direction > 0
      ? [...selectedVisibleIds, visibleIds[nextIndex]]
      : [visibleIds[nextIndex], ...selectedVisibleIds];
    restoreBlockSelection(selection.ownerType, selection.ownerId, nextIds);
    return true;
  }
  const nextIndex = Math.max(0, Math.min(visibleIds.length - 1, direction > 0 ? lastIndex + 1 : firstIndex - 1));
  restoreBlockSelection(selection.ownerType, selection.ownerId, [visibleIds[nextIndex]]);
  return true;
}

function visibleBlockIdsInEditor(editor) {
  const ids = [];
  editor.querySelectorAll(".block").forEach((block) => {
    if (block.hidden || block.getAttribute("aria-hidden") === "true") return;
    const blockId = block.dataset.blockId;
    if (blockId) ids.push(blockId);
  });
  return ids;
}

function clearBlockSelection() {
  const selectedBlocks = [...document.querySelectorAll(".block.is-selected")];
  if (!ui.blockSelection.ids.length && !selectedBlocks.length) return;
  selectedBlocks.forEach((block) => block.classList.remove("is-selected"));
  ui.blockSelection = { ownerType: "", ownerId: "", ids: [] };
  ui.selectedBlockDragHover = null;
  announceBlockSelection(0);
}

function clearInlineEditingOverlaysForBlockSelection() {
  const hadInlineOverlay = Boolean(ui.inlineToolbar || ui.linkPopover || ui.resourceCitationPopover || ui.commentPopover || ui.equationPopover);
  ui.inlineToolbar = null;
  ui.linkPopover = null;
  ui.resourceCitationPopover = null;
  ui.commentPopover = null;
  ui.equationPopover = null;
  if (hadInlineOverlay) renderOverlays();
}

function handleBlockSelectionClick(event) {
  if (!(event.shiftKey || ui.shiftKeyDown) || !(event.target instanceof Element)) return false;
  if (event.target.closest("button, input, select, textarea, summary, a, .selected-block-menu, .inline-format-toolbar, .inline-link-popover, .resource-citation-popover, .inline-comment-popover")) return false;
  const block = event.target.closest(".block[data-block-id]");
  const editor = block?.closest(".block-editor");
  const blockId = block?.dataset?.blockId || "";
  if (!block || !editor || !blockId) return false;
  const ownerType = editor.dataset.ownerType;
  const ownerId = editor.dataset.ownerId;
  event.preventDefault();
  event.stopPropagation();
  ui.pendingMarkdownTextTarget = null;
  ui.pendingEmptyContinuationExit = null;
  window.getSelection()?.removeAllRanges();
  if (event.metaKey || event.altKey) {
    toggleBlockSelectionByClick(ownerType, ownerId, blockId);
  } else {
    selectBlockRangeByClick(editor, ownerType, ownerId, blockId);
  }
  deactivateActiveBlockContent(true);
  return true;
}

function toggleBlockSelectionByClick(ownerType, ownerId, blockId) {
  const item = itemById(ownerType, ownerId);
  if (!item?.blocks) return;
  const sameSelection = ui.blockSelection.ownerType === ownerType && ui.blockSelection.ownerId === ownerId;
  const currentIds = sameSelection ? ui.blockSelection.ids.slice() : [];
  const currentSet = new Set(currentIds);
  const clickedSubtree = selectedBlockSubtreeIds(item.blocks, [blockId]);
  if (currentSet.has(blockId)) {
    const nextIds = currentIds.filter((id) => !clickedSubtree.has(id));
    if (nextIds.length) {
      restoreBlockSelection(ownerType, ownerId, nextIds);
    } else {
      clearBlockSelection();
    }
    return;
  }
  restoreBlockSelection(ownerType, ownerId, [...currentIds, blockId]);
}

function selectBlockRangeByClick(editor, ownerType, ownerId, blockId) {
  const visibleIds = visibleBlockIdsInEditor(editor);
  if (!visibleIds.length || !visibleIds.includes(blockId)) {
    restoreBlockSelection(ownerType, ownerId, [blockId]);
    return;
  }
  const anchorId = blockRangeSelectionAnchorId(ownerType, ownerId, visibleIds, blockId);
  const anchorIndex = visibleIds.indexOf(anchorId);
  const blockIndex = visibleIds.indexOf(blockId);
  if (anchorIndex < 0 || blockIndex < 0) {
    restoreBlockSelection(ownerType, ownerId, [blockId]);
    return;
  }
  const start = Math.min(anchorIndex, blockIndex);
  const end = Math.max(anchorIndex, blockIndex);
  restoreBlockSelection(ownerType, ownerId, visibleIds.slice(start, end + 1));
}

function blockRangeSelectionAnchorId(ownerType, ownerId, visibleIds, fallbackId) {
  if (ui.blockSelection.ownerType === ownerType && ui.blockSelection.ownerId === ownerId) {
    const selectedVisible = visibleIds.filter((id) => ui.blockSelection.ids.includes(id));
    if (selectedVisible.length) return selectedVisible[0];
  }
  const recent = ui.recentBlockFocus;
  if (ui.activeBlockId && recent?.blockId === ui.activeBlockId && recent.ownerType === ownerType && recent.ownerId === ownerId && visibleIds.includes(ui.activeBlockId)) {
    return ui.activeBlockId;
  }
  if (recent && recent.ownerType === ownerType && recent.ownerId === ownerId && Date.now() <= recent.expiresAt && visibleIds.includes(recent.blockId)) {
    return recent.blockId;
  }
  return fallbackId;
}







function pushEditorHistoryEntry(entry) {
  if (!entry) return false;
  ui.editorHistory.undo.push(entry);
  if (ui.editorHistory.undo.length > ui.editorHistory.limit) ui.editorHistory.undo.shift();
  ui.editorHistory.redo = [];
  return true;
}

function beginEditorHistory(ownerType, ownerId, focus = null, options = {}) {
  if (!options.skipPendingTextFlush) flushPendingEditorTextHistory();
  if (!editorOwnerMutationAllowed(ownerType, ownerId)) return null;
  const item = itemById(ownerType, ownerId);
  if (!item?.blocks) return null;
  return {
    ownerType,
    ownerId,
    beforeBlocks: cloneEditorBlocks(item.blocks),
    beforeFocus: normalizeEditorHistoryFocus(focus),
  };
}





function commitEditorHistory(token, focus = null) {
  if (!token || !token.ownerType || !token.ownerId) return false;
  if (!editorOwnerMutationAllowed(token.ownerType, token.ownerId)) return false;
  const item = itemById(token.ownerType, token.ownerId);
  if (!item?.blocks) return false;
  const afterBlocks = cloneEditorBlocks(item.blocks);
  if (JSON.stringify(token.beforeBlocks) === JSON.stringify(afterBlocks)) return false;
  if (token.ownerType === "resources") markResourceChanged(token.ownerId);
  return pushEditorHistoryEntry({
    ownerType: token.ownerType,
    ownerId: token.ownerId,
    beforeBlocks: token.beforeBlocks,
    afterBlocks,
    beforeFocus: token.beforeFocus,
    afterFocus: normalizeEditorHistoryFocus(focus),
  });
}


function refreshLatestEditorHistoryAfter(ownerType, ownerId, focus = null) {
  if (!editorOwnerMutationAllowed(ownerType, ownerId)) return;
  const latest = ui.editorHistory.undo[ui.editorHistory.undo.length - 1];
  if (
    !latest
    || latest.ownerType !== ownerType
    || latest.ownerId !== ownerId
    || !Array.isArray(latest.afterBlocks)
  ) return;
  const item = itemById(ownerType, ownerId);
  if (!item?.blocks) return;
  latest.afterBlocks = cloneEditorBlocks(item.blocks);
  latest.afterFocus = normalizeEditorHistoryFocus(focus);
  ui.editorHistory.redo = [];
}

function undoEditorHistory() {
  flushPendingEditorTextHistory();
  const pending = ui.editorHistory.undo[ui.editorHistory.undo.length - 1];
  if (pending && !editorHistoryEntryMutationAllowed(pending)) return false;
  const entry = ui.editorHistory.undo.pop();
  if (!entry) return false;
  ui.editorHistory.redo.push(entry);
  restoreEditorHistoryEntry(entry, "before");
  return true;
}

function redoEditorHistory() {
  flushPendingEditorTextHistory();
  const pending = ui.editorHistory.redo[ui.editorHistory.redo.length - 1];
  if (pending && !editorHistoryEntryMutationAllowed(pending)) return false;
  const entry = ui.editorHistory.redo.pop();
  if (!entry) return false;
  ui.editorHistory.undo.push(entry);
  restoreEditorHistoryEntry(entry, "after");
  return true;
}

function restoreEditorHistoryEntry(entry, direction) {
  if (!editorHistoryEntryMutationAllowed(entry)) return;
  const item = itemById(entry.ownerType, entry.ownerId);
  if (!item) return;
  ui.pendingMarkdownTextTarget = null;
  item.blocks = cloneEditorBlocks(direction === "before" ? entry.beforeBlocks : entry.afterBlocks);
  ensureEditableBlocks(item, { save: false });
  if (entry.ownerType === "resources") markResourceChanged(entry.ownerId);
  clearBlockSelection();
  saveState();
  renderEditorMutation(entry.ownerType, entry.ownerId, { forceView: true });
  const focus = direction === "before" ? entry.beforeFocus : entry.afterFocus;
  restoreEditorHistoryFocus(focus);
}

function editorHistoryEntryMutationAllowed(entry) {
  return Boolean(entry?.ownerType && entry?.ownerId && editorOwnerMutationAllowed(entry.ownerType, entry.ownerId));
}




function pendingEditorTextHistoryMatches(ownerType, ownerId, blockId) {
  const pending = ui.pendingEditorTextHistory;
  return Boolean(
    pending
    && pending.ownerType === ownerType
    && pending.ownerId === ownerId
    && pending.blockId === blockId,
  );
}

function beginEditorTextHistory(ownerType, ownerId, blockId, focus = null, options = {}) {
  if (!editorOwnerMutationAllowed(ownerType, ownerId) || !blockId) return null;
  if (options.forceNew || !pendingEditorTextHistoryMatches(ownerType, ownerId, blockId)) {
    flushPendingEditorTextHistory();
  }
  if (!ui.pendingEditorTextHistory) {
    const token = beginEditorHistory(ownerType, ownerId, focus, { skipPendingTextFlush: true });
    if (!token) return null;
    ui.pendingEditorTextHistory = {
      ownerType,
      ownerId,
      blockId,
      token,
      timerId: 0,
    };
  }
  schedulePendingEditorTextHistoryCommit();
  return ui.pendingEditorTextHistory;
}

function schedulePendingEditorTextHistoryCommit() {
  const pending = ui.pendingEditorTextHistory;
  if (!pending) return;
  window.clearTimeout(pending.timerId);
  pending.timerId = window.setTimeout(flushPendingEditorTextHistory, EDITOR_TEXT_HISTORY_IDLE_MS);
}

function currentEditorTextHistoryFocus(pending) {
  const blockContent = document.querySelector(`[data-block-content="${cssEscape(pending.blockId)}"]`);
  const editor = blockContent?.closest(".block-editor");
  if (
    blockContent
    && editor?.dataset.ownerType === pending.ownerType
    && editor?.dataset.ownerId === pending.ownerId
  ) {
    const offsets = selectionOffsetsInside(blockContent);
    if (offsets) return { blockId: pending.blockId, start: offsets.start, end: offsets.end };
  }
  const item = itemById(pending.ownerType, pending.ownerId);
  const block = item?.blocks?.find((entry) => entry.id === pending.blockId);
  const length = typeof block?.text === "string" ? block.text.length : 0;
  return { blockId: pending.blockId, start: length, end: length };
}

function flushPendingEditorTextHistory(focus = null) {
  const pending = ui.pendingEditorTextHistory;
  if (!pending) return false;
  window.clearTimeout(pending.timerId);
  ui.pendingEditorTextHistory = null;
  return commitEditorHistory(pending.token, focus || currentEditorTextHistoryFocus(pending), { touch: false });
}

function stageEditorTextHistoryBeforeInput(event, blockContent) {
  const inputType = String(event?.inputType || "");
  if (
    !blockContent
    || event?.isComposing
    || (!inputType.startsWith("insert") && !inputType.startsWith("delete"))
    || inputType === "insertParagraph"
    || inputType === "insertLineBreak"
    || inputType === "historyUndo"
    || inputType === "historyRedo"
  ) return false;
  const editor = blockContent.closest(".block-editor");
  if (!editor) return false;
  const offsets = selectionOffsetsInside(blockContent);
  beginEditorTextHistory(
    editor.dataset.ownerType,
    editor.dataset.ownerId,
    blockContent.dataset.blockContent,
    {
      blockId: blockContent.dataset.blockContent,
      start: offsets?.start ?? 0,
      end: offsets?.end ?? offsets?.start ?? 0,
    },
  );
  return true;
}

function ensureEditorTextHistoryForInput(ownerType, ownerId, block, blockContent) {
  if (!block || pendingEditorTextHistoryMatches(ownerType, ownerId, block.id)) {
    schedulePendingEditorTextHistoryCommit();
    return;
  }
  const offsets = selectionOffsetsInside(blockContent);
  const length = typeof block.text === "string" ? block.text.length : 0;
  beginEditorTextHistory(ownerType, ownerId, block.id, {
    blockId: block.id,
    start: Math.min(length, offsets?.start ?? length),
    end: Math.min(length, offsets?.end ?? offsets?.start ?? length),
  });
}


function cloneEditorBlocks(blocksList = []) {
  return JSON.parse(JSON.stringify(blocksList || []));
}




function normalizeEditorHistoryFocus(focus = null) {
  if (!focus?.blockId) return null;
  return {
    blockId: focus.blockId,
    start: Number.isInteger(focus.start) ? focus.start : null,
    end: Number.isInteger(focus.end) ? focus.end : Number.isInteger(focus.start) ? focus.start : null,
    position: focus.position || "",
  };
}


function restoreEditorHistoryFocus(focus = null) {
  if (!focus?.blockId) return;
  if (Number.isInteger(focus.start)) {
    focusBlockContentAfterRender(focus.blockId, { range: { start: focus.start, end: Number.isInteger(focus.end) ? focus.end : focus.start } });
  } else {
    focusBlockContentAfterRender(focus.blockId, { position: focus.position || "end" });
  }
}


function deleteSelectedBlocks() {
  const selection = ui.blockSelection;
  if (!editorOwnerMutationAllowed(selection.ownerType, selection.ownerId)) return false;
  if (!selection.ids.length) return false;
  const item = itemById(selection.ownerType, selection.ownerId);
  if (!item?.blocks) return false;
  const selectedIds = selectedBlockSubtreeIds(item.blocks, selection.ids);
  const fallbackFocus = deletedSelectionFocusTarget(item.blocks, selectedIds);
  const history = beginEditorHistory(selection.ownerType, selection.ownerId, { blockId: selection.ids[0], position: "end" });
  let writeIndex = 0;
  let removed = false;
  for (const block of item.blocks) {
    if (selectedIds.has(block.id)) {
      removed = true;
      continue;
    }
    item.blocks[writeIndex] = block;
    writeIndex += 1;
  }
  if (!removed) {
    clearBlockSelection();
    return false;
  }
  item.blocks.length = writeIndex;
  ensureEditableBlocks(item);
  if (!fallbackFocus.blockId && item.blocks.length) fallbackFocus.blockId = item.blocks[0].id;
  clearBlockSelection();
  deactivateActiveBlockContent();
  window.getSelection()?.removeAllRanges();
  commitEditorHistory(history, fallbackFocus);
  saveState();
  renderEditorMutation(selection.ownerType, selection.ownerId, { forceView: true });
  if (fallbackFocus.blockId) {
    focusBlockContentAfterRender(fallbackFocus.blockId, { position: fallbackFocus.position });
  }
  return true;
}

function replaceSelectedBlocksWithText(text = "") {
  if (isSelectedBlocksMenuOpen()) return false;
  if (hasActiveEditableShortcutTarget()) {
    clearBlockSelection();
    return false;
  }
  const selection = ui.blockSelection;
  if (!editorOwnerMutationAllowed(selection.ownerType, selection.ownerId)) return false;
  if (!selection.ids.length) return false;
  const item = itemById(selection.ownerType, selection.ownerId);
  if (!item?.blocks) {
    clearBlockSelection();
    return false;
  }
  const selectedIds = selectedBlockSubtreeIds(item.blocks, selection.ids);
  const firstSelectedIndex = item.blocks.findIndex((block) => selectedIds.has(block.id));
  if (firstSelectedIndex < 0) {
    clearBlockSelection();
    return false;
  }
  const firstSelected = item.blocks[firstSelectedIndex];
  const recentFocusId =
    ui.recentBlockFocus?.ownerType === selection.ownerType &&
    ui.recentBlockFocus?.ownerId === selection.ownerId &&
    ui.recentBlockFocus.expiresAt > Date.now()
      ? ui.recentBlockFocus.blockId
      : "";
  const newBlock = {
    id: recentFocusId || firstSelected.id || id(),
    type: "paragraph",
    text,
    marks: [],
    checked: false,
    indent: firstSelectedIndex <= 0 ? 0 : blockIndent(firstSelected),
    collapsed: false,
  };
  const history = beginEditorHistory(selection.ownerType, selection.ownerId, { blockId: firstSelected.id, position: "end" });
  item.blocks = item.blocks.filter((block) => !selectedIds.has(block.id));
  item.blocks.splice(Math.min(firstSelectedIndex, item.blocks.length), 0, newBlock);
  clearBlockSelection();
  commitEditorHistory(history, { blockId: newBlock.id, start: text.length, end: text.length });
  saveState();
  renderEditorMutation(selection.ownerType, selection.ownerId, { forceView: true });
  focusBlockContentAfterRender(newBlock.id, { range: { start: text.length, end: text.length } });
  if (text) schedulePendingMarkdownTextTarget(selection.ownerType, selection.ownerId, newBlock);
  else ui.pendingMarkdownTextTarget = null;
  return true;
}

function duplicateSelectedBlocks() {
  const selection = ui.blockSelection;
  if (!editorOwnerMutationAllowed(selection.ownerType, selection.ownerId)) return false;
  if (!selection.ids.length) return false;
  const item = itemById(selection.ownerType, selection.ownerId);
  if (!item?.blocks) {
    clearBlockSelection();
    return false;
  }
  const selectedIds = selectedBlockSubtreeIds(item.blocks, selection.ids);
  const sourceBlocks = [];
  for (const block of item.blocks) {
    if (selectedIds.has(block.id)) sourceBlocks.push(block);
  }
  if (!sourceBlocks.length) {
    clearBlockSelection();
    return false;
  }
  const sourceToDuplicate = new Map();
  const duplicates = sourceBlocks.map((block) => {
    const duplicate = duplicateEditorBlock(block);
    sourceToDuplicate.set(block.id, duplicate.id);
    return duplicate;
  });
  const duplicatedSelectionIds = selection.ids.map((blockId) => sourceToDuplicate.get(blockId)).filter(Boolean);
  if (!duplicatedSelectionIds.length) duplicatedSelectionIds.push(duplicates[0].id);
  let lastSourceIndex = -1;
  for (let index = 0; index < item.blocks.length; index += 1) {
    if (selectedIds.has(item.blocks[index].id)) lastSourceIndex = index;
  }
  const insertIndex = lastSourceIndex < 0 ? item.blocks.length : lastSourceIndex + 1;
  const history = beginEditorHistory(selection.ownerType, selection.ownerId, { blockId: sourceBlocks[0].id, position: "end" });
  item.blocks.splice(insertIndex, 0, ...duplicates);
  ui.blockSelection = { ownerType: selection.ownerType, ownerId: selection.ownerId, ids: duplicatedSelectionIds };
  commitEditorHistory(history, { blockId: duplicatedSelectionIds[0], position: "end" });
  saveState();
  renderEditorMutation(selection.ownerType, selection.ownerId, { forceView: true });
  requestAnimationFrame(() => restoreBlockSelection(selection.ownerType, selection.ownerId, duplicatedSelectionIds));
  return true;
}

function duplicateEditorBlock(block) {
  const clone = cloneEditorBlocks([block])[0] || {};
  let type = isSupportedEditorBlockType(clone.type) ? clone.type : "paragraph";
  const text = typeof clone.text === "string" ? clone.text : "";
  const safeUrl = type === IMAGE_BLOCK_TYPE
    ? normalizeResourceImageUrl(clone.url)
    : isUrlPreviewBlockType(type) ? normalizeStandaloneHttpsUrl(clone.url || text) : "";
  if ((isUrlPreviewBlockType(type) || type === IMAGE_BLOCK_TYPE) && !safeUrl) type = "paragraph";
  const imageAlt = type === IMAGE_BLOCK_TYPE ? String(clone.alt || text) : "";
  const duplicate = {
    id: id(),
    type,
    text: type === IMAGE_BLOCK_TYPE ? imageAlt : safeUrl || text,
    marks: safeUrl ? [] : normalizeInlineMarks(text, clone.marks).filter((mark) => mark.type !== "comment"),
    checked: type === "todo" && clone.checked === true,
    indent: normalizedBlockIndent(clone.indent),
    collapsed: type === "toggle" && clone.collapsed === true,
    color: normalizeBlockColorValue(clone.color),
    backgroundColor: normalizeBlockColorValue(clone.backgroundColor),
  };
  if (safeUrl) duplicate.url = safeUrl;
  if (type === IMAGE_BLOCK_TYPE) duplicate.alt = imageAlt;
  if (type === "code" && typeof clone.language === "string") duplicate.language = clone.language.trim().split(/\s+/, 1)[0].slice(0, 64);
  return duplicate;
}



function selectedBlockSubtreeIds(blocksList, ids) {
  const selectedIds = new Set(ids);
  for (const blockId of ids) {
    const index = blocksList.findIndex((block) => block.id === blockId);
    if (index < 0) continue;
    const endIndex = blockSubtreeEndIndex(blocksList, index);
    for (let nextIndex = index; nextIndex <= endIndex; nextIndex += 1) {
      selectedIds.add(blocksList[nextIndex].id);
    }
  }
  return selectedIds;
}

function deletedSelectionFocusTarget(blocksList, selectedIds) {
  let firstSelectedIndex = blocksList.findIndex((block) => selectedIds.has(block.id));
  if (firstSelectedIndex < 0) firstSelectedIndex = 0;
  for (let index = firstSelectedIndex; index < blocksList.length; index += 1) {
    if (selectedIds.has(blocksList[index].id)) continue;
    if (blockIsHiddenByCollapsedToggle(blocksList, index)) continue;
    return { blockId: blocksList[index].id, position: "start" };
  }
  for (let index = firstSelectedIndex - 1; index >= 0; index -= 1) {
    if (selectedIds.has(blocksList[index].id)) continue;
    if (blockIsHiddenByCollapsedToggle(blocksList, index)) continue;
    return { blockId: blocksList[index].id, position: "end" };
  }
  return { blockId: "", position: "start" };
}

function handleDocumentCopy(event) {
  if (!ui.blockSelection.ids.length || !event.clipboardData) return;
  const blocks = selectedBlocksForClipboard();
  if (!blocks.length) return;
  writeBlocksToClipboard(event.clipboardData, blocks);
  event.preventDefault();
}

function copySelectedBlocksToSystemClipboard() {
  const blocks = selectedBlocksForClipboard();
  if (!blocks.length) return false;
  const plainText = clipboardBlocksPlainText(blocks);
  const htmlText = clipboardBlocksHtml(blocks);
  const write = async () => {
    if (navigator.clipboard?.write && window.ClipboardItem) {
      await navigator.clipboard.write([
        new ClipboardItem({
          "text/plain": new Blob([plainText], { type: "text/plain" }),
          "text/html": new Blob([htmlText], { type: "text/html" }),
        }),
      ]);
      return;
    }
    await writePlainTextToClipboard(plainText);
  };
  write()
    .then(() => showToast("블록을 복사했어요"))
    .catch(() => writePlainTextToClipboard(plainText)
      .then(() => showToast("블록을 복사했어요"))
      .catch(() => showToast("복사하지 못했어요")));
  return true;
}

function handleDocumentCut(event) {
  if (!ui.blockSelection.ids.length || !event.clipboardData) return;
  const blocks = selectedBlocksForClipboard();
  if (!blocks.length) return;
  writeBlocksToClipboard(event.clipboardData, blocks);
  event.preventDefault();
  if (!editorOwnerMutationAllowed(ui.blockSelection.ownerType, ui.blockSelection.ownerId)) return;
  deleteSelectedBlocks();
}

function handleDocumentPaste(event) {
  if (!event.clipboardData) return;
  const composingTarget = event.target instanceof Element ? event.target.closest("[data-block-content]") : null;
  if (composingTarget && isComposingBlock(composingTarget)) return;
  const shouldClearBlockSelection = pasteEventShouldClearBlockSelection(event);
  const target = clipboardPasteTarget(event);
  if (target && !editorOwnerMutationAllowed(target.ownerType, target.ownerId)) {
    event.preventDefault();
    return;
  }
  const imageFile = resourceImageFileFromClipboard(event.clipboardData);
  if (imageFile && target?.ownerType === "resources" && target.blockId) {
    event.preventDefault();
    pasteResourceImageFile(imageFile, target);
    return;
  }
  const customBlocks = readClipboardBlocks(event.clipboardData);
  const rawHtml = customBlocks.length ? "" : String(event.clipboardData.getData("text/html") || "");
  const parsedHtmlBlocks = rawHtml && htmlClipboardHasSafePasteContent(rawHtml) ? readHtmlClipboardBlocks(event.clipboardData) : [];
  const htmlBlocks = clipboardBlocksHaveMeaningfulPasteContent(parsedHtmlBlocks) ? parsedHtmlBlocks : [];
  const text = codeBlockPasteTextFromBlocks(event, customBlocks.length ? customBlocks : htmlBlocks) || event.clipboardData.getData("text/plain");
  if (pasteTextIntoCodeBlock(event, text, { clearBlockSelectionBeforeCommit: shouldClearBlockSelection && pasteEventTargetBlockContent(event) && pasteEventTargetsCodeBlock(event, { actualTargetOnly: true }) })) {
    event.preventDefault();
    return;
  }
  const standaloneHttpsUrl = customBlocks.length ? "" : normalizeStandaloneHttpsUrl(text);
  if (shouldClearBlockSelection && standaloneHttpsUrl) clearBlockSelection();
  if (standaloneHttpsUrl && openUrlPasteChoice(event, standaloneHttpsUrl)) {
    event.preventDefault();
    return;
  }
  if (customBlocks.length && target) {
    event.preventDefault();
    pasteBlocksFromClipboard(event, customBlocks);
    return;
  }
  if (htmlBlocks.length && target) {
    event.preventDefault();
    pasteBlocksFromClipboard(event, htmlBlocks);
    return;
  }
  const shouldNativeSingleLineFallthrough = (shouldClearBlockSelection || !ui.blockSelection.ids.length) && pasteEventBlockContent(event) && !shouldPastePlainTextAsBlocks(event, text);
  if (shouldNativeSingleLineFallthrough) {
    if (shouldClearBlockSelection) clearBlockSelection();
    return;
  }
  const plainBlocks = plainTextToClipboardBlocks(text);
  if (!plainBlocks.length) return;
  const shouldPlainNativeFallthrough = (shouldClearBlockSelection || !ui.blockSelection.ids.length) && !shouldPastePlainTextAsBlocks(event, text);
  if (shouldPlainNativeFallthrough) {
    if (shouldClearBlockSelection) clearBlockSelection();
    return;
  }
  if (target) {
    event.preventDefault();
    pasteBlocksFromClipboard(event, plainBlocks, { mergeIntoTarget: true });
  }
}

function resourceImageFileFromClipboard(clipboardData) {
  for (const item of clipboardData?.items || []) {
    if (item.kind !== "file" || !RESOURCE_IMAGE_MIME_TYPES.has(item.type)) continue;
    const file = item.getAsFile();
    if (file) return file;
  }
  return null;
}

async function pasteResourceImageFile(file, target) {
  if (file.size < 1 || file.size > MAX_RESOURCE_IMAGE_BYTES) {
    showToast("이미지는 8MB까지 붙여넣을 수 있습니다.");
    return false;
  }
  try {
    const url = await uploadResourceImageFile(file);
    const blockContent = document.querySelector(`[data-block-content="${cssEscape(target.blockId)}"]`);
    const range = selectionOffsetsInside(blockContent);
    return insertResourceImageBlock(
      { ownerType: target.ownerType, ownerId: target.ownerId, blockId: target.blockId, range },
      url,
      file.name.replace(/\.[^.]+$/, ""),
    );
  } catch (error) {
    showToast(error?.message || "이미지 붙여넣기에 실패했습니다.");
    focusBlockContentAfterRender(target.blockId);
    return false;
  }
}

function clipboardBlocksHaveMeaningfulPasteContent(blocks = []) {
  return blocks.some((block) => block?.type === "divider" || String(block?.text || block?.url || "").length > 0);
}

function htmlClipboardHasSafePasteContent(rawHtml = "") {
  const template = document.createElement("template");
  template.innerHTML = String(rawHtml || "");
  template.content.querySelectorAll("script, style, template, noscript, iframe, object, embed, svg, math, link, meta").forEach((node) => node.remove());
  for (const image of template.content.querySelectorAll("img")) {
    if (!normalizeResourceImageUrl(image.getAttribute("src"))) image.remove();
  }
  return Boolean(template.content.textContent?.trim() || template.content.querySelector("hr,img"));
}









function pasteEventShouldClearBlockSelection(event) {
  if (!ui.blockSelection.ids.length) return false;
  const blockContent = pasteEventBlockContent(event);
  if (!blockContent) return false;
  const editor = blockContent.closest(".block-editor");
  const blockId = blockContent.dataset.blockContent || "";
  if (!editor || editor.dataset.ownerType !== ui.blockSelection.ownerType || editor.dataset.ownerId !== ui.blockSelection.ownerId) {
    return true;
  }
  return !ui.blockSelection.ids.includes(blockId);
}

function codeBlockPasteTextFromBlocks(event, blocks) {
  if (!blocks.length || !pasteEventTargetsCodeBlock(event)) return "";
  return clipboardBlocksCodeText(blocks);
}

function pasteEventTargetBlockContent(event) {
  return event.target instanceof Element ? event.target.closest("[data-block-content]") : null;
}

function pasteEventTargetsCodeBlock(event, options = {}) {
  const targetBlock = pasteEventTargetBlockContent(event);
  const activeBlock = document.activeElement instanceof Element ? document.activeElement.closest("[data-block-content]") : null;
  const blockContent = options.actualTargetOnly ? targetBlock : targetBlock || activeBlock;
  const editor = blockContent?.closest(".block-editor");
  if (!blockContent || !editor) return false;
  const item = itemById(editor.dataset.ownerType, editor.dataset.ownerId);
  const block = item?.blocks?.find((entry) => entry.id === blockContent.dataset.blockContent);
  return block?.type === "code";
}

function clipboardBlocksCodeText(blocks) {
  const lines = [];
  for (const block of blocks) {
    lines.push(clipboardBlockPlainText(block));
  }
  return lines.join("\n");
}

function pasteTextIntoCodeBlock(event, text = "", options = {}) {
  if ((ui.blockSelection.ids.length && !options.clearBlockSelectionBeforeCommit) || !text) return false;
  const targetBlock = event.target instanceof Element ? event.target.closest("[data-block-content]") : null;
  const activeBlock = document.activeElement instanceof Element ? document.activeElement.closest("[data-block-content]") : null;
  const blockContent = targetBlock || activeBlock;
  const editor = blockContent?.closest(".block-editor");
  if (!blockContent || !editor) return false;
  if (!editorOwnerMutationAllowed(editor.dataset.ownerType, editor.dataset.ownerId)) return false;
  const item = itemById(editor.dataset.ownerType, editor.dataset.ownerId);
  const block = item?.blocks?.find((entry) => entry.id === blockContent.dataset.blockContent);
  if (!block || block.type !== "code") return false;
  const originalText = block.text || blockContent.textContent || "";
  const offsets = selectionOffsetsInside(blockContent) || { start: originalText.length, end: originalText.length };
  const start = Math.max(0, Math.min(originalText.length, Number.parseInt(offsets.start, 10) || 0));
  const end = Math.max(start, Math.min(originalText.length, Number.parseInt(offsets.end, 10) || start));
  const nextText = `${originalText.slice(0, start)}${text}${originalText.slice(end)}`;
  const preflightAt = new Date().toISOString();
  if (options.clearBlockSelectionBeforeCommit) clearBlockSelection();
  const history = beginEditorHistory(editor.dataset.ownerType, editor.dataset.ownerId, { blockId: block.id, start, end });
  block.text = nextText;
  block.marks = [];
  const caretOffset = start + text.length;
  commitEditorHistory(history, { blockId: block.id, start: caretOffset, end: caretOffset }, { at: preflightAt });
  saveState();
  renderEditorMutation(editor.dataset.ownerType, editor.dataset.ownerId, { forceView: true });
  focusBlockContentAfterRender(block.id, { range: { start: caretOffset, end: caretOffset } });
  return true;
}



function normalizeStandaloneHttpsUrl(value = "") {
  const raw = String(value || "").trim();
  if (!raw || raw.length > 4096 || !/^https:\/\//i.test(raw) || /[\u0000-\u0020\u007f<>"'`]/.test(raw)) return "";
  try {
    const parsed = new URL(raw);
    if (parsed.protocol !== "https:" || !parsed.hostname || parsed.username || parsed.password) return "";
    return parsed.href;
  } catch (_) {
    return "";
  }
}

function normalizeResourceImageUrl(value = "") {
  const raw = String(value || "").trim();
  if (/^\/api\/resource-images\/[a-f0-9]{64}$/.test(raw)) return raw;
  return normalizeStandaloneHttpsUrl(raw);
}

function openUrlPasteChoice(event, text = "") {
  const url = normalizeStandaloneHttpsUrl(text);
  if (!url) return false;
  const target = urlPasteChoiceTarget(event);
  if (!target || !editorOwnerMutationAllowed(target.ownerType, target.ownerId)) return false;
  const anchor = urlPasteChoiceAnchorRect(target.blockContent);
  ui.inlineToolbar = null;
  ui.linkPopover = null;
  ui.resourceCitationPopover = null;
  ui.commentPopover = null;
  ui.equationPopover = null;
  ui.selectedBlockMenu = null;
  ui.mention = null;
  ui.pageCommand = null;
  ui.emojiCommand = null;
  ui.urlPasteChoice = {
    ...target,
    url,
    selectedIndex: 0,
    x: anchor.left,
    y: anchor.bottom + 8,
  };
  renderOverlays();
  requestAnimationFrame(() => {
    clampUrlPasteChoiceToViewport();
    focusUrlPasteChoiceItem();
  });
  return true;
}

function urlPasteChoiceTarget(event) {
  if (ui.blockSelection.ids.length) {
    if (ui.blockSelection.ids.length !== 1) return null;
    const ownerType = ui.blockSelection.ownerType;
    const ownerId = ui.blockSelection.ownerId;
    const blockId = ui.blockSelection.ids[0];
    const item = itemById(ownerType, ownerId);
    const block = item?.blocks?.find((entry) => entry.id === blockId);
    if (!block || !urlPasteChoiceSupportsBlock(block)) return null;
    const blockContent = document.querySelector(`.block-editor[data-owner-type="${cssEscape(ownerType)}"][data-owner-id="${cssEscape(ownerId)}"] [data-block-content="${cssEscape(blockId)}"]`);
    return {
      ownerType,
      ownerId,
      blockId,
      blockContent,
      mode: "block-selection",
      start: 0,
      end: (block.text || "").length,
    };
  }
  const blockContent = pasteEventBlockContent(event);
  const editor = blockContent?.closest(".block-editor");
  if (!blockContent || !editor) return null;
  const ownerType = editor.dataset.ownerType;
  const ownerId = editor.dataset.ownerId;
  const blockId = blockContent.dataset.blockContent;
  const item = itemById(ownerType, ownerId);
  const block = item?.blocks?.find((entry) => entry.id === blockId);
  if (!block || !urlPasteChoiceSupportsBlock(block)) return null;
  const text = block.text || "";
  const offsets = selectionOffsetsInside(blockContent) || { start: text.length, end: text.length, collapsed: true };
  const start = Math.max(0, Math.min(text.length, Number.parseInt(offsets.start, 10) || 0));
  const end = Math.max(start, Math.min(text.length, Number.parseInt(offsets.end, 10) || start));
  if (text !== "" && end <= start) return null;
  return {
    ownerType,
    ownerId,
    blockId,
    blockContent,
    mode: text === "" ? "empty" : "text-selection",
    start,
    end,
  };
}

function urlPasteChoiceSupportsBlock(block) {
  return Boolean(block && BLOCK_TYPES[block.type] && !["code", "divider"].includes(block.type));
}

function urlPasteChoiceAnchorRect(blockContent) {
  const selection = window.getSelection();
  if (blockContent && selection?.rangeCount && !selection.isCollapsed) {
    const range = selection.getRangeAt(0);
    if (blockContent.contains(range.commonAncestorContainer)) {
      const rect = range.getBoundingClientRect();
      if (rect.width || rect.height) return rect;
    }
  }
  return blockContent?.getBoundingClientRect?.() || { left: 8, top: 8, right: 8, bottom: 8, width: 0, height: 0 };
}

function clampUrlPasteChoiceToViewport() {
  const choice = ui.urlPasteChoice;
  const menu = document.querySelector("[data-url-paste-choice-menu]");
  if (!choice || !menu) return;
  const inset = 8;
  const viewportWidth = Math.max(1, Math.min(window.innerWidth, window.visualViewport?.width || window.innerWidth));
  const viewportHeight = Math.max(1, Math.min(window.innerHeight, window.visualViewport?.height || window.innerHeight));
  menu.style.maxHeight = `${Math.max(1, viewportHeight - inset * 2)}px`;
  const rect = menu.getBoundingClientRect();
  const maxX = Math.max(inset, viewportWidth - rect.width - inset);
  const maxY = Math.max(inset, viewportHeight - rect.height - inset);
  const x = Math.max(inset, Math.min(maxX, choice.x || inset));
  const y = Math.max(inset, Math.min(maxY, choice.y || inset));
  choice.x = x;
  choice.y = y;
  menu.style.left = `${Math.round(x)}px`;
  menu.style.top = `${Math.round(y)}px`;
}

function focusUrlPasteChoiceItem() {
  if (!ui.urlPasteChoice) return;
  const index = Math.max(0, Math.min(URL_PASTE_CHOICE_ACTIONS.length - 1, ui.urlPasteChoice.selectedIndex || 0));
  document.querySelector(`[data-url-paste-choice-index="${index}"]`)?.focus?.({ preventScroll: true });
}

function moveUrlPasteChoiceSelection(nextIndex) {
  if (!ui.urlPasteChoice) return false;
  const count = URL_PASTE_CHOICE_ACTIONS.length;
  ui.urlPasteChoice.selectedIndex = ((nextIndex % count) + count) % count;
  renderOverlays();
  requestAnimationFrame(() => {
    clampUrlPasteChoiceToViewport();
    focusUrlPasteChoiceItem();
  });
  return true;
}

function handleUrlPasteChoiceKeydown(event) {
  if (!ui.urlPasteChoice) return false;
  const currentIndex = Math.max(0, Math.min(URL_PASTE_CHOICE_ACTIONS.length - 1, ui.urlPasteChoice.selectedIndex || 0));
  if (event.key === "Escape") {
    event.preventDefault();
    event.stopPropagation();
    closeUrlPasteChoice({ restoreFocus: true });
    return true;
  }
  if (["ArrowDown", "ArrowRight", "ArrowUp", "ArrowLeft", "Home", "End", "Tab"].includes(event.key)) {
    event.preventDefault();
    event.stopPropagation();
    const nextIndex = event.key === "Home"
      ? 0
      : event.key === "End"
        ? URL_PASTE_CHOICE_ACTIONS.length - 1
        : currentIndex + ((event.key === "ArrowDown" || event.key === "ArrowRight" || (event.key === "Tab" && !event.shiftKey)) ? 1 : -1);
    moveUrlPasteChoiceSelection(nextIndex);
    return true;
  }
  if ((event.key === "Enter" || event.key === " ") && !event.metaKey && !event.ctrlKey && !event.altKey) {
    event.preventDefault();
    event.stopPropagation();
    const action = event.target instanceof Element
      ? event.target.closest("[data-url-paste-choice-action]")?.dataset.urlPasteChoiceAction
      : "";
    applyUrlPasteChoice(action || URL_PASTE_CHOICE_ACTIONS[currentIndex].action);
    return true;
  }
  return false;
}

function closeUrlPasteChoice(options = {}) {
  const choice = ui.urlPasteChoice;
  if (!choice) return false;
  ui.urlPasteChoice = null;
  renderOverlays();
  if (options.restoreFocus) requestAnimationFrame(() => restoreUrlPasteChoiceTarget(choice));
  return true;
}

function restoreUrlPasteChoiceTarget(choice) {
  if (!choice?.blockId) return;
  if (choice.mode === "block-selection") {
    restoreBlockSelection(choice.ownerType, choice.ownerId, [choice.blockId]);
    return;
  }
  focusBlockContentAfterRender(choice.blockId, { range: { start: choice.start, end: choice.end } });
}

function applyUrlPasteChoice(action = "") {
  const choice = ui.urlPasteChoice;
  if (!choice) return false;
  if (action === "cancel") return closeUrlPasteChoice({ restoreFocus: true });
  if (!["link", "bookmark", "embed"].includes(action)) return false;
  const url = normalizeStandaloneHttpsUrl(choice.url);
  const item = itemById(choice.ownerType, choice.ownerId);
  const block = item?.blocks?.find((entry) => entry.id === choice.blockId);
  if (!url || !block || !urlPasteChoiceSupportsBlock(block) || !editorOwnerMutationAllowed(choice.ownerType, choice.ownerId)) {
    closeUrlPasteChoice({ restoreFocus: false });
    return false;
  }
  const beforeFocus = { blockId: block.id, start: choice.start, end: choice.end };
  const history = beginEditorHistory(choice.ownerType, choice.ownerId, beforeFocus);
  const focus = action === "link"
    ? applyUrlPasteAsLink(block, choice, url)
    : applyUrlPasteAsPreviewBlock(item, block, choice, url, action);
  if (!focus) {
    closeUrlPasteChoice({ restoreFocus: true });
    return false;
  }
  ui.urlPasteChoice = null;
  clearBlockSelection();
  commitEditorHistory(history, focus);
  saveState();
  renderEditorMutation(choice.ownerType, choice.ownerId, { forceView: true });
  renderOverlays();
  if (action === "link") {
    focusBlockContentAfterRender(focus.blockId, { range: { start: focus.start, end: focus.end } });
  } else {
    focusUrlPreviewBlockAfterRender(focus.blockId);
  }
  return true;
}

function applyUrlPasteAsLink(block, choice, url) {
  const text = block.text || "";
  const start = Math.max(0, Math.min(text.length, Number.parseInt(choice.start, 10) || 0));
  const end = Math.max(start, Math.min(text.length, Number.parseInt(choice.end, 10) || start));
  delete block.url;
  if (end > start) {
    let marks = removeInlineMarkRange(normalizeInlineMarks(text, block.marks), "resourceLink", start, end);
    marks = removeInlineMarkRange(marks, "link", start, end);
    marks.push({ type: "link", start, end, href: url });
    block.marks = normalizeInlineMarks(text, marks);
    return { blockId: block.id, start, end };
  }
  block.text = url;
  block.marks = [{ type: "link", start: 0, end: url.length, href: url }];
  return { blockId: block.id, start: 0, end: url.length };
}

function applyUrlPasteAsPreviewBlock(item, block, choice, url, type) {
  const blockIndex = item.blocks.indexOf(block);
  if (blockIndex < 0 || !isUrlPreviewBlockType(type)) return null;
  const text = block.text || "";
  const start = Math.max(0, Math.min(text.length, Number.parseInt(choice.start, 10) || 0));
  const end = Math.max(start, Math.min(text.length, Number.parseInt(choice.end, 10) || start));
  if (start === 0 && end === text.length) {
    block.type = type;
    block.text = url;
    block.url = url;
    block.marks = [];
    block.checked = false;
    block.collapsed = false;
    return { blockId: block.id, position: "end" };
  }
  const splitMarks = splitInlineMarksAtSelection(block.marks || [], text, start, end);
  const replacement = [];
  if (start > 0) {
    const before = { ...block, text: text.slice(0, start), marks: splitMarks.before };
    delete before.url;
    replacement.push(before);
  }
  const previewBlock = {
    id: start > 0 ? id() : block.id,
    type,
    text: url,
    url,
    marks: [],
    checked: false,
    indent: blockIndent(block),
    collapsed: false,
  };
  if (normalizeBlockColorValue(block.color)) previewBlock.color = normalizeBlockColorValue(block.color);
  if (normalizeBlockColorValue(block.backgroundColor)) previewBlock.backgroundColor = normalizeBlockColorValue(block.backgroundColor);
  replacement.push(previewBlock);
  if (end < text.length) {
    replacement.push({
      id: id(),
      type: "paragraph",
      text: text.slice(end),
      marks: splitMarks.after,
      checked: false,
      indent: blockIndent(block),
      collapsed: false,
    });
  }
  item.blocks.splice(blockIndex, 1, ...replacement);
  return { blockId: previewBlock.id, position: "end" };
}

function focusUrlPreviewBlockAfterRender(blockId) {
  const focus = () => {
    const target = document.querySelector(`[data-block-id="${cssEscape(blockId)}"] [data-url-block-preview]`);
    target?.focus?.({ preventScroll: true });
    target?.scrollIntoView?.({ block: "nearest" });
  };
  focus();
  requestAnimationFrame(focus);
}

function shouldPastePlainTextAsBlocks(event, text) {
  const raw = String(text || "");
  if (!raw) return false;
  if (/[\r\n]/.test(raw)) return true;
  const parsedBlock = markdownBlockFromPlainText(raw);
  if (parsedBlock.type !== "paragraph" || parsedBlock.text !== raw) return true;
  if (parseMarkdownInlineText(raw).marks.length) return true;
  return false;
}

function pasteEventBlockContent(event) {
  const targetBlock = event.target instanceof Element ? event.target.closest("[data-block-content]") : null;
  const activeBlock = document.activeElement instanceof Element ? document.activeElement.closest("[data-block-content]") : null;
  return targetBlock || activeBlock;
}

function selectedBlocksForClipboard() {
  const selection = ui.blockSelection;
  const item = itemById(selection.ownerType, selection.ownerId);
  if (!item?.blocks) return [];
  const selectedIds = selectedBlockSubtreeIds(item.blocks, selection.ids);
  const blocks = [];
  for (const block of item.blocks) {
    if (!selectedIds.has(block.id)) continue;
    blocks.push(clipboardBlockFromBlock(block));
  }
  return blocks;
}

function clipboardBlockFromBlock(block) {
  let type = isSupportedEditorBlockType(block.type) ? block.type : "paragraph";
  const safeUrl = type === IMAGE_BLOCK_TYPE
    ? normalizeResourceImageUrl(block.url)
    : isUrlPreviewBlockType(type) ? normalizeStandaloneHttpsUrl(block.url || block.text || "") : "";
  if ((isUrlPreviewBlockType(type) || type === IMAGE_BLOCK_TYPE) && !safeUrl) type = "paragraph";
  const imageAlt = type === IMAGE_BLOCK_TYPE ? String(block.alt || block.text || "") : "";
  const clipboardBlock = {
    type,
    text: type === IMAGE_BLOCK_TYPE ? imageAlt : safeUrl || block.text || "",
    marks: safeUrl ? [] : normalizeInlineMarks(block.text || "", block.marks).filter((mark) => mark.type !== "comment"),
    checked: block.checked === true,
    indent: blockIndent(block),
    collapsed: block.type === "toggle" && block.collapsed === true,
    color: normalizeBlockColorValue(block.color),
    backgroundColor: normalizeBlockColorValue(block.backgroundColor),
  };
  if (safeUrl) clipboardBlock.url = safeUrl;
  if (type === IMAGE_BLOCK_TYPE) clipboardBlock.alt = imageAlt;
  if (type === "numbered" && numberedBlockStart(block)) clipboardBlock.listStart = numberedBlockStart(block);
  if (type === "code" && typeof block.language === "string") clipboardBlock.language = block.language.trim().split(/\s+/, 1)[0].slice(0, 64);
  return clipboardBlock;
}

function writeBlocksToClipboard(clipboardData, blocks) {
  clipboardData.setData(BLOCK_CLIPBOARD_MIME, JSON.stringify({ version: 1, blocks }));
  clipboardData.setData("text/plain", clipboardBlocksPlainText(blocks));
  clipboardData.setData("text/html", clipboardBlocksHtml(blocks));
}

function clipboardBlocksPlainText(blocks) {
  const lines = [];
  const numberedCounters = [];
  for (const block of blocks) {
    const prefix = clipboardBlockTextPrefix(block, clipboardNumberedPrefixForBlock(block, numberedCounters));
    lines.push(clipboardBlockPlainText(block, prefix));
  }
  return lines.join("\n");
}

function clipboardBlockPlainText(block, prefix = clipboardBlockTextPrefix(block)) {
  const indent = "\t".repeat(block.indent || 0);
  const rawText = block.text || "";
  if (block.type === IMAGE_BLOCK_TYPE) return `${indent}![${rawText}](${normalizeResourceImageUrl(block.url)})`;
  const rawLines = rawText.split("\n");
  if (block.type === "code") {
    const longestRun = Math.max(0, ...[...rawText.matchAll(/`+/g)].map((match) => match[0].length));
    const fence = "`".repeat(Math.max(3, longestRun + 1));
    const language = String(block.language || "").trim().split(/\s+/, 1)[0].slice(0, 64);
    return `${indent}${fence}${language}\n${rawLines.map((line) => `${indent}${line}`).join("\n")}\n${indent}${fence}`;
  }
  return rawLines.map((line, index) => `${indent}${index === 0 ? prefix : ""}${line}`).join("\n");
}

function clipboardNumberedPrefixForBlock(block, counters) {
  const indent = block.indent || 0;
  counters.length = Math.min(counters.length, indent + 1);
  if (block.type !== "numbered") {
    counters[indent] = 0;
    return "";
  }
  const nextNumber = numberedBlockStart(block) || (counters[indent] || 0) + 1;
  counters[indent] = nextNumber;
  return `${nextNumber}. `;
}

function clipboardBlockTextPrefix(block, numberedPrefix = "") {
  if (block.type === "heading1") return "# ";
  if (block.type === "heading2") return "## ";
  if (block.type === "heading3") return "### ";
  if (block.type === "heading4") return "#### ";
  if (block.type === "heading5") return "##### ";
  if (block.type === "heading6") return "###### ";
  if (block.type === "bullet") return "- ";
  if (block.type === "numbered") return numberedPrefix || "1. ";
  if (block.type === "todo") return block.checked ? "- [x] " : "- [ ] ";
  if (block.type === "toggle") return "> ";
  if (block.type === "quote") return "| ";
  if (block.type === "callout") return "! ";
  if (block.type === "code") return "``` ";
  if (block.type === "divider") return "---";
  return "";
}

function clipboardBlocksHtml(blocks) {
  let html = "";
  const numberedCounters = [];
  for (const block of blocks) {
    const blockType = esc(block.type);
    const blockIndent = block.indent || 0;
    const prefix = clipboardBlockTextPrefix(block, clipboardNumberedPrefixForBlock(block, numberedCounters));
    const colorAttr = block.color ? ` data-block-color="${esc(block.color)}"` : "";
    const backgroundColorAttr = block.backgroundColor ? ` data-block-background="${esc(block.backgroundColor)}"` : "";
    const urlAttr = (isUrlPreviewBlockType(block.type) || block.type === IMAGE_BLOCK_TYPE) && normalizeResourceImageUrl(block.url || block.text || "")
      ? ` data-block-url="${esc(normalizeResourceImageUrl(block.url || block.text || ""))}"`
      : "";
    if (block.type === "code") {
      html += `<pre data-block-type="${blockType}" data-block-indent="${blockIndent}"${colorAttr}${backgroundColorAttr}><code>${esc(block.text || "")}</code></pre>`;
    } else if (block.type === IMAGE_BLOCK_TYPE) {
      html += `<figure data-block-type="image" data-block-indent="${blockIndent}"${urlAttr}><img src="${esc(normalizeResourceImageUrl(block.url))}" alt="${esc(block.alt || block.text || "")}"></figure>`;
    } else {
      const checkedAttr = block.type === "todo" ? ` data-block-checked="${block.checked ? "true" : "false"}"` : "";
      html += `<div data-block-type="${blockType}" data-block-indent="${blockIndent}"${checkedAttr}${urlAttr}${colorAttr}${backgroundColorAttr}>${esc(prefix)}${renderInlineTextForClipboard(block)}</div>`;
    }
  }
  return html;
}

function renderInlineTextForClipboard(block) {
  const text = block.text || "";
  if (!text) return "";
  const marks = normalizeInlineMarks(text, block.marks);
  if (!marks.length) return esc(text).replace(/\n/g, "<br>");
  const points = new Set([0, text.length]);
  for (const mark of marks) {
    points.add(mark.start);
    points.add(mark.end);
  }
  const sorted = [...points].sort((a, b) => a - b);
  let html = "";
  for (let index = 0; index < sorted.length - 1; index += 1) {
    const start = sorted[index];
    const end = sorted[index + 1];
    if (end <= start) continue;
    const active = marks.filter((mark) => mark.start <= start && mark.end >= end);
    html += renderInlineSegmentForClipboard(text.slice(start, end), active);
  }
  return html;
}

function renderInlineSegmentForClipboard(text, activeMarks) {
  const escaped = esc(text).replace(/\n/g, "<br>");
  if (!activeMarks.length) return escaped;
  const marker = `__SYGMA_BR_${id()}__`;
  const rendered = renderInlineSegment(text.replace(/\n/g, marker), activeMarks);
  return rendered.replaceAll(esc(marker), "<br>");
}

function readHtmlClipboardBlocks(clipboardData) {
  const html = clipboardData.getData("text/html");
  if (!html || typeof DOMParser !== "function") return [];
  const doc = new DOMParser().parseFromString(html, "text/html");
  return normalizeClipboardBlocks(htmlClipboardStructuredBlocks(doc.body));
}

function clipboardBlockFromHtmlElement(element) {
  if (!(element instanceof Element)) return null;
  const rawType = element.matches("pre") ? "code" : element.dataset.blockType;
  let type = isSupportedEditorBlockType(rawType) ? rawType : "";
  if (!type) return null;
  const checked = element.dataset.blockChecked === "true";
  const inline = htmlClipboardInlineData(element);
  const text = normalizeHtmlClipboardText(element.innerText || element.textContent || "");
  const stripped = stripClipboardBlockInlinePrefix(type, inline, checked);
  const safeUrl = type === IMAGE_BLOCK_TYPE
    ? normalizeResourceImageUrl(element.dataset.blockUrl || element.querySelector("img")?.getAttribute("src") || "")
    : isUrlPreviewBlockType(type) ? normalizeStandaloneHttpsUrl(element.dataset.blockUrl || stripped.text) : "";
  if ((isUrlPreviewBlockType(type) || type === IMAGE_BLOCK_TYPE) && !safeUrl) type = "paragraph";
  const imageAlt = type === IMAGE_BLOCK_TYPE ? String(element.querySelector("img")?.getAttribute("alt") || "") : "";
  const block = {
    type,
    text: type === IMAGE_BLOCK_TYPE ? imageAlt : safeUrl || (type === "code" ? text : stripped.text),
    marks: type === "code" || safeUrl ? [] : stripped.marks,
    checked,
    indent: normalizedBlockIndent(element.dataset.blockIndent),
    collapsed: false,
    color: normalizeBlockColorValue(element.dataset.blockColor),
    backgroundColor: normalizeBlockColorValue(element.dataset.blockBackground),
  };
  if (safeUrl) block.url = safeUrl;
  if (type === IMAGE_BLOCK_TYPE) block.alt = imageAlt;
  return block;
}

function htmlClipboardStructuredBlocks(root) {
  const blocks = [];
  appendHtmlClipboardChildren(blocks, root, 0);
  return blocks;
}

function appendHtmlClipboardChildren(blocks, element, indent) {
  if (!(element instanceof Element)) return;
  for (const child of element.children) appendHtmlClipboardElement(blocks, child, indent);
  if (!blocks.length) {
    const inline = htmlClipboardInlineData(element);
    if (inline.text) blocks.push({ type: "paragraph", text: inline.text, marks: inline.marks, checked: false, indent, collapsed: false });
  }
}

function appendHtmlClipboardElement(blocks, element, indent) {
  if (!(element instanceof Element)) return;
  const dataBlock = clipboardBlockFromHtmlElement(element);
  if (dataBlock) {
    blocks.push(dataBlock);
    return;
  }
  const tag = element.tagName.toLowerCase();
  if (["script", "style", "meta", "link", "template"].includes(tag)) return;
  if (tag === "pre") {
    const text = normalizeHtmlClipboardText(element.innerText || element.textContent || "");
    blocks.push({ type: "code", text, marks: [], checked: false, indent, collapsed: false });
    return;
  }
  if (tag === "img") {
    const url = normalizeResourceImageUrl(element.getAttribute("src"));
    if (url) blocks.push({ type: IMAGE_BLOCK_TYPE, text: element.getAttribute("alt") || "", alt: element.getAttribute("alt") || "", url, marks: [], checked: false, indent, collapsed: false });
    return;
  }
  if (tag === "ul" || tag === "ol") {
    appendHtmlClipboardList(blocks, element, indent, tag === "ol");
    return;
  }
  if (tag === "li") {
    appendHtmlClipboardListItem(blocks, element, indent, false);
    return;
  }
  const headingType = htmlClipboardHeadingType(tag);
  if (headingType) {
    const inline = htmlClipboardInlineData(element);
    if (inline.text) blocks.push({ type: headingType, text: inline.text, marks: inline.marks, checked: false, indent, collapsed: false });
    return;
  }
  if (tag === "blockquote") {
    const inline = htmlClipboardInlineData(element, { removeSelectors: "ul,ol,pre,blockquote,script,style,template" });
    if (inline.text) blocks.push({ type: "quote", text: inline.text, marks: inline.marks, checked: false, indent, collapsed: false });
    for (const child of element.children) {
      const childTag = child.tagName.toLowerCase();
      if (["ul", "ol", "pre", "blockquote"].includes(childTag)) appendHtmlClipboardElement(blocks, child, indent + 1);
    }
    return;
  }
  if (htmlClipboardElementHasStructuredChildren(element)) {
    const inline = htmlClipboardInlineData(element, { removeSelectors: "h1,h2,h3,h4,h5,h6,p,div,section,article,main,blockquote,pre,ul,ol,li,script,style,template" });
    if (inline.text) blocks.push({ type: "paragraph", text: inline.text, marks: inline.marks, checked: false, indent, collapsed: false });
    for (const child of element.children) appendHtmlClipboardElement(blocks, child, indent);
    return;
  }
  const inline = htmlClipboardInlineData(element);
  if (inline.text) blocks.push({ type: "paragraph", text: inline.text, marks: inline.marks, checked: false, indent, collapsed: false });
}

function appendHtmlClipboardList(blocks, listElement, indent, ordered) {
  for (const child of listElement.children) {
    if (child.tagName.toLowerCase() === "li") appendHtmlClipboardListItem(blocks, child, indent, ordered);
  }
}

function appendHtmlClipboardListItem(blocks, itemElement, indent, ordered) {
  const inline = htmlClipboardInlineData(itemElement, { removeSelectors: "ul,ol,pre,blockquote,script,style,template" });
  const checked = htmlClipboardListItemCheckedState(itemElement);
  const type = checked === null ? (ordered ? "numbered" : "bullet") : "todo";
  if (inline.text) blocks.push({ type, text: inline.text, marks: inline.marks, checked: checked === true, indent, collapsed: false });
  for (const child of itemElement.children) {
    const tag = child.tagName.toLowerCase();
    if (tag === "ul" || tag === "ol") appendHtmlClipboardList(blocks, child, indent + 1, tag === "ol");
  }
}

function htmlClipboardHeadingType(tag) {
  if (tag === "h1") return "heading1";
  if (tag === "h2") return "heading2";
  if (tag === "h3") return "heading3";
  if (tag === "h4") return "heading4";
  if (tag === "h5") return "heading5";
  if (tag === "h6") return "heading6";
  return "";
}

function htmlClipboardElementHasStructuredChildren(element) {
  return [...element.children].some((child) => htmlClipboardElementIsStructured(child));
}

function htmlClipboardElementIsStructured(element) {
  const tag = element.tagName.toLowerCase();
  return ["h1", "h2", "h3", "h4", "h5", "h6", "p", "div", "section", "article", "main", "blockquote", "pre", "ul", "ol", "li", "img"].includes(tag);
}

function htmlClipboardInlineData(element, options = {}) {
  const clone = element.cloneNode(true);
  const removeSelectors = options.removeSelectors || "script,style,template";
  clone.querySelectorAll(removeSelectors).forEach((child) => child.remove());
  clone.querySelectorAll("input[type='checkbox']").forEach((input) => input.remove());
  const data = { text: "", marks: [] };
  appendHtmlClipboardInlineNode(data, clone, []);
  return trimHtmlClipboardInlineData(data);
}

function appendHtmlClipboardInlineNode(data, node, activeMarks) {
  if (node.nodeType === Node.TEXT_NODE) {
    appendHtmlClipboardInlineText(data, node.textContent || "", activeMarks);
    return;
  }
  if (!(node instanceof Element)) return;
  if (["SCRIPT", "STYLE", "TEMPLATE"].includes(node.tagName)) return;
  const nextMarks = htmlClipboardInlineMarksForElement(node, activeMarks);
  if (node.tagName === "BR") {
    appendHtmlClipboardInlineBreak(data);
    return;
  }
  for (const child of node.childNodes) appendHtmlClipboardInlineNode(data, child, nextMarks);
}

function appendHtmlClipboardInlineText(data, text, activeMarks) {
  const nextText = String(text || "").replace(/\u00a0/g, " ").replace(/\s+/g, " ");
  if (!nextText) return;
  const start = data.text.length;
  data.text += nextText;
  const end = data.text.length;
  for (const mark of activeMarks) data.marks.push({ ...mark, start, end });
}

function appendHtmlClipboardInlineBreak(data) {
  if (data.text.endsWith("\n")) return;
  data.text = data.text.replace(/[ \t]+$/, "");
  data.text += "\n";
}

function htmlClipboardInlineMarksForElement(element, activeMarks) {
  const marks = activeMarks.slice();
  const tag = element.tagName.toLowerCase();
  if (tag === "strong" || tag === "b") marks.push({ type: "bold" });
  if (tag === "em" || tag === "i") marks.push({ type: "italic" });
  if (tag === "u") marks.push({ type: "underline" });
  if (tag === "s" || tag === "del" || tag === "strike") marks.push({ type: "strike" });
  if (tag === "code") marks.push({ type: "code" });
  if (tag === "a" && element.dataset.inlineMark === "resourceLink") {
    const resourceId = String(element.dataset.resourceCitation || "").trim();
    if (resourceId) marks.push({ type: "resourceLink", resourceId });
  } else if (tag === "a") {
    const href = normalizeInlineHref(element.getAttribute("href") || "");
    if (href) marks.push({ type: "link", href });
  }
  return marks;
}

function trimHtmlClipboardInlineData(data) {
  const raw = data.text || "";
  const leading = raw.length - raw.trimStart().length;
  const trailing = raw.length - raw.trimEnd().length;
  const endLimit = raw.length - trailing;
  const text = raw.slice(leading, endLimit);
  const marks = data.marks
    .map((mark) => ({
      ...mark,
      start: Math.max(0, mark.start - leading),
      end: Math.min(text.length, mark.end - leading),
    }))
    .filter((mark) => mark.end > mark.start);
  return { text, marks: normalizeInlineMarks(text, marks) };
}

function htmlClipboardListItemCheckedState(itemElement) {
  const itemState = htmlClipboardCheckedAttributeState(itemElement);
  if (itemState !== null) return itemState;
  const checkbox = [...itemElement.querySelectorAll("input[type='checkbox'], [role='checkbox']")]
    .find((input) => input.closest("li") === itemElement);
  if (!checkbox) return null;
  const checkboxState = htmlClipboardCheckedAttributeState(checkbox);
  if (checkboxState !== null) return checkboxState;
  if (checkbox instanceof HTMLInputElement) return checkbox.checked || checkbox.hasAttribute("checked");
  return null;
}

function htmlClipboardCheckedAttributeState(element) {
  if (!(element instanceof Element)) return null;
  const explicit = [
    element.getAttribute("data-block-checked"),
    element.getAttribute("data-checked"),
    element.getAttribute("aria-checked"),
  ].find((value) => value !== null);
  if (explicit !== undefined) return htmlClipboardBooleanAttributeValue(explicit);
  if (element.hasAttribute("checked")) return true;
  return null;
}

function htmlClipboardBooleanAttributeValue(value = "") {
  const normalized = String(value).trim().toLowerCase();
  if (!normalized || ["true", "checked", "1", "yes"].includes(normalized)) return true;
  if (["false", "unchecked", "0", "no"].includes(normalized)) return false;
  return null;
}

function normalizeHtmlClipboardText(text = "") {
  return String(text).replace(/\r\n?/g, "\n").replace(/\n$/, "");
}

function stripClipboardBlockInlinePrefix(type, inline, checked = false) {
  const text = inline.text || "";
  if (type === "numbered") {
    const match = /^(\d+[.)]\s+)/.exec(text);
    return match ? stripClipboardInlinePrefixLength(inline, match[1].length) : inline;
  }
  const prefix = type === "todo"
    ? checked ? "[x] " : "[ ] "
    : clipboardBlockTextPrefix({ type, checked });
  if (!prefix || !text.startsWith(prefix)) return inline;
  return stripClipboardInlinePrefixLength(inline, prefix.length);
}

function stripClipboardInlinePrefixLength(inline, prefixLength) {
  const text = inline.text || "";
  const nextText = text.slice(prefixLength);
  const nextMarks = inline.marks
    .map((mark) => ({
      ...mark,
      start: Math.max(0, mark.start - prefixLength),
      end: Math.min(nextText.length, mark.end - prefixLength),
    }))
    .filter((mark) => mark.end > mark.start);
  return { text: nextText, marks: normalizeInlineMarks(nextText, nextMarks) };
}

function readClipboardBlocks(clipboardData) {
  const raw = clipboardData.getData(BLOCK_CLIPBOARD_MIME);
  if (!raw) return [];
  try {
    const payload = JSON.parse(raw);
    if (!payload || !Array.isArray(payload.blocks)) return [];
    return normalizeClipboardBlocks(payload.blocks);
  } catch (_) {
    return [];
  }
}

function normalizeClipboardBlocks(blocks) {
  const normalized = [];
  for (const block of blocks) {
    if (!block || typeof block !== "object") continue;
    let type = isSupportedEditorBlockType(block.type) ? block.type : "paragraph";
    const rawText = typeof block.text === "string" ? block.text : "";
    const safeUrl = type === IMAGE_BLOCK_TYPE
      ? normalizeResourceImageUrl(block.url)
      : isUrlPreviewBlockType(type) ? normalizeStandaloneHttpsUrl(block.url || rawText) : "";
    if ((isUrlPreviewBlockType(type) || type === IMAGE_BLOCK_TYPE) && !safeUrl) type = "paragraph";
    const imageAlt = type === IMAGE_BLOCK_TYPE ? String(block.alt || rawText).slice(0, 2_000) : "";
    const normalizedBlock = {
      type,
      text: type === IMAGE_BLOCK_TYPE ? imageAlt : safeUrl || rawText,
      marks: safeUrl ? [] : normalizeInlineMarks(rawText, block.marks).filter((mark) => mark.type !== "comment"),
      checked: block.checked === true,
      indent: normalizedBlockIndent(block.indent),
      collapsed: type === "toggle" && block.collapsed === true,
      color: normalizeBlockColorValue(block.color),
      backgroundColor: normalizeBlockColorValue(block.backgroundColor),
    };
    if (safeUrl) normalizedBlock.url = safeUrl;
    if (type === IMAGE_BLOCK_TYPE) normalizedBlock.alt = imageAlt;
    if (type === "numbered" && numberedBlockStart(block)) normalizedBlock.listStart = numberedBlockStart(block);
    if (type === "code" && typeof block.language === "string") normalizedBlock.language = block.language.trim().split(/\s+/, 1)[0].slice(0, 64);
    normalized.push(normalizedBlock);
  }
  return normalized;
}

function plainTextToClipboardBlocks(text) {
  if (!text) return [];
  const normalized = [];
  const lines = String(text).replace(/\r\n?/g, "\n").split("\n");
  const references = markdownReferenceDefinitions(lines);
  let paragraph = null;
  const flushParagraph = () => {
    if (!paragraph) return;
    normalized.push(clipboardBlockFromPlainLineParts({
      indent: paragraph.indent,
      text: paragraph.lines.join("\n"),
    }, references));
    paragraph = null;
  };
  for (let index = 0; index < lines.length; index += 1) {
    if (markdownReferenceDefinition(lines[index])) {
      flushParagraph();
      continue;
    }
    const parts = clipboardPlainLineParts(lines[index]);
    if (!parts.text.trim()) {
      flushParagraph();
      continue;
    }
    const fence = markdownFenceOpen(parts.text);
    if (fence) {
      flushParagraph();
      const codeLines = [];
      let closed = false;
      for (index += 1; index < lines.length; index += 1) {
        const nextParts = clipboardPlainLineParts(lines[index]);
        if (markdownFenceClose(nextParts.text, fence)) {
          closed = true;
          break;
        }
        codeLines.push(lines[index]);
      }
      normalized.push({ type: "code", text: codeLines.join("\n"), language: fence.language, checked: false, indent: parts.indent, collapsed: false });
      if (!closed) break;
    } else {
      const setext = /^(=+|-+)\s*$/.exec(parts.text);
      if (setext && paragraph && paragraph.indent === parts.indent) {
        const heading = clipboardBlockFromPlainLineParts({ indent: paragraph.indent, text: paragraph.lines.join("\n") }, references);
        heading.type = setext[1][0] === "=" ? "heading1" : "heading2";
        normalized.push(heading);
        paragraph = null;
        continue;
      }
      const block = markdownBlockFromPlainText(parts.text);
      if (block.type === "paragraph") {
        if (!paragraph || paragraph.indent !== parts.indent) {
          flushParagraph();
          paragraph = { indent: parts.indent, lines: [] };
        }
        paragraph.lines.push(parts.text);
      } else {
        flushParagraph();
        applyMarkdownInlineSyntax(block, references);
        block.indent = parts.indent;
        normalized.push(block);
      }
    }
  }
  flushParagraph();
  while (normalized.length > 1 && normalized[normalized.length - 1].text === "" && normalized[normalized.length - 1].type === "paragraph") {
    normalized.pop();
  }
  return normalized;
}

function clipboardPlainLineParts(line) {
  let indent = 0;
  let text = line || "";
  while (text.startsWith("\t")) {
    indent += 1;
    text = text.slice(1);
  }
  while (text.startsWith("  ")) {
    indent += 1;
    text = text.slice(2);
  }
  return { indent: normalizedBlockIndent(indent), text };
}

function clipboardBlockFromPlainLineParts(parts, references = null) {
  const parsed = markdownBlockFromPlainText(parts.text);
  applyMarkdownInlineSyntax(parsed, references);
  parsed.indent = parts.indent;
  return parsed;
}

function markdownBlockFromPlainText(text) {
  const image = text.match(/^!\[([^\]\n]*)\]\((https:\/\/[^)\s]+)\)$/i);
  if (image && normalizeResourceImageUrl(image[2])) return { type: IMAGE_BLOCK_TYPE, text: image[1], alt: image[1], url: normalizeResourceImageUrl(image[2]), checked: false, collapsed: false };
  if (/^######\s+/.test(text)) return { type: "heading6", text: text.replace(/^######\s+/, ""), checked: false, collapsed: false };
  if (/^#####\s+/.test(text)) return { type: "heading5", text: text.replace(/^#####\s+/, ""), checked: false, collapsed: false };
  if (/^####\s+/.test(text)) return { type: "heading4", text: text.replace(/^####\s+/, ""), checked: false, collapsed: false };
  if (/^###\s+/.test(text)) return { type: "heading3", text: text.replace(/^###\s+/, ""), checked: false, collapsed: false };
  if (/^##\s+/.test(text)) return { type: "heading2", text: text.replace(/^##\s+/, ""), checked: false, collapsed: false };
  if (/^#\s+/.test(text)) return { type: "heading1", text: text.replace(/^#\s+/, ""), checked: false, collapsed: false };
  if (/^[-*]\s+\[[xX]\]\s+/.test(text)) return { type: "todo", text: text.replace(/^[-*]\s+\[[xX]\]\s+/, ""), checked: true, collapsed: false };
  if (/^[-*]\s+\[\s?\]\s+/.test(text)) return { type: "todo", text: text.replace(/^[-*]\s+\[\s?\]\s+/, ""), checked: false, collapsed: false };
  if (/^\d+[.)]\s+\[[xX]\]\s+/.test(text)) return { type: "todo", text: text.replace(/^\d+[.)]\s+\[[xX]\]\s+/, ""), checked: true, collapsed: false };
  if (/^\d+[.)]\s+\[\s?\]\s+/.test(text)) return { type: "todo", text: text.replace(/^\d+[.)]\s+\[\s?\]\s+/, ""), checked: false, collapsed: false };
  if (/^[-*+]\s+/.test(text)) return { type: "bullet", text: text.replace(/^[-*+]\s+/, ""), checked: false, collapsed: false };
  const numbered = /^(\d+)[.)]\s+/.exec(text);
  if (numbered) return { type: "numbered", text: text.slice(numbered[0].length), listStart: Number(numbered[1]), checked: false, collapsed: false };
  if (/^[aAiI][.)]\s+/.test(text)) return { type: "numbered", text: text.replace(/^[aAiI][.)]\s+/, ""), checked: false, collapsed: false };
  if (/^\[[xX]\]\s+/.test(text)) return { type: "todo", text: text.replace(/^\[[xX]\]\s+/, ""), checked: true, collapsed: false };
  if (/^\[\s?\]\s+/.test(text)) return { type: "todo", text: text.replace(/^\[\s?\]\s+/, ""), checked: false, collapsed: false };
  if (/^>\s+/.test(text)) return { type: "toggle", text: text.replace(/^>\s+/, ""), checked: false, collapsed: false };
  if (/^\|\s+/.test(text)) return { type: "quote", text: text.replace(/^\|\s+/, ""), checked: false, collapsed: false };
  if (/^!\s+/.test(text)) return { type: "callout", text: text.replace(/^!\s+/, ""), checked: false, collapsed: false };
  if (/^```\s*/.test(text)) return { type: "code", text: text.replace(/^```\s*/, ""), checked: false, collapsed: false };
  if (/^(?:---|\*\*\*|___)$/.test(text)) return { type: "divider", text: "", checked: false, collapsed: false };
  return { type: "paragraph", text, checked: false, collapsed: false };
}

function markdownReferenceDefinitions(lines = []) {
  const references = new Map();
  let fence = null;
  for (const line of lines) {
    const parts = clipboardPlainLineParts(line);
    if (fence) {
      if (markdownFenceClose(parts.text, fence)) fence = null;
      continue;
    }
    fence = markdownFenceOpen(parts.text);
    if (fence) continue;
    const definition = markdownReferenceDefinition(line);
    if (definition) references.set(definition.label, definition.href);
  }
  return references;
}

function markdownReferenceDefinition(line = "") {
  const match = /^\s{0,3}\[([^\]\n]+)\]:\s*(?:<([^>\s]+)>|(\S+))(?:\s+(?:"[^"]*"|'[^']*'|\([^)]*\)))?\s*$/.exec(String(line));
  if (!match) return null;
  const href = normalizeInlineHref(match[2] || match[3] || "");
  return href ? { label: markdownReferenceLabel(match[1]), href } : null;
}

function markdownReferenceLabel(label = "") {
  return String(label).trim().replace(/\s+/g, " ").toLowerCase();
}

function markdownFenceOpen(text = "") {
  const match = /^(?<fence>`{3,}|~{3,})(?<info>[^`]*)$/.exec(String(text || ""));
  if (!match) return null;
  return {
    character: match.groups.fence[0],
    length: match.groups.fence.length,
    language: String(match.groups.info || "").trim().split(/\s+/, 1)[0].slice(0, 64),
  };
}

function markdownFenceClose(text = "", fence = null) {
  if (!fence) return false;
  const character = fence.character === "~" ? "~" : "`";
  const match = new RegExp(`^${character === "`" ? "`" : "~"}{${fence.length},}\\s*$`).exec(String(text || ""));
  return Boolean(match);
}

function applyMarkdownInlineSyntax(block, references = null) {
  if (!block || ["code", "divider"].includes(block.type)) {
    if (block) block.marks = [];
    return block;
  }
  const inline = parseMarkdownInlineText(block.text || "", references);
  block.text = inline.text;
  block.marks = inline.marks;
  return block;
}

function parseMarkdownInlineText(text = "", references = null) {
  const source = String(text || "");
  const marks = [];
  let output = "";
  const sourceToOutput = Array(source.length + 1).fill(0);
  const markSourceRange = (startIndex, endIndex, outputStart, outputEnd) => {
    for (let sourceIndex = startIndex; sourceIndex <= endIndex; sourceIndex += 1) {
      sourceToOutput[sourceIndex] = sourceIndex === endIndex ? outputEnd : Math.max(outputStart, Math.min(outputEnd, sourceToOutput[sourceIndex] || outputStart));
    }
  };
  const appendPlainCharacter = (index) => {
    sourceToOutput[index] = output.length;
    output += source[index];
    sourceToOutput[index + 1] = output.length;
  };
  const appendNested = (nestedSource, wrapper = null) => {
    const start = output.length;
    const nested = parseMarkdownInlineText(nestedSource, references);
    output += nested.text;
    for (const mark of nested.marks) marks.push({ ...mark, start: mark.start + start, end: mark.end + start });
    if (wrapper && output.length > start) marks.push({ ...wrapper, start, end: output.length });
    return { start, end: output.length };
  };
  for (let index = 0; index < source.length;) {
    if (source[index] === "\\" && index + 1 < source.length && /[\\`*{}\[\]()#+.!_>~-]/.test(source[index + 1])) {
      sourceToOutput[index] = output.length;
      output += source[index + 1];
      sourceToOutput[index + 1] = output.length - 1;
      sourceToOutput[index + 2] = output.length;
      index += 2;
      continue;
    }
    const linkMatch = source.slice(index).match(/^\[([^\]\n]+)\]\((?:<([^>\n]+)>|([^\s)]+))(?:\s+(?:"[^"]*"|'[^']*'|\([^)]*\)))?\)/i);
    const linkHref = linkMatch ? normalizeInlineHref(linkMatch[2] || linkMatch[3] || "") : "";
    if (linkMatch && linkHref) {
      const nested = appendNested(linkMatch[1], { type: "link", href: linkHref });
      markSourceRange(index, index + linkMatch[0].length, nested.start, nested.end);
      index += linkMatch[0].length;
      continue;
    }
    const referenceMatch = references?.size
      ? source.slice(index).match(/^\[([^\]\n]+)\](?:\[([^\]\n]*)\])?/)
      : null;
    if (referenceMatch) {
      const label = referenceMatch[1];
      const key = markdownReferenceLabel(referenceMatch[2] || label);
      const href = references.get(key) || "";
      if (href) {
        const nested = appendNested(label, { type: "link", href });
        markSourceRange(index, index + referenceMatch[0].length, nested.start, nested.end);
        index += referenceMatch[0].length;
        continue;
      }
    }
    const angleLinkMatch = source.slice(index).match(/^<(https?:\/\/[^<>\s]+|[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})>/i);
    if (angleLinkMatch) {
      const label = angleLinkMatch[1];
      const start = output.length;
      output += label;
      marks.push({ type: "link", start, end: output.length, href: normalizeInlineHref(label) });
      markSourceRange(index, index + angleLinkMatch[0].length, start, output.length);
      index += angleLinkMatch[0].length;
      continue;
    }
    const bareLinkMatch = source.slice(index).match(/^(https?:\/\/[^\s<>]+|www\.[^\s<>]+|[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})(?=$|\s)/i);
    if (bareLinkMatch && (index === 0 || /[\s(\[{]/.test(source[index - 1]))) {
      let label = bareLinkMatch[1];
      const trailing = label.match(/[.,!?;:]+$/)?.[0] || "";
      if (trailing) label = label.slice(0, -trailing.length);
      const href = normalizeInlineHref(label);
      if (href && label) {
        const start = output.length;
        output += label;
        marks.push({ type: "link", start, end: output.length, href });
        if (trailing) output += trailing;
        markSourceRange(index, index + bareLinkMatch[0].length, start, output.length);
        index += bareLinkMatch[0].length;
        continue;
      }
    }
    const codeFence = source[index] === "`" ? /^`+/.exec(source.slice(index))?.[0] || "" : "";
    const codeEnd = codeFence ? source.indexOf(codeFence, index + codeFence.length) : -1;
    if (codeFence && codeEnd >= 0) {
      let codeText = source.slice(index + codeFence.length, codeEnd).replace(/\n/g, " ");
      if (/^\s[\s\S]*\s$/.test(codeText) && /\S/.test(codeText)) codeText = codeText.slice(1, -1);
      const start = output.length;
      output += codeText;
      marks.push({ type: "code", start, end: output.length });
      markSourceRange(index, codeEnd + codeFence.length, start, output.length);
      index = codeEnd + codeFence.length;
      continue;
    }
    const boldItalicMatch = source.slice(index).match(/^(\*\*\*|___)(\S(?:[\s\S]*?\S)?)\1/);
    if (boldItalicMatch) {
      const nested = appendNested(boldItalicMatch[2], { type: "bold" });
      if (nested.end > nested.start) marks.push({ type: "italic", start: nested.start, end: nested.end });
      markSourceRange(index, index + boldItalicMatch[0].length, nested.start, nested.end);
      index += boldItalicMatch[0].length;
      continue;
    }
    const boldMatch = source.slice(index).match(/^(\*\*|__)(\S(?:[\s\S]*?\S)?)\1/);
    if (boldMatch) {
      const nested = appendNested(boldMatch[2], { type: "bold" });
      markSourceRange(index, index + boldMatch[0].length, nested.start, nested.end);
      index += boldMatch[0].length;
      continue;
    }
    if (source.slice(index).startsWith("**") || source.slice(index).startsWith("__")) {
      appendPlainCharacter(index);
      index += 1;
      continue;
    }
    const strikeMatch = source.slice(index).match(/^~~(\S(?:[\s\S]*?\S)?)~~/);
    if (strikeMatch) {
      const nested = appendNested(strikeMatch[1], { type: "strike" });
      markSourceRange(index, index + strikeMatch[0].length, nested.start, nested.end);
      index += strikeMatch[0].length;
      continue;
    }
    const italicMatch = source.slice(index).match(/^(\*|_)(\S(?:[^*_]*?\S)?)\1/);
    if ((source[index] === "*" || source[index] === "_") && source[index - 1] === source[index]) {
      appendPlainCharacter(index);
      index += 1;
      continue;
    }
    if (italicMatch) {
      const nested = appendNested(italicMatch[2], { type: "italic" });
      markSourceRange(index, index + italicMatch[0].length, nested.start, nested.end);
      index += italicMatch[0].length;
      continue;
    }
    appendPlainCharacter(index);
    index += 1;
  }
  sourceToOutput[source.length] = output.length;
  return { text: output, marks: normalizeInlineMarks(output, marks), sourceToOutput };
}

function pasteBlocksFromClipboard(event, blocks, options = {}) {
  const target = clipboardPasteTarget(event, options);
  if (!target) return false;
  if (!editorOwnerMutationAllowed(target.ownerType, target.ownerId)) return false;
  const item = itemById(target.ownerType, target.ownerId);
  if (!item?.blocks) return false;
  const prepared = prepareClipboardBlockPaste(item, target, blocks);
  if (!prepared) return false;
  const preflightAt = new Date().toISOString();
  const focusTarget = prepared.focusTarget;
  const history = beginEditorHistory(
    target.ownerType,
    target.ownerId,
    { blockId: target.replaceSelection ? target.selection?.ids?.[0] : target.blockId, position: "end" },
  );
  item.blocks = prepared.item.blocks;
  ensureEditableBlocks(item);
  clearBlockSelection();
  commitEditorHistory(history, Number.isInteger(focusTarget.offset)
    ? { blockId: focusTarget.blockId, start: focusTarget.offset, end: focusTarget.offset }
    : { blockId: focusTarget.blockId, position: "end" }, { at: preflightAt });
  saveState();
  renderEditorMutation(target.ownerType, target.ownerId, { forceView: true });
  focusBlockContentAfterRender(focusTarget.blockId, Number.isInteger(focusTarget.offset)
    ? { range: { start: focusTarget.offset, end: focusTarget.offset } }
    : { position: "end" });
  return true;
}

function prepareClipboardBlockPaste(item, target, blocks) {
  const projectedItem = cloneForLocalPersistence(item);
  const normalizedBlocks = normalizeClipboardBlocks(blocks);
  const baseIndent = clipboardPasteBaseIndent(projectedItem.blocks, target);
  const minIndent = minimumClipboardIndent(normalizedBlocks);
  const pasted = [];
  for (const block of normalizedBlocks) {
    const pastedBlock = {
      id: id(),
      type: block.type,
      text: block.text,
      marks: normalizeInlineMarks(block.text, block.marks).filter((mark) => (
        mark.type !== "resourceLink"
        || (target.ownerType === "resources" && !["code", "divider", "bookmark", "embed", "image"].includes(block.type))
      )),
      checked: block.type === "todo" && block.checked === true,
      indent: normalizedBlockIndent(baseIndent + block.indent - minIndent),
      collapsed: block.type === "toggle" && block.collapsed === true,
    };
    if (isUrlPreviewBlockType(block.type)) pastedBlock.url = normalizeStandaloneHttpsUrl(block.url || block.text || "");
    if (block.type === IMAGE_BLOCK_TYPE) {
      pastedBlock.url = normalizeResourceImageUrl(block.url);
      pastedBlock.alt = String(block.alt || block.text || "");
    }
    if (block.type === "numbered" && numberedBlockStart(block)) pastedBlock.listStart = numberedBlockStart(block);
    if (block.type === "code" && typeof block.language === "string") pastedBlock.language = block.language.trim().split(/\s+/, 1)[0].slice(0, 64);
    pasted.push(pastedBlock);
  }
  if (!pasted.length) return null;
  let focusTarget = { blockId: pasted[pasted.length - 1].id };
  if (target.replaceSelection) {
    replaceSelectedBlocksWithPasted(projectedItem, pasted, target.selection);
  } else {
    focusTarget = insertPastedBlocksAtTarget(projectedItem, pasted, target);
  }
  return { item: projectedItem, focusTarget };
}




function resourcePutRequestBody(resource, options = {}) {
  const fixtureFields = isPlainObject(options.fixtureFields) ? options.fixtureFields : e2eFixtureGenerationRequestFields();
  return JSON.stringify({ resource: cloneForLocalPersistence(resource), ...fixtureFields });
}

function clipboardPasteBaseIndent(blocksList, target) {
  if (target.replaceSelection) {
    const selected = new Set(target.selection?.ids || []);
    const selectedBlock = blocksList.find((block) => selected.has(block.id));
    return blockIndent(selectedBlock);
  }
  const block = blocksList.find((entry) => entry.id === target.blockId);
  return blockIndent(block);
}

function minimumClipboardIndent(blocks) {
  if (!blocks.length) return 0;
  let minimum = MAX_BLOCK_INDENT;
  for (const block of blocks) minimum = Math.min(minimum, block.indent || 0);
  return minimum;
}

function clipboardPasteTarget(event, options = {}) {
  if (ui.blockSelection.ids.length) {
    const eventBlock = pasteEventBlockContent(event);
    const eventEditor = eventBlock?.closest(".block-editor");
    if (eventBlock && (!eventEditor || eventEditor.dataset.ownerType !== ui.blockSelection.ownerType || eventEditor.dataset.ownerId !== ui.blockSelection.ownerId || !ui.blockSelection.ids.includes(eventBlock.dataset.blockContent || ""))) {
      return clipboardPasteTargetFromBlockContent(eventBlock, options);
    }
    return {
      ownerType: ui.blockSelection.ownerType,
      ownerId: ui.blockSelection.ownerId,
      replaceSelection: true,
      selection: { ownerType: ui.blockSelection.ownerType, ownerId: ui.blockSelection.ownerId, ids: ui.blockSelection.ids.slice() },
    };
  }
  const targetBlock = event.target instanceof Element ? event.target.closest("[data-block-content]") : null;
  const activeBlock = document.activeElement instanceof Element ? document.activeElement.closest("[data-block-content]") : null;
  return clipboardPasteTargetFromBlockContent(targetBlock || activeBlock, options);
}

function clipboardPasteTargetFromBlockContent(blockContent, options = {}) {
  const editor = blockContent?.closest(".block-editor");
  if (!blockContent || !editor) return null;
  const target = {
    ownerType: editor.dataset.ownerType,
    ownerId: editor.dataset.ownerId,
    blockId: blockContent.dataset.blockContent,
    replaceSelection: false,
  };
  if (options.mergeIntoTarget) {
    target.mergeIntoTarget = true;
    target.textSplit = splitTextAtSelection(blockContent);
    target.selectionOffsets = selectionOffsetsInside(blockContent);
  }
  return target;
}

function replaceSelectedBlocksWithPasted(item, pasted, selection) {
  const selectedIds = selectedBlockSubtreeIds(item.blocks, selection.ids);
  const nextBlocks = [];
  let inserted = false;
  for (const block of item.blocks) {
    if (selectedIds.has(block.id)) {
      if (!inserted) {
        for (const pastedBlock of pasted) nextBlocks.push(pastedBlock);
        inserted = true;
      }
      continue;
    }
    nextBlocks.push(block);
  }
  if (!inserted) {
    for (const pastedBlock of pasted) nextBlocks.push(pastedBlock);
  }
  item.blocks = nextBlocks;
  ensureEditableBlocks(item);
}

function insertPastedBlocksAtTarget(item, pasted, target) {
  const blockId = typeof target === "string" ? target : target?.blockId;
  const index = item.blocks.findIndex((block) => block.id === blockId);
  if (index < 0) {
    item.blocks.push(...pasted);
    return { blockId: pasted[pasted.length - 1].id };
  }
  const current = item.blocks[index];
  const replaceCurrent =
    current &&
    current.type === "paragraph" &&
    (current.text || "") === "";
  if (replaceCurrent) {
    item.blocks.splice(index, 1, ...pasted);
    return { blockId: pasted[pasted.length - 1].id };
  }
  if (target?.mergeIntoTarget && target.textSplit && current.type !== "divider") {
    return mergePastedBlocksIntoTarget(item, pasted, index, target.textSplit, target.selectionOffsets);
  }
  item.blocks.splice(blockSubtreeEndIndex(item.blocks, index) + 1, 0, ...pasted);
  return { blockId: pasted[pasted.length - 1].id };
}

function mergePastedBlocksIntoTarget(item, pasted, index, split, offsets = null) {
  const current = item.blocks[index];
  const before = split.before || "";
  const after = split.after || "";
  const firstText = pasted[0]?.text || "";
  const originalText = current.text || "";
  const selectionStart = Number.isInteger(offsets?.start) ? offsets.start : before.length;
  const selectionEnd = Number.isInteger(offsets?.end) ? offsets.end : originalText.length - after.length;
  const currentMarks = splitInlineMarksAtSelection(current.marks, originalText, selectionStart, selectionEnd);
  const firstMarks = shiftInlineMarks(pasted[0]?.marks || [], before.length);
  current.text = `${before}${firstText}`;
  current.marks = normalizeInlineMarks(current.text, [...currentMarks.before, ...firstMarks]);
  const trailing = [];
  for (let pastedIndex = 1; pastedIndex < pasted.length; pastedIndex += 1) {
    const block = { ...pasted[pastedIndex] };
    if (pastedIndex === pasted.length - 1) {
      const originalPastedText = block.text || "";
      block.text = `${originalPastedText}${after}`;
      block.marks = normalizeInlineMarks(block.text, [
        ...(block.marks || []),
        ...shiftInlineMarks(currentMarks.after, originalPastedText.length),
      ]);
    }
    trailing.push(block);
  }
  if (!trailing.length) {
    current.text = `${before}${firstText}${after}`;
    current.marks = normalizeInlineMarks(current.text, [
      ...currentMarks.before,
      ...firstMarks,
      ...shiftInlineMarks(currentMarks.after, before.length + firstText.length),
    ]);
  }
  if (trailing.length) item.blocks.splice(index + 1, 0, ...trailing);
  const focusBlock = trailing.length ? trailing[trailing.length - 1] : current;
  const offset = trailing.length ? (pasted[pasted.length - 1].text || "").length : before.length + firstText.length;
  return { blockId: focusBlock.id, offset };
}

function handleSelectedBlocksTabKey(event) {
  if (!ui.blockSelection.ids.length || event.key !== "Tab") return false;
  event.preventDefault();
  event.stopPropagation();
  indentSelectedBlocks(event.shiftKey ? -1 : 1);
  return true;
}

function isPlainSpaceKey(event) {
  return (
    (event.key === " " || event.key === "Spacebar" || event.code === "Space") &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.altKey &&
    !event.shiftKey &&
    !event.isComposing
  );
}

function toggleSelectedActionBlocks() {
  const selection = ui.blockSelection;
  if (!editorOwnerMutationAllowed(selection.ownerType, selection.ownerId)) return false;
  if (!selection.ids.length) return false;
  const item = itemById(selection.ownerType, selection.ownerId);
  if (!item?.blocks) {
    clearBlockSelection();
    return false;
  }
  const selectedIds = new Set(selection.ids);
  const actionBlocks = item.blocks.filter((block) => selectedIds.has(block.id) && (block.type === "todo" || block.type === "toggle"));
  if (!actionBlocks.length) return false;
  const history = beginEditorHistory(selection.ownerType, selection.ownerId, { blockId: actionBlocks[0].id, position: "end" });
  for (const block of actionBlocks) {
    if (block.type === "todo") block.checked = !block.checked;
    if (block.type === "toggle") block.collapsed = block.collapsed !== true;
  }
  commitEditorHistory(history, { blockId: actionBlocks[0].id, position: "end" });
  saveState();
  renderEditorMutation(selection.ownerType, selection.ownerId, { forceView: true });
  requestAnimationFrame(() => restoreBlockSelection(selection.ownerType, selection.ownerId, selection.ids));
  return true;
}

function handleSelectedBlocksEditableKey(event, blockContent = null) {
  if (!ui.blockSelection.ids.length || !blockContent) return false;
  const editor = blockContent.closest(".block-editor");
  if (!editor || editor.dataset.ownerType !== ui.blockSelection.ownerType || editor.dataset.ownerId !== ui.blockSelection.ownerId) return false;
  if (document.activeElement === blockContent && !shouldPreserveBlockSelectionFocus(blockContent)) {
    clearBlockSelection();
    return false;
  }
  if (!ui.blockSelection.ids.includes(blockContent.dataset.blockContent)) {
    clearBlockSelection();
    return false;
  }
  if (isPlainSpaceKey(event) && toggleSelectedActionBlocks()) {
    event.preventDefault();
    event.stopPropagation();
    return true;
  }
  if (event.key === "Enter" && !event.metaKey && !event.ctrlKey && !event.altKey) {
    event.preventDefault();
    event.stopPropagation();
    focusSelectedBlockForEditing(event.shiftKey ? "start" : "end");
    return true;
  }
  if (["Backspace", "Delete"].includes(event.key)) {
    event.preventDefault();
    event.stopPropagation();
    deleteSelectedBlocks();
    return true;
  }
  if (!event.metaKey && !event.ctrlKey && !event.altKey && !event.isComposing && event.key.length === 1) {
    event.preventDefault();
    event.stopPropagation();
    replaceSelectedBlocksWithText(event.key);
    return true;
  }
  return false;
}


function blockDragHandleFromEvent(event) {
  if (!(event.target instanceof Element)) return null;
  const handle = event.target.closest("[data-block-drag]");
  return handle?.closest('[aria-hidden="true"], [hidden], [inert]') ? null : handle;
}





function selectedBlockDragTarget(event) {
  if (!(event.target instanceof Element)) return null;
  const dragHandle = event.target.closest("[data-block-drag]");
  if (dragHandle || event.target.closest("input, select, textarea, a, button")) return null;
  let block = event.target.closest(".block.is-selected");
  if (!block && typeof document.elementsFromPoint === "function") {
    for (const element of document.elementsFromPoint(event.clientX, event.clientY)) {
      block = element.closest?.(".block.is-selected");
      if (block) break;
    }
  }
  if (!block) {
    const editorScope = event.target.closest(".block-editor");
    const candidates = editorScope
      ? [...editorScope.querySelectorAll(".block.is-selected[data-block-id]")]
      : [...document.querySelectorAll(".block.is-selected[data-block-id]")];
    block = candidates.find((candidate) => {
      if (candidate.hidden || candidate.getAttribute("aria-hidden") === "true") return false;
      return selectedBlockRowHitTest(candidate, event.clientX, event.clientY);
    }) || null;
  }
  const editor = block?.closest(".block-editor");
  const blockId = block?.dataset?.blockId || "";
  if (!block || !editor || !blockId) return null;
  if (ui.blockSelection.ownerType !== editor.dataset.ownerType || ui.blockSelection.ownerId !== editor.dataset.ownerId) return null;
  if (!ui.blockSelection.ids.includes(blockId)) return null;
  return { block, editor, blockId };
}

function selectedBlockRowHitTest(block, clientX, clientY) {
  const rect = block.getBoundingClientRect();
  if (clientY < rect.top || clientY > rect.bottom) return false;
  return clientX >= rect.left && clientX <= rect.right;
}


function rememberSelectedBlockDragHover(event) {
  if (!(event.target instanceof Element)) return;
  if (event.buttons !== undefined && event.buttons !== 0) return;
  const target = selectedBlockDragTarget(event);
  if (!target) return;
  ui.selectedBlockDragHover = {
    ownerType: target.editor.dataset.ownerType,
    ownerId: target.editor.dataset.ownerId,
    blockId: target.blockId,
    pointerId: eventPointerId(event),
    x: event.clientX,
    y: event.clientY,
    time: Date.now(),
  };
}

function selectedBlockDragHoverTarget(event) {
  const cached = ui.selectedBlockDragHover;
  if (!cached || !sameMouseLikePointer(cached.pointerId, event)) return null;
  if (Date.now() - cached.time > 300) return null;
  if (Math.hypot(event.clientX - cached.x, event.clientY - cached.y) > 28) return null;
  if (ui.blockSelection.ownerType !== cached.ownerType || ui.blockSelection.ownerId !== cached.ownerId) return null;
  if (!ui.blockSelection.ids.includes(cached.blockId)) return null;
  const editor = document.querySelector(`.block-editor[data-owner-type="${cached.ownerType}"][data-owner-id="${cached.ownerId}"]`);
  const block = editor?.querySelector(`[data-block-id="${cssEscape(cached.blockId)}"]`);
  if (!block || block.hidden || block.getAttribute("aria-hidden") === "true") return null;
  return { block, editor, blockId: cached.blockId };
}

function sameMouseLikePointer(cachedPointerId, event) {
  const eventId = eventPointerId(event);
  if (cachedPointerId === eventId) return true;
  const mouseEvent =
    event.pointerType === "mouse" ||
    event.type === "mousedown" ||
    event.type === "mousemove" ||
    event.type === "mouseup";
  return mouseEvent && (cachedPointerId === "mouse" || eventId === "mouse");
}

function canBypassBlockClickSuppressionForDrag(event) {
  if (!(event.target instanceof Element)) return false;
  if ((event.pointerType === "mouse" || event.type === "mousedown") && event.button !== 0) return false;
  if (event.target.closest("[data-block-content]")) return true;
  if (blockDragHandleFromEvent(event)) return true;
  if (event.target.closest("[data-block-add]")) return true;
  return Boolean(selectedBlockDragTarget(event));
}





function handlePointerDown(event) {
  preferredVerticalCaretX = null;
  if (handleSelectedBlocksMenuOutsidePointerDown(event)) return;

  const todayBatchTask = event.target.closest("[data-today-batch-task]");
  if (ui.todayBatch?.phase === "place" && todayBatchTask) {
    if (!canStartCustomPointerDrag(event)) return;
    const task = itemById("tasks", todayBatchTask.dataset.todayBatchTask);
    if (!task || !ui.todayBatch.taskIds.includes(task.id)) return;
    window.getSelection()?.removeAllRanges();
    ui.pendingTodayTaskDrag = {
      taskId: task.id,
      card: todayBatchTask,
      batch: true,
      pointerId: event.pointerId ?? "mouse",
      startX: event.clientX,
      startY: event.clientY,
    };
    return;
  }

  if (event.target.closest("[data-inline-mark-toggle], [data-inline-resource-citation-open], [data-resource-citation-id], [data-resource-citation-remove], [data-inline-equation-open], [data-inline-color-menu-toggle], [data-inline-color-choice], [data-inline-link-remove], [data-inline-comment-remove], [data-inline-equation-remove], [data-mention-index], [data-page-command-index], [data-emoji-index]")) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  rememberEditableControlFocusRange(event);
  if (ui.suppressBlockClickUntil > Date.now() && event.target.closest(".block, .block-editor")) {
    if (canBypassBlockClickSuppressionForDrag(event)) {
      ui.suppressBlockClickUntil = 0;
    } else {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
  }
  if (event.type === "pointerdown" && handleBlockSelectionClick(event)) {
    ui.suppressBlockClickUntil = Date.now() + 160;
    return;
  }
  if (event.type === "mousedown" && (event.shiftKey || ui.shiftKeyDown) && ui.suppressBlockClickUntil > Date.now() && event.target.closest(".block")) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  if (
    event.type === "mousedown" &&
    (ui.blockDrag || ui.pendingBlockToolDrag || ui.pendingNavDrag || ui.navPointerDrag || ui.pendingEditorMarquee || ui.editorMarquee)
  ) {
    return;
  }

  if (beginPendingEditorMarquee(event)) return;

  const navButton = event.target.closest("[data-nav-key]");
  if (navButton && !navButton.hasAttribute("data-nav-fixed") && (ui.navOpen || ui.navDocked)) {
    if (event.type === "mousedown" && (ui.pendingNavDrag || ui.navPointerDrag)) return;
    if (!canStartCustomPointerDrag(event)) return;
    ui.pendingNavDrag = {
      key: navButton.dataset.navKey,
      pointerId: event.pointerId ?? "mouse",
      startX: event.clientX,
      startY: event.clientY,
    };
    return;
  }




  const blockDragHandle = blockDragHandleFromEvent(event);
  if (blockDragHandle) {
    if (event.type === "mousedown" && ui.blockDrag) return;
    if (!canStartCustomPointerDrag(event)) return;
    beginBlockDrag(blockDragHandle.dataset.blockDrag, event, {
      block: blockDragHandle.closest(".block"),
      editor: blockDragHandle.closest(".block-editor"),
      captureTarget: blockDragHandle,
      openMenuOnClick: true,
    });
    return;
  }

  const selectedBlockDrag = selectedBlockDragTarget(event) || selectedBlockDragHoverTarget(event);
  if (selectedBlockDrag) {
    if (event.type === "mousedown" && ui.blockDrag) return;
    if (!canStartCustomPointerDrag(event)) return;
    beginBlockDrag(selectedBlockDrag.blockId, event, {
      block: selectedBlockDrag.block,
      editor: selectedBlockDrag.editor,
      captureTarget: selectedBlockDrag.block,
      indentOriginX: event.clientX,
      activationDistance: BLOCK_BODY_DRAG_ACTIVATION_DISTANCE,
      editOnClickIfNotDragged: true,
    });
    return;
  }

  const selectedBlockAddDrag = event.target.closest("[data-block-add]");
  if (selectedBlockAddDrag) {
    const selectedAddBlock = selectedBlockAddDrag.closest(".block[data-block-id]");
    const selectedAddEditor = selectedAddBlock?.closest(".block-editor");
    const selectedAddBlockId = selectedBlockAddDrag.dataset.blockAdd || selectedAddBlock?.dataset.blockId || "";
    const selectedAddMatchesSelection =
      selectedAddEditor &&
      ui.blockSelection.ownerType === selectedAddEditor.dataset.ownerType &&
      ui.blockSelection.ownerId === selectedAddEditor.dataset.ownerId &&
      ui.blockSelection.ids.includes(selectedAddBlockId);
    if (selectedAddMatchesSelection) {
      if (event.type === "mousedown" && ui.pendingBlockToolDrag) return;
      if (!canStartCustomPointerDrag(event)) return;
      ui.pendingBlockToolDrag = {
        blockId: selectedAddBlockId,
        pointerId: eventPointerId(event),
        startX: event.clientX,
        startY: event.clientY,
        target: selectedBlockAddDrag,
      };
      return;
    }
  }


  const blockAddDrag = event.target.closest("[data-block-add]");
  if (blockAddDrag) {
    if (event.type === "mousedown" && ui.pendingBlockToolDrag) return;
    if (!canStartCustomPointerDrag(event)) return;
    ui.pendingBlockToolDrag = {
      blockId: blockAddDrag.dataset.blockAdd,
      pointerId: eventPointerId(event),
      startX: event.clientX,
      startY: event.clientY,
      target: blockAddDrag,
    };
    return;
  }


  const todayTaskDragRow = event.target.closest(".today-dashboard-grid [data-task-inline-toggle]");
  if (ui.view === "today" && todayTaskDragRow && !event.target.closest("button, input, select, textarea, [contenteditable='true']")) {
    if (!canStartCustomPointerDrag(event)) return;
    const card = todayTaskDragRow.closest("[data-today-task-id]");
    const task = itemById("tasks", card?.dataset.todayTaskId);
    if (!card || !task || ["done", "canceled"].includes(task.status)) return;
    window.getSelection()?.removeAllRanges();
    ui.pendingTodayTaskDrag = {
      taskId: task.id,
      card,
      pointerId: event.pointerId ?? "mouse",
      startX: event.clientX,
      startY: event.clientY,
    };
    return;
  }

  const deleteDragCard = event.target.closest("[data-delete-drag-type][data-delete-drag-id]");
  if (deleteDragCard && (["projects", "boxes"].includes(ui.view) || (ui.view === "today" && deleteDragCard.closest("[data-today-inbox]"))) && !event.target.closest("button, input, select, textarea, [contenteditable='true']")) {
    if (!canStartCustomPointerDrag(event)) return;
    window.getSelection()?.removeAllRanges();
    ui.pendingDeleteDrag = {
      type: deleteDragCard.dataset.deleteDragType,
      id: deleteDragCard.dataset.deleteDragId,
      pointerId: event.pointerId ?? "mouse",
      startX: event.clientX,
      startY: event.clientY,
    };
    return;
  }

  const schedulerButton = event.target.closest("[data-scheduler-open]");
  if (schedulerButton) {
    if (!canStartCustomPointerDrag(event)) return;
    const card = schedulerButton.closest("[data-schedule-hold]");
    const task = itemById("tasks", schedulerButton.dataset.schedulerOpen);
    if (!card || !task || ["done", "canceled"].includes(task.status)) return;
    ui.pendingScheduleDrag = {
      taskId: task.id,
      pointerId: event.pointerId ?? "mouse",
      startX: event.clientX,
      startY: event.clientY,
    };
    return;
  }

  const card = event.target.closest("[data-schedule-hold]");
  if (!card || event.target.closest("[data-toggle-task]")) return;
  if (event.type === "mousedown" && Date.now() - ui.lastSchedulePointerAt < 500) return;
  if (event.type === "pointerdown") ui.lastSchedulePointerAt = Date.now();
  if (!canStartCustomPointerDrag(event)) return;
  const task = itemById("tasks", card.dataset.scheduleHold);
  if (!task || ["done", "canceled"].includes(task.status)) return;
  ui.pendingScheduleDrag = {
    taskId: task.id,
    pointerId: event.pointerId ?? "mouse",
    startX: event.clientX,
    startY: event.clientY,
  };
}

function beginScheduleDrag(task, card, event) {
  cancelScheduleDrag();
;
  ui.scheduleHoldTaskId = task.id;
  ui.suppressTaskClickUntil = Date.now() + 1600;
  card.classList.add("is-holding");
  try {
    if (event.pointerId !== undefined && card.setPointerCapture) card.setPointerCapture(event.pointerId);
  } catch (_) {}
  const rect = card.getBoundingClientRect();
  const clientX = event.clientX || card.getBoundingClientRect().left + card.getBoundingClientRect().width / 2;
  const clientY = event.clientY || card.getBoundingClientRect().top + card.getBoundingClientRect().height / 2;
  openTaskScheduler(task.id, clientX, clientY, {
    dragging: true,
    pointerId: event.pointerId ?? "mouse",
    dragX: clientX + 14,
    dragY: clientY + 14,
    dragWidth: Math.min(300, Math.max(220, rect.width)),
  });
  updateScheduleDragPosition(clientX, clientY);
}

function cancelScheduleDrag() {
  const hadDrag = Boolean(ui.scheduler?.dragging || ui.scheduleHoldTaskId);
  ui.pendingScheduleDrag = null;
  if (ui.scheduleHoldTaskId) {
    document.querySelector(`[data-schedule-hold="${ui.scheduleHoldTaskId}"]`)?.classList.remove("is-holding");
  }
  ui.scheduleHoldTaskId = "";
  stopSchedulerMonthHover();
  document.querySelectorAll(".task-scheduler-day.is-drop-target, .task-scheduler-lane.is-drop-target, .task-scheduler-delete-zone.is-drop-target").forEach((target) => target.classList.remove("is-drop-target"));
  if (hadDrag) markScheduleDragEnded();
  if (ui.scheduler?.dragging) {
    closeTaskScheduler();
  }
}

function markScheduleDragEnded() {
  ui.lastScheduleDragEndedAt = Date.now();
  ui.suppressTaskClickUntil = Math.max(ui.suppressTaskClickUntil, ui.lastScheduleDragEndedAt + 1400);
}

function handleSchedulePointerExit(event) {
  if (!ui.scheduler?.dragging || event.relatedTarget) return;
  cancelScheduleDrag();
}

function handleScheduleVisibilityChange() {
  if (document.visibilityState === "hidden") {
    cancelEditorMarqueeDrag();
    cancelScheduleDrag();
    cancelTodayTaskDrag();
    cancelDeleteDrag();
    resetNavShortcutState({ closeAutoOpened: true });
  }
}

function handleTodayTaskPointerMove(event) {
  maybeStartPendingTodayTaskDrag(event);
  if (!ui.todayTaskDrag) return;
  if (!isActiveTodayTaskPointer(event)) return;
  event.preventDefault();
  updateTodayTaskDragPosition(event.clientX, event.clientY);
}

function maybeStartPendingTodayTaskDrag(event) {
  const pending = ui.pendingTodayTaskDrag;
  if (!pending) return;
  if (event.pointerId !== undefined && pending.pointerId !== event.pointerId) return;
  if (event.buttons !== undefined && event.buttons === 0) {
    ui.pendingTodayTaskDrag = null;
    return;
  }
  const dx = event.clientX - pending.startX;
  const dy = event.clientY - pending.startY;
  if (Math.hypot(dx, dy) < POINTER_DRAG_ACTIVATION_DISTANCE) return;
  const card = pending.card instanceof Element && pending.card.isConnected
    ? pending.card
    : document.querySelector(pending.batch
      ? `[data-today-batch-task="${cssEscape(pending.taskId)}"]`
      : `[data-today-task-id="${cssEscape(pending.taskId)}"]`);
  const task = itemById("tasks", pending.taskId);
  ui.pendingTodayTaskDrag = null;
  if (!card || !task) return;
  event.preventDefault();
  event.stopPropagation();
  beginTodayTaskDrag(task, card, event, { batch: Boolean(pending.batch) });
}

function beginTodayTaskDrag(task, card, event, options = {}) {
  cancelTodayTaskDrag();
  const rect = card.getBoundingClientRect();
  const offsetX = Math.min(Math.max(event.clientX - rect.left, 0), rect.width);
  const offsetY = Math.min(Math.max(event.clientY - rect.top, 0), rect.height);
  try {
    if (event.pointerId !== undefined && card.setPointerCapture) card.setPointerCapture(event.pointerId);
  } catch (_) {}
  ui.todayTaskDrag = {
    taskId: task.id,
    pointerId: event.pointerId ?? "mouse",
    dragX: rect.left,
    dragY: rect.top,
    dragWidth: rect.width,
    offsetX,
    offsetY,
    targetDate: "",
    targetAction: "",
    targetElement: null,
    sourceCard: card,
    batch: Boolean(options.batch),
  };
  ui.suppressTaskClickUntil = Date.now() + 900;
  window.getSelection()?.removeAllRanges();
  app.classList.add("is-today-task-dragging");
  card.classList.add("is-holding");
  if (options.batch) {
    els.overlayRoot.querySelector(".today-drag-ghost")?.remove();
    els.overlayRoot.insertAdjacentHTML("beforeend", renderTodayTaskDragGhost());
  } else {
    renderOverlays();
  }
  updateTodayTaskDragPosition(event.clientX, event.clientY);
}

function updateTodayTaskDragPosition(clientX, clientY) {
  if (!ui.todayTaskDrag) return;
  ui.todayTaskDrag.dragX = clientX - (ui.todayTaskDrag.offsetX || 0);
  ui.todayTaskDrag.dragY = clientY - (ui.todayTaskDrag.offsetY || 0);
  const ghost = document.querySelector(".today-drag-ghost");
  if (ghost) {
    ghost.style.setProperty("--drag-x", `${ui.todayTaskDrag.dragX}px`);
    ghost.style.setProperty("--drag-y", `${ui.todayTaskDrag.dragY}px`);
  }
  setTodayTaskDropTarget(todayTaskTargetFromPoint(clientX, clientY));
}

function todayTaskTargetFromPoint(clientX, clientY) {
  const element = closestElementFromPoint(clientX, clientY, "[data-drop-date], [data-today-task-action]");
  if (!element) return {};
  return {
    element,
    date: element.dataset.dropDate || "",
    action: element.dataset.todayTaskAction || "",
  };
}

function setTodayTaskDropTarget(target = {}) {
  if (!ui.todayTaskDrag) return;
  document.querySelectorAll(".today-drop-zone.is-over, .today-floating-drop.is-over, .today-batch-target.is-over").forEach((entry) => entry.classList.remove("is-over"));
  if (target.date || target.action) target.element?.classList.add("is-over");
  ui.todayTaskDrag.targetDate = target.date || "";
  ui.todayTaskDrag.targetAction = target.action || "";
  ui.todayTaskDrag.targetElement = target.element || null;
}

function finishTodayTaskDrag(event) {
  if (!ui.todayTaskDrag) {
    if (ui.pendingTodayTaskDrag && (event?.pointerId === undefined || ui.pendingTodayTaskDrag.pointerId === event.pointerId)) ui.pendingTodayTaskDrag = null;
    return;
  }
  if (ui.todayTaskDrag.settling) return;
  if (!isActiveTodayTaskPointer(event)) return;
  event.preventDefault();
  event.stopPropagation();
  const drag = ui.todayTaskDrag;
  const task = itemById("tasks", drag.taskId);
  const pointTarget = todayTaskTargetFromPoint(event.clientX, event.clientY);
  const targetAction = drag.targetAction || pointTarget.action || "";
  const targetDate = drag.targetDate || pointTarget.date || "";
  const targetElement = (pointTarget.action && pointTarget.action === targetAction) || (pointTarget.date && pointTarget.date === targetDate)
    ? pointTarget.element
    : drag.targetElement?.isConnected
      ? drag.targetElement
      : null;
  ui.suppressTaskClickUntil = Date.now() + 900;

  if (!task || (drag.batch ? !targetAction : !targetAction && !targetDate)) {
    clearTodayTaskDragState();
    renderOverlays();
    return;
  }

  drag.settling = true;
  const commit = () => {
    clearTodayTaskDragState();
    if (drag.batch) {
      commitTodayBatchDrop(task, targetAction);
      return;
    }
    if (targetAction === "delete") {
      commitDragAction("tasks", task.id, "delete");
      renderOverlays();
      return;
    }
    if (targetAction === "scheduled") {
      commitTaskScheduleAction(task, "scheduled");
      return;
    }
    moveTaskToDate(task, targetDate);
    saveState();
    showToast(targetElement?.classList.contains("today-floating-drop") ? "예정으로 옮겼습니다." : `${compactDateLabel(targetDate)}로 옮겼습니다.`);
    renderView({ soft: true, animateCards: true });
;
    renderOverlays();
  };
  animateTodayTaskDrop(drag, targetElement, commit);
}

function animateTodayTaskDrop(drag, target, done) {
  const ghost = document.querySelector(".today-drag-ghost");
  if (
    !ghost ||
    !target ||
    typeof ghost.animate !== "function" ||
    typeof target.animate !== "function" ||
    window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
  ) {
    done();
    return;
  }
  const ghostRect = ghost.getBoundingClientRect();
  const targetRect = target.getBoundingClientRect();
  const translateX = targetRect.left + targetRect.width / 2 - ghostRect.left - ghostRect.width / 2;
  const translateY = targetRect.top + targetRect.height / 2 - ghostRect.top - ghostRect.height / 2;
  ghost.classList.add("is-settling");
  ghost.style.left = `${ghostRect.left}px`;
  ghost.style.top = `${ghostRect.top}px`;
  ghost.style.width = `${ghostRect.width}px`;
  ghost.style.setProperty("--drag-x", "0px");
  ghost.style.setProperty("--drag-y", "0px");
  target.classList.add("is-receiving");

  const animations = [
    ghost.animate(
      [
        { opacity: 1, transform: "translate3d(0, 0, 0) scale(1)" },
        { offset: 0.66, opacity: 1, transform: `translate3d(${translateX}px, ${translateY}px, 0) scale(0.48)` },
        { opacity: 0, transform: `translate3d(${translateX}px, ${translateY}px, 0) scale(0.18)` },
      ],
      { duration: 380, easing: "cubic-bezier(0.16, 0.92, 0.22, 1)", fill: "forwards" },
    ),
    target.animate(
      [
        { scale: "1" },
        { offset: 0.56, scale: "1" },
        { offset: 0.72, scale: "1.055" },
        { offset: 0.86, scale: "0.985" },
        { scale: "1" },
      ],
      { duration: 420, easing: "cubic-bezier(0.16, 0.92, 0.22, 1)" },
    ),
  ];
  Promise.allSettled(animations.map((animation) => animation.finished)).then(() => {
    target.classList.remove("is-receiving");
    done();
  });
}

function cancelTodayTaskDrag() {
  ui.pendingTodayTaskDrag = null;
  if (!ui.todayTaskDrag) return;
  clearTodayTaskDragState();
  renderOverlays();
}

function clearTodayTaskDragState() {
  ui.pendingTodayTaskDrag = null;
  if (ui.todayTaskDrag?.sourceCard?.isConnected) ui.todayTaskDrag.sourceCard.classList.remove("is-holding");
  if (ui.todayTaskDrag?.taskId) {
    document.querySelectorAll(`[data-today-task-id="${cssEscape(ui.todayTaskDrag.taskId)}"]`).forEach((card) => card.classList.remove("is-holding"));
    document.querySelectorAll(`[data-today-batch-task="${cssEscape(ui.todayTaskDrag.taskId)}"]`).forEach((card) => card.classList.remove("is-holding"));
  }
  ui.todayTaskDrag = null;
  app.classList.remove("is-today-task-dragging");
  document.querySelector(".today-drag-ghost")?.remove();
  document.querySelectorAll(".today-drop-zone.is-over, .today-floating-drop.is-over, .today-batch-target.is-over").forEach((entry) => entry.classList.remove("is-over"));
}

function isActiveTodayTaskPointer(event) {
  if (!ui.todayTaskDrag) return false;
  if (event?.pointerId !== undefined) return ui.todayTaskDrag.pointerId === event.pointerId;
  if (event?.type === "mouseup") return true;
  return ui.todayTaskDrag.pointerId === "mouse";
}

function handleDeleteDragPointerMove(event) {
  maybeStartPendingDeleteDrag(event);
  if (!ui.deleteDrag) return;
  if (!isActiveDeleteDragPointer(event)) return;
  event.preventDefault();
  updateDeleteDragPosition(event.clientX, event.clientY);
}

function maybeStartPendingDeleteDrag(event) {
  const pending = ui.pendingDeleteDrag;
  if (!pending) return;
  if (event.pointerId !== undefined && pending.pointerId !== event.pointerId) return;
  if (event.buttons !== undefined && event.buttons === 0) {
    ui.pendingDeleteDrag = null;
    return;
  }
  const dx = event.clientX - pending.startX;
  const dy = event.clientY - pending.startY;
  if (Math.hypot(dx, dy) < POINTER_DRAG_ACTIVATION_DISTANCE) return;
  const card = document.querySelector(`[data-delete-drag-type="${pending.type}"][data-delete-drag-id="${pending.id}"]`);
  const item = itemById(pending.type, pending.id);
  ui.pendingDeleteDrag = null;
  if (!card || !item) return;
  event.preventDefault();
  event.stopPropagation();
  beginDeleteDrag(pending.type, pending.id, card, event);
}

function beginDeleteDrag(type, itemId, card, event) {
  cancelDeleteDrag();
  const rect = card.getBoundingClientRect();
  const offsetX = Math.min(Math.max(event.clientX - rect.left, 0), rect.width);
  const offsetY = Math.min(Math.max(event.clientY - rect.top, 0), rect.height);
  try {
    if (event.pointerId !== undefined && card.setPointerCapture) card.setPointerCapture(event.pointerId);
  } catch (_) {}
  ui.deleteDrag = {
    type,
    id: itemId,
    title: deleteDragItemTitle(type, itemId),
    pointerId: event.pointerId ?? "mouse",
    dragX: rect.left,
    dragY: rect.top,
    dragWidth: Math.min(320, Math.max(220, rect.width)),
    offsetX,
    offsetY,
    targetAction: "",
  };
  ui.suppressDeleteClickUntil = Date.now() + 900;
  window.getSelection()?.removeAllRanges();
  card.classList.add("is-holding");
  renderOverlays();
  updateDeleteDragPosition(event.clientX, event.clientY);
}

function updateDeleteDragPosition(clientX, clientY) {
  if (!ui.deleteDrag) return;
  ui.deleteDrag.dragX = clientX - (ui.deleteDrag.offsetX || 0);
  ui.deleteDrag.dragY = clientY - (ui.deleteDrag.offsetY || 0);
  const ghost = document.querySelector(".delete-drag-ghost");
  if (ghost) {
    ghost.style.left = `${ui.deleteDrag.dragX}px`;
    ghost.style.top = `${ui.deleteDrag.dragY}px`;
  }
  setDeleteDropTarget(deleteTargetFromPoint(clientX, clientY));
}

function deleteTargetFromPoint(clientX, clientY) {
  const element = closestElementFromPoint(clientX, clientY, "[data-delete-drop]");
  return element ? { element, action: element.dataset.dragAction || "delete" } : {};
}

function closestElementFromPoint(clientX, clientY, selector) {
  for (const entry of document.elementsFromPoint(clientX, clientY)) {
    const element = entry.closest?.(selector);
    if (element) return element;
  }
  return null;
}

function setDeleteDropTarget(target = {}) {
  if (!ui.deleteDrag) return;
  document.querySelectorAll(".delete-drop-zone.is-drop-target").forEach((entry) => entry.classList.remove("is-drop-target"));
  if (target.element) target.element.classList.add("is-drop-target");
  ui.deleteDrag.targetAction = target.action || "";
}

function finishDeleteDrag(event) {
  if (!ui.deleteDrag) {
    if (ui.pendingDeleteDrag && (event?.pointerId === undefined || ui.pendingDeleteDrag.pointerId === event.pointerId)) ui.pendingDeleteDrag = null;
    return;
  }
  if (!isActiveDeleteDragPointer(event)) return;
  event.preventDefault();
  event.stopPropagation();
  ui.suppressDeleteClickUntil = Date.now() + 900;
  const pointTarget = deleteTargetFromPoint(event.clientX, event.clientY);
  const action = pointTarget.action || "";
  const target = action
    ? {
        element: pointTarget.element || document.querySelector(`[data-delete-drop][data-drag-action="${cssEscape(action)}"]`),
        action,
      }
    : {};
  if (!target.element) {
    clearDeleteDragState();
    renderOverlays();
    return;
  }
  target.element.classList.add("is-drop-target");
  animateDeleteDragDrop(() => {
    const current = ui.deleteDrag;
    clearDeleteDragState();
    if (!current) {
      renderOverlays();
      return;
    }
    commitDragAction(current.type, current.id, action);
    renderOverlays();
  });
}

function cancelDeleteDrag(event) {
  if (event?.pointerId !== undefined && ui.deleteDrag?.pointerId !== event.pointerId) return;
  ui.pendingDeleteDrag = null;
  if (!ui.deleteDrag) return;
  clearDeleteDragState();
  renderOverlays();
}

function clearDeleteDragState() {
  ui.pendingDeleteDrag = null;
  if (ui.deleteDrag?.id) {
    document
      .querySelector(`[data-delete-drag-type="${ui.deleteDrag.type}"][data-delete-drag-id="${ui.deleteDrag.id}"]`)
      ?.classList.remove("is-holding");
  }
  ui.deleteDrag = null;
  ui.suppressDeleteClickUntil = Date.now() + 800;
  document.querySelectorAll(".delete-drop-zone.is-drop-target").forEach((entry) => entry.classList.remove("is-drop-target"));
}

function isActiveDeleteDragPointer(event) {
  if (!ui.deleteDrag) return false;
  if (event?.pointerId !== undefined) return ui.deleteDrag.pointerId === event.pointerId;
  if (event?.type === "mouseup") return true;
  return ui.deleteDrag.pointerId === "mouse";
}

function animateDeleteDragDrop(done) {
  const ghost = document.querySelector(".delete-drag-ghost");
  const target = document.querySelector(".delete-drop-zone.is-drop-target");
  if (!ghost || !target) {
    done();
    return;
  }
  const ghostRect = ghost.getBoundingClientRect();
  const targetRect = target.getBoundingClientRect();
  const translateX = targetRect.left + targetRect.width / 2 - ghostRect.left - ghostRect.width / 2;
  const translateY = targetRect.top + targetRect.height / 2 - ghostRect.top - ghostRect.height / 2;
  ghost.classList.add("is-dropping");
  ghost.style.left = `${ghostRect.left}px`;
  ghost.style.top = `${ghostRect.top}px`;
  ghost.style.width = `${ghostRect.width}px`;
  ghost.style.transform = `translate(${translateX}px, ${translateY}px) scale(0.54)`;
  ghost.style.opacity = "0";
  target.classList.add("is-receiving");
  window.setTimeout(() => {
    target.classList.remove("is-receiving");
    done();
  }, 260);
}

function dragActionTargets(type, itemId) {
  if (type === "projects") {
    const buckets = projectStatusBuckets(state.projects, itemId);
    return Object.entries(STATUSES.project).map(([action, title]) => ({
      action,
      title,
      meta: `${title} 상태로`,
      count: buckets[action].length,
    }));
  }
  if (type === "boxes") {
    const boxBuckets = boxVisibilityBuckets(state.boxes, itemId);
    return [
      {
        action: "pinBox",
        title: "고정",
        meta: "고정 Box로",
        count: boxBuckets.pinned.length,
      },
      {
        action: "normalBox",
        title: "일반",
        meta: "일반 Box로",
        count: boxBuckets.normal.length,
      },
      {
        action: "archiveBox",
        title: "아카이브",
        meta: "보관 영역으로",
        count: boxBuckets.archived.length,
      },
      {
        action: "delete",
        title: "삭제",
        meta: "완전히 제거",
        tone: "delete",
      },
    ];
  }
  return [
    {
      action: "delete",
      title: "삭제",
      meta: `${deleteDragTypeLabel(type)} 완전히 제거`,
      tone: "delete",
    },
  ];
}

function commitDragAction(type, itemId, action) {
  if (type === "projects" && Object.prototype.hasOwnProperty.call(STATUSES.project, action)) {
    const project = itemById("projects", itemId);
    if (!project || project.status === action) return false;
    project.status = action;
    saveState();
    showToast(`${STATUSES.project[action]} 상태로 옮겼습니다.`);
    renderView({ soft: true, animateCards: true });
    return true;
  }
  if (type === "boxes" && ["pinBox", "normalBox", "archiveBox"].includes(action)) {
    const box = itemById("boxes", itemId);
    if (!box) return false;
    const nextVisibility = action === "pinBox" ? "pinned" : action === "archiveBox" ? "archived" : "normal";
    box.visibility = nextVisibility;
    saveState();
    showToast(`${nextVisibility === "pinned" ? "고정" : nextVisibility === "archived" ? "아카이브" : "일반"} Box로 옮겼습니다.`);
    renderView({ soft: true, animateCards: true });
    return true;
  }
  if (action === "delete") {
    const removed = deleteEntity(type, itemId);
    if (!removed) return false;
    saveState();
    showToast(`${deleteDragTypeLabel(type)}을 삭제했습니다.`);
    renderView({ soft: true, animateCards: true });
    return true;
  }
  return false;
}

function handleSchedulePointerMove(event) {
  maybeStartPendingScheduleDrag(event);
  if (!ui.scheduler) return;
  if (ui.scheduler.dragging) {
    if (isReleasedSchedulePointer(event)) {
      cancelScheduleDrag();
      return;
    }
    if (!isActiveSchedulePointer(event)) return;
    event.preventDefault();
  }
  updateScheduleDragPosition(event.clientX, event.clientY);
}

function finishScheduleDrag(event) {
  if (!ui.scheduler?.dragging) {
    clearPendingScheduleDrag(event);
    return;
  }
  if (!isActiveSchedulePointer(event)) return;
  event.preventDefault();
  event.stopPropagation();
  const pointTarget = schedulerTargetFromPoint(event.clientX, event.clientY);
  const action = pointTarget.action || "";
  const date = pointTarget.date || "";
  if (ui.scheduleHoldTaskId) {
    document.querySelector(`[data-schedule-hold="${ui.scheduleHoldTaskId}"]`)?.classList.remove("is-holding");
  }
  ui.scheduleHoldTaskId = "";
  markScheduleDragEnded();
  stopSchedulerMonthHover();
  if (action) {
    scheduleTaskActionFromScheduler(action);
    return;
  }
  if (date) {
    scheduleTaskFromScheduler(date);
    return;
  }
  closeTaskScheduler();
}

function isActiveSchedulePointer(event) {
  if (!ui.scheduler?.dragging) return false;
  if (event.pointerId !== undefined) return ui.scheduler.pointerId === event.pointerId;
  if (event.type === "mouseup") return true;
  return ui.scheduler.pointerId === "mouse";
}

function isReleasedSchedulePointer(event) {
  if (event.buttons === undefined || event.buttons !== 0) return false;
  return event.type === "mousemove" || event.pointerType === "mouse" || ui.scheduler?.pointerId === "mouse";
}

function maybeStartPendingScheduleDrag(event) {
  const pending = ui.pendingScheduleDrag;
  if (!pending) return;
  if (event.pointerId !== undefined && pending.pointerId !== event.pointerId) return;
  if (event.buttons !== undefined && event.buttons === 0) {
    ui.pendingScheduleDrag = null;
    return;
  }
  const dx = event.clientX - pending.startX;
  const dy = event.clientY - pending.startY;
  if (Math.hypot(dx, dy) < POINTER_DRAG_ACTIVATION_DISTANCE) return;
  const task = itemById("tasks", pending.taskId);
  const card = document.querySelector(`[data-schedule-hold="${pending.taskId}"]`);
  ui.pendingScheduleDrag = null;
  if (!task || !card) return;
  event.preventDefault();
  event.stopPropagation();
  beginScheduleDrag(task, card, event);
}

function clearPendingScheduleDrag(event) {
  if (!ui.pendingScheduleDrag) return;
  if (event?.pointerId !== undefined && ui.pendingScheduleDrag.pointerId !== event.pointerId) return;
  ui.pendingScheduleDrag = null;
}

function updateScheduleDragPosition(clientX, clientY) {
  if (!ui.scheduler?.dragging) return;
  ui.scheduler.dragX = clientX + 14;
  ui.scheduler.dragY = clientY + 14;
  const ghost = document.querySelector(".schedule-drag-ghost");
  if (ghost) {
    ghost.style.left = `${ui.scheduler.dragX}px`;
    ghost.style.top = `${ui.scheduler.dragY}px`;
  }
  setScheduleDropTarget(schedulerTargetFromPoint(clientX, clientY));
  updateSchedulerMonthHover(clientX, clientY);
}

function schedulerTargetFromPoint(clientX, clientY) {
  return schedulerTargetFromElement(document.elementFromPoint(clientX, clientY)?.closest("[data-scheduler-date], [data-scheduler-action]"));
}

function schedulerTargetFromElement(element) {
  if (!element) return {};
  const action = element.dataset.schedulerAction || "";
  const date = element.dataset.schedulerDate || "";
  return {
    action,
    date,
    element,
    targetKey: action ? `action:${action}` : date ? `date:${date}` : "",
  };
}

function setScheduleDropTarget(target = {}) {
  if (!ui.scheduler || (ui.scheduler.dragOverTarget === target.targetKey && (!target.element || target.element.classList.contains("is-drop-target")))) return;
  document.querySelectorAll(".task-scheduler-day.is-drop-target, .task-scheduler-lane.is-drop-target, .task-scheduler-delete-zone.is-drop-target").forEach((entry) => entry.classList.remove("is-drop-target"));
  if (target.targetKey) target.element?.classList.add("is-drop-target");
  ui.scheduler.dragOverDate = target.date || "";
  ui.scheduler.dragOverAction = target.action || "";
  ui.scheduler.dragOverTarget = target.targetKey || "";
}

function updateSchedulerMonthHover(clientX, clientY) {
  const calendar = document.querySelector(".task-scheduler");
  const stage = document.querySelector(".task-scheduler-stage");
  if (!calendar || !ui.scheduler) {
    stopSchedulerMonthHover();
    return;
  }
  ui.scheduler.monthHoverX = clientX;
  ui.scheduler.monthHoverY = clientY;
  const prevZone = document.querySelector(".task-scheduler-month-zone.is-prev");
  const nextZone = document.querySelector(".task-scheduler-month-zone.is-next");
  const prevRect = prevZone?.getBoundingClientRect();
  const nextRect = nextZone?.getBoundingClientRect();
  const inLeftZone =
    prevRect &&
    prevRect.width > 0 &&
    clientX >= prevRect.left &&
    clientX <= prevRect.right &&
    clientY >= prevRect.top &&
    clientY <= prevRect.bottom;
  const inRightZone =
    nextRect &&
    nextRect.width > 0 &&
    clientX >= nextRect.left &&
    clientX <= nextRect.right &&
    clientY >= nextRect.top &&
    clientY <= nextRect.bottom;
  if (!inLeftZone && !inRightZone) {
    stopSchedulerMonthHover();
    return;
  }
  const edge = inLeftZone ? "prev" : "next";
  if (ui.scheduler.monthEdge === edge && scheduleMonthHoverTimer) return;
  stopSchedulerMonthHover();
  ui.scheduler.monthEdge = edge;
  stage?.classList.add(edge === "prev" ? "is-edge-prev" : "is-edge-next");
  scheduleMonthHoverTimer = window.setTimeout(() => advanceSchedulerMonth(edge), 680);
}

function advanceSchedulerMonth(edge) {
  if (!ui.scheduler) {
    stopSchedulerMonthHover();
    return;
  }
  const current = parseMonthKey(ui.scheduler.month);
  ui.scheduler.month = monthKey(addMonths(current, edge === "prev" ? -1 : 1));
  ui.scheduler.dragOverDate = "";
  ui.scheduler.dragOverTarget = "";
  ui.scheduler.dragOverAction = "";
  ui.scheduler.monthEdge = "";
  window.clearTimeout(scheduleMonthHoverTimer);
  scheduleMonthHoverTimer = 0;
  renderOverlays();
  window.setTimeout(() => {
    if (ui.scheduler) updateSchedulerMonthHover(ui.scheduler.monthHoverX, ui.scheduler.monthHoverY);
  }, 40);
}

function stopSchedulerMonthHover() {
  window.clearTimeout(scheduleMonthHoverTimer);
  scheduleMonthHoverTimer = 0;
  if (ui.scheduler) ui.scheduler.monthEdge = "";
  document.querySelector(".task-scheduler-stage")?.classList.remove("is-edge-prev", "is-edge-next");
  document.querySelector(".task-scheduler")?.classList.remove("is-edge-prev", "is-edge-next");
}

function handleTodayBatchKeydown(event) {
  const batch = ui.todayBatch;
  if (!batch) return false;
  if (event.key === "Escape") {
    event.preventDefault();
    event.stopPropagation();
    closeTodayBatch({ announce: true });
    return true;
  }
  if (event.key === "Tab") {
    event.stopPropagation();
    trapTodayBatchFocus(event);
    return true;
  }
  const input = event.target.closest?.("[data-today-batch-input]");
  if (
    batch.phase === "input"
    && input
    && event.key === "Enter"
    && !event.isComposing
    && (
      ((event.metaKey || event.ctrlKey) && !event.altKey)
      || (!event.shiftKey && !event.altKey && input.value.endsWith("\n"))
    )
  ) {
    event.preventDefault();
    event.stopPropagation();
    startTodayBatchPlacement(input.value);
    return true;
  }
  return false;
}

function trapTodayBatchFocus(event) {
  const surface = document.querySelector("[data-today-batch-dialog]");
  if (!surface) return;
  const focusable = [...surface.querySelectorAll("button:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex='-1'])")]
    .filter((element) => element.getClientRects().length);
  if (!focusable.length) return;
  const activeIndex = focusable.indexOf(document.activeElement);
  const nextIndex = event.shiftKey ? focusable.length - 1 : 0;
  if (activeIndex < 0 || (event.shiftKey && activeIndex === 0) || (!event.shiftKey && activeIndex === focusable.length - 1)) {
    event.preventDefault();
    focusable[nextIndex]?.focus({ preventScroll: true });
  }
}

function handleKeydown(event) {
  if (event.key !== "ArrowUp" && event.key !== "ArrowDown" && !event.isComposing) preferredVerticalCaretX = null;
  if (handleFinancePickerKeydown(event)) return;
  if (handleTodayBatchKeydown(event)) return;
  if (handleTaskPlacementKeydown(event)) return;
  if (handleCodeLanguagePickerKeydown(event)) return;
  if (trapResourceDocumentFocus(event)) return;
  if (handleUrlPasteChoiceKeydown(event)) return;
  if (handleInlineColorMenuKeydown(event)) return;
  if (handleSelectedBlockMenuKeydown(event)) return;
  if (event.key === "Escape" && document.querySelector(".calendar-span-event.is-expanded")) {
    event.preventDefault();
    event.stopPropagation();
    closeCalendarSpanEvents();
    return;
  }
  if (event.key === "Escape" && (ui.pendingEditorMarquee || ui.editorMarquee)) {
    event.preventDefault();
    event.stopPropagation();
    cancelEditorMarqueeDrag();
    return;
  }
  const externalInlineLink = event.target.closest("a[data-inline-mark='link']");
  if (
    externalInlineLink
    && !event.isComposing
    && !event.metaKey
    && !event.ctrlKey
    && !event.altKey
    && (event.key === "Enter" || event.key === " ")
  ) {
    event.preventDefault();
    event.stopPropagation();
    const blockContent = externalInlineLink.closest("[data-block-content]");
    const editor = blockContent?.closest(".block-editor");
    if (editor?.dataset.ownerType === "resources") {
      clearInlineEditingOverlaysForBlockSelection();
      openInlineLinkExternally(externalInlineLink);
      return;
    }
    if (blockContent && editor) {
      activateBlockContent(blockContent);
      openLinkPopover(
        editor.dataset.ownerType,
        editor.dataset.ownerId,
        blockContent.dataset.blockContent,
        textRangeForInlineElement(blockContent, externalInlineLink),
        externalInlineLink.getBoundingClientRect(),
      );
    }
    return;
  }
  const resourceCitation = event.target.closest("a[data-inline-mark='resourceLink'][data-resource-citation]");
  if (
    resourceCitation &&
    !event.isComposing &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.altKey &&
    (event.key === "Enter" || event.key === " ")
  ) {
    event.preventDefault();
    event.stopPropagation();
    activateResourceCitationTarget(resourceCitation);
    return;
  }
  const pageMention = event.target.closest("[data-inline-mark='mention'][data-mention-type='page'][data-mention-target-type][data-mention-target-id]");
  if (
    pageMention &&
    !event.isComposing &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.altKey &&
    (event.key === "Enter" || event.key === " ")
  ) {
    event.preventDefault();
    event.stopPropagation();
    activatePageMentionTarget(pageMention);
    return;
  }
  if (ui.blockDrag && event.key === "Escape") {
    event.preventDefault();
    event.stopPropagation();
    cancelBlockDrag();
    return;
  }

  const resourceTitle = event.target.closest("[data-resource-title]");
  if (resourceTitle && event.key === "Enter" && !event.isComposing) {
    event.preventDefault();
    const resourceId = resourceTitle.dataset.resourceTitle;
    document.querySelector(`.block-editor[data-owner-type="resources"][data-owner-id="${cssEscape(resourceId)}"] [data-block-content]`)?.focus();
    return;
  }

  const habitToggle = event.target.closest("[data-habit-toggle]");
  if (
    habitToggle &&
    !event.target.closest("[data-toggle-habit], button, input, textarea, select, [contenteditable='true']") &&
    (event.key === "Enter" || event.key === " ")
  ) {
    event.preventDefault();
    toggleHabitDetail(habitToggle.dataset.habitToggle);
    return;
  }

  const blockContent = event.target.closest("[data-block-content]");
  if (handleSelectedBlocksTabKey(event)) return;
  if (handleSelectedBlocksEditableKey(event, blockContent)) return;
  if (!blockContent) return;
  const editor = blockContent.closest(".block-editor");
  const ownerType = editor.dataset.ownerType;
  const ownerId = editor.dataset.ownerId;
  const blockId = blockContent.dataset.blockContent;

  if (!editorOwnerMutationAllowed(ownerType, ownerId)) {
    const isMutationKey = event.key.length === 1 || ["Enter", "Backspace", "Delete", "Tab"].includes(event.key);
    if (isMutationKey || event.metaKey || event.ctrlKey) {
      event.preventDefault();
      event.stopPropagation();
    }
    return;
  }

  const currentBlock = itemById(ownerType, ownerId)?.blocks?.find((block) => block.id === blockId);
  if (currentBlock?.type === IMAGE_BLOCK_TYPE && handleResourceImageBlockKeydown(event, ownerType, ownerId, currentBlock, blockContent)) return;

  if (isComposingInput(event, blockContent)) return;
  if (handleRecentCompositionEnter(event, ownerType, ownerId, blockId, blockContent)) return;

  if (handlePendingEmptyContinuationEnter(event)) return;
  if (handlePendingEmptyContinuationTab(event)) return;

  if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "a") {
    event.preventDefault();
    event.stopPropagation();
    handleBlockContentSelectAllShortcut(blockContent, ownerType, ownerId);
    return;
  }

  if ((event.metaKey || event.ctrlKey) && !event.altKey && !event.shiftKey && event.key === "Enter") {
    if (modifyCurrentBlockFromKeyboard(ownerType, ownerId, blockId)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
  }

  if (toggleAllTogglesKeyboardShortcut(event)) {
    if (toggleAllTogglesInEditor(ownerType, ownerId, blockId)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
  }

  if (lastBlockColorKeyboardShortcut(event) && applyLastBlockColorAction(ownerType, ownerId, [blockId], { focusBlockId: blockId })) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }

  const shortcutBlockType = blockTypeKeyboardShortcut(event);
  if (shortcutBlockType) {
    event.preventDefault();
    event.stopPropagation();
    changeBlockType(ownerType, ownerId, blockId, shortcutBlockType);
    return;
  }

  const inlineShortcut = inlineMarkKeyboardShortcut(event);
  if (inlineShortcut) {
    event.preventDefault();
    event.stopPropagation();
    if (inlineShortcut === "link") {
      openLinkPopover(ownerType, ownerId, blockId);
      return;
    }
    toggleInlineMark(ownerType, ownerId, blockId, inlineShortcut);
    return;
  }

  if (ui.mention?.blockId === blockId) {
    const mentionEntries = mentionMenuEntries(ui.mention.query || "");
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      event.stopPropagation();
      if (mentionEntries.length) moveMentionSelection(event.key === "ArrowDown" ? 1 : -1);
      return;
    }
    if (event.key === "Enter" || event.key === "Tab") {
      if (mentionEntries.length) {
        event.preventDefault();
        event.stopPropagation();
        applyMentionSelection();
        return;
      }
      closeMentionMenu();
    }
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      closeMentionMenu();
      return;
    }
  }

  if (ui.pageCommand?.blockId === blockId) {
    const pageCommandEntries = pageCommandMenuEntries(ui.pageCommand.query || "", ui.pageCommand.trigger || "brackets");
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      event.stopPropagation();
      if (pageCommandEntries.length) movePageCommandSelection(event.key === "ArrowDown" ? 1 : -1);
      return;
    }
    if (event.key === "Enter" || event.key === "Tab") {
      if (pageCommandEntries.length) {
        event.preventDefault();
        event.stopPropagation();
        applyPageCommandSelection();
        return;
      }
      closePageCommandMenu();
    }
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      closePageCommandMenu();
      return;
    }
  }

  if (ui.emojiCommand?.blockId === blockId) {
    const emojiEntries = emojiMenuEntries(ui.emojiCommand.query || "");
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      event.stopPropagation();
      if (emojiEntries.length) moveEmojiSelection(event.key === "ArrowDown" ? 1 : -1);
      return;
    }
    if (event.key === "Enter" || event.key === "Tab") {
      if (emojiEntries.length) {
        event.preventDefault();
        event.stopPropagation();
        applyEmojiSelection();
        return;
      }
      closeEmojiMenu();
    }
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      closeEmojiMenu();
      return;
    }
  }

  if (event.key === "Escape" && !event.metaKey && !event.ctrlKey && !event.altKey) {
    event.preventDefault();
    event.stopPropagation();
    selectSingleBlock(ownerType, ownerId, blockId);
    return;
  }

  if (event.key === "Tab") {
    event.preventDefault();
    event.stopPropagation();
    if (editCodeBlockIndent(ownerType, ownerId, blockId, blockContent, event.shiftKey ? -1 : 1)) return;
    indentBlock(ownerType, ownerId, blockId, event.shiftKey ? -1 : 1);
    return;
  }

  if (
    (event.key === "ArrowUp" || event.key === "ArrowDown") &&
    event.shiftKey &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.altKey &&
    extendCaretSelectionBetweenBlocks(blockContent, event.key)
  ) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }

  if (
    (event.key === "ArrowUp" || event.key === "ArrowDown") &&
    !event.shiftKey &&
    moveCaretBetweenBlocks(blockContent, event.key)
  ) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }

  if (
    (event.key === "ArrowLeft" || event.key === "ArrowRight") &&
    event.shiftKey &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.altKey &&
    extendCaretHorizontalSelectionBetweenBlocks(blockContent, event.key)
  ) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }

  if (
    (event.key === "ArrowLeft" || event.key === "ArrowRight") &&
    !event.shiftKey &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.altKey &&
    moveCaretHorizontallyBetweenBlocks(blockContent, event.key)
  ) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }

  if (
    event.key === "Enter"
    && !event.shiftKey
    && applyMarkdownFenceShortcutOnEnter(blockContent, currentBlock, ownerType, ownerId)
  ) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }

  if (event.key === "Enter" && !event.shiftKey) {
    event.preventDefault();
    event.stopPropagation();
    markHandledBlockParagraphInput(blockId);
    if (insertCodeBlockLineBreak(ownerType, ownerId, blockId, blockContent)) return;
    insertBlockFromCaret(ownerType, ownerId, blockId, blockContent);
    return;
  }

  if (event.key === "Backspace" && isCaretAtStart(blockContent)) {
    if (handleBackspaceAtBlockStart(ownerType, ownerId, blockId, blockContent)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
  }

  if (event.key === "Delete" && isCaretAtEnd(blockContent)) {
    if (handleDeleteAtBlockEnd(ownerType, ownerId, blockId, blockContent)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
  }

}

function handleResourceImageBlockKeydown(event, ownerType, ownerId, block, blockContent) {
  if (event.metaKey || event.ctrlKey || event.altKey) return false;
  if (["ArrowUp", "ArrowLeft", "ArrowDown", "ArrowRight"].includes(event.key)) {
    const direction = event.key === "ArrowUp" || event.key === "ArrowLeft" ? -1 : 1;
    const target = adjacentBlockContent(blockContent, direction);
    if (!target) return false;
    event.preventDefault();
    event.stopPropagation();
    preferredVerticalCaretX = null;
    focusBlockContentAfterRender(target.dataset.blockContent, { position: direction < 0 ? "end" : "start" });
    return true;
  }
  if (event.key === "Enter") {
    event.preventDefault();
    event.stopPropagation();
    return insertParagraphAfterMediaBlock(ownerType, ownerId, block.id);
  }
  if (event.key === "Backspace" || event.key === "Delete") {
    event.preventDefault();
    event.stopPropagation();
    selectSingleBlock(ownerType, ownerId, block.id);
    return deleteSelectedBlocks();
  }
  return false;
}

function insertParagraphAfterMediaBlock(ownerType, ownerId, blockId) {
  const item = itemById(ownerType, ownerId);
  const index = item?.blocks?.findIndex((block) => block.id === blockId) ?? -1;
  if (index < 0) return false;
  const paragraph = { id: id(), type: "paragraph", text: "", marks: [], checked: false, indent: blockIndent(item.blocks[index]), collapsed: false };
  const history = beginEditorHistory(ownerType, ownerId, { blockId, position: "end" });
  item.blocks.splice(index + 1, 0, paragraph);
  commitEditorHistory(history, { blockId: paragraph.id, start: 0, end: 0 });
  saveState();
  renderEditorMutation(ownerType, ownerId);
  focusBlockContentAfterRender(paragraph.id, { position: "start" });
  return true;
}

function blockTypeKeyboardShortcut(event) {
  const macShortcut = event.metaKey && event.altKey && !event.ctrlKey && !event.shiftKey;
  const nonMacShortcut = event.ctrlKey && event.shiftKey && !event.metaKey && !event.altKey;
  if (!macShortcut && !nonMacShortcut) return "";
  const keyShortcut = BLOCK_TYPE_KEYBOARD_SHORTCUTS[event.key];
  if (keyShortcut) return keyShortcut;
  const digit = /^Digit([0-9])$/.exec(event.code || "")?.[1];
  return digit ? BLOCK_TYPE_KEYBOARD_SHORTCUTS[digit] || "" : "";
}

function inlineMarkKeyboardShortcut(event) {
  if (!(event.metaKey || event.ctrlKey) || event.altKey) return "";
  const key = event.key.toLowerCase();
  if (!event.shiftKey && key === "b") return "bold";
  if (!event.shiftKey && key === "i") return "italic";
  if (!event.shiftKey && key === "u") return "underline";
  if (!event.shiftKey && key === "e") return "code";
  if (!event.shiftKey && key === "k") return "link";
  if (event.shiftKey && key === "m") return "comment";
  if (event.shiftKey && key === "s") return "strike";
  return "";
}

function lastBlockColorKeyboardShortcut(event) {
  return (event.metaKey || event.ctrlKey) && event.shiftKey && !event.altKey && event.key.toLowerCase() === "h";
}

function handleNavShortcutKeydown(event) {
  if (isEditableShortcutTarget(event.target)) return false;

  if (isOptionKey(event) && updateBlockDragCopyMode(true)) {
    event.preventDefault();
    event.stopPropagation();
    return true;
  }

  if (isOptionKey(event)) {
    if (!event.repeat) scheduleNavShortcutHints();
    return false;
  }

  if (!event.altKey) return false;

  if (isDockedNavShortcut(event)) {
    event.preventDefault();
    event.stopPropagation();
    toggleDockedNav();
    return true;
  }

  const shortcutKey = navShortcutKeyFromEvent(event);
  if (!shortcutKey) return false;

  event.preventDefault();
  event.stopPropagation();
  window.clearTimeout(navShortcutHoldTimer);
  navShortcutHoldTimer = 0;

  return navigateNavShortcut(shortcutKey);
}

function toggleDockedNav() {
  window.clearTimeout(navShortcutHoldTimer);
  navShortcutHoldTimer = 0;
  ui.navShortcutHints = false;
  ui.navOpenedByShortcut = false;
  ui.navDocked = !ui.navDocked;
  app.classList.remove("is-undocking-nav");
  if (ui.navDocked) {
    ui.navOpen = true;
    els.sidebar?.classList.remove("is-fast-closing", "is-row-closing");
    els.sidebar?.style.setProperty("--nav-close-top", "50%");
    els.sidebar?.style.setProperty("--nav-close-bottom", "50%");
    updateNav();
    return;
  }
  app.classList.add("is-undocking-nav");
  ui.navOpen = false;
  updateNav();
}

function handleDocumentKeyup(event) {
  if (event.key === "Shift" || !event.shiftKey) ui.shiftKeyDown = false;
  if (!isOptionKey(event)) return;
  if (updateBlockDragCopyMode(false)) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  resetNavShortcutState({ closeAutoOpened: true });
}

function updateBlockDragCopyMode(copyMode) {
  const drag = ui.blockDrag;
  if (!drag?.active) return false;
  const nextCopyMode = Boolean(copyMode);
  if (drag.copyMode === nextCopyMode) return true;
  drag.copyMode = nextCopyMode;
  renderOverlays();
  return true;
}

function scheduleNavShortcutHints() {
  window.clearTimeout(navShortcutHoldTimer);
  navShortcutHoldTimer = window.setTimeout(() => {
    ui.navShortcutHints = true;
    if (!ui.navOpen) {
      ui.navOpenedByShortcut = true;
      openNav();
    } else {
      ui.navOpenedByShortcut = false;
      updateNav();
    }
  }, NAV_SHORTCUT_HOLD_MS);
}

function resetNavShortcutState(options = {}) {
  const { closeAutoOpened = true } = options;
  window.clearTimeout(navShortcutHoldTimer);
  navShortcutHoldTimer = 0;
  const shouldClose = closeAutoOpened && ui.navOpenedByShortcut && ui.navOpen;
  ui.navShortcutHints = false;
  ui.navOpenedByShortcut = false;
  if (shouldClose) {
    closeNav();
  } else {
    updateNav();
  }
}

function navigateNavShortcut(shortcutKey) {
  const index = NAV_SHORTCUT_KEYS.indexOf(shortcutKey);
  if (index < 0) return false;
  const navItem = orderedNavItems()[index];
  if (!navItem) return false;
  window.clearTimeout(navShortcutHoldTimer);
  navShortcutHoldTimer = 0;
  ui.navShortcutHints = false;
  const target = app.querySelector(`[data-nav-shortcut="${shortcutKey}"]`);
  setView(navItem[0], { navTarget: target });
  ui.navOpenedByShortcut = false;
  updateNav();
  return true;
}

function navShortcutKeyForIndex(index) {
  return NAV_SHORTCUT_KEYS[index] || "";
}

function navShortcutKeyFromEvent(event) {
  if (event.code === "KeyQ" || event.key.toLowerCase() === "q") return "q";
  if (event.code === "KeyW" || event.key.toLowerCase() === "w") return "w";
  const digitMatch = event.code?.match(/^(?:Digit|Numpad)([0-9])$/);
  if (digitMatch && NAV_SHORTCUT_KEYS.includes(digitMatch[1])) return digitMatch[1];
  if (/^[0-9]$/.test(event.key) && NAV_SHORTCUT_KEYS.includes(event.key)) return event.key;
  return "";
}

function isDockedNavShortcut(event) {
  return event.code === "KeyE" || event.key.toLowerCase() === "e";
}

function isOptionKey(event) {
  return event.key === "Alt" || event.code === "AltLeft" || event.code === "AltRight";
}

function isEditableShortcutTarget(target) {
  return target instanceof Element && Boolean(target.closest("input, textarea, select, [contenteditable='true']"));
}

function hasActiveEditableShortcutTarget() {
  return isEditableShortcutTarget(document.activeElement);
}

function isPrintableBlockReplacementKey(event) {
  return (
    ui.blockSelection.ids.length > 0 &&
    !isEditableShortcutTarget(event.target) &&
    !hasActiveEditableShortcutTarget() &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.altKey &&
    !event.isComposing &&
    event.key.length === 1
  );
}

function handleDocumentKeydown(event) {
  if (app.dataset.workspaceAuthority !== "ready") return;
  if (event.key === "Escape" && (ui.pendingEditorMarquee || ui.editorMarquee)) {
    event.preventDefault();
    event.stopPropagation();
    cancelEditorMarqueeDrag();
    return;
  }
  if (handleTodayBatchKeydown(event)) return;
  if (handleTaskPlacementKeydown(event)) return;
  if (handleUrlPasteChoiceKeydown(event)) return;
  if (handleResourceCitationKeydown(event)) return;
  if (event.key === "Shift" || event.shiftKey) ui.shiftKeyDown = true;
  if (handleSelectedBlockMenuKeydown(event)) return;
  if (ui.blockDrag && event.key === "Escape") {
    event.preventDefault();
    event.stopPropagation();
    cancelBlockDrag();
    return;
  }
  if (handlePendingEmptyContinuationEnter(event)) return;
  if (handlePendingEmptyContinuationTab(event)) return;
  if (handlePendingMarkdownTargetTab(event)) return;
  if (handlePendingMarkdownTextKey(event)) return;
  if (
    editorHistoryShortcutContext(event)
    && (event.metaKey || event.ctrlKey)
    && !event.altKey
    && event.key.toLowerCase() === "z"
  ) {
    event.preventDefault();
    event.stopPropagation();
    if (event.shiftKey) redoEditorHistory();
    else undoEditorHistory();
    return;
  }
  if (
    editorHistoryShortcutContext(event)
    && event.ctrlKey
    && !event.metaKey
    && !event.altKey
    && !event.shiftKey
    && event.key.toLowerCase() === "y"
  ) {
    event.preventDefault();
    event.stopPropagation();
    redoEditorHistory();
    return;
  }

  if (toggleAllTogglesKeyboardShortcut(event)) {
    const target = ui.blockSelection.ids.length
      ? { ownerType: ui.blockSelection.ownerType, ownerId: ui.blockSelection.ownerId, blockId: ui.blockSelection.ids[0], selectionIds: ui.blockSelection.ids.slice() }
      : recentBlockContentForSelectionShortcut();
    if (target && toggleAllTogglesInEditor(target.ownerType, target.ownerId, target.blockId, { selectionIds: target.selectionIds })) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
  }

  if (handleSelectedBlocksTabKey(event)) return;

  if ((event.metaKey || event.ctrlKey) && !event.altKey && event.key.toLowerCase() === "a" && !isEditableShortcutTarget(event.target)) {
    const recent = recentBlockContentForSelectionShortcut();
    if (recent) {
      event.preventDefault();
      event.stopPropagation();
      handleBlockSelectAll(recent.blockContent, recent.ownerType, recent.ownerId);
      return;
    }
  }

  if (ui.linkPopover && event.key === "Escape") {
    event.preventDefault();
    ui.linkPopover = null;
    renderOverlays();
    return;
  }
  if (ui.commentPopover && event.key === "Escape") {
    event.preventDefault();
    ui.commentPopover = null;
    renderOverlays();
    return;
  }

  if (ui.blockSelection.ids.length && event.key === "Escape") {
    event.preventDefault();
    clearBlockSelection();
    return;
  }
  if (ui.blockSelection.ids.length && (event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "a") {
    event.preventDefault();
    selectAllBlocks(ui.blockSelection.ownerType, ui.blockSelection.ownerId);
    return;
  }
  if (ui.blockSelection.ids.length && (event.metaKey || event.ctrlKey) && !event.altKey && !event.shiftKey && event.key.toLowerCase() === "d") {
    event.preventDefault();
    event.stopPropagation();
    duplicateSelectedBlocks();
    return;
  }
  if (ui.blockSelection.ids.length && (event.metaKey || event.ctrlKey) && !event.altKey && !event.shiftKey && isBlockMenuShortcutKey(event)) {
    event.preventDefault();
    event.stopPropagation();
    openSelectedBlocksMenu();
    return;
  }
  if (ui.blockSelection.ids.length && isPlainSpaceKey(event) && toggleSelectedActionBlocks()) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  if (ui.blockSelection.ids.length && lastBlockColorKeyboardShortcut(event)) {
    if (applyLastBlockColorAction(ui.blockSelection.ownerType, ui.blockSelection.ownerId, ui.blockSelection.ids, { preserveSelection: true })) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
  }
  const selectedShortcutBlockType = ui.blockSelection.ids.length ? blockTypeKeyboardShortcut(event) : "";
  if (selectedShortcutBlockType) {
    event.preventDefault();
    event.stopPropagation();
    changeSelectedBlocksType(selectedShortcutBlockType);
    return;
  }
  const selectedInlineShortcut = ui.blockSelection.ids.length ? inlineMarkKeyboardShortcut(event) : "";
  if (selectedInlineShortcut && selectedInlineShortcut !== "link") {
    event.preventDefault();
    event.stopPropagation();
    toggleSelectedBlocksInlineMark(selectedInlineShortcut);
    return;
  }
  if (ui.blockSelection.ids.length && (event.metaKey || event.ctrlKey) && event.shiftKey && !event.altKey && ["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(event.key)) {
    event.preventDefault();
    event.stopPropagation();
    if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
      indentSelectedBlocks(event.key === "ArrowRight" ? 1 : -1);
    } else {
      moveSelectedBlocksByKeyboard(event.key === "ArrowDown" ? 1 : -1);
    }
    return;
  }
  if (ui.blockSelection.ids.length && (event.key === "ArrowUp" || event.key === "ArrowDown") && !event.metaKey && !event.ctrlKey && !event.altKey) {
    if (moveSelectedBlockSelection(event.key === "ArrowDown" ? 1 : -1, event.shiftKey)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
  }
  if (ui.blockSelection.ids.length && event.key === "Enter" && !event.metaKey && !event.ctrlKey && !event.altKey) {
    event.preventDefault();
    focusSelectedBlockForEditing(event.shiftKey ? "start" : "end");
    return;
  }
  if (ui.blockSelection.ids.length && ["Backspace", "Delete"].includes(event.key) && !isEditableShortcutTarget(event.target)) {
    event.preventDefault();
    deleteSelectedBlocks();
    return;
  }
  if (isPrintableBlockReplacementKey(event)) {
    event.preventDefault();
    replaceSelectedBlocksWithText(event.key);
    return;
  }

  if (handleNavShortcutKeydown(event)) return;

  if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
    event.preventDefault();
    ui.commandOpen = !ui.commandOpen;
    ui.selectedBlockMenu = null;
    renderOverlays();
  }
  if (event.key === "Escape") {
    if (ui.scheduler) {
      closeTaskScheduler();
      return;
    }
    if (ui.navOpen && !ui.navDocked) {
      closeNav();
      return;
    }
    if (ui.commandOpen || ui.selectedBlockMenu) {
      ui.commandOpen = false;
      ui.selectedBlockMenu = null;
      renderOverlays();
      return;
    }
    if (ui.mention || ui.pageCommand || ui.emojiCommand || ui.inlineToolbar || ui.equationPopover) {
      ui.mention = null;
      ui.pageCommand = null;
      ui.emojiCommand = null;
      ui.inlineToolbar = null;
      ui.equationPopover = null;
      renderOverlays();
      return;
    }
    if (ui.activeResourceId) {
      event.preventDefault();
      closeResourceDocument();
      return;
    }
  }
}

function editorHistoryShortcutContext(event) {
  const target = event?.target instanceof Element ? event.target : null;
  const editable = target?.closest("input, textarea, select, [contenteditable='true']");
  if (editable) {
    return Boolean(editable.matches("[data-block-content], [data-field]"));
  }
  if (target?.closest("[data-block-content]")) return true;
  if (ui.blockSelection.ids.length) return true;
  const recent = ui.recentBlockFocus;
  return Boolean(recent?.ownerType && recent?.ownerId && recent?.blockId && Date.now() <= recent.expiresAt);
}

function recentBlockContentForSelectionShortcut() {
  const recent = ui.recentBlockFocus;
  if (!recent || Date.now() > recent.expiresAt || !recent.ownerType || !recent.ownerId || !recent.blockId) {
    ui.recentBlockFocus = null;
    return null;
  }
  const blockContent = document.querySelector(`[data-block-content="${cssEscape(recent.blockId)}"]`);
  const editor = blockContent?.closest(".block-editor");
  if (!blockContent || !editor || editor.dataset.ownerType !== recent.ownerType || editor.dataset.ownerId !== recent.ownerId) {
    ui.recentBlockFocus = null;
    return null;
  }
  return { blockContent, ownerType: recent.ownerType, ownerId: recent.ownerId };
}

function handlePendingEmptyContinuationEnter(event) {
  if (ui.blockSelection.ids.length) return false;
  if (
    event.defaultPrevented ||
    event.key !== "Enter" ||
    event.shiftKey ||
    event.metaKey ||
    event.ctrlKey ||
    event.altKey ||
    event.isComposing
  ) {
    return false;
  }
  const pending = ui.pendingEmptyContinuationExit;
  if (!pending) return false;
  if (!pendingEmptyContinuationMatchesEvent(event, pending)) return false;
  if (!pendingEmptyContinuationIsStillValid(pending)) return false;
  if (!exitEmptyContinuationBlock(pending.ownerType, pending.ownerId, pending.blockId)) {
    ui.pendingEmptyContinuationExit = null;
    return false;
  }
  event.preventDefault();
  event.stopPropagation();
  return true;
}

function handlePendingEmptyContinuationTab(event) {
  if (ui.blockSelection.ids.length) return false;
  if (
    event.defaultPrevented ||
    event.key !== "Tab" ||
    event.metaKey ||
    event.ctrlKey ||
    event.altKey ||
    event.isComposing
  ) {
    return false;
  }
  const pending = ui.pendingEmptyContinuationExit;
  if (!pending) return false;
  if (!pendingEmptyContinuationMatchesEvent(event, pending)) return false;
  if (!pendingEmptyContinuationIsStillValid(pending)) return false;
  indentBlock(pending.ownerType, pending.ownerId, pending.blockId, event.shiftKey ? -1 : 1);
  event.preventDefault();
  event.stopPropagation();
  return true;
}

function pendingEmptyContinuationMatchesEvent(event, pending) {
  const targetElement = event.target instanceof Element ? event.target : null;
  const targetBlockContent = targetElement?.closest("[data-block-content]");
  if (targetBlockContent) return targetBlockContent.dataset.blockContent === pending.blockId;
  const activeElement = document.activeElement instanceof Element ? document.activeElement : null;
  const activeBlockContent = activeElement?.closest("[data-block-content]");
  if (activeBlockContent) return activeBlockContent.dataset.blockContent === pending.blockId;
  return ui.activeBlockId === pending.blockId;
}

function pendingEmptyContinuationIsStillValid(pending) {
  const item = itemById(pending.ownerType, pending.ownerId);
  const block = item?.blocks?.find((entry) => entry.id === pending.blockId);
  if (block && !(block.text || "") && emptyBlockCanExitOnSecondEnter(block)) return true;
  ui.pendingEmptyContinuationExit = null;
  return false;
}

function handlePendingMarkdownTextKey(event) {
  if (ui.blockSelection.ids.length) return false;
  if (
    event.defaultPrevented ||
    event.metaKey ||
    event.ctrlKey ||
    event.altKey ||
    event.isComposing ||
    event.key.length !== 1
  ) {
    return false;
  }
  const pending = ui.pendingMarkdownTextTarget;
  if (!pending) return false;
  if (Date.now() > pending.expiresAt) {
    ui.pendingMarkdownTextTarget = null;
    return false;
  }
  const targetElement = event.target instanceof Element ? event.target : null;
  const targetIsLiveEditable = targetElement && document.contains(targetElement) && isEditableShortcutTarget(targetElement);
  const targetBlockContent = targetElement?.closest("[data-block-content]");
  if (targetIsLiveEditable && targetBlockContent?.dataset.blockContent === pending.blockId) return false;
  if (targetIsLiveEditable && targetBlockContent?.dataset.blockContent !== pending.blockId) return false;
  if (!appendPendingMarkdownText(pending.ownerType, pending.ownerId, pending.blockId, event.key)) {
    ui.pendingMarkdownTextTarget = null;
    return false;
  }
  event.preventDefault();
  event.stopPropagation();
  return true;
}

function handlePendingMarkdownTextBeforeInput(event, blockContent) {
  if (ui.blockSelection.ids.length) return false;
  if (
    event.defaultPrevented ||
    event.inputType !== "insertText" ||
    !event.data ||
    event.isComposing
  ) {
    return false;
  }
  const pending = ui.pendingMarkdownTextTarget;
  if (!pending) return false;
  if (Date.now() > pending.expiresAt) {
    ui.pendingMarkdownTextTarget = null;
    return false;
  }
  if (blockContent?.dataset.blockContent !== pending.blockId) return false;
  if (!appendPendingMarkdownText(pending.ownerType, pending.ownerId, pending.blockId, event.data)) {
    ui.pendingMarkdownTextTarget = null;
    return false;
  }
  event.preventDefault();
  event.stopPropagation();
  return true;
}

function handlePendingMarkdownTargetTab(event) {
  if (ui.blockSelection.ids.length) return false;
  if (
    event.defaultPrevented ||
    event.key !== "Tab" ||
    event.metaKey ||
    event.ctrlKey ||
    event.altKey ||
    event.isComposing
  ) {
    return false;
  }
  const pending = ui.pendingMarkdownTextTarget;
  if (!pending) return false;
  if (Date.now() > pending.expiresAt) {
    ui.pendingMarkdownTextTarget = null;
    return false;
  }
  const targetElement = event.target instanceof Element ? event.target : null;
  const targetBlockContent = targetElement?.closest("[data-block-content]");
  const targetIsLiveEditable = targetElement && document.contains(targetElement) && isEditableShortcutTarget(targetElement);
  if (targetIsLiveEditable && targetBlockContent?.dataset.blockContent === pending.blockId) return false;
  const pendingElement = document.querySelector(`[data-block-content="${cssEscape(pending.blockId)}"]`);
  if (pendingElement && targetIsLiveEditable) return false;
  if (pendingElement && pendingMarkdownBlockType(pending) === "code") {
    const handled = editCodeBlockIndent(pending.ownerType, pending.ownerId, pending.blockId, pendingElement, event.shiftKey ? -1 : 1);
    if (!handled) {
      ui.pendingMarkdownTextTarget = null;
      return false;
    }
    pending.expiresAt = Date.now() + 700;
    event.preventDefault();
    event.stopPropagation();
    return true;
  }
  indentBlock(pending.ownerType, pending.ownerId, pending.blockId, event.shiftKey ? -1 : 1);
  pending.expiresAt = Date.now() + 700;
  event.preventDefault();
  event.stopPropagation();
  return true;
}

function pendingMarkdownBlockType(pending) {
  const item = itemById(pending?.ownerType, pending?.ownerId);
  return item?.blocks?.find((block) => block.id === pending?.blockId)?.type || "";
}

function handleDocumentSelectionChange() {
  if (ui.blockDrag || ui.editorMarquee || ui.deleteDrag || ui.todayTaskDrag) return;
  const nextToolbar = inlineToolbarFromSelection();
  if (inlineToolbarEqual(ui.inlineToolbar, nextToolbar)) return;
  ui.inlineToolbar = nextToolbar;
  renderOverlays();
}

function inlineToolbarFromSelection() {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0 || selection.isCollapsed) return null;
  const range = selection.getRangeAt(0);
  const startElement = range.startContainer instanceof Element ? range.startContainer : range.startContainer.parentElement;
  const endElement = range.endContainer instanceof Element ? range.endContainer : range.endContainer.parentElement;
  const blockContent = startElement?.closest("[data-block-content]");
  if (!blockContent || blockContent !== endElement?.closest("[data-block-content]")) return null;
  const editor = blockContent.closest(".block-editor");
  if (!editor) return null;
  if (!editorOwnerMutationAllowed(editor.dataset.ownerType, editor.dataset.ownerId)) return null;
  const offsets = selectionOffsetsInside(blockContent);
  if (!offsets || offsets.collapsed || offsets.end <= offsets.start) return null;
  const rect = range.getBoundingClientRect();
  const fallbackRect = blockContent.getBoundingClientRect();
  const block = itemById(editor.dataset.ownerType, editor.dataset.ownerId)?.blocks?.find((entry) => entry.id === blockContent.dataset.blockContent);
  if (!block || block.type === "code") return null;
  const marks = normalizeInlineMarks(block?.text || blockContent.textContent || "", block?.marks || inlineMarksFromContent(blockContent));
  const existingToolbarElement = els.overlayRoot?.querySelector("[data-inline-toolbar]");
  const existingToolbarRect = existingToolbarElement?.getBoundingClientRect();
  const position = inlineToolbarPositionForRect(
    inlineSelectionRect(rect, fallbackRect),
    existingToolbarRect?.width || INLINE_TOOLBAR_ESTIMATED_WIDTH,
    existingToolbarRect?.height || INLINE_TOOLBAR_ESTIMATED_HEIGHT,
  );
  const sameSelection = ui.inlineToolbar?.ownerType === editor.dataset.ownerType &&
    ui.inlineToolbar?.ownerId === editor.dataset.ownerId &&
    ui.inlineToolbar?.blockId === blockContent.dataset.blockContent &&
    ui.inlineToolbar?.start === offsets.start &&
    ui.inlineToolbar?.end === offsets.end;
  return {
    ownerType: editor.dataset.ownerType,
    ownerId: editor.dataset.ownerId,
    blockId: blockContent.dataset.blockContent,
    start: offsets.start,
    end: offsets.end,
    ...position,
    colorMenuOpen: sameSelection && ui.inlineToolbar?.colorMenuOpen === true,
    activeTypes: INLINE_FORMAT_MARK_TYPES.filter((type) => inlineRangeFullyMarked(marks, type, offsets.start, offsets.end)),
    activeResourceCitation: inlineRangeFullyMarked(marks, "resourceLink", offsets.start, offsets.end),
    activeTextColor: inlineColorForRange(marks, INLINE_COLOR_MARK_TYPES.text, offsets.start, offsets.end),
    activeBackgroundColor: inlineColorForRange(marks, INLINE_COLOR_MARK_TYPES.background, offsets.start, offsets.end),
  };
}

function inlineSelectionRect(rect, fallbackRect) {
  if (rect && Number.isFinite(rect.left) && Number.isFinite(rect.top) && (rect.width || rect.height)) return rect;
  return fallbackRect;
}

function inlineToolbarViewportBounds() {
  const viewport = window.visualViewport;
  const left = Number.isFinite(viewport?.offsetLeft) ? viewport.offsetLeft : 0;
  const top = Number.isFinite(viewport?.offsetTop) ? viewport.offsetTop : 0;
  const width = Number.isFinite(viewport?.width) ? viewport.width : window.innerWidth;
  const height = Number.isFinite(viewport?.height) ? viewport.height : window.innerHeight;
  return { left, top, right: left + width, bottom: top + height };
}

function inlineToolbarPositionForRect(anchorRect, width = INLINE_TOOLBAR_ESTIMATED_WIDTH, height = INLINE_TOOLBAR_ESTIMATED_HEIGHT) {
  const viewport = inlineToolbarViewportBounds();
  const margin = INLINE_TOOLBAR_VIEWPORT_MARGIN;
  const safeWidth = Math.max(1, Math.min(width, Math.max(1, viewport.right - viewport.left - margin * 2)));
  const safeHeight = Math.max(1, Math.min(height, Math.max(1, viewport.bottom - viewport.top - margin * 2)));
  const anchorLeft = Number.isFinite(anchorRect?.left) ? anchorRect.left : viewport.left + (viewport.right - viewport.left) / 2;
  const anchorTop = Number.isFinite(anchorRect?.top) ? anchorRect.top : viewport.top + (viewport.bottom - viewport.top) / 2;
  const anchorWidth = Number.isFinite(anchorRect?.width) ? anchorRect.width : 0;
  const anchorBottom = Number.isFinite(anchorRect?.bottom) ? anchorRect.bottom : anchorTop + (Number.isFinite(anchorRect?.height) ? anchorRect.height : 0);
  const minX = viewport.left + margin;
  const maxX = Math.max(minX, viewport.right - margin - safeWidth);
  const x = Math.max(minX, Math.min(anchorLeft + anchorWidth / 2 - safeWidth / 2, maxX));
  const availableAbove = anchorTop - (viewport.top + margin);
  const availableBelow = (viewport.bottom - margin) - anchorBottom;
  const requiredSpace = safeHeight + INLINE_TOOLBAR_SELECTION_GAP;
  const placement = availableAbove >= requiredSpace || availableAbove >= availableBelow ? "above" : "below";
  const rawY = placement === "above"
    ? anchorTop - INLINE_TOOLBAR_SELECTION_GAP - safeHeight
    : anchorBottom + INLINE_TOOLBAR_SELECTION_GAP;
  const minY = viewport.top + margin;
  const maxY = Math.max(minY, viewport.bottom - margin - safeHeight);
  const y = Math.max(minY, Math.min(rawY, maxY));
  return { x, y, placement };
}

function inlineToolbarAnchorRect(toolbar = ui.inlineToolbar) {
  if (!toolbar) return null;
  const editor = document.querySelector(`.block-editor[data-owner-type="${cssEscape(toolbar.ownerType)}"][data-owner-id="${cssEscape(toolbar.ownerId)}"]`);
  const blockContent = editor?.querySelector(`[data-block-content="${cssEscape(toolbar.blockId)}"]`);
  if (!blockContent) return null;
  const textLength = (blockContent.textContent || "").length;
  const start = Math.max(0, Math.min(textLength, toolbar.start));
  const end = Math.max(start, Math.min(textLength, toolbar.end));
  try {
    const range = document.createRange();
    const startPoint = textPointAtOffset(blockContent, start);
    const endPoint = textPointAtOffset(blockContent, end);
    range.setStart(startPoint.node, startPoint.offset);
    range.setEnd(endPoint.node, endPoint.offset);
    return inlineSelectionRect(range.getBoundingClientRect(), blockContent.getBoundingClientRect());
  } catch (_) {
    return blockContent.getBoundingClientRect();
  }
}

function syncInlineToolbarPosition() {
  if (!ui.inlineToolbar) return;
  const element = els.overlayRoot?.querySelector("[data-inline-toolbar]");
  if (!element) return;
  const elementRect = element.getBoundingClientRect();
  const position = inlineToolbarPositionForRect(
    inlineToolbarAnchorRect(ui.inlineToolbar),
    elementRect.width || INLINE_TOOLBAR_ESTIMATED_WIDTH,
    elementRect.height || INLINE_TOOLBAR_ESTIMATED_HEIGHT,
  );
  ui.inlineToolbar.x = position.x;
  ui.inlineToolbar.y = position.y;
  ui.inlineToolbar.placement = position.placement;
  element.style.left = `${Math.floor(position.x)}px`;
  element.style.top = `${Math.floor(position.y)}px`;
  element.dataset.placement = position.placement;
}

function scheduleInlineToolbarPositionSync() {
  if (!ui.inlineToolbar || inlineToolbarPositionFrame) return;
  inlineToolbarPositionFrame = window.requestAnimationFrame(() => {
    inlineToolbarPositionFrame = 0;
    syncInlineToolbarPosition();
  });
}

function hasInlineSelectionInside(element) {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0 || selection.isCollapsed) return false;
  const anchor = selection.anchorNode;
  const focus = selection.focusNode;
  return Boolean(anchor && focus && element.contains(anchor) && element.contains(focus));
}

function inlineToolbarEqual(left, right) {
  if (!left || !right) return left === right;
  return (
    left.ownerType === right.ownerType &&
    left.ownerId === right.ownerId &&
    left.blockId === right.blockId &&
    left.start === right.start &&
    left.end === right.end &&
    Math.round(left.x) === Math.round(right.x) &&
    Math.round(left.y) === Math.round(right.y) &&
    left.placement === right.placement &&
    left.colorMenuOpen === right.colorMenuOpen &&
    left.activeResourceCitation === right.activeResourceCitation &&
    left.activeTextColor === right.activeTextColor &&
    left.activeBackgroundColor === right.activeBackgroundColor &&
    (left.activeTypes || []).join(",") === (right.activeTypes || []).join(",")
  );
}

function handleDocumentClick(event) {
  if (!event.target.closest?.("[data-finance-select]")) closeFinanceSelects();
  document.querySelectorAll(".code-language-picker[open]").forEach((picker) => {
    if (!picker.contains(event.target)) closeCodeLanguagePicker(picker);
  });
  if (handleSelectedBlocksMenuOutsideClick(event)) return;

  if (!event.target.closest("[data-calendar-event-key]")) closeCalendarSpanEvents();

  if (ui.urlPasteChoice && !event.target.closest("[data-url-paste-choice-menu]")) {
    closeUrlPasteChoice({ restoreFocus: false });
  }

  if (ui.suppressBlockClickUntil > Date.now() && event.target.closest(".block, .block-editor")) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }

  const whitespaceBlockContent = editorWhitespaceBlockClickTarget(event);
  if (whitespaceBlockContent) {
    event.preventDefault();
    event.stopPropagation();
    focusBlockContentAtClientPoint(whitespaceBlockContent, event.clientX, event.clientY);
    return;
  }

  const bottomEditor = editorBottomClickTarget(event);
  if (bottomEditor) {
    event.preventDefault();
    event.stopPropagation();
    focusEditorBottom(bottomEditor.dataset.ownerType, bottomEditor.dataset.ownerId);
    return;
  }
  if (!event.target.closest("[data-block-content]") && !event.target.closest(".selected-block-menu") && !event.target.closest(".mention-menu") && !event.target.closest(".inline-format-toolbar") && !event.target.closest(".inline-link-popover") && !event.target.closest(".inline-comment-popover") && !event.target.closest(".inline-equation-popover")) {
    clearBlockSelection();
    deactivateActiveBlockContent();
  }
  if (
    ui.navOpen &&
    !ui.navDocked &&
    !event.target.closest(".sidebar") &&
    !event.target.closest("[data-action='toggle-nav']")
  ) {
    closeNav();
    return;
  }
  if (!event.target.closest(".command-menu") && !event.target.closest("[data-action='open-command']") && ui.commandOpen) {
    ui.commandOpen = false;
    renderOverlays();
  }
  if (!event.target.closest(".selected-block-menu") && !event.target.closest(".block-content") && !event.target.closest(".inline-format-toolbar") && !event.target.closest(".inline-link-popover") && !event.target.closest(".inline-comment-popover") && !event.target.closest(".inline-equation-popover") && ui.selectedBlockMenu) {
    ui.selectedBlockMenu = null;
    renderOverlays();
  }
  if (!event.target.closest(".mention-menu") && !event.target.closest(".block-content") && ui.mention) {
    ui.mention = null;
    renderOverlays();
  }
  if (!event.target.closest(".page-command-menu") && !event.target.closest(".block-content") && ui.pageCommand) {
    ui.pageCommand = null;
    renderOverlays();
  }
  if (!event.target.closest(".emoji-menu") && !event.target.closest(".block-content") && ui.emojiCommand) {
    ui.emojiCommand = null;
    renderOverlays();
  }
  if (ui.linkPopover && !event.target.closest(".inline-link-popover") && !event.target.closest(".inline-format-toolbar")) {
    ui.linkPopover = null;
    renderOverlays();
  }
  if (ui.resourceCitationPopover && !event.target.closest("[data-resource-citation-popover]") && !event.target.closest(".inline-format-toolbar")) {
    ui.resourceCitationPopover = null;
    renderOverlays();
  }
  if (ui.commentPopover && !event.target.closest(".inline-comment-popover") && !event.target.closest(".inline-format-toolbar")) {
    ui.commentPopover = null;
    renderOverlays();
  }
  if (ui.equationPopover && !event.target.closest(".inline-equation-popover") && !event.target.closest(".inline-format-toolbar")) {
    ui.equationPopover = null;
    renderOverlays();
  }
  if (
    ui.scheduler &&
    !event.target.closest(".task-scheduler") &&
    !event.target.closest("[data-schedule-hold]") &&
    !event.target.closest("[data-action='new-task']")
  ) {
    closeTaskScheduler();
  }
}

function handleDragStart(event) {
  if (event.target.closest(
    "[data-nav-key], [data-delete-drag-type], [data-today-task-id], [data-block-drag], [data-block-add], [data-scheduler-open], [data-schedule-hold]",
  )) {
    event.preventDefault();
    return;
  }
  if (handleNavDragStart(event)) return;
  if (ui.view === "today" && event.target.closest("[data-today-task-id]")) {
    event.preventDefault();
    return;
  }
  const card = event.target.closest("[data-task-id]");
  if (!card) return;
  ui.draggedTaskId = card.dataset.taskId;
  event.dataTransfer.setData("text/plain", card.dataset.taskId);
  event.dataTransfer.effectAllowed = "move";
  if (ui.view === "today" && card.closest("[data-today-task-zone='today']")) {
    app.classList.add("is-today-task-dragging");
  }
}

function handleDragOver(event) {
  if (handleNavDragOver(event)) return;
  const zone = event.target.closest("[data-drop-date]");
  if (!zone) return;
  event.preventDefault();
  zone.classList.add("is-over");
}

function handleDragLeave(event) {
  if (handleNavDragLeave(event)) return;
  const zone = event.target.closest("[data-drop-date]");
  if (zone && !zone.contains(event.relatedTarget)) zone.classList.remove("is-over");
}

function handleDrop(event) {
  if (handleNavDrop(event)) return;
  const zone = event.target.closest("[data-drop-date]");
  if (!zone) return;
  event.preventDefault();
  zone.classList.remove("is-over");
  const taskId = event.dataTransfer.getData("text/plain") || ui.draggedTaskId;
  const task = itemById("tasks", taskId);
  if (!task) return;
  moveTaskToDate(task, zone.dataset.dropDate);
  saveState();
  showToast(zone.classList.contains("today-floating-drop") ? "예정으로 옮겼습니다." : `${compactDateLabel(zone.dataset.dropDate)}로 옮겼습니다.`);
  clearTaskDrag();
  renderView({ soft: true });
}

function clearTaskDrag() {
  ui.draggedTaskId = "";
  app.classList.remove("is-today-task-dragging");
  document.querySelectorAll(".today-drop-zone.is-over, .today-floating-drop.is-over").forEach((zone) => zone.classList.remove("is-over"));
}

function handleNavPointerMove(event) {
  const pending = ui.pendingNavDrag;
  if (pending && navPointerMatches(pending, event)) {
    const distance = Math.hypot(event.clientX - pending.startX, event.clientY - pending.startY);
    if (distance < BLOCK_BODY_DRAG_ACTIVATION_DISTANCE) return;
    beginNavPointerDrag(pending, event);
  }

  const drag = ui.navPointerDrag;
  if (!drag || !navPointerMatches(drag, event)) return;
  event.preventDefault();
  event.stopPropagation();
  updateNavPointerDropTarget(event);
}

function beginNavPointerDrag(pending, event) {
  ui.pendingNavDrag = null;
  ui.navPointerDrag = {
    key: pending.key,
    pointerId: pending.pointerId,
    targetKey: "",
    position: "",
  };
  ui.navDragKey = pending.key;
  els.navTrack?.querySelector(`[data-nav-key="${cssEscape(pending.key)}"]`)?.classList.add("is-nav-dragging");
  updateNavPointerDropTarget(event);
}

function updateNavPointerDropTarget(event) {
  const target = navDropTargetFromPointer(event);
  if (!target) {
    ui.navPointerDrag.targetKey = "";
    ui.navPointerDrag.position = "";
    clearNavDropMarkers();
    return;
  }
  ui.navPointerDrag.targetKey = target.button.dataset.navKey;
  ui.navPointerDrag.position = target.position;
  setNavDropMarker(target.button, target.position);
}

function finishNavPointerDrag(event) {
  const pending = ui.pendingNavDrag;
  if (pending && navPointerMatches(pending, event)) {
    ui.pendingNavDrag = null;
    return;
  }

  const drag = ui.navPointerDrag;
  if (!drag || !navPointerMatches(drag, event)) return;
  event.preventDefault();
  event.stopPropagation();
  const target = navDropTargetFromPointer(event) || navStoredPointerDropTarget(drag);
  if (target) {
    reorderNav(drag.key, target.button.dataset.navKey, target.position);
  }
  ui.suppressNavClickUntil = Date.now() + 450;
  cancelNavPointerDrag();
}

function cancelNavPointerDrag() {
  ui.pendingNavDrag = null;
  ui.navPointerDrag = null;
  clearNavDrag();
}

function navPointerMatches(drag, event) {
  return drag.pointerId === (event.pointerId ?? "mouse");
}

function navDropTargetFromPointer(event) {
  if (!els.navTrack) return null;
  const rect = els.navTrack.getBoundingClientRect();
  const withinX = event.clientX >= rect.left - 28 && event.clientX <= rect.right + 28;
  const withinY = event.clientY >= rect.top - 34 && event.clientY <= rect.bottom + 34;
  if (!withinX || !withinY) return null;
  return navDropTargetFromTrack(event, els.navTrack);
}

function navStoredPointerDropTarget(drag) {
  if (!drag.targetKey) return null;
  const button = els.navTrack?.querySelector(`[data-nav-key="${cssEscape(drag.targetKey)}"]`);
  return button ? { button, position: drag.position || "before" } : null;
}

function handleNavDragStart(event) {
  const button = event.target.closest("[data-nav-key]");
  if (!button || button.hasAttribute("data-nav-fixed")) return false;
  if (!ui.navOpen && !ui.navDocked) {
    event.preventDefault();
    return true;
  }
  ui.navDragKey = button.dataset.navKey;
  button.classList.add("is-nav-dragging");
  if (event.dataTransfer) {
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData("application/x-sygma-nav-key", ui.navDragKey);
    event.dataTransfer.setData("text/plain", ui.navDragKey);
  }
  return true;
}

function handleNavDragOver(event) {
  if (!ui.navDragKey) return false;
  const button = event.target.closest("[data-nav-key]:not([data-nav-fixed])");
  const track = event.target.closest("#navTrack");
  if (!button && !track) return false;
  event.preventDefault();
  if (button && button.dataset.navKey !== ui.navDragKey) {
    setNavDropMarker(button, navDropPositionForEvent(event, button));
  } else if (track) {
    const target = navDropTargetFromTrack(event, track);
    if (target) {
      setNavDropMarker(target.button, target.position);
    } else {
      clearNavDropMarkers();
    }
  } else {
    clearNavDropMarkers();
  }
  if (event.dataTransfer) event.dataTransfer.dropEffect = "move";
  return true;
}

function handleNavDragLeave(event) {
  if (!ui.navDragKey) return false;
  const track = event.target.closest("#navTrack");
  if (track && !track.contains(event.relatedTarget)) clearNavDropMarkers();
  return Boolean(track);
}

function handleNavDrop(event) {
  if (!ui.navDragKey) return false;
  const button = event.target.closest("[data-nav-key]:not([data-nav-fixed])");
  const track = event.target.closest("#navTrack");
  if (!button && !track) return false;
  event.preventDefault();
  if (button && button.dataset.navKey !== ui.navDragKey) {
    reorderNav(ui.navDragKey, button.dataset.navKey, navDropPositionForEvent(event, button));
  } else if (track) {
    const target = navDropTargetFromTrack(event, track);
    if (target) reorderNav(ui.navDragKey, target.button.dataset.navKey, target.position);
  }
  clearNavDrag();
  return true;
}

function navDropPositionForEvent(event, button) {
  const rect = button.getBoundingClientRect();
  return event.clientY > rect.top + rect.height / 2 ? "after" : "before";
}

function navDropTargetFromTrack(event, track) {
  let lastButton = null;
  for (const button of track.querySelectorAll("[data-nav-key]")) {
    if (button.hasAttribute("data-nav-fixed")) continue;
    if (button.dataset.navKey === ui.navDragKey) continue;
    lastButton = button;
    const rect = button.getBoundingClientRect();
    if (event.clientY <= rect.top + rect.height / 2) {
      return { button, position: "before" };
    }
  }
  return lastButton ? { button: lastButton, position: "after" } : null;
}

function setNavDropMarker(button, position) {
  clearNavDropMarkers();
  button.classList.toggle("is-nav-drop-before", position === "before");
  button.classList.toggle("is-nav-drop-after", position === "after");
}

function clearNavDropMarkers() {
  app.querySelectorAll(".is-nav-drop-before, .is-nav-drop-after").forEach((button) => {
    button.classList.remove("is-nav-drop-before", "is-nav-drop-after");
  });
}

function clearNavDrag() {
  ui.navDragKey = "";
  app.querySelectorAll(".is-nav-dragging").forEach((button) => button.classList.remove("is-nav-dragging"));
  clearNavDropMarkers();
}

function reorderNav(dragKey, targetKey, position = "before") {
  const order = normalizeNavOrder(state.settings.navOrder);
  const previousOrder = order.join("|");
  if (!dragKey || !targetKey || dragKey === targetKey) return false;
  const fromIndex = order.indexOf(dragKey);
  if (fromIndex < 0 || !order.includes(targetKey)) return false;
  order.splice(fromIndex, 1);
  const targetIndex = order.indexOf(targetKey);
  const insertIndex = position === "after" ? targetIndex + 1 : targetIndex;
  order.splice(insertIndex, 0, dragKey);
  const nextOrder = normalizeNavOrder(order);
  if (nextOrder.join("|") === previousOrder) return false;
  state.settings.navOrder = nextOrder;
  saveState();
  renderNav();
  showToast("목차 순서를 변경했습니다.");
  return true;
}

